// ─── 1. Parse Script into Scenes ─────────────────────────────────────────────

const SCENE_PARSE_BATCH_SIZE = 16;

function narrationWordCount(text: string): number {
  return text.split(/\s+/).filter((w) => w.length > 0).length;
}

/** Split or merge markdown blocks to exactly maxScenes without repeating narration. */
function partitionNarrationBlocks(blocks: MarkdownNarrationBlock[], maxScenes: number): string[] {
  if (blocks.length === 0) return [];
  if (blocks.length === maxScenes) return blocks.map((b) => b.text);
  if (blocks.length > maxScenes) {
    const texts = blocks.map((b) => b.text);
    const merged: string[] = [];
    let cursor = 0;
    for (let i = 0; i < maxScenes; i++) {
      const take = i === maxScenes - 1
        ? texts.length - cursor
        : Math.max(1, Math.round((texts.length - cursor) / (maxScenes - i)));
      merged.push(texts.slice(cursor, cursor + take).join(" "));
      cursor += take;
    }
    return merged;
  }
  const texts = [...blocks.map((b) => b.text)];
  while (texts.length < maxScenes) {
    let splitIdx = 0;
    let maxWords = 0;
    for (let i = 0; i < texts.length; i++) {
      const w = narrationWordCount(texts[i]);
      if (w > maxWords) {
        maxWords = w;
        splitIdx = i;
      }
    }
    const words = texts[splitIdx].split(/\s+/).filter(Boolean);
    if (words.length < 24) break;
    const mid = Math.ceil(words.length / 2);
    const a = words.slice(0, mid).join(" ");
    const b = words.slice(mid).join(" ");
    texts.splice(splitIdx, 1, a, b);
  }
  return texts.slice(0, maxScenes);
}

function scenesFromMarkdownScript(script: string, maxScenes: number, topicContext?: string): Scene[] | null {
  const blocks = parseMarkdownNarrationBlocks(script);
  if (blocks.length < 2) return null;

  const texts = partitionNarrationBlocks(blocks, maxScenes);
  if (texts.length < 2) return null;

  const scriptPersons = extractPersonNamesFromText(topicContext ?? script);

  return texts.map((text, index) => {
    const block =
      blocks.find((b) => text.includes(b.text.slice(0, Math.min(60, b.text.length)))) ??
      blocks[Math.min(index, blocks.length - 1)];
    const beatPersons = [
      ...new Set([...extractPersonNamesFromText(text), ...scriptPersons]),
    ].filter(Boolean);
    const primaryQuery = stockQueryFromBeatScript(text, beatPersons, text, topicContext);
    const allQueries = [
      ...new Set([
        primaryQuery,
        ...scriptStockSearchQueries(text, beatPersons, text, topicContext),
      ]),
    ].slice(0, 4);
    const primary = beatPersons[0] ?? "";
    return {
      index,
      text,
      visualCue: primaryQuery,
      pexelsQuery: primaryQuery,
      pexelsQueries: allQueries.length ? allQueries : [primaryQuery],
      personNames: beatPersons,
      literalVisualCue: undefined,
      highlightWords: [],
      // RONDE 93 (§6): the subject itself. "interview" and "news" were appended to every scene
      // regardless of what it says, and the gate refuses both on a beat that mentions neither.
      brollQueries: primary
        ? [primary].filter((q) => q.length >= 3 && !isBlockedStockQuery(q))
        : [],
      statCallout: "",
      aiImagePrompt: `Cinematic ${primaryQuery}, documentary lighting, photorealistic`,
      duration: 0,
      isChapterCard: false,
      chapterTitle: isPublishableChapterTitle(block.sectionTitle) ? block.sectionTitle : undefined,
      sectionTitle: isPublishableChapterTitle(block.sectionTitle) ? block.sectionTitle : undefined,
    };
  });
}

/** Remove LLM-parse overlap so scene 2+ does not replay the opening hook. */
function dedupeSceneNarration(scenes: Scene[]): Scene[] {
  if (scenes.length < 2) return scenes;
  const hookPrefix = scenes[0].text.trim().slice(0, 100);
  for (let i = 1; i < scenes.length; i++) {
    let text = scenes[i].text.trim();
    if (hookPrefix.length > 30) {
      for (const len of [100, 80, 60, 40]) {
        const prefix = hookPrefix.slice(0, len).trim();
        if (prefix.length > 20 && text.startsWith(prefix)) {
          text = text.slice(prefix.length).trim();
          break;
        }
      }
    }
    const prev = scenes[i - 1].text.trim();
    if (prev.length > 40) {
      const tail = prev.slice(-80);
      if (text.startsWith(tail.slice(0, 50))) {
        text = text.slice(tail.slice(0, 50).length).trim();
      }
    }
    scenes[i].text = text.length > 0 ? text : scenes[i].text;
  }
  return scenes;
}

function parseLLMJson<T>(content: unknown, label: string): T {
  try {
    if (content && typeof content === "object") return content as T;
    const raw = typeof content === "string" ? content : JSON.stringify(content);
    return JSON.parse(raw) as T;
  } catch (err) {
    throw pipelineError(
      PIPELINE_ERROR.SCRIPT_PARSE,
      `${label}: ${(err as Error).message}`
    );
  }
}

function splitScriptForSceneParsing(script: string, parts: number): string[] {
  if (parts <= 1) return [script];
  const sections = script.split(/(?=^## )/m).filter((s) => s.trim().length > 0);
  if (sections.length >= parts) {
    const chunks: string[] = Array.from({ length: parts }, () => "");
    sections.forEach((sec, i) => {
      chunks[i % parts] += (chunks[i % parts] ? "\n" : "") + sec;
    });
    return chunks.filter((c) => c.trim().length > 0);
  }
  const size = Math.ceil(script.length / parts);
  return Array.from({ length: parts }, (_, i) => script.slice(i * size, (i + 1) * size)).filter(Boolean);
}

const SCENE_JSON_SCHEMA = {
  type: "json_schema" as const,
  json_schema: {
    name: "scenes",
    strict: true,
    schema: {
      type: "object",
      properties: {
        scenes: {
          type: "array",
          items: {
            type: "object",
            properties: {
              text: { type: "string" },
              visualCue: { type: "string" },
              pexelsQuery: { type: "string" },
              pexelsQueries: { type: "array", items: { type: "string" } },
              personNames: { type: "array", items: { type: "string" } },
              brollQueries: { type: "array", items: { type: "string" } },
              literalVisualCue: { type: "string" },
              sectionTitle: { type: "string" },
              statCallout: { type: "string" },
            },
            required: ["text", "visualCue", "pexelsQuery", "pexelsQueries", "personNames", "brollQueries", "literalVisualCue", "sectionTitle", "statCallout"],
            additionalProperties: false,
          },
        },
      },
      required: ["scenes"],
      additionalProperties: false,
    },
  },
};

async function parseScriptIntoScenesBatch(
  script: string,
  sceneCount: number,
  startIndex: number,
  stepTiming?: PipelineStepTiming
): Promise<Scene[]> {
  const response = await timePipelineStep(
    stepTiming,
    "llm_call",
    "Script scene parse (GPT)",
    () =>
      withTimeout(
        invokeLLM({
      messages: [
        {
          role: "system",
          content: `Parse the script into exactly ${sceneCount} scenes for Vidrush-quality documentary video.

Scripts are NARRATION ONLY (no [VISUAL:] tags). Footage search is derived server-side from spoken words.

For each scene return:
- text: narration only (max 500 chars, full sentences) — strip any [VISUAL: ...] if present
- visualCue: "" (leave empty)
- literalVisualCue: "" (leave empty)
- pexelsQuery: "" (leave empty)
- pexelsQueries: [] (leave empty)
- brollQueries: [] (leave empty)
- personNames: full names of real people mentioned in text, or []. If the video is about one celebrity, include their full name on EVERY scene even when narration says "she" or "her".
- sectionTitle: ALL CAPS chapter heading shown on yellow card BEFORE this scene when starting a new topic; "" if not a chapter start. NEVER use HOOK, OPENING, CTA, INTRO, or OUTRO as sectionTitle — always "" for those meta sections.
- statCallout: ONE key number or stat from this scene for a yellow corner box (e.g. "$1B", "45%", "2024") or "" if none.

Split narration into contiguous slices — NEVER repeat the opening hook or earlier sentences in later scenes. Each scene text is ONLY its own slice. Name real people, brands, and events in the spoken lines when relevant.`,
        },
        {
          role: "user",
          content: `Parse into exactly ${sceneCount} scenes:\n\n${script.slice(0, 14000)}`,
        },
      ],
      preferProvider: "groq",
      response_format: SCENE_JSON_SCHEMA,
      maxTokens: 16384,
        }),
        120_000,
        `Parse scenes batch from ${startIndex}`
      )
  );

  const content = response.choices[0]?.message?.content;
  if (!content) throw pipelineError(PIPELINE_ERROR.SCRIPT_PARSE, "Failed to parse script into scenes");
  const parsed = parseLLMJson<{ scenes: Array<Omit<Scene, "index" | "duration"> & { sectionTitle?: string }> }>(
    content,
    "Scene parse JSON"
  );
  const rawScenes = (parsed.scenes ?? []).slice(0, sceneCount);
  return rawScenes.map((s, i) => mapRawScene(s, startIndex + i));
}

function mapRawScene(
  s: Omit<Scene, "index" | "duration"> & { sectionTitle?: string },
  index: number
): Scene {
  const rawS = s as Record<string, unknown>;
  const hint = `${s.text ?? ""}`.replace(/\[visual:[^\]]*\]/gi, " ").trim();
  const personNames = [
    ...new Set(
      [
        ...(Array.isArray(rawS.personNames) ? rawS.personNames : [])
          .map(coercePersonName)
          .filter((n) => n.length > 0),
        ...extractPersonNamesFromText(hint),
      ]
    ),
  ];
  const subject = extractBeatSubject(hint, personNames);
  // RONDE 100B: no subject means no query. This was `subject || "documentary"`, and the literal
  // word travelled from here into scene.pexelsQuery and scene.visualCue, which the stock
  // fallback hands to Pexels and Pixabay verbatim.
  const primaryQuery = subject;
  const allQueries = scriptStockSearchQueries(hint, personNames);
  const brollQueries: string[] = [];
  const sectionTitle =
    typeof rawS.sectionTitle === "string" ? rawS.sectionTitle.trim().slice(0, 60) : "";
  const statCallout =
    typeof rawS.statCallout === "string" ? rawS.statCallout.trim().slice(0, 24) : "";
  return {
    ...s,
    index,
    duration: 0,
    text: hint,
    visualCue: primaryQuery,
    pexelsQuery: primaryQuery,
    pexelsQueries: allQueries,
    personNames,
    literalVisualCue: undefined,
    highlightWords: [],
    brollQueries,
    statCallout,
    aiImagePrompt: `Cinematic ${primaryQuery}, dramatic lighting, photorealistic`,
    isChapterCard: false,
    chapterTitle: isPublishableChapterTitle(sectionTitle) ? sectionTitle : undefined,
    sectionTitle: isPublishableChapterTitle(sectionTitle) ? sectionTitle : undefined,
  };
}

export async function parseScriptIntoScenes(
  script: string,
  maxScenes: number,
  topicContext?: string,
  stepTiming?: PipelineStepTiming
): Promise<Scene[]> {
  const fromMarkdown = scenesFromMarkdownScript(script, maxScenes, topicContext);
  if (fromMarkdown && fromMarkdown.length >= Math.min(2, maxScenes)) {
    console.log(`[Pipeline] Parsed ${fromMarkdown.length} scenes from markdown (no LLM re-parse)`);
    recordPipelineTiming(stepTiming, "scene_generation", "Script parse (markdown)", 0);
    return dedupeSceneNarration(fromMarkdown);
  }

  let scenes: Scene[];
  if (maxScenes <= SCENE_PARSE_BATCH_SIZE) {
    scenes = await parseScriptIntoScenesBatch(script, maxScenes, 0, stepTiming);
  } else {
    const batchCount = Math.ceil(maxScenes / SCENE_PARSE_BATCH_SIZE);
    const chunks = splitScriptForSceneParsing(script, batchCount);
    const scenesPerBatch = Math.ceil(maxScenes / chunks.length);
    const allScenes: Scene[] = [];

    for (let b = 0; b < chunks.length; b++) {
      const remaining = maxScenes - allScenes.length;
      if (remaining <= 0) break;
      const count = Math.min(scenesPerBatch, remaining, SCENE_PARSE_BATCH_SIZE);
      const batchScenes = await parseScriptIntoScenesBatch(chunks[b], count, allScenes.length, stepTiming);
      allScenes.push(...batchScenes);
    }
    scenes = allScenes;
  }

  if (scenes.length === 0) {
    throw pipelineError(PIPELINE_ERROR.SCRIPT_PARSE, "No scenes parsed from script");
  }
  return dedupeSceneNarration(scenes.slice(0, maxScenes));
}

// ─── 2. TTS Voiceover ───────────────────────────────────────────────────────────────────────────
export type VoiceoverGenerateOptions = {
  /** Per-scene cap 800; full-script bulk uses ~10k (1–2 min documentaries). */
  maxChars?: number;
  /** One ElevenLabs call for entire narration (faster, consistent tone). */
  preferElevenLabs?: boolean;
  /** Phase 10: override the fixed ElevenLabs voice_settings — e.g. narration-tone-derived
   *  values from elevenLabsVoiceSettingsForTone(). Omitting it keeps the original constants. */
  voiceSettings?: ElevenLabsVoiceSettings;
};

export type VoiceoverProvider = "elevenlabs" | "fish-audio" | "google-tts" | "silent";

/** Result of generateVoiceover() — callers must check usedSilentFallback rather than assume
 *  a returned duration means real narration was produced. */
export type VoiceoverResult = {
  duration: number;
  usedSilentFallback: boolean;
  provider: VoiceoverProvider;
};

function sanitizeVoiceoverText(text: string, maxChars = 800): string {
  const rawText = text
    .replace(/\[visual:[^\]]*\]/gi, "")
    .replace(/[#*_`~>]/g, "")
    // Phase 11: map common LLM-emitted non-ASCII punctuation to an ASCII equivalent, then
    // replace any remaining non-ASCII with a space (never deletion), before collapsing
    // whitespace last. The previous order deleted non-ASCII chars outright, so an unspaced em
    // dash ("growth—an unprecedented", which LLMs emit routinely) merged into "growthan" once
    // sent to TTS — audibly garbled narration. Deleting to a space instead of "" ensures a
    // stripped character never silently joins two words.
    .replace(/[‒-―]/g, " - ")
    .replace(/[‘’]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/…/g, "...")
    .replace(/[^\x00-\x7F]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (rawText.length <= maxChars) return rawText;
  return rawText.slice(0, maxChars).replace(/\s\S*$/, "");
}

/** ElevenLabs safe max per request; long scripts are chunked at scene boundaries then concatenated. */
const BULK_VO_CHUNK_CHARS = 9_500;

async function concatVoiceoverParts(partPaths: string[], outputPath: string, workDir: string): Promise<void> {
  if (partPaths.length === 1) {
    // Best-effort re-encode to a known, fixed 192k CBR mp3 — whatever bitrate/format the TTS
    // provider itself used otherwise. That guarantee lets splitFullVoiceoverByScenes fall back
    // to a byte-count-based duration estimate if ffprobe can't run at all under load (see
    // probeVideoDurationSec / "Bulk voiceover file has no duration"). But this re-encode is
    // itself just another ffmpeg spawn, so under the SAME resource pressure it's meant to guard
    // against, it can time out too — that must never take down an otherwise-fine voiceover, so
    // fall back to the original zero-cost copy (no process spawn, cannot fail from load) instead
    // of throwing. The byte-count fallback simply won't apply to this file if we had to bail here.
    try {
      await withSceneFetchTimeout(
        () => exec(`${FFMPEG_BIN} -y -i "${partPaths[0]}" -c:a libmp3lame -b:a 192k "${outputPath}"`),
        60_000,
        "Re-encode single-part voiceover"
      );
    } catch (err) {
      console.warn(
        `[Pipeline] Single-part voiceover re-encode failed, falling back to plain copy: ${(err as Error).message?.slice(0, 150)}`
      );
      fs.copyFileSync(partPaths[0], outputPath);
    }
    return;
  }
  const listFile = path.join(workDir, "voiceover_concat_list.txt");
  fs.writeFileSync(listFile, partPaths.map((p) => `file '${p.replace(/'/g, "'\\''")}'`).join("\n"));
  await withSceneFetchTimeout(
    () => exec(
      `${FFMPEG_BIN} -y -f concat -safe 0 -i "${listFile}" -c:a libmp3lame -b:a 192k "${outputPath}"`
    ),
    120_000,
    "Concat bulk voiceover parts"
  );
}

/** Build one MP3 for the full narration (1+ ElevenLabs calls if script is very long). */
export async function synthesizeFullNarrationMp3(
  scenes: Scene[],
  workDir: string,
  voiceId?: string,
  onTtsPart?: (part: number, totalParts: number) => void,
  sourceScript?: string
): Promise<string> {
  // Phase 10: join scene/section narration with a breathing-pause separator (falls back to
  // extractFullNarrationText's plain-space join when the script doesn't parse into blocks).
  const narrationText = sourceScript
    ? (() => {
        const blocks = parseMarkdownNarrationBlocks(sourceScript);
        return blocks.length > 0
          ? joinNarrationWithBreathingPauses(blocks.map((b) => b.text))
          : extractFullNarrationText(sourceScript);
      })()
    : joinNarrationWithBreathingPauses(scenes.map((s) => s.text));
  const fullNarration = sanitizeVoiceoverText(narrationText, 200_000);
  if (fullNarration.length === 0) {
    throw pipelineError(PIPELINE_ERROR.VOICEOVER_EMPTY, "No narration text for bulk voiceover");
  }

  const chunks: string[] = [];
  let rest = fullNarration;
  while (rest.length > BULK_VO_CHUNK_CHARS) {
    const slice = rest.slice(0, BULK_VO_CHUNK_CHARS);
    const breakAt = Math.max(slice.lastIndexOf(". "), slice.lastIndexOf("! "), slice.lastIndexOf("? "));
    const cut = breakAt > 200 ? breakAt + 1 : BULK_VO_CHUNK_CHARS;
    chunks.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
  }
  if (rest.length > 0) chunks.push(rest);

  const partPaths: string[] = [];
  const alignParts: Array<{ offsetSec: number; alignment: TtsCharacterAlignment }> = [];
  let timeOffset = 0;
  const useTtsAlign =
    ttsWordAlignmentEnabled() &&
    Boolean(ELEVENLABS_API_KEY) &&
    Boolean(voiceId?.trim());
  const TTS_TIMEOUT_MS = 180_000;
  const silentFallbackChunks: number[] = [];

  for (let i = 0; i < chunks.length; i++) {
    onTtsPart?.(i + 1, chunks.length);
    const partPath = path.join(workDir, `full_voiceover_part_${i}.mp3`);
    // Phase 10: derive this chunk's voice_settings from its own narration tone instead of
    // applying one fixed stability/style to every chunk regardless of content.
    const chunkVoiceSettings = narrationEmotionalVoiceEnabled()
      ? elevenLabsVoiceSettingsForTone(classifyNarrationEmotionalTone(chunks[i]!))
      : undefined;
    if (useTtsAlign && voiceId) {
      const stamped = await fetchElevenLabsWithTimestamps(
        chunks[i]!,
        voiceId,
        ELEVENLABS_API_KEY,
        TTS_TIMEOUT_MS,
        chunkVoiceSettings
      );
      if (stamped) {
        fs.writeFileSync(partPath, stamped.audioBuffer);
        alignParts.push({ offsetSec: timeOffset, alignment: stamped.alignment });
        const partDur = await probeVideoDurationSec(partPath);
        timeOffset += partDur > 0 ? partDur : 0;
        partPaths.push(partPath);
        continue;
      }
    }
    const voResult = await generateVoiceover(chunks[i], partPath, voiceId, {
      maxChars: BULK_VO_CHUNK_CHARS,
      preferElevenLabs: true,
      voiceSettings: chunkVoiceSettings,
    });
    if (voResult.usedSilentFallback) silentFallbackChunks.push(i + 1);
    const partDur = await probeVideoDurationSec(partPath);
    timeOffset += partDur > 0 ? partDur : 0;
    partPaths.push(partPath);
  }

  if (silentFallbackChunks.length > 0) {
    // generateVoiceover already logs per-chunk; this aggregate line makes the overall impact on
    // THIS video's narration immediately visible in logs, since a single-chunk warning can be
    // easy to miss among the rest of a long render's output.
    console.error(
      `[Pipeline] synthesizeFullNarrationMp3: ${silentFallbackChunks.length}/${chunks.length} narration ` +
      `chunk(s) used SILENT fallback (parts ${silentFallbackChunks.join(", ")}) — this video's narration ` +
      `will be partially or fully silent.`
    );
  }

  const fullPath = path.join(workDir, "full_voiceover.mp3");
  await concatVoiceoverParts(partPaths, fullPath, workDir);

  if (useTtsAlign && alignParts.length === chunks.length) {
    const merged = mergeCharacterAlignments(alignParts);
    const words = wordsFromCharacterAlignment(merged);
    if (words.length > 0) {
      const totalDur = await probeVideoDurationSec(fullPath);
      saveStoredTtsAlignment(workDir, {
        words,
        totalDurationSec: totalDur > 0 ? totalDur : timeOffset,
        updatedAt: new Date().toISOString(),
      });
      console.log(`[Pipeline] TTS word alignment: ${words.length} words indexed`);
    }
  }

  return fullPath;
}

/** Full-script TTS (ElevenLabs) then split MP3 per scene by word counts — all video lengths. */
export async function generateBulkSceneVoiceovers(
  scenes: Scene[],
  audioPaths: string[],
  workDir: string,
  voiceId?: string,
  onProgress?: (done: number, total: number) => void,
  sourceScript?: string
): Promise<number[]> {
  onProgress?.(0, scenes.length);
  const fullPath = await synthesizeFullNarrationMp3(scenes, workDir, voiceId, (part, total) => {
    console.log(`[Pipeline] Bulk voiceover TTS part ${part}/${total}`);
  }, sourceScript);

  const storedTts = loadStoredTtsAlignment(workDir);
  const useTtsSplit = Boolean(storedTts?.words.length);
  if (!useTtsSplit) {
    await trimVoiceoverSilence(fullPath);
  } else {
    console.log("[Pipeline] TTS scene split: skipping full-file silence trim (word-timed boundaries)");
  }

  const durations = await splitFullVoiceoverByScenes(fullPath, scenes, audioPaths, workDir);
  onProgress?.(scenes.length, scenes.length);
  console.log(
    `[Pipeline] Bulk voiceover: ${scenes.length} scenes, split durations ${durations.map((d) => d.toFixed(1)).join("s, ")}s`
  );
  return durations;
}

// NOTE: at this pipeline's one call site (bulk voiceover generation, early in the render before
// computeRenderBudget() has run), get_activeRenderBudget() is always null, so this always falls
// through to the static sceneCount-based estimate below — the ttsMs branch above only fires for
// callers later in the pipeline where a budget has already been computed. This is intentional:
// voiceover generation must happen before scene/beat counts are final inputs to
// computeRenderBudget(), so reordering to compute the budget first would create a circular
// dependency rather than a real fix. Do not "simplify" this by dropping the branch.
function bulkVoiceoverTimeoutMs(sceneCount: number, videoLength?: string): number {
  const _budget = get_activeRenderBudget(); if (_budget) return _budget.ttsMs;
  if (isFastShortVideoLength(videoLength)) {
    return Math.min(75_000, 40_000 + sceneCount * 8_000);
  }
  return Math.min(900_000, 120_000 + sceneCount * 20_000);
}

export async function splitFullVoiceoverByScenes(
  fullAudioPath: string,
  scenes: Scene[],
  outputPaths: string[],
  workDir?: string
): Promise<number[]> {
  let totalDur = await probeVideoDurationSec(fullAudioPath);
  if (totalDur <= 0 && fs.existsSync(fullAudioPath)) {
    // probeVideoDurationSec already retries hard (semaphore-gated exec(), fork-pressure backoff,
    // 4 ffprobe binary candidates) — if it STILL comes back empty, that's sustained resource
    // pressure outlasting even that budget, not a genuinely empty file. concatVoiceoverParts
    // always re-encodes this exact file to a fixed 192k CBR mp3 (single part or not — see
    // there), so estimate duration straight from the byte count instead of failing the whole
    // render: no process spawn involved, so it can't lose to the same fork/CPU pressure.
    const sizeBytes = fs.statSync(fullAudioPath).size;
    if (sizeBytes > 2_000) {
      totalDur = (sizeBytes * 8) / 192_000;
      console.warn(
        `[Pipeline] Bulk voiceover duration probe failed under load — estimated ${totalDur.toFixed(1)}s ` +
        `from file size (${(sizeBytes / 1024).toFixed(0)}KB @ 192kbps CBR)`
      );
    }
  }
  if (totalDur <= 0) {
    throw pipelineError(PIPELINE_ERROR.VOICEOVER_EMPTY, "Bulk voiceover file has no duration");
  }

  const storedTts = workDir ? loadStoredTtsAlignment(workDir) : null;
  const ttsBounds =
    storedTts?.words.length ? sceneSplitBoundariesFromTts(scenes, storedTts) : null;

  if (ttsBounds?.length === scenes.length) {
    const durations: number[] = [];
    for (let i = 0; i < scenes.length; i++) {
      const { startSec, endSec } = ttsBounds[i]!;
      const segDur = Math.max(0.25, endSec - startSec);
      const out = outputPaths[i];
      await withSceneFetchTimeout(
        () => exec(
          `${FFMPEG_BIN} -y -ss ${startSec.toFixed(3)} -i "${fullAudioPath}" -t ${segDur.toFixed(3)} ` +
          `-c:a libmp3lame -b:a 192k "${out}"`
        ),
        45_000,
        `TTS split bulk VO scene ${i}`
      );
      if (i > 0) await trimVoiceoverLeadingSilence(out);
      let dur = await probeVideoDurationSec(out);
      if (dur <= 0) dur = segDur;
      durations.push(dur);
    }
    console.log(
      `[Pipeline] TTS scene split: ${scenes.length} scenes at word boundaries ` +
      `(${durations.map((d) => d.toFixed(1)).join("s, ")}s)`
    );
    return durations;
  }

  const weights = scenes.map((s) => {
    const words = sanitizeVoiceoverText(s.text, 50_000).split(/\s+/).filter(Boolean).length;
    return Math.max(1, words);
  });
  const totalWeight = weights.reduce((sum, w) => sum + w, 0);
  const durations: number[] = [];
  let cursor = 0;

  for (let i = 0; i < scenes.length; i++) {
    const isLast = i === scenes.length - 1;
    const segDur = isLast
      ? Math.max(0.25, totalDur - cursor)
      : Math.max(0.25, (totalDur * weights[i]) / totalWeight);
    const out = outputPaths[i];
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -ss ${cursor.toFixed(3)} -i "${fullAudioPath}" -t ${segDur.toFixed(3)} ` +
        `-c:a libmp3lame -b:a 192k "${out}"`
      ),
      45_000,
      `Split bulk VO scene ${i}`
    );
    if (i > 0) await trimVoiceoverLeadingSilence(out);
    let dur = await probeVideoDurationSec(out);
    if (dur <= 0) dur = segDur;
    durations.push(dur);
    cursor += segDur;
  }
  return durations;
}

/** Trim only leading silence on per-scene splits (keeps scene boundaries tight). */
async function trimVoiceoverLeadingSilence(audioPath: string): Promise<void> {
  const tmpPath = audioPath.replace(/\.mp3$/i, "_leadtrim.mp3");
  try {
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -i "${audioPath}" -af ` +
        `"silenceremove=start_periods=1:start_duration=0.04:start_threshold=-40dB:detection=peak" ` +
        `-c:a libmp3lame -b:a 192k "${tmpPath}"`
      ),
      30_000,
      "Trim leading silence on scene VO"
    );
    if (fs.existsSync(tmpPath) && fs.statSync(tmpPath).size > 200) {
      fs.unlinkSync(audioPath);
      fs.renameSync(tmpPath, audioPath);
    } else if (fs.existsSync(tmpPath)) {
      fs.unlinkSync(tmpPath);
    }
  } catch {
    try { if (fs.existsSync(tmpPath)) fs.unlinkSync(tmpPath); } catch { /* ignore */ }
  }
}

/** UI voices are ElevenLabs IDs (stored in voices.fishAudioReferenceId). Never remap to Fish. */
const FISH_AUDIO_REFERENCE_ID = "0327fdb5da9e4fd782899a8058c8ae2b";

async function synthesizeFishAudioVoice(
  text: string,
  outputPath: string,
  timeoutMs: number,
  label: string
): Promise<number> {
  if (!FISH_AUDIO_API_KEY) {
    throw pipelineError(PIPELINE_ERROR.VOICEOVER, "Fish Audio API key is not configured");
  }
  if (isFishAudioInCooldown() && googleTtsFallbackEnabled()) {
    console.warn(`[Pipeline] Fish Audio ${label}: in cooldown — skipping straight to Google Cloud TTS`);
    return synthesizeGoogleCloudVoice(text, outputPath, timeoutMs, label);
  }
  const MAX_ATTEMPTS = 3;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      // fetchWithTimeout (not withTimeout) — actually aborts the HTTP request on timeout
      // instead of just racing a timer, so a slow response can't keep running (and get
      // billed) in the background after we've already given up on it.
      const response = await fetchWithTimeout(
        "https://api.fish.audio/v1/tts",
        timeoutMs,
        `Fish Audio ${label} attempt ${attempt}`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${FISH_AUDIO_API_KEY}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            text,
            reference_id: FISH_AUDIO_REFERENCE_ID,
            format: "mp3",
            mp3_bitrate: 192,
            normalize: true,
            latency: "normal",
          }),
        }
      );

      if (response.status === 429) {
        await new Promise((r) => setTimeout(r, 1000 + attempt * 1000));
        continue;
      }

      if (!response.ok) {
        const errText = await response.text();
        throw pipelineError(
          PIPELINE_ERROR.VOICEOVER,
          `Fish Audio HTTP ${response.status}: ${errText.slice(0, 200)}`
        );
      }

      const audioBuffer = Buffer.from(await response.arrayBuffer());
      if (audioBuffer.length < 100) {
        throw pipelineError(PIPELINE_ERROR.VOICEOVER_EMPTY, "Fish Audio returned empty audio");
      }

      fs.writeFileSync(outputPath, audioBuffer);
      const dur = await probeVideoDurationSec(outputPath);
      console.log(`[Pipeline] Fish Audio ${label}: ${dur.toFixed(1)}s`);
      markFishAudioResult(true);
      return dur > 0 ? dur : Math.max(3, Math.round(audioBuffer.length / 40000));
    } catch (err) {
      if (attempt === MAX_ATTEMPTS) {
        markFishAudioResult(false);
        // Fish Audio itself is out of retries — Google Cloud TTS is the last tier in the chain
        // (free 1M chars/month, commercial-use-safe), so try it before giving up entirely.
        if (googleTtsFallbackEnabled()) {
          console.warn(`[Pipeline] Fish Audio ${label}: failed after retries — switching to Google Cloud TTS`);
          return synthesizeGoogleCloudVoice(text, outputPath, timeoutMs, label);
        }
        throw err;
      }
      await new Promise((r) => setTimeout(r, 500));
    }
  }
  markFishAudioResult(false);
  throw pipelineError(PIPELINE_ERROR.VOICEOVER, "Fish Audio TTS failed after retries");
}

async function synthesizeGoogleCloudVoice(
  text: string,
  outputPath: string,
  timeoutMs: number,
  label: string
): Promise<number> {
  if (!GOOGLE_TTS_API_KEY) {
    throw pipelineError(PIPELINE_ERROR.VOICEOVER, "Google Cloud TTS API key is not configured");
  }
  if (isGoogleTtsInCooldown()) {
    // Last tier in the waterfall — no further fallback to skip to, but there's still no reason
    // to burn 3 retries x timeoutMs discovering a known-down provider before the caller falls
    // through to silent audio.
    throw pipelineError(PIPELINE_ERROR.VOICEOVER, "Google Cloud TTS: in cooldown after repeated failures");
  }
  const MAX_ATTEMPTS = 3;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      // X-Goog-Api-Key header (not a ?key= query param) — same reasoning as the Gemini
      // integration: keeps the key out of URLs that could end up in logs.
      const response = await fetchWithTimeout(
        "https://texttospeech.googleapis.com/v1/text:synthesize",
        timeoutMs,
        `Google Cloud TTS ${label} attempt ${attempt}`,
        {
          method: "POST",
          headers: {
            "X-Goog-Api-Key": GOOGLE_TTS_API_KEY,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            input: { text },
            // Neural2: included in the free 1M-chars/month tier and licensed for commercial use.
            voice: { languageCode: "en-US", name: "en-US-Neural2-D" },
            audioConfig: { audioEncoding: "MP3", speakingRate: 1.0 },
          }),
        }
      );

      if (response.status === 429) {
        await new Promise((r) => setTimeout(r, 1000 + attempt * 1000));
        continue;
      }

      if (!response.ok) {
        const errText = await response.text();
        throw pipelineError(
          PIPELINE_ERROR.VOICEOVER,
          `Google Cloud TTS HTTP ${response.status}: ${errText.slice(0, 200)}`
        );
      }

      const { audioContent } = (await response.json()) as { audioContent?: string };
      if (!audioContent) {
        throw pipelineError(PIPELINE_ERROR.VOICEOVER_EMPTY, "Google Cloud TTS returned no audio");
      }
      const audioBuffer = Buffer.from(audioContent, "base64");
      if (audioBuffer.length < 100) {
        throw pipelineError(PIPELINE_ERROR.VOICEOVER_EMPTY, "Google Cloud TTS returned empty audio");
      }

      fs.writeFileSync(outputPath, audioBuffer);
      const dur = await probeVideoDurationSec(outputPath);
      console.log(`[Pipeline] Google Cloud TTS ${label}: ${dur.toFixed(1)}s`);
      markGoogleTtsResult(true);
      return dur > 0 ? dur : Math.max(3, Math.round(audioBuffer.length / 40000));
    } catch (err) {
      if (attempt === MAX_ATTEMPTS) {
        markGoogleTtsResult(false);
        throw err;
      }
      await new Promise((r) => setTimeout(r, 500));
    }
  }
  markGoogleTtsResult(false);
  throw pipelineError(PIPELINE_ERROR.VOICEOVER, "Google Cloud TTS failed after retries");
}

/** After ElevenLabs fails: Fish Audio if configured (which itself falls back to Google Cloud TTS
 *  on its own failure), else straight to Google Cloud TTS if that's the only fallback configured. */
async function synthesizeVoiceoverFallback(
  text: string,
  outputPath: string,
  timeoutMs: number,
  label: string
): Promise<number> {
  if (fishAudioFallbackEnabled()) {
    return synthesizeFishAudioVoice(text, outputPath, timeoutMs, label);
  }
  return synthesizeGoogleCloudVoice(text, outputPath, timeoutMs, label);
}

async function synthesizeElevenLabsVoice(
  text: string,
  outputPath: string,
  elevenVoiceId: string,
  timeoutMs: number,
  label: string,
  voiceSettings?: ElevenLabsVoiceSettings
): Promise<number> {
  if (!ELEVENLABS_API_KEY) {
    throw pipelineError(
      PIPELINE_ERROR.VOICEOVER,
      "ElevenLabs API key is not configured. Add ELEVENLABS_API_KEY in Railway to use your selected voice."
    );
  }
  if (
    (get_elevenLabsQuotaExhausted() || isElevenLabsInCooldown()) &&
    (fishAudioFallbackEnabled() || googleTtsFallbackEnabled())
  ) {
    console.warn(`[Pipeline] ElevenLabs ${label}: quota exhausted or in cooldown — fallback direct`);
    return synthesizeVoiceoverFallback(text, outputPath, timeoutMs, label);
  }
  const MAX_ATTEMPTS = 3;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      // fetchWithTimeout (not withTimeout) — actually aborts the HTTP request via
      // AbortController on timeout, instead of just racing a timer while the request keeps
      // running server-side. Without this, a timed-out request could still complete and be
      // billed by ElevenLabs in the background after the catch block below already switched
      // to Fish Audio for the same segment — double-billing the same narration.
      const response = await fetchWithTimeout(
        `https://api.elevenlabs.io/v1/text-to-speech/${elevenVoiceId}`,
        timeoutMs,
        `${label} attempt ${attempt}`,
        {
          method: "POST",
          headers: {
            "xi-api-key": ELEVENLABS_API_KEY,
            "Content-Type": "application/json",
            Accept: "audio/mpeg",
          },
          body: JSON.stringify({
            text,
            model_id: "eleven_multilingual_v2",
            voice_settings: voiceSettings ?? { stability: 0.58, similarity_boost: 0.88, style: 0.05, use_speaker_boost: true },
          }),
        }
      );
      if (response.status === 429) {
        await new Promise((r) => setTimeout(r, 600 + attempt * 600));
        continue;
      }
      if (!response.ok) {
        const errText = await response.text();
        // Any non-429 failure means ElevenLabs isn't usable right now — quota, auth, payment,
        // server error, whatever the exact status/message is. Switch straight to the next tier
        // (Fish Audio, then Google Cloud TTS) instead of burning retries against a provider
        // that's already known to be down.
        markElevenLabsResult(false);
        if (fishAudioFallbackEnabled() || googleTtsFallbackEnabled()) {
          set_elevenLabsQuotaExhausted(true);
          console.warn(
            `[Pipeline] ElevenLabs ${label}: HTTP ${response.status} — switching to fallback: ${errText.slice(0, 150)}`
          );
          return synthesizeVoiceoverFallback(text, outputPath, timeoutMs, label);
        }
        throw pipelineError(
          PIPELINE_ERROR.VOICEOVER,
          `ElevenLabs voice ${elevenVoiceId.slice(0, 8)}… HTTP ${response.status}: ${errText.slice(0, 200)}`
        );
      }
      const audioBuffer = Buffer.from(await response.arrayBuffer());
      if (audioBuffer.length < 100) {
        throw pipelineError(PIPELINE_ERROR.VOICEOVER_EMPTY, "ElevenLabs returned empty audio");
      }
      fs.writeFileSync(outputPath, audioBuffer);
      const dur = await probeVideoDurationSec(outputPath);
      console.log(`[Pipeline] ElevenLabs ${label}: voice=${elevenVoiceId.slice(0, 10)}… ${dur.toFixed(1)}s`);
      markElevenLabsResult(true);
      return dur > 0 ? dur : Math.max(3, Math.round(audioBuffer.length / 40000));
    } catch (err) {
      // Same reasoning as above: a thrown error (network failure, our own timeout, etc.) means
      // ElevenLabs isn't answering right now — go straight to the next fallback tier rather
      // than retrying.
      const msg = err instanceof Error ? err.message : String(err);
      if (fishAudioFallbackEnabled() || googleTtsFallbackEnabled()) {
        markElevenLabsResult(false);
        set_elevenLabsQuotaExhausted(true);
        console.warn(`[Pipeline] ElevenLabs ${label}: error — switching to fallback: ${msg.slice(0, 150)}`);
        return synthesizeVoiceoverFallback(text, outputPath, timeoutMs, label);
      }
      if (attempt === MAX_ATTEMPTS) {
        markElevenLabsResult(false);
        throw err;
      }
      await new Promise((r) => setTimeout(r, 500));
    }
  }
  markElevenLabsResult(false);
  if (fishAudioFallbackEnabled() || googleTtsFallbackEnabled()) {
    console.warn(`[Pipeline] ElevenLabs ${label}: out of retries (rate-limited) — switching to fallback`);
    return synthesizeVoiceoverFallback(text, outputPath, timeoutMs, label);
  }
  throw pipelineError(PIPELINE_ERROR.VOICEOVER, "ElevenLabs TTS failed after retries");
}

// Per-scene fallback only when bulk path is not used. Default pipeline: full-script ElevenLabs + split.
//
// Provider waterfall: ElevenLabs (if configured) → Fish Audio (if configured) → Google Cloud TTS
// (if configured) → silent audio, ONLY once every configured real provider has been tried and
// failed. Previously the Fish/Google branches below were gated on `!options?.preferElevenLabs`,
// but the sole caller (synthesizeFullNarrationMp3) always passes `preferElevenLabs: true` — so
// whenever ELEVENLABS_API_KEY was unset (or every ElevenLabs attempt failed without an internal
// fallback being reachable), this function fell straight to silent audio even with a healthy
// Fish Audio or Google Cloud TTS key configured. `preferElevenLabs` now only affects ordering
// ("try ElevenLabs first when available"), never whether Fish/Google get tried at all.
export async function generateVoiceover(
  text: string,
  outputPath: string,
  voiceId?: string,
  options?: VoiceoverGenerateOptions
): Promise<VoiceoverResult> {
  const maxChars = options?.maxChars ?? 800;
  const cleanText = sanitizeVoiceoverText(text, maxChars);

  const TTS_TIMEOUT_MS = maxChars > 2000 ? 180_000 : 90_000;

  const selectedElevenVoice = voiceId?.trim();
  // User picked a voice in the dashboard → always that exact ElevenLabs voice (never Fish remap).
  // Intentionally no silent fallback here — an explicit voice selection should fail loudly, not
  // silently substitute a different provider's voice or silence.
  if (selectedElevenVoice) {
    const duration = await synthesizeElevenLabsVoice(
      cleanText,
      outputPath,
      selectedElevenVoice,
      TTS_TIMEOUT_MS,
      "selected voice",
      options?.voiceSettings
    );
    return { duration, usedSilentFallback: false, provider: "elevenlabs" };
  }

  // Product decision to use ElevenLabs exclusively (ELEVENLABS_ONLY=true) — no cross-provider
  // fallback by design; synthesizeElevenLabsVoice's own internal fallback is disabled by
  // fishAudioFallbackEnabled()/googleTtsFallbackEnabled() both returning false in that mode.
  if (elevenLabsOnlyVoice()) {
    const duration = await synthesizeElevenLabsVoice(
      cleanText,
      outputPath,
      "pNInz6obpgDQGcFmaJgB",
      TTS_TIMEOUT_MS,
      "default documentary",
      options?.voiceSettings
    );
    return { duration, usedSilentFallback: false, provider: "elevenlabs" };
  }

  // Try ElevenLabs first when it's configured at all — synthesizeElevenLabsVoice already chains
  // into Fish Audio → Google Cloud TTS internally (via synthesizeVoiceoverFallback) on failure,
  // so this alone covers the full waterfall whenever an ElevenLabs key exists.
  if (ELEVENLABS_API_KEY) {
    try {
      const duration = await synthesizeElevenLabsVoice(
        cleanText,
        outputPath,
        voiceId || "pNInz6obpgDQGcFmaJgB",
        TTS_TIMEOUT_MS,
        "default documentary",
        options?.voiceSettings
      );
      return { duration, usedSilentFallback: false, provider: "elevenlabs" };
    } catch (err) {
      console.warn(
        `[Pipeline] generateVoiceover: ElevenLabs (+ its Fish/Google fallback chain) exhausted: ${(err as Error).message?.slice(0, 200)}`
      );
    }
  } else if (fishAudioFallbackEnabled()) {
    // No ElevenLabs key at all — Fish Audio is the primary provider. synthesizeFishAudioVoice
    // already falls through to Google Cloud TTS internally on its own final-attempt failure.
    try {
      const duration = await synthesizeFishAudioVoice(cleanText, outputPath, TTS_TIMEOUT_MS, "primary");
      return { duration, usedSilentFallback: false, provider: "fish-audio" };
    } catch (err) {
      console.warn(
        `[Pipeline] generateVoiceover: Fish Audio (+ its Google fallback) exhausted: ${(err as Error).message?.slice(0, 200)}`
      );
    }
  } else if (googleTtsFallbackEnabled()) {
    // No ElevenLabs, no Fish Audio — Google Cloud TTS is the only configured real provider.
    try {
      const duration = await synthesizeGoogleCloudVoice(cleanText, outputPath, TTS_TIMEOUT_MS, "primary");
      return { duration, usedSilentFallback: false, provider: "google-tts" };
    } catch (err) {
      console.warn(`[Pipeline] generateVoiceover: Google Cloud TTS exhausted: ${(err as Error).message?.slice(0, 200)}`);
    }
  }

  // Silent fallback — reached ONLY when every configured real TTS provider was tried and failed,
  // or no real provider is configured at all. Logged loudly (console.error, not warn), flagged
  // via usedSilentFallback so callers can never mistake this for real narration, AND recorded on
  // the render's own context so it survives into the persisted quality-report warnings even if
  // nobody is watching server logs at the time — a render must never look like an ordinary
  // "completed" video when part of its narration is actually silent.
  const silentNote = `TTS: silent fallback used for "${path.basename(outputPath)}" — no real audio provider produced narration for this chunk`;
  getRenderCtx().voiceoverSilentFallbackNotes.push(silentNote);
  console.error(
    `[Pipeline] generateVoiceover: ALL configured real TTS providers unavailable or failed for ` +
    `"${outputPath}" — falling back to SILENT audio. This chunk will have NO narration.`
  );
  const estimatedDuration = Math.max(3, Math.ceil(cleanText.split(" ").length / 2.5));
  try {
    await withSceneFetchTimeout(
      () => exec(`${FFMPEG_BIN} -y -f lavfi -i anullsrc=r=44100:cl=stereo -t ${estimatedDuration} -c:a libmp3lame -b:a 64k "${outputPath}"`),
      10_000, "Silent audio fallback"
    );
  } catch {
    fs.writeFileSync(outputPath, Buffer.from([0xff, 0xfb, 0x90, 0x00, ...Array(413).fill(0)]));
  }
  return { duration: estimatedDuration, usedSilentFallback: true, provider: "silent" };
}

/**
 * RONDE 138 — a generated still becomes a clip, in one place.
 *
 * This was the tail of generateStabilityAIClip. Extracted verbatim — same documentary composition,
 * same simple-Ken-Burns fallback, same encode arguments, same size check — so that a second image
 * provider produces a clip that is indistinguishable from a Stability one rather than carrying its
 * own copy of sixty lines of ffmpeg that would drift.
 */
async function renderAiStillToClip(
  pngPath: string,
  outputPath: string,
  duration: number,
  sceneIndex: number
): Promise<string | null> {
  // Ken Burns with blur-fill/polaroid when documentary style is enabled.
    const fps = 25;
    if (documentaryStyleEnabled()) {
      const filterComplex = resolveStillCompositionVF(duration, sceneIndex, 0, false);
      try {
        await withSceneFetchTimeout(
          () => exec(`${FFMPEG_BIN} ${buildStillEncodeArgs(pngPath, outputPath, duration, filterComplex)}`),
          90_000,
          `AI image to video scene ${sceneIndex}`
        );
      } catch (docErr) {
        console.warn(`[Pipeline] Scene ${sceneIndex}: AI documentary still failed, using simple Ken Burns:`, (docErr as Error).message);
        const fallbackFc = buildSimpleKenBurnsVF(duration, false);
        await withSceneFetchTimeout(
          () => exec(`${FFMPEG_BIN} ${buildStillEncodeArgs(pngPath, outputPath, duration, fallbackFc)}`),
          90_000,
          `AI image to video scene ${sceneIndex} (fallback)`
        );
      }
    } else {
      const totalFrames = Math.ceil(duration * fps);
      const zoomStep = 0.0003; // slow 7% zoom over full duration
      const direction = sceneIndex % 2 === 0 ? 1 : -1;
      const panX = direction > 0 ? `iw/2-(iw/zoom/2)` : `iw/2-(iw/zoom/2)+2`;
      await withSceneFetchTimeout(
        () => exec(
          `${FFMPEG_BIN} -y -loop 1 -i "${pngPath}" ` +
          `-vf "scale=${VIDEO_WIDTH}:${VIDEO_HEIGHT}:force_original_aspect_ratio=increase,crop=${VIDEO_WIDTH}:${VIDEO_HEIGHT},` +
          `zoompan=z='min(zoom+${zoomStep},1.07)':x='${panX}':y='ih/2-(ih/zoom/2)':d=${totalFrames}:s=${VIDEO_WIDTH}x${VIDEO_HEIGHT}:fps=${fps}" ` +
          `-t ${duration} -r ${fps} -c:v libx264 ${pipelineFfmpegThreadFlag()} -preset fast -crf 18 -pix_fmt yuv420p "${outputPath}"`
        ),
        90_000,
        `AI image to video scene ${sceneIndex}`
      );
    }

  try { fs.unlinkSync(pngPath); } catch { /* ignore */ }

  if (fs.existsSync(outputPath) && fs.statSync(outputPath).size > 1000) {
    return outputPath;
  }
  return null;
}

/**
 * RONDE 138 — the image provider you already pay for.
 *
 * ── Why this exists ──────────────────────────────────────────────────────────────────────────
 *
 * The fallback ladder's promise is written a few hundred lines below: "AI clip when stock/YouTube
 * miss — never grey". Video 558 shipped seven colour cards anyway, because that promise needs an
 * image API and production had none: no STABILITY_AI_API_KEY, no LEONARDO_API_KEY, Kling absent
 * (adopt audit: kling=0), and generateImage() in _core wants a BUILT_IN_FORGE_API_URL that is not
 * set — the storage backend is s3.
 *
 * OpenAI, meanwhile, was configured and in use all along, as the LLM ("provider=openai, Using
 * OpenAI (gpt-4o)"). The same key can generate images. So this adds no new dependency and no new
 * account: it lets the ladder keep its promise with what the deployment already has.
 *
 * ── What it is not ───────────────────────────────────────────────────────────────────────────
 *
 * Not a new engine. It is a third entry in the existing cheap image tier, next to Stability Core
 * and Leonardo, with the same signature, the same prompt, and — via renderAiStillToClip — the same
 * still-to-clip encode. A clip from here is indistinguishable downstream from a Stability one, and
 * every gate that judges it is unchanged.
 *
 * ── Cost, deliberately visible ───────────────────────────────────────────────────────────────
 *
 * gpt-image-1 at "low" quality is roughly $0.01–0.02 per 1024x1024 image, which is the same order
 * as Stability Core's ~$0.03 and cheaper than the premium video tier's ~$0.25. The quality knob is
 * an env var rather than a constant because it is a money decision, not an engineering one.
 */
function openAiImageModel(): string {
  return process.env.OPENAI_IMAGE_MODEL?.trim() || "gpt-image-1";
}

/** low | medium | high. Defaults to low — this is a fallback picture, not a hero shot. */
function openAiImageQuality(): string {
  const raw = process.env.OPENAI_IMAGE_QUALITY?.trim().toLowerCase();
  return raw === "medium" || raw === "high" ? raw : "low";
}

/**
 * Whether OpenAI images may be used at all.
 *
 * Off unless explicitly switched on, because it spends money per beat on an account that was
 * configured for text. An operator turning this on is making a billing decision and should have
 * done so on purpose.
 */
export function openAiImageFallbackEnabled(): boolean {
  if (process.env.ENABLE_OPENAI_IMAGE_FALLBACK !== "true") return false;
  return Boolean(openAiKeyFromEnv());
}

export async function generateOpenAiImageClip(
  prompt: string,
  duration: number,
  outputPath: string,
  sceneIndex: number
): Promise<string | null> {
  const key = openAiKeyFromEnv();
  if (!key) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: no OpenAI key, skipping AI image`);
    return null;
  }
  try {
    const t = Date.now();
    console.log(
      `[Pipeline] Scene ${sceneIndex}: OpenAI ${openAiImageModel()} (${openAiImageQuality()}, ~$0.01–0.04/img)...`
    );
    const resp = await withSceneFetchTimeout(
      () =>
        fetchWithTimeout("https://api.openai.com/v1/images/generations", 60_000, `OpenAI image scene ${sceneIndex}`, {
          method: "POST",
          headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
          body: JSON.stringify({
            model: openAiImageModel(),
            prompt,
            n: 1,
            size: "1536x1024", // landscape, closest to 16:9 of the supported sizes
            quality: openAiImageQuality(),
          }),
        }),
      70_000,
      `OpenAI image scene ${sceneIndex}`
    );
    if (!resp.ok) {
      // The status is what distinguishes a billing problem from a content refusal from an outage,
      // and it is the only thing an operator can act on.
      console.warn(
        `[Pipeline] Scene ${sceneIndex}: OpenAI image HTTP ${resp.status} — no image generated`
      );
      return null;
    }
    const json = (await resp.json()) as { data?: Array<{ b64_json?: string; url?: string }> };
    const first = json.data?.[0];
    let imgBuffer: Buffer | null = null;
    if (first?.b64_json) {
      imgBuffer = Buffer.from(first.b64_json, "base64");
    } else if (first?.url) {
      // dall-e-3 answers with a URL rather than bytes; both shapes are accepted.
      const imgResp = await fetchWithTimeout(first.url, 30_000, `OpenAI image download scene ${sceneIndex}`);
      if (imgResp.ok) imgBuffer = Buffer.from(await imgResp.arrayBuffer());
    }
    if (!imgBuffer || imgBuffer.length < 1000) {
      console.warn(`[Pipeline] Scene ${sceneIndex}: OpenAI returned no usable image`);
      return null;
    }
    const pngPath = outputPath.replace(".mp4", "_ai.png");
    fs.writeFileSync(pngPath, imgBuffer);
    console.log(
      `[Pipeline] Scene ${sceneIndex}: OpenAI image in ${((Date.now() - t) / 1000).toFixed(1)}s ` +
        `(${(imgBuffer.length / 1024).toFixed(0)}KB)`
    );
    // The same encode Stability's stills go through — see renderAiStillToClip.
    return await renderAiStillToClip(pngPath, outputPath, duration, sceneIndex);
  } catch (err) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: OpenAI image clip failed:`, (err as Error).message?.slice(0, 120));
    return null;
  }
}

// ─── 3a. Stability AI Image → Video Loop (PRIMARY visual) ────────────────────
export async function generateStabilityAIClip(
  prompt: string,
  duration: number,
  outputPath: string,
  sceneIndex: number
): Promise<string | null> {
  if (!stabilityAiEnabled()) {
    return null;
  }
  if (!stabilityAiApiKey()) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: No Stability AI key, skipping AI image`);
    return null;
  }

  try {
    const useUltra = process.env.STABILITY_AI_TIER === "ultra";
    const endpoint = useUltra
      ? "https://api.stability.ai/v2beta/stable-image/generate/ultra"
      : "https://api.stability.ai/v2beta/stable-image/generate/core";
    console.log(
      `[Pipeline] Scene ${sceneIndex}: Stability ${useUltra ? "Ultra" : "Core"} (~$0.03–0.08/img)...`
    );
    const t = Date.now();

    const negative =
      "blurry, low quality, watermark, text, logo, ugly, deformed, cartoon, anime, illustration";
    const form = new FormData();
    form.append("prompt", prompt.slice(0, 1000));
    form.append("aspect_ratio", "16:9");
    form.append("output_format", "png");
    form.append("negative_prompt", negative);
    form.append("style_preset", "photographic");

    let imgBuffer: Buffer | null = null;
    const coreResp = await fetchWithTimeout(
      endpoint,
      45_000,
      `Stability Core scene ${sceneIndex}`,
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${stabilityAiApiKey()}`,
          Accept: "image/*",
        },
        body: form,
      }
    );

    if (coreResp.ok) {
      const raw = Buffer.from(await coreResp.arrayBuffer());
      if (raw.length > 50_000) imgBuffer = raw;
    } else {
      const errText = await coreResp.text();
      console.warn(
        `[Pipeline] Scene ${sceneIndex}: Stability v2beta ${coreResp.status}: ${errText.slice(0, 180)} — legacy SDXL`
      );
      const stabilityPayload = {
        text_prompts: [
          { text: prompt, weight: 1 },
          { text: negative, weight: -1 },
        ],
        cfg_scale: 7,
        height: 768,
        width: 1344,
        samples: 1,
        steps: 35,
      };
      const legacyResp = await fetchWithTimeout(
        "https://api.stability.ai/v1/generation/stable-diffusion-xl-1024-v1-0/text-to-image",
        45_000,
        `Stability SDXL scene ${sceneIndex}`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${stabilityAiApiKey()}`,
            Accept: "application/json",
            "Content-Type": "application/json",
          },
          body: JSON.stringify(stabilityPayload),
        }
      );
      if (legacyResp.ok) {
        const result = await legacyResp.json() as {
          artifacts?: Array<{ base64: string; finishReason: string }>;
        };
        const artifact = result.artifacts?.[0];
        if (artifact?.base64) imgBuffer = Buffer.from(artifact.base64, "base64");
      }
    }

    if (!imgBuffer) {
      console.warn(`[Pipeline] Scene ${sceneIndex}: Stability AI returned no image`);
      return null;
    }
    const pngPath = outputPath.replace(".mp4", "_ai.png");
    fs.writeFileSync(pngPath, imgBuffer);
    console.log(`[Pipeline] Scene ${sceneIndex}: Stability AI image in ${((Date.now()-t)/1000).toFixed(1)}s (${(imgBuffer.length/1024).toFixed(0)}KB)`);

    // RONDE 138: the still-to-clip step moved to renderAiStillToClip so a second image provider
    // reuses this exact ffmpeg chain instead of carrying a copy of it.
    return await renderAiStillToClip(pngPath, outputPath, duration, sceneIndex);
  } catch (err) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: Stability AI clip failed:`, err);

    return null;
  }
}

// ─── 3b. Pexels Stock Clips (SECONDARY — multiple per scene) ─────────────────
export async function fetchPexelsClips(
  query: string,
  clipDuration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 3,
  extraQueries?: string[],
  strictQueries = false,
  fileTag = "pexels",
  excludeVideoIds?: Set<number>,
  candidateOffset = 0,
  downloadRetries = 3,
  stockBeatCtx?: StockBeatCtx,
  sourcingCache?: SourcingCache
): Promise<string[]> {
  if (!PEXELS_API_KEY) return [];
  if (isPexelsInCooldown()) return [];

  const results: string[] = [];

  // Never fall back to generic nature/city b-roll — that produces irrelevant footage (wind turbines, cyclists, etc.)
  //
  // `strictQueries` is now honoured. It was declared and never read, while nine call sites pass
  // `true` — so a caller asking for a narrow, exact search silently got the broadened one. Two
  // things broaden a query here, and strict mode skips both:
  //   1. extraQueries are appended, searching for things the caller did not ask for;
  //   2. simplifyStockSearchWord collapses a whole phrase down to ONE token (and falls back to
  //      the literal word "documentary" when nothing survives) — "hitler bunker berlin 1945"
  //      becomes a single generic word.
  // With strictQueries=false nothing changes: same inputs, same filter, same simplification.
  const rawQueries = strictQueries ? [query] : [query, ...(extraQueries ?? [])];
  const queryList = Array.from(
    new Set(
      filterQueryStrings(rawQueries, 3, (q) => !isBlockedStockQuery(q)).map((q) =>
        strictQueries ? q : simplifyStockSearchWord(q, q, true)
      )
    )
  );
  if (queryList.length === 0) return [];
  // Deduplicate
  const seen = new Set<string>();
  const uniqueQueries = queryList.filter(q => { if (seen.has(q)) return false; seen.add(q); return true; });

  for (const currentQuery of uniqueQueries) {
    if (results.length >= count) break; // Stop if we have enough clips

    let queryEmbForStock = stockBeatCtx?.queryEmbedding ?? null;
    if (stockClipEmbeddingEnabled() && !queryEmbForStock?.length) {
      const beatText = stockBeatCtx?.beatText?.trim() || currentQuery;
      queryEmbForStock = await resolveBeatVisionQueryEmbedding({ beatText });
    }

    try {
      type PexelsSearchData = {
        videos?: Array<{
          id: number;
          duration: number;
          url?: string;
          video_files: Array<{ width: number; height: number; link: string }>;
        }>;
      };
      // Render-scoped query cache: the exact same provider + normalized query is searched at
      // most once per render — same cachedProviderSearch helper the other 10 providers use, so
      // Pexels/Pixabay follow the identical, already-tested pattern rather than a new one.
      const searchData = await cachedProviderSearch(
        sourcingCache,
        "pexels",
        currentQuery,
        async (): Promise<PexelsSearchData | null> => {
          // HD quality: large size (min 1280px), landscape orientation, fetch 15 candidates
          const searchUrl = `https://api.pexels.com/videos/search?query=${encodeURIComponent(currentQuery)}&per_page=15&size=large&orientation=landscape`;
          // withTimeout only races a timer and never aborts the request — a timed-out Pexels
          // call keeps running in the background and still counts against the metered quota.
          const searchResp = await providerLimiter("pexels").run(() => fetchWithTimeout(
            searchUrl,
            10_000,
            `Pexels search scene ${sceneIndex} query "${currentQuery}"`,
            { headers: { Authorization: PEXELS_API_KEY } }
          ));
          if (!searchResp.ok) {
            markPexelsSearchResult(false);
            console.warn(`[Pipeline] Pexels search HTTP ${searchResp.status} for "${currentQuery}"`);
            return null;
          }
          markPexelsSearchResult(true);
          return await searchResp.json() as PexelsSearchData;
        },
        "fetchPexelsClips"
      );
      if (!searchData) continue;
      // Phase 20 metrics fix: real search-result count, independent of cache-hit/download/accept.
      providerMetrics(sourcingCache, "pexels").resultCount += searchData.videos?.length ?? 0;

    if (!searchData.videos?.length) continue;

    // Filter: min 3s duration, skip already-used Pexels IDs, sort by resolution descending
    const filtered = searchData.videos
      .filter(v => v.duration >= 3 && !excludeVideoIds?.has(v.id) && !isRejectedPexelsVideo(v))
      .sort((a, b) => {
        const aMax = Math.max(...a.video_files.map(f => f.width));
        const bMax = Math.max(...b.video_files.map(f => f.width));
        return bMax - aMax;
      });
    const rankedFiltered = rankStockVideoIdsByEmbedding(filtered, "pexels", queryEmbForStock);
    const offset = rankedFiltered.length > 0 ? candidateOffset % rankedFiltered.length : 0;
    const candidates = [...rankedFiltered.slice(offset), ...rankedFiltered.slice(0, offset)].slice(0, count * 3);

    const needed = count - results.length;
    // Download up to `needed` clips in parallel
    const downloadLimit = pLimit(needed);
    const downloadResults = await Promise.allSettled(
      candidates.slice(0, needed).map((video, idx) => downloadLimit(async () => {
        // Prefer 720p (1280px wide) — cap at 1280 to avoid large file download timeouts
        // 4K files (3840px+) and 1080p (1920px) are too large and cause FetchError: aborted
        const videoFile = video.video_files
          .filter(f => f.width >= 1280 && f.width <= 1280)  // exact 720p/1280p
          .sort((a, b) => b.width - a.width)[0]
          || video.video_files
          .filter(f => f.width >= 960 && f.width <= 1280)   // 960-1280px range
          .sort((a, b) => b.width - a.width)[0]
          || video.video_files
          .filter(f => f.width >= 640 && f.width <= 1920)   // any HD
          .sort((a, b) => b.width - a.width)[0]
          || video.video_files
          .filter(f => f.width <= 1920)
          .sort((a, b) => b.width - a.width)[0]
          || video.video_files.sort((a, b) => a.width - b.width)[0]; // fallback: smallest available

        if (!videoFile?.link) return null;

        const rawPath = path.join(workDir, `scene_${sceneIndex}_${fileTag}_vid${video.id}_raw.mp4`);
        /**
         * RONDE 96 — this provider's assets enter the ledger like every other provider's.
         *
         * These five fetchers wrote their file straight to workDir and handed the path on, so the
         * clip only ever reached the ledger later, through clipAdoptAudit's "adoption of a clip
         * the ledger has never seen" branch — which deliberately records NO provider, because
         * guessing one from a filename is exactly what RONDE 86 removed. The result was honest and
         * useless: every Pexels, Unsplash, SerpAPI, Openverse and YouTube-thumbnail asset counted
         * as UNVERIFIED however normally it had arrived.
         *
         * tagPathWithProviderAsset is the same entry point the other eleven providers use, called
         * at the same moment: provider name, the provider's own id and the destination path all in
         * hand, straight from the API response. It opens the record and files DOWNLOAD_STARTED.
         */
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_${fileTag}_vid${video.id}.mp4`),
          "pexels",
          String(video.id),
          sourcingCache,
          {
            sceneIndex,
            // StockBeatCtx carries the beat's TEXT, not its index; the record's beatText is
            // where that belongs, and beatIndex stays unset rather than guessed.
            beatText: stockBeatCtx?.beatText,
            sourceUrl: videoFile.link,
            mediaType: "video",
            query: currentQuery,
            searchRoute: "fetchPexelsClips",
          }
        );

        // Check media cache before downloading from Pexels CDN
        const fromMediaCache = await tryRestoreFromMediaCache(videoFile.link, rawPath);

        if (!fromMediaCache) {
          // F3-05: streams straight to rawPath instead of buffering the whole clip in memory
          // first — same retry/size-validation/cleanup behavior as before, just without the
          // intermediate Buffer.
          let downloaded = false;
          let retries = downloadRetries;

          while (retries > 0 && !downloaded) {
            try {
              // P0 audit fix: maxBytes matches the existing 80MB ceiling already used by 7 of
              // the other 10 external video providers in this file (Wikimedia/Flickr/Europeana/
              // Vimeo/NASA/NARA/YouTube CC) — same established value, not a newly invented one.
              const { response: downloadResp, bytesWritten } = await downloadToFileStreaming(
                videoFile.link,
                rawPath,
                45_000,
                `Download Pexels clip ${idx} scene ${sceneIndex} (attempt ${4 - retries}/3)`,
                {},
                80 * 1024 * 1024
              );
              if (!downloadResp.ok || bytesWritten === null) {
                retries--;
                if (retries > 0) await new Promise(r => setTimeout(r, 1000));
                continue;
              }

              // Validate size (minimum 50KB for valid video)
              if (bytesWritten < 50_000) {
                console.warn(`[Pipeline] Pexels clip ${idx} too small (${bytesWritten} bytes), retrying...`);
                try { fs.unlinkSync(rawPath); } catch { /* ignore */ }
                retries--;
                if (retries > 0) await new Promise(r => setTimeout(r, 1000));
                continue;
              }

              downloaded = true; // Success
              providerMetrics(sourcingCache, "pexels").downloadCount++;
            } catch (err) {
              console.warn(`[Pipeline] Download attempt failed for Pexels clip ${idx}:`, err);
              try { fs.unlinkSync(rawPath); } catch { /* ignore */ }
              retries--;
              if (retries > 0) await new Promise(r => setTimeout(r, 1000));
            }
          }

          if (!downloaded) {
            console.warn(`[Pipeline] Failed to download Pexels clip ${idx} after 3 attempts`);
            return null;
          }

          // Store in cache for future videos (best-effort, never blocks pipeline)
          void reportToMediaCache(videoFile.link, rawPath, "video/mp4");
        }

        const stockKey = `pexels:${video.id}`;
        if (stockClipEmbeddingEnabled()) {
          scheduleStockClipEmbeddingByKey(stockKey, rawPath);
        }

        // Validate downloaded file with ffprobe before processing
        // Use system ffprobe which supports -show_entries (ffmpeg-static does not have drawtext/libfreetype)
        try {
          const probeCmd = `"${FFPROBE_BIN}" -v error -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 "${rawPath}"`;
          const probeResult = await withSceneFetchTimeout(
            () => exec(probeCmd),
            10_000,
            `Probe Pexels clip ${idx}`
          );
          const probeDuration = typeof probeResult === 'string' ? probeResult : (probeResult as any).stdout || '';
          const duration = parseFloat(probeDuration);
          if (isNaN(duration) || duration < 1) {
            console.warn(`[Pipeline] Pexels clip ${idx} has invalid duration: ${duration}`);
            try { fs.unlinkSync(rawPath); } catch { /* ignore */ }
            return null;
          }
          // Second check: verify video stream is readable (catches 'moov atom not found' and other corrupt MP4 errors)
          const streamCheckCmd = `"${FFPROBE_BIN}" -v error -select_streams v:0 -show_entries stream=codec_type -of default=noprint_wrappers=1:nokey=1 "${rawPath}"`;
          const streamResult = await withSceneFetchTimeout(
            () => exec(streamCheckCmd),
            10_000,
            `Stream check Pexels clip ${idx}`
          );
          const streamOutput = typeof streamResult === 'string' ? streamResult : (streamResult as any).stdout || '';
          if (!streamOutput.includes('video')) {
            console.warn(`[Pipeline] Pexels clip ${idx} has no readable video stream (corrupt/incomplete MP4), skipping`);
            try { fs.unlinkSync(rawPath); } catch { /* ignore */ }
            return null;
          }
        } catch (err) {
          console.warn(`[Pipeline] Failed to validate Pexels clip ${idx}:`, err);
          try { fs.unlinkSync(rawPath); } catch { /* ignore */ }
          return null;
        }

        const startSec = ((sceneIndex + idx) * 0.37) % 1.2;
        const trimmed = await trimDownloadedStockClip(
          rawPath,
          outPath,
          clipDuration,
          video.duration,
          `Trim Pexels clip ${idx} scene ${sceneIndex}`,
          startSec,
          { stockKey, queryEmbedding: queryEmbForStock, clipIndex: idx }
        );

        try { fs.unlinkSync(rawPath); } catch { /* ignore */ }

        if (trimmed) {
          excludeVideoIds?.add(video.id);
          scheduleStockClipEmbedding(outPath);
          // RONDE 96: see above — the trimmed file is on disk, so the download succeeded.
          recordProviderDownloadOutcome(sourcingCache, outPath, true);
          return outPath;
        }
        return null;
      }))
    );

    for (const r of downloadResults) {
      if (r.status === "fulfilled" && r.value) results.push(r.value);
    }
    } catch (err) {
      // RONDE 68: a cancellation FastVid caused is not a provider fault — see isScopeAbortError.
      if (!isScopeAbortError(err)) markPexelsSearchResult(false);
      console.warn(`[Pipeline] Pexels search failed for query "${currentQuery}" scene ${sceneIndex}:`, err);
    }
  }

  return results;
}

// ─── 3b2. Fetch B-roll Clips from Pexels (cutaway footage for visual variety) ─────────────
// Fetches 1-2 B-roll clips using scene.brollQueries (LLM-generated cutaway queries).
// These are inserted between main clips to add visual variety (Vidrush style).
async function fetchBrollClips(
  brollQueries: string[],
  clipDuration: number,
  workDir: string,
  sceneIndex: number,
  excludeVideoIds?: Set<number>,
  /** RONDE 96: b-roll is Pexels too, and its clips belong in the same ledger as every other. */
  sourcingCache?: SourcingCache
): Promise<string[]> {
  if ((!PEXELS_API_KEY && !PIXABAY_API_KEY) || !brollQueries || brollQueries.length === 0) return [];
  const results: string[] = [];
  for (let qi = 0; qi < brollQueries.length && results.length < 3; qi++) {
    const query = simplifyStockSearchWord(brollQueries[qi] ?? "", brollQueries[qi] ?? "", true);
    if (!query || query.length < 3 || isBlockedStockQuery(query)) continue;
    let queryEmbForStock: number[] | null = null;
    if (stockClipEmbeddingEnabled()) {
      queryEmbForStock = await resolveBeatVisionQueryEmbedding({ beatText: query });
    }
    // RONDE 89: the provider gate, per query in the loop. A refused query is skipped, never
    // repaired or replaced.
    if (admitProviderQuery("pexels", query, "fetchBrollClips") === null) continue;
    try {
      const searchUrl = `https://api.pexels.com/videos/search?query=${encodeURIComponent(query)}&per_page=5&size=large&orientation=landscape`;
      const searchResp = await fetchWithTimeout(
        searchUrl,
        10_000,
        `B-roll Pexels search scene ${sceneIndex} query "${query}"`,
        { headers: { Authorization: PEXELS_API_KEY } }
      );
      if (!searchResp.ok) {
        if (PIXABAY_API_KEY) {
          const pixPaths = await fetchPixabayClips(
            query, clipDuration, workDir, sceneIndex, 1, `scene_${sceneIndex}_broll_pix`, true, undefined, qi
          );
          if (pixPaths[0]) {
            results.push(pixPaths[0]);
            console.log(`[Pipeline] Scene ${sceneIndex}: B-roll Pixabay: "${query}"`);
            continue;
          }
        }
        continue;
      }
      const searchData = await searchResp.json() as {
        videos?: Array<{ id: number; duration: number; video_files: Array<{ width: number; height: number; link: string }> }>;
      };
      if (!searchData.videos?.length) {
        if (PIXABAY_API_KEY) {
          const pixPaths = await fetchPixabayClips(
            query, clipDuration, workDir, sceneIndex, 1, `scene_${sceneIndex}_broll_pix`, true, undefined, qi
          );
          if (pixPaths[0]) {
            results.push(pixPaths[0]);
            console.log(`[Pipeline] Scene ${sceneIndex}: B-roll Pixabay: "${query}"`);
            continue;
          }
        }
        continue;
      }
      const candidates = searchData.videos
        .filter(v => v.duration >= 3 && !excludeVideoIds?.has(v.id))
        .slice(0, 3);
      for (const video of candidates) {
        if (results.length >= 3) break;
        const videoFile = video.video_files
          .filter(f => f.width >= 1280 && f.width <= 1920)
          .sort((a, b) => b.width - a.width)[0]
          || video.video_files.filter(f => f.width <= 1920).sort((a, b) => b.width - a.width)[0];
        if (!videoFile?.link) continue;
        const rawPath = path.join(workDir, `scene_${sceneIndex}_broll_vid${video.id}_raw.mp4`);
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_broll_vid${video.id}.mp4`),
          "pexels",
          String(video.id),
          sourcingCache,
          {
            sceneIndex,
            sourceUrl: videoFile.link,
            mediaType: "video",
            query,
            searchRoute: "fetchBrollClips",
          }
        );
        try {
          // F3-05: streams straight to rawPath instead of buffering the whole clip in memory.
          const { response: dlResp, bytesWritten } = await downloadToFileStreaming(
            videoFile.link, rawPath, 8_000, `B-roll download scene ${sceneIndex}`
          );
          if (!dlResp.ok || bytesWritten === null) continue;
          if (bytesWritten < 50_000) {
            try { fs.unlinkSync(rawPath); } catch { /* ignore */ }
            continue;
          }
          const stockKey = `pexels:${video.id}`;
          if (stockClipEmbeddingEnabled()) {
            scheduleStockClipEmbeddingByKey(stockKey, rawPath);
          }
          const startSec = (sceneIndex + qi) * 0.29 % 1.0;
          const trimmed = await trimDownloadedStockClip(
            rawPath,
            outPath,
            clipDuration,
            video.duration,
            `B-roll trim scene ${sceneIndex}`,
            startSec,
            { stockKey, queryEmbedding: queryEmbForStock, clipIndex: qi }
          );
          try { fs.unlinkSync(rawPath); } catch { /* ignore */ }
          if (trimmed) {
            excludeVideoIds?.add(video.id);
            results.push(outPath);
            scheduleStockClipEmbedding(outPath);
            console.log(`[Pipeline] Scene ${sceneIndex}: B-roll clip added: "${query}"`);
          }
        } catch (err) {
          console.warn(`[Pipeline] B-roll clip failed for scene ${sceneIndex} query "${query}":`, (err as Error).message);
          try { fs.unlinkSync(rawPath); } catch { /* ignore */ }
        }
        break; // one clip per query
      }
    } catch (err) {
      console.warn(`[Pipeline] B-roll search failed for scene ${sceneIndex} query "${query}":`, (err as Error).message);
    }
  }
  return results;
}


// ─── 3b3. Fetch Clips from Pixabay (B-roll + main visual source) ─────────────────────────────
// Pixabay Video API: free, no attribution required for commercial use.
// Returns up to `count` trimmed HD clips matching the query.
export async function fetchPixabayClips(
  query: string,
  clipDuration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 2,
  suffix: string = "pixabay",
  strictQueries = false,
  excludeVideoIds?: Set<number>,
  candidateOffset = 0,
  stockBeatCtx?: StockBeatCtx,
  sourcingCache?: SourcingCache
): Promise<string[]> {
  if (!PIXABAY_API_KEY) return [];
  if (isPixabayInCooldown()) return [];
  const results: string[] = [];

  // `strictQueries` is now honoured — see the note in fetchPexelsClips. This function never
  // took extraQueries, so the only broadening here is simplifyStockSearchWord collapsing the
  // phrase to a single token; strict mode keeps the caller's query as given. Unchanged when false.
  const queryList = Array.from(
    new Set(
      filterQueryStrings([query], 3, (q) => !isBlockedStockQuery(q)).map((q) =>
        strictQueries ? q : simplifyStockSearchWord(q, q, true)
      )
    )
  );
  if (queryList.length === 0) return [];
  const seen = new Set<string>();
  const uniqueQueries = queryList.filter(q => { if (seen.has(q)) return false; seen.add(q); return true; });

  for (const currentQuery of uniqueQueries) {
    if (results.length >= count) break;

    let queryEmbForStock = stockBeatCtx?.queryEmbedding ?? null;
    if (stockClipEmbeddingEnabled() && !queryEmbForStock?.length) {
      const beatText = stockBeatCtx?.beatText?.trim() || currentQuery;
      queryEmbForStock = await resolveBeatVisionQueryEmbedding({ beatText });
    }

    try {
      type PixabaySearchData = {
        totalHits?: number;
        hits?: Array<{
          id: number;
          duration: number;
          tags?: string;
          videos: {
            large?: { url: string; width: number; height: number; size: number };
            medium?: { url: string; width: number; height: number; size: number };
            small?: { url: string; width: number; height: number; size: number };
          };
        }>;
      };
      // Render-scoped query cache — same cachedProviderSearch helper the other 10 providers
      // (and now Pexels) use; "pixabay" as the provider key keeps it isolated from "pexels"
      // even for an identical query string.
      const searchData = await cachedProviderSearch(
        sourcingCache,
        "pixabay",
        currentQuery,
        async (): Promise<PixabaySearchData | null> => {
          // Pixabay Video API: https://pixabay.com/api/docs/#api_videos
          // video_type=film gives real footage (not animation); min_width=1280 for HD
          const searchUrl =
            `https://pixabay.com/api/videos/?key=${PIXABAY_API_KEY}` +
            `&q=${encodeURIComponent(currentQuery)}` +
            `&per_page=10&video_type=film&min_width=1280&safesearch=true`;
          // withTimeout only races a timer and never aborts the request — a timed-out Pixabay
          // call keeps running in the background and still counts against the metered quota.
          const searchResp = await providerLimiter("pixabay").run(() => fetchWithTimeout(
            searchUrl,
            10_000,
            `Pixabay search scene ${sceneIndex} query "${currentQuery}"`
          ));
          if (!searchResp.ok) {
            markPixabaySearchResult(false);
            console.warn(`[Pipeline] Pixabay search HTTP ${searchResp.status} for "${currentQuery}"`);
            return null;
          }
          markPixabaySearchResult(true);
          return await searchResp.json() as PixabaySearchData;
        },
        "fetchPixabayClips"
      );
      if (!searchData) continue;
      // Phase 20 metrics fix: real search-result count, independent of cache-hit/download/accept.
      providerMetrics(sourcingCache, "pixabay").resultCount += searchData.hits?.length ?? 0;

      if (!searchData.hits?.length) continue;

      // Filter: min 3s duration, skip used IDs, sort by resolution descending
      const filtered = searchData.hits
        .filter(v => v.duration >= 3 && !excludeVideoIds?.has(v.id) && !hasBlockedStockTags(v.tags))
        .sort((a, b) => {
          const aW = a.videos.large?.width ?? a.videos.medium?.width ?? 0;
          const bW = b.videos.large?.width ?? b.videos.medium?.width ?? 0;
          return bW - aW;
        });
      const rankedFiltered = rankStockVideoIdsByEmbedding(filtered, "pixabay", queryEmbForStock);
      const offset = rankedFiltered.length > 0 ? candidateOffset % rankedFiltered.length : 0;
      const candidates = [...rankedFiltered.slice(offset), ...rankedFiltered.slice(0, offset)].slice(0, count * 2);

      for (let idx = 0; idx < candidates.length && results.length < count; idx++) {
        const video = candidates[idx];
        // Prefer large (1080p) → medium (720p) → small
        const videoFile =
          video.videos.large?.url ? video.videos.large :
          video.videos.medium?.url ? video.videos.medium :
          video.videos.small?.url ? video.videos.small : null;

        if (!videoFile?.url) continue;

        const rawPath = path.join(workDir, `scene_${sceneIndex}_${suffix}_vid${video.id}_raw.mp4`);
        // RONDE 96: Pixabay was not on the round's list of five, but the re-scan found it writing
        // outside the ledger just as they were — same gap, same fix, same entry point.
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_${suffix}_vid${video.id}.mp4`),
          "pixabay",
          String(video.id),
          sourcingCache,
          {
            sceneIndex,
            beatText: stockBeatCtx?.beatText,
            sourceUrl: videoFile.url,
            mediaType: "video",
            query: currentQuery,
            searchRoute: "fetchPixabayClips",
          }
        );

        try {
          // F3-05: streams straight to rawPath instead of buffering the whole clip in memory.
          let downloaded = false;
          for (let attempt = 0; attempt < 3 && !downloaded; attempt++) {
            try {
              // P0 audit fix: maxBytes matches the existing 80MB ceiling already used by 7 of
              // the other 10 external video providers in this file — same established value.
              const { response: dlResp, bytesWritten } = await downloadToFileStreaming(
                videoFile.url,
                rawPath,
                20_000,
                `Pixabay download scene ${sceneIndex} clip ${idx} attempt ${attempt + 1}`,
                {},
                80 * 1024 * 1024
              );
              if (!dlResp.ok || bytesWritten === null) { await new Promise(r => setTimeout(r, 1000)); continue; }
              if (bytesWritten < 200_000) {
                try { fs.unlinkSync(rawPath); } catch { /* ignore */ }
                await new Promise(r => setTimeout(r, 1000));
                continue;
              }
              downloaded = true;
              providerMetrics(sourcingCache, "pixabay").downloadCount++;
            } catch (dlErr) {
              console.warn(`[Pipeline] Pixabay download attempt ${attempt + 1} failed:`, dlErr);
              try { fs.unlinkSync(rawPath); } catch { /* ignore */ }
              await new Promise(r => setTimeout(r, 1000));
            }
          }
          if (!downloaded) continue;

          const stockKey = `pixabay:${video.id}`;
          if (stockClipEmbeddingEnabled()) {
            scheduleStockClipEmbeddingByKey(stockKey, rawPath);
          }
          // Fase 4: real Pixabay-authored tags, independent of our search query. Pixabay/Pexels
          // stock clips are keyed by clipContentKey as `stock:vid:${id}` (not the hashed
          // providerAssetKey scheme), so this stores directly under that same literal key rather
          // than through putCachedProviderAsset — adoptClip's providerText lookup reads
          // dedup.sourcingCache.assets by exactly that key either way.
          if (sourcingCache && video.tags) {
            sourcingCache.assets.set(`stock:vid:${video.id}`, {
              provider: "pixabay",
              providerAssetId: String(video.id),
              providerText: { tags: video.tags },
            });
          }

          // Validate with ffprobe
          try {
            const probeResult = await withSceneFetchTimeout(
              () => exec(`"${FFPROBE_BIN}" -v error -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 "${rawPath}"`),
              10_000, `Probe Pixabay clip ${idx}`
            );
            const dur = parseFloat(typeof probeResult === 'string' ? probeResult : (probeResult as any).stdout || '');
            if (isNaN(dur) || dur < 1) { try { fs.unlinkSync(rawPath); } catch { /**/ } continue; }
          } catch { try { fs.unlinkSync(rawPath); } catch { /**/ } continue; }

          // Stable trim — color grade applied later in composeSceneVideo
          const startSec = (sceneIndex + idx) * 0.33 % 1.1;
          const trimmed = await trimDownloadedStockClip(
            rawPath,
            outPath,
            clipDuration,
            video.duration,
            `Trim Pixabay clip ${idx} scene ${sceneIndex}`,
            startSec,
            { stockKey, queryEmbedding: queryEmbForStock, clipIndex: idx }
          );

          try { fs.unlinkSync(rawPath); } catch { /**/ }

          if (trimmed) {
            excludeVideoIds?.add(video.id);
            results.push(outPath);
            scheduleStockClipEmbedding(outPath);
            console.log(`[Pipeline] Scene ${sceneIndex}: Pixabay clip added: "${currentQuery}"`);
          }
        } catch (err) {
          console.warn(`[Pipeline] Pixabay clip ${idx} failed for scene ${sceneIndex}:`, (err as Error).message);
          try { fs.unlinkSync(rawPath); } catch { /**/ }
        }
      }
    } catch (err) {
      // RONDE 68: a cancellation FastVid caused is not a provider fault — see isScopeAbortError.
      if (!isScopeAbortError(err)) markPixabaySearchResult(false);
      console.warn(`[Pipeline] Pixabay search failed for query "${currentQuery}" scene ${sceneIndex}:`, err);
    }
  }

  return results;
}

/** Encode a still image to MP4 with Ken Burns; motion graphics, gray mat, or documentary blur-fill. */
async function encodeStillImageMp4(
  imgPath: string,
  outPath: string,
  duration: number,
  label: string,
  sceneIndex: number,
  beatIndex: number,
  personPortrait: boolean,
  styleContext?: StillStyleContext
): Promise<void> {
  const styled = resolveStillImageFilterComplex(duration, sceneIndex, beatIndex, styleContext);
  if (styled) {
    try {
      await withSceneFetchTimeout(
        () => exec(`${FFMPEG_BIN} ${buildStillEncodeArgs(imgPath, outPath, duration, styled.filterComplex)}`),
        25_000,
        label
      );
      if (styled.consumedBudget && styleContext?.motionGraphicsBudget) {
        styleContext.motionGraphicsBudget.used++;
      }
      if (fs.existsSync(outPath) && fs.statSync(outPath).size > 1000) {
        const probed = await probeVideoDurationSec(outPath);
        if (probed >= duration * 0.5) return;
      }
    } catch (err) {
      console.warn(`[Pipeline] ${label}: motion graphic still failed:`, (err as Error).message);
    }
    try {
      if (fs.existsSync(outPath)) fs.unlinkSync(outPath);
    } catch {
      /* ignore */
    }
  }

  const fps = 25;
  const frames = stillOutputFrameCount(duration, fps);

  // Documentary blur-fill (blurred background + sharp foreground) takes priority
  // over mat-frame layout — cleaner, more professional look.
  // Always enabled when cinematic motion is on (regardless of ENABLE_DOC_STYLE flag).
  if (documentaryStyleEnabled() || process.env.CINEMATIC_MOTION !== "false") {
    const filterComplex = resolveStillCompositionVF(duration, sceneIndex, beatIndex, personPortrait);
    try {
      await withSceneFetchTimeout(
        () => exec(`${FFMPEG_BIN} ${buildStillEncodeArgs(imgPath, outPath, duration, filterComplex)}`),
        25_000,
        label
      );
      if (fs.existsSync(outPath) && fs.statSync(outPath).size > 1000) {
        const probed = await probeVideoDurationSec(outPath);
        if (probed >= duration * 0.5) return;
        console.warn(`[Pipeline] ${label}: documentary still too short (${probed.toFixed(2)}s), retrying simple Ken Burns`);
      }
    } catch (err) {
      console.warn(`[Pipeline] ${label}: documentary still encode failed, retrying simple Ken Burns:`, (err as Error).message);
    }
    try {
      fs.unlinkSync(outPath);
    } catch {
      /* ignore */
    }
    const fallbackFc = buildSimpleKenBurnsVF(duration, personPortrait);
    await withSceneFetchTimeout(
      () => exec(`${FFMPEG_BIN} ${buildStillEncodeArgs(imgPath, outPath, duration, fallbackFc)}`),
      25_000,
      `${label} (fallback)`
    );
    return;
  }

  // Fallback when documentary style is off: mat-frame layout on gray mat.
  if (framedArchiveStillsEnabled()) {
    try {
      const filterComplex = buildMatFramedStillVF(duration);
      await withSceneFetchTimeout(
        () => exec(`${FFMPEG_BIN} ${buildStillEncodeArgs(imgPath, outPath, duration, filterComplex)}`),
        25_000,
        `${label} (mat frame)`
      );
      if (fs.existsSync(outPath) && fs.statSync(outPath).size > 1000) {
        const probed = await probeVideoDurationSec(outPath);
        if (probed >= duration * 0.5) return;
      }
    } catch (err) {
      console.warn(`[Pipeline] ${label}: mat frame still failed:`, (err as Error).message);
    }
    try {
      if (fs.existsSync(outPath)) fs.unlinkSync(outPath);
    } catch {
      /* ignore */
    }
  }

  const totalFrames = frames;
  const zoomEnd = personPortrait ? 1.02 : 1.03;
  const zoomStep = (zoomEnd - 1.0) / totalFrames;
  const padW = Math.round(VIDEO_WIDTH * 1.05);
  const padH = Math.round(VIDEO_HEIGHT * 1.05);
  const cropY = personPortrait ? "0" : `(ih-${VIDEO_HEIGHT})/2`;
  const yExpr = personPortrait ? "ih/4-(ih/zoom/4)" : "ih/2-(ih/zoom/2)";
  await withSceneFetchTimeout(
    () => exec(
      `${FFMPEG_BIN} -y -i "${imgPath}" ` +
        `-vf "scale=${personPortrait ? VIDEO_WIDTH : padW}:${personPortrait ? VIDEO_HEIGHT : padH}:force_original_aspect_ratio=increase,` +
        `crop=${VIDEO_WIDTH}:${VIDEO_HEIGHT}:(iw-${VIDEO_WIDTH})/2:${cropY},` +
        `select='eq(n\\,0)',` +
        `zoompan=z='min(zoom+${zoomStep.toFixed(7)},${zoomEnd})':x='iw/2-(iw/zoom/2)':y='${yExpr}':` +
        `d=${totalFrames}:s=${VIDEO_WIDTH}x${VIDEO_HEIGHT}:fps=${fps}" ` +
        `-frames:v ${totalFrames} -c:v libx264 ${pipelineFfmpegThreadFlag()} -preset veryfast -crf 18 -an -pix_fmt yuv420p -r ${fps} "${outPath}"`
    ),
    25_000,
    label
  );
}

/** Gentle Ken Burns for stills: ~3% center zoom. */
async function convertImageToVideoGentle(
  imgPath: string,
  outPath: string,
  duration: number,
  label: string,
  sceneIndex = 0,
  beatIndex = 0,
  styleContext?: StillStyleContext
): Promise<void> {
  await encodeStillImageMp4(imgPath, outPath, duration, label, sceneIndex, beatIndex, false, styleContext);
}

/** Person stills: top-aligned 16:9 crop so faces stay visible on red-carpet / full-body photos. */
async function convertImageToVideoPersonPortrait(
  imgPath: string,
  outPath: string,
  duration: number,
  label: string,
  sceneIndex = 0,
  beatIndex = 0,
  styleContext?: StillStyleContext
): Promise<void> {
  await encodeStillImageMp4(imgPath, outPath, duration, label, sceneIndex, beatIndex, true, styleContext);
}

async function stillImageToVideo(
  imgPath: string,
  outPath: string,
  duration: number,
  label: string,
  personPortrait: boolean,
  sceneIndex = 0,
  beatIndex = 0,
  styleContext?: StillStyleContext
): Promise<void> {
  if (personPortrait) {
    await convertImageToVideoPersonPortrait(imgPath, outPath, duration, label, sceneIndex, beatIndex, styleContext);
  } else {
    await convertImageToVideoGentle(imgPath, outPath, duration, label, sceneIndex, beatIndex, styleContext);
  }
}

function normalizeImageSourceUrl(url: string): string {
  try {
    const u = new URL(url);
    u.hash = "";
    return u.toString();
  } catch {
    return url.split("?")[0] ?? url;
  }
}

// ─── 3c2. Wikimedia Commons Image Search ────────────────────────────────────
// Searches Wikimedia Commons for freely licensed images (good for celebrities, news, etc.)
// F3-16 finding 3.5: Wikimedia/SerpAPI "original" image downloads had no upper bound on response
// size, buffering the entire body in memory via arrayBuffer() before any size check happened. A
// legitimate high-resolution stock/archive photo rarely exceeds a few MB even at full
// resolution — 25MB comfortably covers that while still rejecting pathological outliers well
// before they threaten worker memory. Shared by fetchWikimediaImages, fetchWikimediaImagesV1,
// and fetchSerpAPIImages below.
const MAX_IMAGE_DOWNLOAD_BYTES = 25 * 1024 * 1024;

/**
 * RONDE 34 (point 3): hard ceiling on how many Commons results one rescue-aware search may scan.
 * Bounds both the search request and the per-title imageinfo loop, so an exclusion set can never
 * turn candidate exhaustion into runaway fetching.
 */
const WIKIMEDIA_MAX_CANDIDATE_SCAN = 25;

/**
 * RONDE 136 — every title's imageinfo in one request.
 *
 * MediaWiki's query API accepts up to 50 pipe-separated titles per call and answers with a page
 * entry per title. Asking once instead of once-per-title is what stops Commons throttling this
 * route; see the call site for what the N+1 pattern cost in video 558.
 *
 * Returns a map keyed by the title as it was ASKED FOR. MediaWiki normalises titles (underscores
 * to spaces, first letter capitalised) and reports what it changed in `query.normalized`, so that
 * mapping is applied here — without it a normalised answer would never be found again under the
 * name the caller holds, and the batch would silently return nothing for every title.
 *
 * A failed request yields an empty map, which the caller treats exactly as it treated a failed
 * per-title call: the candidates are skipped, nothing is invented.
 */
export const WIKIMEDIA_IMAGEINFO_BATCH_SIZE = 50;

type WikimediaImageInfo = { url: string; mime: string; size: number };

export async function fetchWikimediaImageInfoBatch(
  titles: string[],
  sceneIndex: number
): Promise<Map<string, WikimediaImageInfo>> {
  const out = new Map<string, WikimediaImageInfo>();
  const wanted = titles.filter((t) => t?.trim());
  for (let i = 0; i < wanted.length; i += WIKIMEDIA_IMAGEINFO_BATCH_SIZE) {
    const chunk = wanted.slice(i, i + WIKIMEDIA_IMAGEINFO_BATCH_SIZE);
    try {
      const infoUrl =
        `https://commons.wikimedia.org/w/api.php?action=query` +
        `&titles=${encodeURIComponent(chunk.join("|"))}` +
        `&prop=imageinfo&iiprop=url|mime|size&format=json&origin=*`;
      const infoResp = await providerLimiter("wikimedia").run(() =>
        fetchWithTimeout(infoUrl, 8_000, `Wikimedia info batch scene ${sceneIndex}`, {
          headers: { "User-Agent": "Fastvid/1.0 (video generation)" },
        })
      );
      if (!infoResp.ok) {
        logWikimediaHttpFailure("imageinfo", sceneIndex, infoResp);
        markWikimediaSearchResult(false);
        continue;
      }
      markWikimediaSearchResult(true);
      const data = (await infoResp.json()) as {
        query?: {
          normalized?: Array<{ from: string; to: string }>;
          pages?: Record<string, { title?: string; imageinfo?: WikimediaImageInfo[] }>;
        };
      };
      // MediaWiki's own record of what it renamed, so the answer can be found under the name the
      // caller asked with.
      const askedFor = new Map<string, string>();
      for (const n of data.query?.normalized ?? []) askedFor.set(n.to, n.from);
      for (const page of Object.values(data.query?.pages ?? {})) {
        const info = page?.imageinfo?.[0];
        if (!info?.url || !page.title) continue;
        out.set(askedFor.get(page.title) ?? page.title, info);
        // Also under the normalised name, so a caller holding either form finds it.
        out.set(page.title, info);
      }
    } catch (err) {
      // RONDE 68/69: a cancellation FastVid caused is not a provider fault, and a failure that is
      // counted must never be counted silently. Same shape as every other Wikimedia catch site.
      if (!isScopeAbortError(err)) {
        console.warn(
          `[Pipeline] Wikimedia info batch for scene ${sceneIndex}: ${(err as Error).message?.slice(0, 80)}`
        );
      }
      // Single line, matching every other Wikimedia catch site: the counter and its cancellation
      // guard travel together, which is the shape RONDE 69/70 pin.
      if (!isScopeAbortError(err)) markWikimediaSearchResult(false);
    }
  }
  return out;
}

export async function fetchWikimediaImages(
  query: string,
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 2,
  fileTag = "",
  opts: {
    beatIndex?: number;
    stillStyleContext?: StillStyleContext;
    /**
     * RONDE 33: caller-owned set of Commons file URLs this batch has already taken. Candidates
     * whose URL is in it are skipped, and every URL this call adopts is added back. The URL is
     * Wikimedia's own stable identity for a file — far more reliable than the local filename,
     * which only carries a scene/tag/index. Omit it and this function behaves exactly as before:
     * no candidate is skipped and no scan window is widened.
     */
    excludeUrls?: Set<string>;
    /** RONDE 96: so Commons images open a lineage record like every other provider's assets. */
    dedup?: VisualDedupState;
  } = {}
): Promise<string[]> {
  const results: string[] = [];
  const excludeUrls = opts.excludeUrls;
  // Same breaker fetchWikimediaImagesV1/fetchWikimediaVideos/adoptWikimediaBeatClip already use
  // (isWikimediaInCooldown/markWikimediaSearchResult, ~664-690) — this legacy function was
  // previously the one Wikimedia call site that bypassed it entirely, so a sustained Wikimedia
  // outage kept hitting commons.wikimedia.org unthrottled from here regardless of the breaker
  // tripping for every other caller.
  if (isWikimediaInCooldown()) return results;
  try {
    // ── Scene candidate cache: skip Wikimedia search + imageinfo API calls on hit ──
    const cachedCandidates = await getCandidatePool(query, "wikimedia");
    if (cachedCandidates) {
      // Pre-filter rather than skip inside the loop: with no excludeUrls this is the identical
      // array, so the loop bound and every existing caller's behaviour are untouched.
      const pool = excludeUrls
        ? cachedCandidates.filter((c) => c.url && !excludeUrls.has(c.url))
        : cachedCandidates;
      for (let i = 0; i < Math.min(pool.length, count); i++) {
        const c = pool[i];
        if (!c.url || !c.contentType.startsWith("image/")) continue;
        const tag = fileTag ? `${fileTag}_` : "";
        const imgPath = path.join(workDir, `scene_${sceneIndex}_${tag}wiki_cached_${i}.jpg`);
        // RONDE 96: fetchWikimediaVideos has opened a record since RONDE 88; this sibling, which
        // serves Commons IMAGES, never did. Same provider, same ledger. The file URL is Commons'
        // own stable identity for the file — see the excludeUrls note on this function's opts.
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_${tag}wiki_cached_${i}.mp4`),
          "wikimedia",
          c.url,
          opts.dedup?.sourcingCache,
          {
            sceneIndex,
            beatIndex: opts.beatIndex,
            sourceUrl: c.url,
            mediaType: "image",
            query,
            searchRoute: "fetchWikimediaImages",
          }
        );
        const fromCache = await tryRestoreFromMediaCache(c.url, imgPath);
        if (!fromCache) {
          const dl = await downloadToFileStreaming(
            c.url,
            imgPath,
            15_000,
            `Wikimedia cached download scene ${sceneIndex}`,
            { headers: { 'User-Agent': 'Fastvid/1.0 (video generation)' } },
            MAX_IMAGE_DOWNLOAD_BYTES
          ).catch(() => null);
          if (!dl || !dl.response.ok || dl.bytesWritten === null) continue;
          if (dl.bytesWritten < 10_000) { try { fs.unlinkSync(imgPath); } catch { /* ignore */ } continue; }
          void reportToMediaCache(c.url, imgPath, c.contentType);
        }
        await stillImageToVideo(
          imgPath, outPath, duration,
          `Wikimedia cached image to video scene ${sceneIndex}`,
          /portrait|face|headshot|person|celebrity/i.test(query),
          sceneIndex, opts.beatIndex ?? 0, opts.stillStyleContext
        );
        try { fs.unlinkSync(imgPath); } catch { /* ignore */ }
        if (fs.existsSync(outPath) && fs.statSync(outPath).size > 1_000) {
          results.push(outPath);
          excludeUrls?.add(c.url);
        }
      }
      // RONDE 50: a cache HIT used to be the end of the story. The pool is stored in the database
      // with a seven-day TTL and is only as deep as the call that wrote it — a plain
      // (non-excluding) call scans at most `count` titles, so a two-entry pool written days ago
      // by another render would cap every later rescue at those same two candidates. With an
      // exclusion set active that is exactly the case where both are already taken and the
      // rescue needs NEW candidates. So when exclusions are in play and the cached pool could
      // not fill the request, fall through to the live search below instead of returning short.
      //
      // Without exclusions nothing changes: the cached pool is still the whole answer, and no
      // extra request is made. With them, the request is made only when the pool fell short —
      // a pool that already satisfied `count` returns here as before. The live path appends to
      // this same `results` array, keeps the same WIKIMEDIA_MAX_CANDIDATE_SCAN ceiling, the same
      // provider limiter and the same timeouts, and every URL adopted above is already in
      // excludeUrls so it cannot be picked twice.
      if (!excludeUrls || results.length >= count) return results;
      // RONDE 89: the provider gate, immediately before the one live search this function makes.
      // A refused query means no live search — and the clips already adopted from the cached pool
      // are returned rather than discarded, which is what the RONDE 50 fall-through guarantees.
      if (admitProviderQuery("wikimedia", query, "fetchWikimediaImages") === null) return results;
    }

    // Cache miss — or a cache hit that exclusions left short (RONDE 50). Search Wikimedia Commons
    // RONDE 34 (point 3): when a rescue batch is excluding what earlier slots already took, ask
    // Commons for a deeper result set in the SAME request rather than settling for a pool too
    // small to satisfy the exclusions. One request either way — no pagination loop, no retry
    // layer — and a hard ceiling (WIKIMEDIA_MAX_CANDIDATE_SCAN) bounds it. Callers that pass no
    // exclusion set keep the original srlimit=10 and are byte-for-byte unaffected.
    const searchLimit = excludeUrls ? WIKIMEDIA_MAX_CANDIDATE_SCAN : 10;
    const searchUrl = `https://commons.wikimedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(query)}&srnamespace=6&srlimit=${searchLimit}&format=json&origin=*`;
    const searchResp = await providerLimiter("wikimedia").run(() => fetchWithTimeout(
      searchUrl,
      5_000,
      `Wikimedia search scene ${sceneIndex}`,
      { headers: { 'User-Agent': 'Fastvid/1.0 (video generation)' } }
    ));
    if (!searchResp.ok) {
      logWikimediaHttpFailure("search", sceneIndex, searchResp);
      markWikimediaSearchResult(false);
      // RONDE 50: `results` may already hold clips adopted from the cached pool above.
      return results;
    }
    markWikimediaSearchResult(true);
    const searchData = await searchResp.json() as { query?: { search?: Array<{ title: string }> } };
    // Without exclusions the window stays count*2, exactly as before. With them it opens up to
    // the whole (already paid for) result set, so N slots can find N distinct files.
    const allTitles = searchData.query?.search?.map(r => r.title) ?? [];
    const titles = excludeUrls
      ? allTitles.slice(0, WIKIMEDIA_MAX_CANDIDATE_SCAN)
      : allTitles.slice(0, count * 2);
    if (!titles.length) return results;
    const poolForCache: CachedCandidate[] = [];

    // Get image info for each result.
    // RONDE 33: a candidate's Commons URL is only known after its imageinfo call, so an excluded
    // one has to be skipped inside the loop — which would otherwise eat this call's whole budget.
    // With excludeUrls set, the scan widens to every title the search returned and stops as soon
    // as `count` results are in hand. Without it, maxScan and the loop are exactly as before.
    const maxScan = excludeUrls ? titles.length : Math.min(titles.length, count);
    /**
     * RONDE 136 — ONE imageinfo request for all titles, not one per title.
     *
     * ── What video 558 measured ──────────────────────────────────────────────────────────────
     *
     *     wikimedia: searches=15  results=38  downloads=0  accepted=0
     *     32x [Pipeline] Wikimedia imageinfo for scene N: HTTP 429 Too Many Requests
     *     34x [ProviderCooldown] provider=wikimedia reason=RATE_LIMITED standing down for 60s
     *
     * Thirty-eight results and not one download. The search was never the problem — every
     * per-title metadata call was refused, and without imageinfo there is no URL, so every
     * candidate was dropped before it could become a file.
     *
     * ── Why it was rate-limited ──────────────────────────────────────────────────────────────
     *
     * This loop asked Commons about ONE title per HTTP request. With the exclusion set open the
     * scan runs to WIKIMEDIA_MAX_CANDIDATE_SCAN (25) titles, and this route is called per scene
     * and per beat — hundreds of requests to api.php in a render. Commons throttles that, which
     * is not a fault in its policy: the API is explicitly built to be asked once.
     *
     * ── The fix ──────────────────────────────────────────────────────────────────────────────
     *
     * MediaWiki's query API takes up to 50 titles in one `titles=A|B|C` call and returns a page
     * entry for each. So the whole scan becomes a single request — 25x fewer calls, the same
     * data, and no new architecture: same endpoint, same params, same parsing, same User-Agent.
     *
     * The per-title loop below is unchanged apart from reading its imageinfo out of this map
     * instead of making its own call. Order, caps, exclusion and early-exit all still behave
     * exactly as they did.
     */
    const infoByTitle = await fetchWikimediaImageInfoBatch(
      titles.slice(0, maxScan),
      sceneIndex
    );
    for (let i = 0; i < maxScan; i++) {
      if (results.length >= count) break;
      try {
        const title = titles[i];
        const imageInfo = infoByTitle.get(title);
        if (!imageInfo?.url) continue;
        if (excludeUrls?.has(imageInfo.url)) continue;
        // Only use JPEG/PNG images, skip SVG/PDF/audio/video
        if (!imageInfo.mime.startsWith('image/jpeg') && !imageInfo.mime.startsWith('image/png')) continue;
        // Skip very small images
        if (imageInfo.size < 10_000) continue;

        // Record for scene candidate cache (stable Wikimedia URLs)
        poolForCache.push({
          assetId: title,
          title,
          url: imageInfo.url,
          thumbnailUrl: null,
          contentType: imageInfo.mime,
          durationSec: null,
          meta: { size: imageInfo.size },
        });

        // Download the image (check media cache first)
        const tag = fileTag ? `${fileTag}_` : "";
        const imgPath = path.join(workDir, `scene_${sceneIndex}_${tag}wiki_${i}.jpg`);
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_${tag}wiki_${i}.mp4`),
          "wikimedia",
          imageInfo.url,
          opts.dedup?.sourcingCache,
          {
            sceneIndex,
            beatIndex: opts.beatIndex,
            sourceUrl: imageInfo.url,
            mediaType: "image",
            query,
            searchRoute: "fetchWikimediaImages",
          }
        );
        const fromWikiCache = await tryRestoreFromMediaCache(imageInfo.url, imgPath);
        if (!fromWikiCache) {
          const { response: imgResp, bytesWritten } = await downloadToFileStreaming(
            imageInfo.url,
            imgPath,
            15_000,
            `Wikimedia download scene ${sceneIndex}`,
            { headers: { 'User-Agent': 'Fastvid/1.0 (video generation)' } },
            MAX_IMAGE_DOWNLOAD_BYTES
          );
          if (!imgResp.ok || bytesWritten === null) continue;
          if (bytesWritten < 10_000) { try { fs.unlinkSync(imgPath); } catch { /* ignore */ } continue; }
          void reportToMediaCache(imageInfo.url, imgPath, imageInfo.mime ?? "image/jpeg");
        }

        await stillImageToVideo(
          imgPath,
          outPath,
          duration,
          `Wikimedia image to video scene ${sceneIndex}`,
          /portrait|face|headshot|person|celebrity/i.test(query),
          sceneIndex,
          opts.beatIndex ?? 0,
          opts.stillStyleContext
        );
        try { fs.unlinkSync(imgPath); } catch { /* ignore */ }
        if (fs.existsSync(outPath) && fs.statSync(outPath).size > 1_000) {
          results.push(outPath);
          excludeUrls?.add(imageInfo.url);
          console.log(`[Pipeline] Scene ${sceneIndex}: Wikimedia image added: ${title}`);
        }
      } catch (err) {
        console.warn(`[Pipeline] Wikimedia image ${i} failed for scene ${sceneIndex}:`, err);
      }
    }
    // Populate scene candidate cache for this query (best-effort)
    if (poolForCache.length > 0) {
      void putCandidatePool(query, "wikimedia", poolForCache);
    }
  } catch (err) {
    // RONDE 68: a cancellation FastVid caused is not a provider fault — see isScopeAbortError.
    if (!isScopeAbortError(err)) markWikimediaSearchResult(false);
    console.warn(`[Pipeline] Wikimedia search failed for scene ${sceneIndex}:`, err);
  }
  return results;
}

// ─── 3c2v1. Visual Matching Engine V1 — Wikimedia scored search ──────────────
// Searches Wikimedia Commons, scores each result against the structured visual
// analysis (Subject 40 · Action 30 · Location 10 · Context 20 = 100), and
// downloads only the best image that reaches wikimediaV1AdoptionThreshold.
// Converts with Wikimedia documentary style (blurred BG + centered 80% FG).
async function fetchWikimediaImagesV1(
  analysis: ReturnType<typeof analyzeSceneVisual>,
  duration: number,
  workDir: string,
  sceneIndex: number,
  beatIndex: number,
  fileTag: string,
  videoTitle?: string,
  minThreshold?: number
): Promise<string | null> {
  if (isWikimediaInCooldown()) return null;
  const UA = { "User-Agent": "Fastvid/1.0 (video generation)" };
  const adoptThreshold = minThreshold ?? wikimediaV1AdoptionThreshold(videoTitle, analysis.sentence);
  const queries = buildV1WikimediaQueries(analysis, videoTitle);

  const downloadWikimediaTitle = async (bestTitle: string, bestScore: number): Promise<string | null> => {
    const infoUrl =
      `https://commons.wikimedia.org/w/api.php?action=query` +
      `&titles=${encodeURIComponent(bestTitle)}&prop=imageinfo` +
      `&iiprop=url|mime|size&format=json&origin=*`;
    const infoResp = await providerLimiter("wikimedia").run(() => fetchWithTimeout(
      infoUrl,
      5_000,
      `V1 Wikimedia info scene ${sceneIndex}`,
      { headers: UA }
    ));
    if (!infoResp.ok) {
      logWikimediaHttpFailure("V1 imageinfo", sceneIndex, infoResp);
      markWikimediaSearchResult(false);
      return null;
    }
    markWikimediaSearchResult(true);
    type WikiInfoPage = { imageinfo?: Array<{ url: string; mime: string; size: number }> };
    const infoData = await infoResp.json() as { query?: { pages?: Record<string, WikiInfoPage> } };
    const page = Object.values(infoData.query?.pages ?? {})[0];
    const imageInfo = page?.imageinfo?.[0];
    if (!imageInfo?.url) return null;
    if (!imageInfo.mime.startsWith("image/jpeg") && !imageInfo.mime.startsWith("image/png")) return null;
    if (imageInfo.size < 10_000) return null;

    const tag = fileTag ? `${fileTag}_` : "";
    const imgPath = path.join(workDir, `scene_${sceneIndex}_${tag}v1wiki_b${beatIndex}.jpg`);
    const outPath = path.join(workDir, `scene_${sceneIndex}_${tag}v1wiki_b${beatIndex}.mp4`);
    const fromV1WikiCache = await tryRestoreFromMediaCache(imageInfo.url, imgPath);
    if (!fromV1WikiCache) {
      const dl = await downloadToFileStreaming(
        imageInfo.url,
        imgPath,
        15_000,
        `V1 Wikimedia download scene ${sceneIndex}`,
        { headers: UA },
        MAX_IMAGE_DOWNLOAD_BYTES
      ).catch(() => null);
      if (!dl || !dl.response.ok || dl.bytesWritten === null) return null;
      if (dl.bytesWritten < 10_000) { try { fs.unlinkSync(imgPath); } catch { /* ignore */ } return null; }
      void reportToMediaCache(imageInfo.url, imgPath, imageInfo.mime ?? "image/jpeg");
    }

    const filterComplex = buildWikimediaDocumentaryVF(duration, "center", sceneIndex, beatIndex);
    await withSceneFetchTimeout(
      () => exec(`${FFMPEG_BIN} ${buildStillEncodeArgs(imgPath, outPath, duration, filterComplex)}`),
      45_000,
      `V1 Wikimedia image→video scene ${sceneIndex}`
    );
    try {
      fs.unlinkSync(imgPath);
    } catch {
      /* ignore */
    }

    if (fs.existsSync(outPath) && fs.statSync(outPath).size > 1_000) {
      console.log(
        `[V1] Scene ${sceneIndex} beat ${beatIndex}: Wikimedia match "${bestTitle.slice(0, 40)}" score=${bestScore}`
      );
      return outPath;
    }
    return null;
  };

  if (wikimediaGeosearchEnabled()) {
    try {
      const geoTitles = await fetchWikimediaTitlesForVideoGeo(videoTitle, 6);
      for (const title of geoTitles) {
        const metadata = title;
        if (!wikimediaMetadataPassesBeatGate(metadata, videoTitle, analysis.sentence)) continue;
        const score = scoreVisualForScene(metadata, analysis);
        if (score < adoptThreshold - 8) continue;
        const clip = await downloadWikimediaTitle(title, score);
        if (clip) return clip;
      }
    } catch (err) {
      console.warn(`[V1] Wikimedia geosearch scene ${sceneIndex}:`, (err as Error).message?.slice(0, 80));
    }
  }

  // Fire all per-query searches concurrently (pure network fetches, no ffmpeg/process spawns,
  // so this doesn't compete for Railway's container pids limit) instead of waiting out each
  // query's search latency one at a time before starting the next.
  type WikiSearchResult = { title: string; snippet?: string };
  const searchResults = await Promise.all(
    queries.map(async (query) => {
      // RONDE 89: the provider gate, per query. A refused query yields no results for that
      // query — it is never repaired, widened or replaced with a guess.
      if (admitProviderQuery("wikimedia", query, "fetchWikimediaImagesV1") === null) {
        return { query, results: [] as WikiSearchResult[] };
      }
      try {
        const searchUrl =
          `https://commons.wikimedia.org/w/api.php?action=query&list=search` +
          `&srsearch=${encodeURIComponent(query)}&srnamespace=6&srlimit=10` +
          `&srprop=snippet|size&format=json&origin=*`;
        const searchResp = await providerLimiter("wikimedia").run(() => fetchWithTimeout(
          searchUrl,
          5_000,
          `V1 Wikimedia search scene ${sceneIndex}`,
          { headers: UA }
        ));
        if (!searchResp.ok) {
          logWikimediaHttpFailure("V1 search", sceneIndex, searchResp);
          markWikimediaSearchResult(false);
          return { query, results: [] as WikiSearchResult[] };
        }
        const searchData = await searchResp.json() as {
          query?: { search?: WikiSearchResult[] };
        };
        markWikimediaSearchResult(true);
        return { query, results: searchData.query?.search ?? [] };
      } catch (err) {
        // RONDE 68: a cancellation FastVid caused is not a provider fault — see isScopeAbortError.
        if (!isScopeAbortError(err)) markWikimediaSearchResult(false);
        console.warn(`[V1] Wikimedia query "${query}" failed:`, (err as Error).message);
        return { query, results: [] as WikiSearchResult[] };
      }
    })
  );

  // Downloads still happen one at a time, in original query priority order, stopping at the
  // first one that actually adopts — same "first good match wins" behavior as before.
  for (const { results } of searchResults) {
    if (!results.length) continue;

    // Score each result — download only the winner above threshold
    let bestTitle: string | null = null;
    let bestScore = adoptThreshold - 1;
    for (const result of results) {
      const metadata = `${result.title} ${(result.snippet ?? "").replace(/<[^>]*>/g, " ")}`;
      if (!wikimediaMetadataPassesBeatGate(metadata, videoTitle, analysis.sentence)) {
        console.log(`[V1] Scene ${sceneIndex} skip geo-offtopic "${result.title.slice(0, 35)}"`);
        continue;
      }
      const score = scoreVisualForScene(metadata, analysis);
      console.log(`[V1] Scene ${sceneIndex} "${result.title.slice(0, 35)}" score=${score}`);
      if (score > bestScore) { bestScore = score; bestTitle = result.title; }
    }
    if (!bestTitle) continue;

    const outPath = await downloadWikimediaTitle(bestTitle, bestScore);
    if (outPath) return outPath;
  }
  return null;
}

// ─── 3c2b. Openverse API Image Search ─────────────────────────────────────
// Searches Openverse (WordPress/Automattic) for CC-licensed photos of public figures.
// No API key required. Returns CC-BY licensed images — safe for commercial use.
// Great source for celebrities, politicians, athletes, and public events.
async function fetchOpenverseImages(
  query: string,
  duration: number,
  workDir: string,
  sceneIndex: number,
  maxResults: number = 2,
  fileTag = "",
  opts: {
    personPortrait?: boolean;
    dedup?: VisualDedupState;
    beatIndex?: number;
    stillStyleContext?: StillStyleContext;
    geoDocumentary?: boolean;
  } = {}
): Promise<string[]> {
  // RONDE 89: the provider gate. A query the contract refuses is not sent, and is
  // never repaired or substituted — the caller simply gets nothing.
  if (admitProviderQuery("openverse", query, "fetchOpenverseImages") === null) return [];
  const geoOk = Boolean(opts.geoDocumentary && openverseGeoDocumentaryEnabled());
  if (!openverseStillsEnabled() && !geoOk) return [];
  const results: string[] = [];
  try {
    // Search Openverse for CC-licensed images (commercial use + modification allowed)
    const searchUrl = `https://api.openverse.org/v1/images/?q=${encodeURIComponent(query)}&license_type=commercial,modification&page_size=${maxResults * 3}&format=json`;
    const searchResp = await withTimeout(
      fetch(searchUrl, { headers: { 'User-Agent': 'Fastvid/1.0 (video generation; contact@fastvid.ai)' } }),
      5000,
      `Openverse search scene ${sceneIndex}`
    );
    if (!searchResp.ok) {
      console.warn(`[Pipeline] Scene ${sceneIndex}: Openverse error ${searchResp.status}`);
      return [];
    }
    const payload = await searchResp.json() as { results?: Array<{ id: string; url: string; title?: string; license?: string; attribution?: string }> };
    const images = payload.results || [];
    if (images.length === 0) return [];

    for (let i = 0; i < Math.min(images.length, maxResults * 2) && results.length < maxResults; i++) {
      try {
        const imgUrl = images[i].url;
        if (!imgUrl || !/\.(jpg|jpeg|png|webp)/i.test(imgUrl)) continue;
        // Phase 12: check dedup before downloading/encoding (was after) — matches
        // fetchUnsplashImages' order below and avoids paying the full download+ffmpeg-encode
        // cost for a URL already used elsewhere in this video.
        const urlKey = normalizeImageSourceUrl(imgUrl);
        if (opts.dedup?.usedImageUrls.has(urlKey)) continue;

        const tag = fileTag ? `${fileTag}_` : "";
        // Production finding: this filename used to be keyed on the loop-local index `i` alone
        // (openverse_0, openverse_1, ...), which restarts at 0 on every call to this function.
        // The caller invokes fetchOpenverseImages once per search query for the same beat/scene
        // (same sceneIndex+fileTag) — so two genuinely different images from two different
        // queries could both land on `i=0` and collide on the exact same output path, silently
        // overwriting each other on disk. Worse, the VisionGate cache falls back to this
        // basename as the candidate's identity when no contentKey is available, so the second
        // (different) image inherited the first image's already-computed pass/fail verdict
        // without ever being evaluated. Keying on the asset's own id (or the image URL when an
        // id is unexpectedly missing) instead of the loop position makes the path — and thus the
        // vision-gate identity — asset-specific: the same asset revisited reuses its own path
        // (intentional, matches the existing usedImageUrls dedup), a different asset never can.
        const assetTag =
          ((images[i]?.id?.trim() || imgUrl).replace(/[^a-zA-Z0-9]/g, "").slice(0, 24)) || String(i);
        const imgPath = path.join(workDir, `scene_${sceneIndex}_${tag}openverse_${assetTag}.jpg`);
        /**
         * RONDE 96 — this provider's assets enter the ledger like every other provider's.
         *
         * These five fetchers wrote their file straight to workDir and handed the path on, so the
         * clip only ever reached the ledger later, through clipAdoptAudit's "adoption of a clip
         * the ledger has never seen" branch — which deliberately records NO provider, because
         * guessing one from a filename is exactly what RONDE 86 removed. The result was honest and
         * useless: every Pexels, Unsplash, SerpAPI, Openverse and YouTube-thumbnail asset counted
         * as UNVERIFIED however normally it had arrived.
         *
         * tagPathWithProviderAsset is the same entry point the other eleven providers use, called
         * at the same moment: provider name, the provider's own id and the destination path all in
         * hand, straight from the API response. It opens the record and files DOWNLOAD_STARTED.
         */
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_${tag}openverse_${assetTag}.mp4`),
          "openverse",
          images[i]?.id?.trim() || imgUrl,
          opts.dedup?.sourcingCache,
          {
            sceneIndex,
            beatIndex: opts.beatIndex,
            sourceUrl: imgUrl,
            title: images[i]?.title,
            mediaType: "image",
            query,
            searchRoute: "fetchOpenverseImages",
          }
        );

        // Download image
        const imgResp = await withTimeout(
          fetch(imgUrl),
          10000,
          `Openverse image download scene ${sceneIndex}`
        );
        if (!imgResp.ok) continue;
        const imgBuf = Buffer.from(await imgResp.arrayBuffer());
        if (imgBuf.length < 5000) continue; // skip tiny/broken images
        fs.writeFileSync(imgPath, imgBuf);

        await stillImageToVideo(
          imgPath,
          outPath,
          duration,
          `Openverse image to video scene ${sceneIndex}`,
          Boolean(opts.personPortrait) || /portrait|face|headshot/i.test(query),
          sceneIndex,
          opts.beatIndex ?? 0,
          opts.stillStyleContext
        );
        try { fs.unlinkSync(imgPath); } catch { /**/ }

        if (fs.existsSync(outPath) && fs.statSync(outPath).size > 10_000) {
          opts.dedup?.usedImageUrls.add(urlKey);
          // RONDE 96: the file exists, so the download is a fact rather than an intention. Same helper the o
          // ther eleven providers use — it flips DOWNLOAD_STARTED to DOWNLOAD_SUCCEEDED on the record tagPat
          // hWithProviderAsset opened.
          recordProviderDownloadOutcome(opts.dedup?.sourcingCache, outPath, true);
          results.push(outPath);
          console.log(`[Pipeline] Scene ${sceneIndex}: Openverse image added: ${images[i].title?.slice(0, 60) || imgUrl.slice(0, 60)}`);
        }
      } catch (err) {
        console.warn(`[Pipeline] Openverse image ${i} failed for scene ${sceneIndex}:`, (err as Error).message);
      }
    }
  } catch (err) {
    console.warn(`[Pipeline] Openverse search failed for scene ${sceneIndex}:`, (err as Error).message);
  }
  return results;
}

// ─── 3c2c. Unsplash API Image Search ─────────────────────────────────────────
// High-quality freely usable photos (Unsplash License). Requires free access key.
async function fetchUnsplashImages(
  query: string,
  duration: number,
  workDir: string,
  sceneIndex: number,
  maxResults: number = 2,
  fileTag = "",
  opts: { personPortrait?: boolean; dedup?: VisualDedupState } = {}
): Promise<string[]> {
  // RONDE 89: the provider gate. A query the contract refuses is not sent, and is
  // never repaired or substituted — the caller simply gets nothing.
  if (admitProviderQuery("unsplash", query, "fetchUnsplashImages") === null) return [];
  if (!UNSPLASH_ACCESS_KEY?.trim()) return [];
  const results: string[] = [];
  try {
    const searchUrl =
      `https://api.unsplash.com/search/photos?query=${encodeURIComponent(query)}` +
      `&per_page=${Math.min(maxResults * 3, 15)}&orientation=landscape`;
    const searchResp = await withTimeout(
      fetch(searchUrl, {
        headers: {
          Authorization: `Client-ID ${UNSPLASH_ACCESS_KEY.trim()}`,
          "Accept-Version": "v1",
        },
      }),
      8000,
      `Unsplash search scene ${sceneIndex}`
    );
    if (!searchResp.ok) {
      console.warn(`[Pipeline] Scene ${sceneIndex}: Unsplash error ${searchResp.status}`);
      return [];
    }
    const payload = await searchResp.json() as {
      results?: Array<{
        id?: string;
        urls?: { regular?: string; small?: string };
        alt_description?: string;
        description?: string;
      }>;
    };
    const images = payload.results ?? [];
    if (!images.length) return [];

    for (let i = 0; i < images.length && results.length < maxResults; i++) {
      try {
        const imgUrl = images[i].urls?.regular || images[i].urls?.small;
        if (!imgUrl) continue;
        const urlKey = normalizeImageSourceUrl(imgUrl);
        if (opts.dedup?.usedImageUrls.has(urlKey)) continue;

        const tag = fileTag ? `${fileTag}_` : "";
        const imgPath = path.join(workDir, `scene_${sceneIndex}_${tag}unsplash_${i}.jpg`);
        /**
         * RONDE 96 — this provider's assets enter the ledger like every other provider's.
         *
         * These five fetchers wrote their file straight to workDir and handed the path on, so the
         * clip only ever reached the ledger later, through clipAdoptAudit's "adoption of a clip
         * the ledger has never seen" branch — which deliberately records NO provider, because
         * guessing one from a filename is exactly what RONDE 86 removed. The result was honest and
         * useless: every Pexels, Unsplash, SerpAPI, Openverse and YouTube-thumbnail asset counted
         * as UNVERIFIED however normally it had arrived.
         *
         * tagPathWithProviderAsset is the same entry point the other eleven providers use, called
         * at the same moment: provider name, the provider's own id and the destination path all in
         * hand, straight from the API response. It opens the record and files DOWNLOAD_STARTED.
         */
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_${tag}unsplash_${i}.mp4`),
          "unsplash",
          images[i].id?.trim() || urlKey,
          opts.dedup?.sourcingCache,
          {
            sceneIndex,
            sourceUrl: imgUrl,
            title: images[i].description ?? images[i].alt_description,
            mediaType: "image",
            query,
            searchRoute: "fetchUnsplashImages",
          }
        );

        const imgResp = await withTimeout(
          fetch(imgUrl),
          10000,
          `Unsplash image download scene ${sceneIndex}`
        );
        if (!imgResp.ok) continue;
        const imgBuf = Buffer.from(await imgResp.arrayBuffer());
        if (imgBuf.length < 5000) continue;
        fs.writeFileSync(imgPath, imgBuf);

        const portrait =
          Boolean(opts.personPortrait) ||
          /portrait|face|headshot/i.test(query) ||
          /portrait|face|headshot/i.test(images[i].alt_description ?? "");
        await stillImageToVideo(
          imgPath,
          outPath,
          duration,
          `Unsplash image to video scene ${sceneIndex}`,
          portrait,
          sceneIndex
        );
        try { fs.unlinkSync(imgPath); } catch { /**/ }

        if (fs.existsSync(outPath) && fs.statSync(outPath).size > 10_000) {
          opts.dedup?.usedImageUrls.add(urlKey);
          // RONDE 96: the file exists, so the download is a fact rather than an intention. Same helper the o
          // ther eleven providers use — it flips DOWNLOAD_STARTED to DOWNLOAD_SUCCEEDED on the record tagPat
          // hWithProviderAsset opened.
          recordProviderDownloadOutcome(opts.dedup?.sourcingCache, outPath, true);
          results.push(outPath);
          const label = images[i].alt_description || images[i].description || query;
          console.log(`[Pipeline] Scene ${sceneIndex}: Unsplash image added: ${label.slice(0, 60)}`);
        }
      } catch (err) {
        console.warn(`[Pipeline] Unsplash image ${i} failed scene ${sceneIndex}:`, (err as Error).message);
      }
    }
  } catch (err) {
    console.warn(`[Pipeline] Unsplash search failed for scene ${sceneIndex}:`, (err as Error).message);
  }
  return results;
}

/*
 * ─── 3c2b-yt. YouTube Data API Thumbnails — REMOVED ──────────────────────────
 *
 * fetchYouTubeThumbnails lived here. It called the YouTube Data API, took the still image from
 * each search result, and ran ffmpeg with `-loop 1 -i thumb.jpg … zoompan` to produce an .mp4 —
 * a slow pan across a promotional picture, then handed to adoptClip like any other clip. Four
 * ladders used it, and the research ladder returned its output under the "youtube_cc" source
 * label, which is the label the genuine video route uses.
 *
 * So a thumbnail could reach finalConcatInputs, and once there nothing — not the compose gate,
 * not the audit, not the [AssetUsageSummary] — could tell it apart from footage.
 *
 * FastVid uses YouTube for video it can cut a fragment out of. That route is intact and is the
 * only one left: searchYoutubeVideoCandidates finds videos, downloadYouTubeCCClip fetches the
 * real stream by videoId and trims it at clipStart, and fetchYouTubeCCClips opens the lineage
 * with that videoId as the provider asset id. A still has no fragment to cut.
 *
 * Removed rather than flagged off: a flag leaves the same picture one environment variable away
 * from the delivered video. ronde97YouTubeVideoOnly holds this grave shut.
 */

// ─── 3c2b. SerpAPI Google Images Search ────────────────────────────────────
// Searches Google Images via SerpAPI for celebrity/person-specific photos.
// Ideal for finding real photos of people mentioned in the narration.
async function fetchSerpAPIImages(
  query: string,
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 2,
  fileTag = "",
  opts: {
    dedup?: VisualDedupState;
    personPortrait?: boolean;
    resultOffset?: number;
    beatIndex?: number;
    stillStyleContext?: StillStyleContext;
  } = {}
): Promise<string[]> {
  // RONDE 89: the provider gate. A query the contract refuses is not sent, and is
  // never repaired or substituted — the caller simply gets nothing.
  if (admitProviderQuery("serpapi", query, "fetchSerpAPIImages") === null) return [];
  if (!SERPAPI_KEY) return [];
  if (isSerpApiInCooldown()) return [];
  // Ensure workDir exists — it may have been cleaned up between pipeline stages
  fs.mkdirSync(workDir, { recursive: true });
  const results: string[] = [];
  try {
    const searchUrl = new URL('https://serpapi.com/search.json');
    searchUrl.searchParams.set('engine', 'google_images');
    searchUrl.searchParams.set('q', query);
    searchUrl.searchParams.set('safe', 'active');
    searchUrl.searchParams.set('num', '10');
    searchUrl.searchParams.set('ijn', '0');
    searchUrl.searchParams.set('api_key', SERPAPI_KEY);

    // withTimeout only races a timer and never aborts the request — a timed-out SerpAPI call
    // keeps running in the background and still counts against the metered quota.
    const searchResp = await providerLimiter("serpapi").run(() => fetchWithTimeout(
      searchUrl.toString(),
      15_000,
      `SerpAPI search scene ${sceneIndex}`
    ));
    if (!searchResp.ok) {
      markSerpApiSearchResult(false);
      console.warn(`[Pipeline] Scene ${sceneIndex}: SerpAPI error ${searchResp.status}`);
      return [];
    }
    markSerpApiSearchResult(true);
    const searchData = await searchResp.json() as {
      images_results?: Array<{
        original?: string;
        thumbnail?: string;
        title?: string;
      }>;
    };

    const offset = opts.resultOffset ?? 0;
    const images = (searchData.images_results || []).slice(offset, offset + count * 4);
    if (!images.length) return [];

    let downloaded = 0;
    for (let i = 0; i < images.length && downloaded < count; i++) {
      const imgUrl = images[i].original || images[i].thumbnail;
      if (!imgUrl) continue;
      const urlKey = normalizeImageSourceUrl(imgUrl);
      if (opts.dedup?.usedImageUrls.has(urlKey)) continue;
      /**
       * RONDE 140 — which SITE this picture is on, decided before the request goes out.
       *
       * This is not a licence check and there is none on this route: FastVid has never asked a
       * rights question of a Google Images result and still does not. What it refuses is the
       * material that was already going to fail — a watermarked agency comp (the baked-text
       * detector's job, one download later) and a re-host with no findable origin — plus whatever
       * the operator has excluded through OPEN_WEB_BLOCKED_DOMAINS / OPEN_WEB_ALLOWED_DOMAINS.
       *
       * Placed above the extension checks so that a host refusal is counted even for URLs the
       * next few lines would have dropped anyway: the policy report's `considered` has to mean
       * "results this policy looked at", not "results that happened to reach it".
       */
      const webDecision = openWebSourceDecision({ url: imgUrl });
      noteOpenWebDecision(opts.dedup?.openWebPolicyStats, webDecision);
      if (!webDecision.allowed) {
        console.log(
          formatOpenWebReject({ sceneIndex, beatIndex: opts.beatIndex, decision: webDecision })
        );
        continue;
      }
      // Skip SVG, GIF, and non-image URLs
      const lowerUrl = imgUrl.toLowerCase();
      if (lowerUrl.endsWith('.svg') || lowerUrl.endsWith('.gif') || lowerUrl.endsWith('.webp')) continue;
      if (!lowerUrl.includes('jpg') && !lowerUrl.includes('jpeg') && !lowerUrl.includes('png') &&
          !lowerUrl.match(/\.(jpg|jpeg|png)(\?|$)/i) && !lowerUrl.match(/image\/(jpeg|png)/i)) {
        // Allow if URL doesn't have a bad extension (many CDN URLs have no extension)
        if (lowerUrl.endsWith('.svg') || lowerUrl.endsWith('.gif')) continue;
      }

      try {
        const tag = fileTag ? `${fileTag}_` : "";
        const imgPath = path.join(workDir, `scene_${sceneIndex}_${tag}serp_${i}.jpg`);
        /**
         * RONDE 96 — this provider's assets enter the ledger like every other provider's.
         *
         * These five fetchers wrote their file straight to workDir and handed the path on, so the
         * clip only ever reached the ledger later, through clipAdoptAudit's "adoption of a clip
         * the ledger has never seen" branch — which deliberately records NO provider, because
         * guessing one from a filename is exactly what RONDE 86 removed. The result was honest and
         * useless: every Pexels, Unsplash, SerpAPI, Openverse and YouTube-thumbnail asset counted
         * as UNVERIFIED however normally it had arrived.
         *
         * tagPathWithProviderAsset is the same entry point the other eleven providers use, called
         * at the same moment: provider name, the provider's own id and the destination path all in
         * hand, straight from the API response. It opens the record and files DOWNLOAD_STARTED.
         */
        /**
         * RONDE 96 (§4) — SerpAPI is the one provider here with no asset id to keep.
         *
         * Its images_results rows carry `original`, `thumbnail` and `title`, and nothing else: no
         * id, no stable key. So the identity used is the normalised source URL, which is the
         * asset's own canonical location rather than something invented — not a hash, not the
         * filename, not the loop index. The URL is what SerpAPI itself identifies the image by.
         */
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_${tag}serp_${i}.mp4`),
          "serpapi",
          urlKey,
          opts.dedup?.sourcingCache,
          {
            sceneIndex,
            beatIndex: opts.beatIndex,
            sourceUrl: imgUrl,
            title: images[i].title,
            mediaType: "image",
            query,
            searchRoute: "fetchSerpAPIImages",
          }
        );

        const dl = await downloadToFileStreaming(
          imgUrl,
          imgPath,
          12_000,
          `SerpAPI image download scene ${sceneIndex}`,
          {
            headers: {
              'User-Agent': 'Mozilla/5.0 (compatible; Fastvid/1.0)',
              'Accept': 'image/jpeg,image/png,image/*',
            },
          },
          MAX_IMAGE_DOWNLOAD_BYTES
        ).catch(() => null);
        if (!dl || !dl.response.ok || dl.bytesWritten === null) continue;
        // Validate content-type: must be an image, not HTML/text
        const contentType = dl.response.headers.get('content-type') || '';
        if (contentType.includes('text/') || contentType.includes('application/') || contentType.includes('html')) {
          try { fs.unlinkSync(imgPath); } catch { /* ignore */ }
          continue;
        }
        // Skip tiny images (likely placeholders)
        if (dl.bytesWritten < 15_000) { try { fs.unlinkSync(imgPath); } catch { /* ignore */ } continue; }
        // Validate magic bytes: JPEG (FFD8FF) or PNG (89504E47)
        const magicFd = fs.openSync(imgPath, "r");
        const magic = Buffer.alloc(4);
        fs.readSync(magicFd, magic, 0, 4, 0);
        fs.closeSync(magicFd);
        const isJpeg = magic[0] === 0xFF && magic[1] === 0xD8 && magic[2] === 0xFF;
        const isPng = magic[0] === 0x89 && magic[1] === 0x50 && magic[2] === 0x4E && magic[3] === 0x47;
        if (!isJpeg && !isPng) { try { fs.unlinkSync(imgPath); } catch { /* ignore */ } continue; }

        await stillImageToVideo(
          imgPath,
          outPath,
          duration,
          `SerpAPI image to video scene ${sceneIndex}`,
          Boolean(opts.personPortrait),
          sceneIndex,
          opts.beatIndex ?? 0,
          opts.stillStyleContext
        );
        try { fs.unlinkSync(imgPath); } catch { /* ignore */ }
        if (fs.existsSync(outPath) && fs.statSync(outPath).size > 1_000) {
          opts.dedup?.usedImageUrls.add(urlKey);
          // RONDE 96: the file exists, so the download is a fact rather than an intention. Same helper the o
          // ther eleven providers use — it flips DOWNLOAD_STARTED to DOWNLOAD_SUCCEEDED on the record tagPat
          // hWithProviderAsset opened.
          recordProviderDownloadOutcome(opts.dedup?.sourcingCache, outPath, true);
          results.push(outPath);
          downloaded++;
          // Problem 1/2 (production render finding): SerpAPI already returns the source page's
          // title per result — independent, provider-authored text, not derived from our own
          // search query — but it was discarded entirely. Registering it here (same
          // clipAnnotationMeta mechanism adoptBestCelebrityClip already uses for the
          // CelebrityClipCandidate providers) is what lets adoptClip's scriptImageFallback
          // relevance floor and the entity-evidence gate actually check these images instead of
          // adopting them on zero signal.
          if (opts.dedup && images[i].title) {
            const existing = opts.dedup.clipAnnotationMeta.get(outPath) ?? {};
            opts.dedup.clipAnnotationMeta.set(outPath, {
              ...existing,
              providerText: { title: images[i].title },
            });
          }
          console.log(`[Pipeline] Scene ${sceneIndex}: SerpAPI image added: ${images[i].title || imgUrl.slice(0, 60)}`);
        }
      } catch (err) {
        console.warn(`[Pipeline] SerpAPI image ${i} failed for scene ${sceneIndex}:`, err);
      }
    }
  } catch (err) {
    console.warn(`[Pipeline] SerpAPI search failed for scene ${sceneIndex}:`, err);
  }
  return results;
}

// ─── 3a. Pad short clip by concatenating additional matching clips ─────────────
/**
 * When an adopted clip is shorter than holdSec, keeps fetching more clips from
 * the archive and concatenating them until the target duration is filled (or no
 * more clips are available).  Returns the path of the combined clip, or null if
 * padding isn't needed or all attempts fail.
 */
async function padShortClipWithNext(
  clipPath: string,
  holdSec: number,
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  videoTitle: string | undefined,
  dedup: VisualDedupState,
  semanticProfile?: BeatSemanticProfile
): Promise<string | null> {
  // RONDE 100B: proof in scope before any provider is asked — see withBeatProvenance.
  return withBeatProvenance(beat, scene, () => padShortClipWithNextInner(clipPath, holdSec, beat, scene, workDir, videoTitle, dedup, semanticProfile));
}

async function padShortClipWithNextInner(
  clipPath: string,
  holdSec: number,
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  videoTitle: string | undefined,
  dedup: VisualDedupState,
  semanticProfile?: BeatSemanticProfile
): Promise<string | null> {
  const firstDur = await probeVideoDurationSec(clipPath);
  if (holdSec - firstDur < 0.3) return null; // already close enough

  const segments: string[] = [clipPath];
  let filledSec = firstDur;
  const MAX_EXTRA_CLIPS = 5;

  for (let attempt = 1; attempt <= MAX_EXTRA_CLIPS && holdSec - filledSec >= 0.3; attempt++) {
    const remaining = holdSec - filledSec;
    console.log(
      `[PadClip] s${scene.index}b${beat.index} attempt ${attempt}: filled ${filledSec.toFixed(2)}s / ${holdSec.toFixed(2)}s — fetching ${remaining.toFixed(2)}s more`
    );

    let fillPath = await fetchCuratedArchiveBeatClip(
      beat,
      scene,
      workDir,
      scene.index,
      remaining,
      dedup.usedCuratedAssetIds,
      dedup.usedCuratedStorageUrls,
      videoTitle,
      curatedInterviewBudget(dedup),
      curatedImageBudget(dedup),
      undefined,
      { relaxed: true, videoLength: dedup.videoLength, assetsCache: dedup.archiveAssetsCache }
    );
    // Fall back to Pexels when the curated archive has nothing more
    if (!fillPath || !(await isValidVideoFile(fillPath))) {
      const pexQuery = beat.searchQuery || scene.pexelsQuery || beat.text.split(/\s+/).slice(0, 3).join(" ");
      const pexPaths = await fetchPexelsClips(
        pexQuery, remaining, workDir, scene.index, 1, undefined, false,
        `pad_pex_s${scene.index}b${beat.index}_${attempt}`, dedup.usedPexelsIds
      );
      fillPath = pexPaths[0] ?? null;
    }
    if (!fillPath || !(await isValidVideoFile(fillPath))) break;

    const trimmedFill = path.join(workDir, `pad_fill_s${scene.index}b${beat.index}_${attempt}_${Date.now()}.mp4`);
    try {
      await withSceneFetchTimeout(
        () => exec(
          `${FFMPEG_BIN} -y -i "${fillPath}" -t ${remaining.toFixed(3)} -vf "${STANDARD_VF}" ` +
          `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset veryfast -crf 18 -an -pix_fmt yuv420p "${trimmedFill}"`
        ),
        25_000,
        `padShortClip-trim-${attempt} s${scene.index}b${beat.index}`
      );
    } catch { break; }
    if (!(await isValidVideoFile(trimmedFill))) break;

    segments.push(trimmedFill);
    filledSec += await probeVideoDurationSec(trimmedFill);
  }

  if (segments.length < 2) return null; // nothing was added

  // Concat all segments into one file
  const combined = path.join(workDir, `pad_combined_s${scene.index}b${beat.index}_${Date.now()}.mp4`);
  const listFile = combined.replace(".mp4", "_list.txt");
  fs.writeFileSync(listFile, segments.map((f) => `file '${f}'`).join("\n") + "\n");
  try {
    await withSceneFetchTimeout(
      () => exec(`${FFMPEG_BIN} -y -f concat -safe 0 -i "${listFile}" -c copy -avoid_negative_ts make_zero "${combined}"`),
      30_000,
      `padShortClip-concat s${scene.index}b${beat.index}`
    );
  } catch {
    try {
      await withSceneFetchTimeout(
        () => exec(
          `${FFMPEG_BIN} -y -f concat -safe 0 -i "${listFile}" -vf "${STANDARD_VF}" ` +
          `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset veryfast -crf 18 -an -pix_fmt yuv420p "${combined}"`
        ),
        40_000,
        `padShortClip-concat-reencode s${scene.index}b${beat.index}`
      );
    } catch { return null; }
  } finally {
    try { fs.unlinkSync(listFile); } catch {}
  }

  if (!(await isValidVideoFile(combined))) return null;

  const combinedDur = await probeVideoDurationSec(combined);
  console.log(
    `[PadClip] s${scene.index}b${beat.index}: ${segments.length} clips → ${combinedDur.toFixed(2)}s (target ${holdSec.toFixed(2)}s)`
  );
  return combined;
}

// ─── 3b. Extend Last Real Clip ───────────────────────────────────────────────
/**
 * Loop/extend the last adopted real clip to fill `beatDuration` seconds.
 * Used as a last resort before color fallback — always better than a solid color.
 */
async function extendLastClip(
  lastClipPath: string,
  beatDuration: number,
  sceneIndex: number,
  beatIndex: number,
  workDir: string,
  /**
   * RONDE 167 — the extension is a NEW file made from a known clip, and nothing said so.
   *
   * `linkDerivedPath`'s own contract is "call it at every site that writes a new file from an
   * existing clip"; this site never did. Two things followed. An adopted extension reached the
   * manifest through `recordClipAdopt`'s hole-filling branch, which opens a record with NO
   * provider — so real Library of Congress footage, looped, was reported UNVERIFIED. And RONDE
   * 165's `extended_rejected` outcome was written against a path the ledger could not resolve,
   * so it silently wrote nothing at all: proven by test, zero events.
   *
   * Linking it fixes both. The extension inherits its source's proven provider — which is not a
   * guess, the pipeline built the file itself from that clip — and the refusal now lands.
   */
  lineage?: VisualSourceLedger
): Promise<string | null> {
  if (!lastClipPath || !fs.existsSync(lastClipPath)) return null;
  if (isPipelineFallbackClip(lastClipPath)) return null;
  if (!(await isValidVideoFile(lastClipPath))) return null;
  const safeDuration = Math.min(Math.max(beatDuration, 1), 60);
  const out = path.join(workDir, `extend_s${sceneIndex}b${beatIndex}_${Date.now()}.mp4`);
  /**
   * RONDE 167 — link the extension to the clip it was looped from, without retiring that clip.
   *
   * `supersedesParent: false` because both files are live: the source under its own beat and the
   * extension under the next. See linkDerivedPath for why the default is the other way.
   */
  const linkExtension = (): void => {
    lineage?.linkDerivedPath(out, lastClipPath, "TRANSFORMED", {
      reason: "extendLastClip",
      supersedesParent: false,
    });
  };

  // A raw stream_loop repeats the exact same footage with zero variation. Over a long hold
  // (this path only runs when nothing else could be found/padded for the beat) that reads as
  // a frozen frame, especially for slow archival footage that has little inherent motion —
  // and it visibly jump-cuts every time the loop restarts. The clip must never actually freeze
  // on a single still frame (that reads as even more static, not less) — instead, keep the
  // looped footage's own frames playing normally and layer a slow, continuous zoom on top
  // (d=1 in zoompan advances one output frame per one real input frame, so nothing is held
  // static) — a moving crop window over real, changing footage, not a stand-in photo.
  try {
    const totalFrames = Math.round(safeDuration * 25);
    const zoomEnd = 1.12;
    const zoomStep = (zoomEnd - 1) / Math.max(1, totalFrames);
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -stream_loop -1 -i "${lastClipPath}" -t ${safeDuration.toFixed(2)} ` +
        `-vf "scale=${VIDEO_WIDTH * 2}:${VIDEO_HEIGHT * 2}:force_original_aspect_ratio=increase,crop=${VIDEO_WIDTH * 2}:${VIDEO_HEIGHT * 2},` +
        `zoompan=z='min(zoom+${zoomStep.toFixed(8)},${zoomEnd})':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=1:s=${VIDEO_WIDTH}x${VIDEO_HEIGHT}:fps=25" ` +
        `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset veryfast -crf 20 -an -pix_fmt yuv420p -avoid_negative_ts make_zero "${out}"`
      ),
      30_000,
      `extendLastClip-zoom s${sceneIndex}b${beatIndex}`
    );
    if (await isValidVideoFile(out)) {
      console.log(`[Retrieval] s${sceneIndex}b${beatIndex}: extendLastClip (zoom, moving) ${path.basename(lastClipPath)} → ${safeDuration.toFixed(1)}s`);
      linkExtension();
      return out;
    }
  } catch {
    /* zoompan-on-loop failed — fall through to raw loop below */
  }

  try {
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -stream_loop -1 -i "${lastClipPath}" -t ${safeDuration.toFixed(2)} -c copy -avoid_negative_ts make_zero "${out}"`
      ),
      20_000,
      `extendLastClip s${sceneIndex}b${beatIndex}`
    );
    if (await isValidVideoFile(out)) {
      console.log(`[Retrieval] s${sceneIndex}b${beatIndex}: extendLastClip ${path.basename(lastClipPath)} → ${safeDuration.toFixed(1)}s`);
      linkExtension();
      return out;
    }
  } catch {
    // copy failed — try re-encode at low quality
    try {
      await withSceneFetchTimeout(
        () => exec(
          `${FFMPEG_BIN} -y -stream_loop -1 -i "${lastClipPath}" -t ${safeDuration.toFixed(2)} -c:v libx264 ${pipelineFfmpegThreadFlag()} -preset ultrafast -crf 28 -an "${out}"`
        ),
        25_000,
        `extendLastClip-reencode s${sceneIndex}b${beatIndex}`
      );
      if (await isValidVideoFile(out)) {
        console.log(`[Retrieval] s${sceneIndex}b${beatIndex}: extendLastClip (re-encode) ${path.basename(lastClipPath)} → ${safeDuration.toFixed(1)}s`);
        linkExtension();
        return out;
      }
    } catch { /* give up */ }
  }
  return null;
}

// ─── 3c. Color Fallback (last resort — unique path per beat so montage never blocks on dedup) ─
/**
 * Production fix (Hitler-render finding — Problem 3/11): this used to cap at 90s — a single
 * static text card was legally allowed to dominate up to a minute and a half of continuous
 * screen time, which is exactly what a real render showed once real visuals ran out around the
 * 9s mark. Capped at the pipeline's own documented per-shot ceiling (archiveVisualMaxClipSec,
 * 5-8s) instead, so a caller that needs to cover a longer gap is forced to call this repeatedly
 * (varying color/text per slot, as appendGuaranteedSceneClips already does) rather than getting
 * one giant placeholder.
 */
export function guaranteedTextOverlayDurationSec(duration: number): number {
  return Math.min(Math.max(duration, 3), archiveVisualMaxClipSec());
}

/**
 * RONDE 50: which rung of the guaranteed ladder actually answered.
 *
 * The first two return real media — curated archive footage and a Commons file. The last two are
 * synthetic cards this pipeline drew itself. Every rung writes to the SAME output path, so this
 * cannot be recovered from the filename afterwards, and until now every guaranteed clip was
 * recorded in the adopt audit as "fallback" regardless. That inflated fallbackBeats, which
 * assertVisualCoverageExportGate reads as `fallbackBeats / beatsFilled > 0.5` — so a render the
 * rescue ladder saved with real footage could be refused for being mostly placeholders.
 */
export type GuaranteedClipTier = "topical" | "wikimedia" | "text_overlay" | "color_fallback";

/** Out-parameter so the tier can be reported without changing this function's return type. */
export type GuaranteedTierOut = { tier?: GuaranteedClipTier };

/**
 * The adopt-audit source for a guaranteed clip, chosen by the rung that answered.
 *
 * Deliberately reuses source labels clipAdoptAudit already classifies — "rescue_archive" counts
 * as archive, "wikimedia" as wiki, "fallback" as fallback. No new vocabulary, no new field, and
 * the gate's threshold is untouched: it simply stops being told that real footage is a placeholder.
 * An unknown tier (a caller that passed no out-parameter) keeps the old "fallback" answer.
 */
export function guaranteedAdoptSource(tier: GuaranteedClipTier | undefined): string {
  switch (tier) {
    case "topical":
      return "rescue_archive";
    case "wikimedia":
      return "wikimedia";
    default:
      return "fallback";
  }
}

/** True when the guaranteed ladder produced a synthetic card rather than real media. */
export function isPlaceholderGuaranteedTier(tier: GuaranteedClipTier | undefined): boolean {
  return tier !== "topical" && tier !== "wikimedia";
}

/**
 * RONDE 100B, second audit — the guaranteed ladder reaches Wikimedia too.
 *
 * The first audit listed the fetchers it knew about and missed fetchWikimediaImages entirely, so
 * this route never showed up: generateGuaranteedBeatClip asks Wikimedia for one more real image
 * before it gives up and draws a card. Thirteen callers reach it, including composeSceneVideoInner
 * and _runVideoPipelineInner — none of them inside a beat scope.
 *
 * It carries the beat's TEXT rather than the beat and scene objects, which is enough: the proof
 * is built from the narration. When beatText is empty there is no proof and the gate refuses the
 * query, which is the correct outcome rather than a missing one.
 */
export async function generateGuaranteedBeatClip(
  sceneIndex: number,
  slotIndex: number,
  duration: number,
  workDir: string,
  beatText?: string,
  usedAssetIds?: Set<number>,
  usedStorageUrls?: Set<string>,
  tierOut?: GuaranteedTierOut,
  /**
   * RONDE 103 phase 7 — the guaranteed ladder reaches real pictures, so it is judged too.
   *
   * The ladder's first two rungs (`topical`, `wikimedia`) fetch genuine imagery and put it under
   * this beat's narration; those are claims about the world and get the same gate every other
   * route gets. Its last two (`text_overlay`, `color_fallback`) draw a card that depicts nothing,
   * and asking a vision model whether a grey rectangle belongs under a line of narration is
   * money spent to learn nothing.
   *
   * The check sits here, on the tier the ladder actually returned, rather than at the twelve
   * call sites — a new caller cannot forget it, and the choice of which tiers are exempt is
   * stated once. A refused clip is NOT swapped for something else: this function's whole contract
   * is that it always returns a path, so the refusal is recorded on the ledger and the compose
   * barrier is what acts on it.
   */
  relevance?: {
    dedup: VisualDedupState;
    scene?: { text?: string };
    videoTitle?: string;
    /**
     * RENDER 563 — THE BEAT THIS PICTURE IS FOR, which is not always the slot it was fetched in.
     *
     * ── What eight renders measured ───────────────────────────────────────────────────────────
     *
     *     [BeatVisual] … verification=never_asked reason=real_footage_never_judged source=rescue_archive
     *
     * 79 of those lines across 8 renders, 49 of them on this ladder's own `rescue_archive` rung.
     * Read literally they say the picture editor was never asked — and that is not what happened.
     * It WAS asked. Its answer was filed under a different number.
     *
     * `slotIndex` is a fetch slot, and several callers deliberately offset it away from the real
     * beat: `2000 + slot` to keep a synthetic entry from colliding with a genuine one,
     * `beat.index + attempt * 100` to keep retries apart, `si` where the beat is `slotBeatIndex`.
     * Each of those callers then records the ADOPTION under the real beat — and the verdict stayed
     * behind on the slot number, in a drawer `verificationForBeat` never opens.
     *
     * ── Why that is worse than never asking ──────────────────────────────────────────────────
     *
     * A refusal filed under slot 2000+n cannot stop an adoption recorded under beat n. The gate
     * looked, said no, and the pipeline adopted the picture anyway — because nothing downstream
     * could find the answer that already existed.
     *
     * The rule this restores is not new. RONDE 34 wrote it on the adopt side, at the call site on
     * line 38860: "record the beat this slot was fetched FOR, not the slot number — the audit is
     * read back as a clip->beat mapping." It was applied to one of the two records and forgotten
     * on the other.
     *
     * Absent means "the slot IS the beat", which is true of the seven call sites that already
     * matched, so those are unchanged.
     */
    beatIndex?: number;
  },
): Promise<string> {
  const tier: GuaranteedTierOut = tierOut ?? {};
  const clip = await withBeatProvenance({ text: beatText ?? "" }, {}, () =>
    generateGuaranteedBeatClipInner(sceneIndex, slotIndex, duration, workDir, beatText, usedAssetIds, usedStorageUrls, tier)
  );
  if (relevance && clip) {
    /** The beat the caller will record the adoption under — see the note on `beatIndex` above. */
    const verdictBeatIndex = relevance.beatIndex ?? slotIndex;
    await judgeBeatClipRelevance(relevance.dedup, sceneIndex, verdictBeatIndex, {
      clipPath: clip,
      contentKey: clipContentKey(clip),
      ctx: {
        sceneIndex,
        beatIndex: verdictBeatIndex,
        beatText: beatText ?? "",
        sceneText: relevance.scene?.text,
        videoTitle: asVideoTitleString(relevance.videoTitle) || undefined,
      },
      workDir,
      state: relevance.dedup.beatImageGate,
      ledger: relevance.dedup.beatRelevance,
      route: `guaranteed:${tier.tier ?? "unknown"}`,
      placeholder: isPlaceholderGuaranteedTier(tier.tier),
    });
  }
  return clip;
}

async function generateGuaranteedBeatClipInner(
  sceneIndex: number,
  slotIndex: number,
  duration: number,
  workDir: string,
  beatText?: string,
  // RONDE 32 (FIX B): optional, caller-owned exclusion sets so a rescue batch that calls this
  // function N times in a row does not get the same curated asset N times. Defaulting to fresh
  // sets keeps every existing caller (which passes neither) behaving exactly as before.
  usedAssetIds?: Set<number>,
  usedStorageUrls?: Set<string>,
  // RONDE 50: optional; filled in with the rung that answered. Callers that omit it are
  // byte-for-byte unaffected.
  tierOut?: GuaranteedTierOut,
): Promise<string> {
  const outputPath = path.join(workDir, `scene_${sceneIndex}_slot${slotIndex}_guaranteed.mp4`);
  const excludeAssetIds = usedAssetIds ?? new Set<number>();
  const excludeStorageUrls = usedStorageUrls ?? new Set<string>();

  // Escalation ladder — before EVER falling back to text-overlay/color, try a series of
  // widening real-search queries: beat-specific entity/event/location first (most relevant),
  // then the overall video topic, then the richer VideoVisualContext (people/locations/period),
  // then one more real provider (Wikimedia). Content-type-agnostic by construction: none of
  // these tiers branch on isHistorical/primaryPerson — buildBeatQueryEscalationTiers already
  // extracts event/location/object cues generically (proven in production by the beat-level
  // Wikimedia rescue ladder above, which uses the same helper for every beat regardless of
  // topic), and the topic/context tiers use whatever videoTitle/videoVisualContext the render
  // already built for itself. This function has no VisualDedupState parameter (it's called from
  // compose-time rescue paths that only have scene/slot/duration/workDir), so the render-scoped
  // topic/context accessors (get_activeVideoTopic/get_activeVideoVisualContext, AsyncLocalStorage
  // — same pattern already used for videoTopic) carry the context here instead of threading a
  // new parameter through every one of this function's callers.
  const topic = get_activeVideoTopic();
  const videoCtx = get_activeVideoVisualContext();
  const topicQuery = topic?.primaryPerson || topic?.videoTitle;

  const tiers: string[] = [];
  if (beatText && beatText.trim().length > 3) {
    tiers.push(...buildBeatQueryEscalationTiers(beatText, topic?.primaryPerson, topic?.videoTitle));
  }
  if (topicQuery) tiers.push(topicQuery);
  if (videoCtx) {
    const ctxParts = [topic?.videoTitle, videoCtx.people[0], videoCtx.locations[0], videoCtx.period].filter(
      (s): s is string => Boolean(s && s.trim().length > 0)
    );
    if (ctxParts.length > 1) tiers.push(ctxParts.join(" "));
  }
  const searchTiers = Array.from(
    new Set(tiers.map((q) => q.replace(/\s+/g, " ").trim()).filter((q) => q.length > 3))
  ).slice(0, 4);

  for (const query of searchTiers) {
    // RONDE 33: per-tier, so a failed tier cannot leave a previous tier's asset identity behind.
    const pickedOut: { assetId?: number; storageUrl?: string } = {};
    try {
      const topicalClip = await withSceneFetchTimeout(
        () => fetchCuratedArchiveBeatClip(
          { keywords: [query], text: query, index: slotIndex },
          { text: query },
          workDir,
          sceneIndex,
          duration,
          excludeAssetIds,
          excludeStorageUrls,
          topic?.videoTitle,
          undefined,
          undefined,
          undefined,
          { relaxed: true, pickedOut }
        ),
        10_000,
        `Guaranteed beat topical fallback s${sceneIndex}slot${slotIndex} "${query.slice(0, 40)}"`
      );
      if (topicalClip && (await isValidVideoFile(topicalClip))) {
        // RONDE 32 (FIX B): fetchCuratedArchiveBeatClip only READS these sets (it filters on
        // usedAssetIds.has(...) while ranking) — marking is a separate, caller-owned step, which
        // is why every other adoption route in this file calls markCuratedAssetUsed itself.
        // Without this line a shared exclusion set stays empty forever and the next slot picks
        // the same top-scoring asset again: render 529 filled all twelve of scene 1's rescue
        // slots with curated asset #55988 and the compose-time content dedup threw eleven away.
        // RONDE 33: the storageUrl comes from the asset the sourcing layer actually picked
        // (pickedOut), never re-derived from the filename — the filename only ever carried the
        // id. Without it usedStorageUrls stayed empty and two rows sharing one storage file
        // could both be adopted into the same rescue batch.
        markCuratedAssetUsed(topicalClip, excludeAssetIds, excludeStorageUrls, pickedOut.storageUrl);
        console.log(`[Pipeline] Scene ${sceneIndex} slot ${slotIndex}: topical archive fallback OK (${query})`);
        if (tierOut) tierOut.tier = "topical";
        return topicalClip;
      }
    } catch {
      /* archive search failed/timed out for this tier — escalate to the next tier */
    }
  }

  // One more real provider before giving up on real footage entirely (isolated failure — a
  // Wikimedia cooldown/outage is handled internally by fetchWikimediaImages and never blocks
  // the text-overlay/color fallback below).
  const wikiQuery = searchTiers[0] ?? topicQuery;
  if (wikiQuery) {
    try {
      const wikiClips = await withSceneFetchTimeout(
        // RONDE 33: two changes, both about one rescue batch not answering every slot with the
        // same picture. The file tag now carries the slot, so two slots cannot write to (and
        // silently overwrite) the same scene_N_guaranteed_wiki_wiki_0.mp4; and the batch's URL
        // set is passed through so a Commons file taken by an earlier slot is skipped here.
        () => fetchWikimediaImages(
          wikiQuery, duration, workDir, sceneIndex, 1, `guaranteed_wiki_s${slotIndex}`,
          { excludeUrls: excludeStorageUrls }
        ),
        10_000,
        `Guaranteed beat wikimedia fallback s${sceneIndex}slot${slotIndex}`
      );
      const wikiClip = wikiClips?.[0];
      if (wikiClip && (await isValidVideoFile(wikiClip))) {
        console.log(`[Pipeline] Scene ${sceneIndex} slot ${slotIndex}: Wikimedia topical fallback OK (${wikiQuery})`);
        if (tierOut) tierOut.tier = "wikimedia";
        return wikiClip;
      }
    } catch {
      /* Wikimedia failed/timed out — fall through to text-overlay/color below */
    }
  }

  // Try text-over-gradient when we have context — more informative than a plain color
  if (beatText && beatText.trim().length > 3) {
    try {
      const safeText = sanitizeForDrawtextStrict(beatText, 90);
      const colors = ["3a4a5e", "4a5a6e", "3a5a6e", "4a4a5e"];
      // RONDE 154: the same sequence counter, for the same reason — every placeholder beat in
      // one scene used to get the identical colour and merge into a single unchanging picture.
      const textVariant = colorFallbackSequence++;
      const color = colors[textVariant % colors.length];
      /**
       * RONDE 155 — the same drifting background as the plain card, for the same reason.
       *
       * This card's only movement was the text fading in over its first 0.4s; every frame after
       * that was identical. A failure here falls through to generateColorFallback below, so a box
       * without the gradients source still gets a card.
       */
      const textColorB = colors[(textVariant + 1) % colors.length];
      const safeDur = guaranteedTextOverlayDurationSec(duration);
      await withSceneFetchTimeout(
        () => exec(
          `${FFMPEG_BIN} -y -f lavfi -i "gradients=s=${VIDEO_WIDTH}x${VIDEO_HEIGHT}:c0=0x${color}:c1=0x${textColorB}:speed=0.20:r=25" -t ${safeDur} ` +
          `-vf "drawtext=text='${safeText}':fontcolor=white:fontsize=52:x=(w-text_w)/2:y=(h-text_h)/2:` +
          `shadowcolor=black:shadowx=3:shadowy=3:alpha='if(lt(t,0.4),t/0.4,1)'" ` +
          `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset ultrafast -pix_fmt yuv420p -an "${outputPath}"`
        ),
        30_000,
        `Guaranteed beat text overlay s${sceneIndex}b${slotIndex}`
      );
      if (await isValidVideoFile(outputPath)) {
        console.log(`[Pipeline] Scene ${sceneIndex} slot ${slotIndex}: text-overlay fallback OK`);
        if (tierOut) tierOut.tier = "text_overlay";
        return outputPath;
      }
    } catch { /* fall through to plain color */ }
  }
  try {
    const card = await generateColorFallback(sceneIndex * 1000 + slotIndex, duration, workDir, outputPath);
    if (tierOut) tierOut.tier = "color_fallback";
    return card;
  } catch (err) {
    console.warn(
      `[Pipeline] Scene ${sceneIndex} slot ${slotIndex}: guaranteed clip fallback failed:`,
      (err as Error).message?.slice(0, 80)
    );
    // Whatever is on disk here came from a partially-completed placeholder attempt, never from a
    // real provider — the two real rungs return early and never reach this catch.
    if (fs.existsSync(outputPath) && (await isValidVideoFile(outputPath))) {
      if (tierOut) tierOut.tier = "color_fallback";
      return outputPath;
    }
    throw err;
  }
}

/**
 * RONDE 169 — a scene whose picture list is rebuilt must say what became of the old one.
 *
 * ── What render 555 measured ─────────────────────────────────────────────────────────────────
 *
 *     [OutcomeInvariant] FAILED selectedWithoutOutcome=18
 *     [AssetLifecycleAudit] unresolvedByRoute backfill=6 rescue=6 fallback=4 primary=2
 *
 * Eighteen assets chosen, delivered nowhere, explained by nothing — and every one of them carried
 * `provider=UNVERIFIED`, the signature of `recordClipAdopt`'s hole-filling branch on the backfill,
 * rescue and fallback routes.
 *
 * Twelve places assign `sceneVisualResults[i]`. Several rebuild a scene's list from scratch — a
 * coverage repair, a strict-voice refill, a guaranteed fill after an empty scene. The clips of the
 * PREVIOUS list were adopted and then simply stopped being referenced: no gate refused them,
 * nothing replaced them one for one, and the array they lived in was overwritten. That is the
 * common cause behind all eighteen, and it is one cause rather than eighteen.
 *
 * ── Why here and not in the audit ────────────────────────────────────────────────────────────
 *
 * The audit could derive this at the end — "adopted, not delivered, therefore dropped" — and that
 * would make `unresolved` unfalsifiable: every hole would explain itself. The code that drops the
 * clip is the code that knows, so it is the code that says so.
 *
 * `hasOutcomeFor` keeps it honest in the other direction. A clip a compose gate already refused
 * keeps that ending; this never overwrites a specific reason with a vaguer one, and it is safe to
 * call at every assignment site including the ones that only refine a list.
 */
function noteSceneClipsResourced(
  dedup: VisualDedupState | undefined,
  previous: { clips?: string[] } | undefined,
  next: { clips?: string[] } | undefined,
  context: string
): void {
  const lineage = dedup?.sourcingCache?.lineage;
  if (!lineage || !previous?.clips?.length) return;
  const kept = new Set(next?.clips ?? []);
  for (const clip of previous.clips) {
    if (!clip || kept.has(clip)) continue;
    const contentKey = clipContentKey(clip);
    // Already explained by whoever dropped it — a compose gate, a duplicate, a validation swap.
    if (lineage.hasOutcomeFor(clip, contentKey)) continue;
    recordAssetOutcome(lineage, clip, "scene_resourced", context, contentKey);
  }
}

async function appendGuaranteedSceneClips(
  scene: Scene,
  workDir: string,
  clips: string[],
  beatDurations: number[],
  minClips: number,
  dedup?: VisualDedupState,
  existingBeatIndices?: number[]
): Promise<void> {
  const holdSec = Math.max(
    archiveVisualMinClipSec(),
    Math.min(archiveVisualMaxClipSec(), scene.duration / Math.max(1, minClips))
  );
  const seedCount = clips.length;
  let slot = clips.length;
  while (clips.length < minClips) {
    try {
      const tierOut: GuaranteedTierOut = {};
      const clip = await generateGuaranteedBeatClip(
        scene.index, slot, holdSec, workDir, scene.text?.slice(0, 90), undefined, undefined, tierOut,
        dedup ? { dedup, scene, beatIndex: 2000 + slot } : undefined
      );
      const key = clipContentKey(clip);
      if (!clips.some((c) => clipContentKey(c) === key)) {
        clips.push(clip);
        beatDurations.push(holdSec);
        // Audit-gap fix (same class as Round 17 + follow-up fixes): every other
        // generateGuaranteedBeatClip call site records its adoption so
        // assertVisualCoverageExportGate/canAddGuaranteedFallbackClip can see it. This
        // function's 5 callers all previously appended guaranteed clips straight into their
        // local `clips` array with no bookkeeping at all — additive, no change to selection.
        //
        // Review finding: `slot` is this array's own position counter (clips.length at start,
        // incrementing per guaranteed clip appended) — NOT a real narrative beat index. Callers
        // can now pass in a `clips` array pre-seeded with already-adopted real clips (see
        // refillSceneStrictVoiceMatch's "already attempted" branch), so `slot` can start above 0
        // and land on a number that coincides with a genuine beatIndex already used by one of
        // those real clips for this same scene. Recording the audit entry under that raw `slot`
        // could then overwrite the real clip's coverage classification with "fallback" even
        // though the real clip is still sitting untouched in `clips`. Offsetting into a range no
        // real narrative beat index ever reaches (matching the sentinel-slot pattern already used
        // by other guaranteed-fill call sites — 999/1001/8888/9999) keeps this purely-synthetic
        // audit entry from ever colliding with a real beat's entry.
        if (dedup) {
          // RONDE 50: the source now names the rung that answered, so a guaranteed clip that
          // came back with real archive/Commons media stops counting toward fallbackBeats.
          recordClipAdopt(
            dedup.clipAdoptAudit, scene.index, 2000 + slot, scene.text, clip,
            guaranteedAdoptSource(tierOut.tier)
          );
        }
      }
    } catch (err) {
      // Even the guaranteed clip's own color-fallback can exhaust every retry under severe
      // fork-pressure (all ffmpeg variants failing). Don't let one unlucky slot throw out of
      // this function — it runs inside a per-scene chain that's part of a Promise.all over every
      // scene, so an uncaught throw here fails the ENTIRE batch, not just this scene. Skip the
      // slot and let the scene proceed with whatever clips it already has.
      console.error(
        `[Pipeline] Scene ${scene.index} slot ${slot}: guaranteed clip totally unavailable, skipping:`,
        (err as Error).message?.slice(0, 150)
      );
    }
    slot++;
    if (slot > minClips + 8) break;
  }

  // Bug 1 fix (final hardening round): when the caller seeded `clips` with real clips that keep
  // their own narrative beatIndex (parallel `existingBeatIndices` — see
  // refillSceneStrictVoiceMatch's "already attempted" branch), those real beats can be scattered
  // anywhere in [0, minClips) instead of filling it contiguously from 0 — e.g. beat 1 and beat 3
  // real, beats 0 and 2 missing. The loop above only ever appends new guaranteed clips at the
  // END of `clips`, so the array would end up as [real-b1, real-b3, fallback, fallback] and the
  // montage would play both real clips before either fallback, instead of the narratively
  // correct [fallback-b0, real-b1, fallback-b2, real-b3]. Reassign each newly-appended guaranteed
  // clip to the next actually-missing beat index and re-sort the whole array back into narrative
  // beat order. Real clips are only ever repositioned here, never dropped or overwritten.
  if (existingBeatIndices && existingBeatIndices.length === seedCount && clips.length > seedCount) {
    const filled = new Set(existingBeatIndices);
    const missing: number[] = [];
    for (let beatIdx = 0; missing.length < clips.length - seedCount && beatIdx < minClips + 8; beatIdx++) {
      if (!filled.has(beatIdx)) missing.push(beatIdx);
    }
    const merged = existingBeatIndices
      .map((beatIndex, i) => ({ beatIndex, clip: clips[i], dur: beatDurations[i] }))
      .concat(
        clips.slice(seedCount).map((clip, i) => ({
          beatIndex: missing[i] ?? minClips + i,
          clip,
          dur: beatDurations[seedCount + i],
        }))
      )
      .sort((a, b) => a.beatIndex - b.beatIndex);
    clips.length = 0;
    beatDurations.length = 0;
    for (const entry of merged) {
      clips.push(entry.clip);
      beatDurations.push(entry.dur);
    }
  }
}

/**
 * RONDE 154 — two cards in a row must not be the same colour.
 *
 * The colour was `colors[Math.abs(seed) % colors.length]` with `seed = sceneIndex * 1000 +
 * slotIndex`. Video 551's scene 2 asked for slots 101, 102 and 302; the last two both landed on
 * palette index 6 and came out identically coloured. To `mpdecimate` that is not two cards, it is
 * ONE unchanging picture — which is how a 19.38s still appeared in a render whose longest single
 * card is about five seconds.
 *
 * ── Why a counter and not better arithmetic ──────────────────────────────────────────────────
 *
 * Slot numbers are tier markers, not a sequence: 101, 102, then 302. ANY linear function of the
 * slot collides whenever two slots differ by a multiple of the palette size, and 302 − 102 = 200
 * is. `(scene * 31 + slot) % 8` fails on exactly this case too — it was tried and measured.
 *
 * So the colour comes from how many cards have actually been made, which is the only quantity that
 * is guaranteed to advance by one between consecutive cards. Cross-scene interleaving under
 * parallel compose can shuffle WHICH colour a card gets; it cannot make two successive calls
 * return the same one, which is the property that matters.
 *
 * It changes nothing about what a card IS: still a placeholder in the audit, still counted in
 * fallbackRatio, still a beat with no footage behind it.
 */
let colorFallbackSequence = 0;

async function generateColorFallback(
  sceneIndex: number,
  duration: number,
  workDir: string,
  outputPath?: string,
  variantIndex?: number
): Promise<string> {
  fs.mkdirSync(workDir, { recursive: true });
  const out = outputPath ?? path.join(workDir, `scene_${sceneIndex}_fallback.mp4`);
  // Drawn ONCE here and passed down, so the counter advances once per card rather than once per
  // internal retry — and so the colour this function logs is the colour the encoder actually uses.
  const variant = variantIndex ?? colorFallbackSequence++;
  // Guard NaN/Infinity/0 — Math.max(NaN, 3) = NaN which breaks ffmpeg -t
  const rawDuration = Number.isFinite(duration) && duration > 0 ? duration : 5;
  const safeDuration = Math.min(Math.max(rawDuration, 3), 90);

  console.log(`[Pipeline] Scene ${sceneIndex}: generateColorFallback duration=${duration} safe=${safeDuration} out=${path.basename(out)}`);

  if (fs.existsSync(out)) {
    try { fs.unlinkSync(out); } catch { /* ignore */ }
  }

  // NOTE: no longer wrapped in ffmpegSemaphore.run() here — exec() (called inside
  // _generateColorFallbackInner, both for the disk-space check and each fallback attempt)
  // now acquires the same global semaphore itself for every individual spawn. Wrapping the
  // whole multi-attempt operation in an outer acquire meant each call held one slot for its
  // entire duration while its own inner exec() calls tried to acquire a SECOND slot from the
  // same semaphore before the first was released — under load, with all slots held by other
  // outer callers doing the same thing, no inner call could ever get a slot, and every
  // attempt eventually timed out and failed ("all color-fallback attempts failed") even
  // though the commands themselves (a trivial solid-color test pattern) were never actually
  // broken.
  return _generateColorFallbackInner(sceneIndex, safeDuration, out, workDir, variant);
}

async function _generateColorFallbackInner(sceneIndex: number, safeDuration: number, out: string, workDir: string, variantIndex?: number): Promise<string> {
  const colors = ["3a4a5e", "4a5a6e", "3a5a6e", "4a4a5e", "3a5a5e", "4a5a5e", "3a4a6e", "4a4a6e"];
  // RONDE 154: the card's own position in the sequence, so two in a row are never one picture.
  const variant = Math.abs(variantIndex ?? colorFallbackSequence++);
  const color = colors[variant % colors.length];
  /**
   * RONDE 155 — a placeholder is still a placeholder, but it is not a frozen frame.
   *
   * A flat `color=` source is, by construction, one unchanging picture for its whole duration. The
   * stillness audit measures exactly that, and measured it: a five-second card reports
   * longestStill 5.00s with zero visual changes.
   *
   * The second colour is the NEXT palette entry, so the drift stays inside the same muted family
   * rather than becoming a light show. Measured with the pipeline's own auditVideoStillness:
   *
   *     color=            0 changes   longest still 5.00s
   *     gradients speed=0.05    marginal: 0.00s / 0.75s / 0.75s over three runs
   *     gradients speed=0.20   32-39 changes  longest still 0.00s, 8 runs of 8
   *
   * speed=0.20 was chosen by repeated measurement, not by taste. 0.05 looked adequate in a single
   * run and turned out to be MARGINAL: across three runs it reported 0.00s once and 0.75s twice,
   * because the drift is slow enough that whether two sampled frames differ is close to a
   * coin-flip. 0.20 returned 0.00s in eight runs out of eight (32-39 changes each). A guarantee
   * needs margin, not a setting that happens to pass.
   *
   * It changes NOTHING about the accounting. The clip is still adopted as `rescue_placeholder`,
   * still counted in fallbackRatio, still penalised in the quality score. What it stops is the
   * viewer being shown a frozen video, which is a rendering fault regardless of what caused it.
   */
  const colorB = colors[(variant + 1) % colors.length];
  const commands = [
    `${FFMPEG_BIN} -y -f lavfi -i "gradients=s=${VIDEO_WIDTH}x${VIDEO_HEIGHT}:c0=0x${color}:c1=0x${colorB}:speed=0.20:r=25" -t ${safeDuration} -c:v libx264 ${pipelineFfmpegThreadFlag()} -preset ultrafast -pix_fmt yuv420p -an "${out}"`,
    // Every command below is a flat colour and therefore a still picture. They are the ladder that
    // already existed for a box where the first command cannot run at all — an older ffmpeg without
    // the gradients source, or one under such load that only the cheapest encode survives. A card
    // that is a held frame beats no card at all, which is the whole point of a last-resort net.
    `${FFMPEG_BIN} -y -f lavfi -i "color=c=#${color}:s=${VIDEO_WIDTH}x${VIDEO_HEIGHT}:r=25" -t ${safeDuration} -c:v libx264 ${pipelineFfmpegThreadFlag()} -preset ultrafast -pix_fmt yuv420p -an "${out}"`,
    `${FFMPEG_BIN} -y -f lavfi -i "color=c=black:s=${VIDEO_WIDTH}x${VIDEO_HEIGHT}:r=25" -t ${safeDuration} -c:v libx264 ${pipelineFfmpegThreadFlag()} -preset ultrafast -pix_fmt yuv420p -an "${out}"`,
    `${FFMPEG_BIN} -y -f lavfi -i "color=c=black:s=1280x720:r=25" -t ${safeDuration} -c:v mpeg4 -q:v 5 -an "${out}"`,
    `${FFMPEG_BIN} -y -f lavfi -i "color=c=black:s=640x360:r=25" -t ${safeDuration} -c:v mpeg4 -q:v 8 -an "${out}"`,
  ];
  try {
    const { stdout: dfOut } = await withSceneFetchTimeout(() => exec(`df -h "${workDir}" 2>&1 || df -h /var/tmp 2>&1 || df -h /tmp 2>&1`), 5_000, "df");
    console.log(`[Pipeline] Scene ${sceneIndex}: disk space: ${dfOut.trim().split("\n").slice(-1)[0]}`);
  } catch { /* ignore */ }

  // This is the last-resort safety net (compose + rescue-compose already both failed) — it's a
  // trivial, cheap ffmpeg command, so it's worth retrying hard on ANY transient failure, not just
  // ones recognized as "fork pressure". Under concurrent load the far more common failure here is
  // simply queueing behind the shared ffmpegSemaphore long enough to hit this call's own 45s
  // withSceneFetchTimeout — that surfaces as a plain timeout error, which isForkPressureError()
  // doesn't match, so it used to skip the retry entirely and give up after one shot per variant.
  const FALLBACK_RETRIES = 4;
  for (let i = 0; i < commands.length; i++) {
    let lastErr: unknown;
    for (let retry = 0; retry < FALLBACK_RETRIES; retry++) {
      try {
        if (fs.existsSync(out)) {
          try { fs.unlinkSync(out); } catch { /* ignore */ }
        }
        const { stderr } = await withSceneFetchTimeout(() => exec(commands[i]), 45_000, `Fallback video scene ${sceneIndex} attempt ${i + 1}`);
        if (await isValidVideoFile(out)) {
          console.log(`[Pipeline] Scene ${sceneIndex}: fallback video OK (${(fs.statSync(out).size / 1024).toFixed(0)}KB, attempt ${i + 1})`);
          return out;
        }
        console.warn(`[Pipeline] Scene ${sceneIndex}: fallback attempt ${i + 1} produced unreadable file — stderr: ${String(stderr).slice(-400)}`);
        break;
      } catch (err) {
        lastErr = err;
        /**
         * RONDE 129 — "transient" was the word for every failure, including the one that cannot
         * possibly go away.
         *
         * From production:
         *
         *     fallback attempt 1 failed (transient) — retry 1/3 in 3.6s: Video generation cancelled
         *     fallback attempt 1 failed (transient) — retry 2/3 in 7.1s: Video generation cancelled
         *
         * `throwIfVideoGenerationCancelled` throws that when the render has been called off, and
         * the cancel flag stays set — so this slept four seconds and asked again for something
         * guaranteed to fail, three times, for each command variant, on a render that had already
         * been told to stop. The classifier answers the question the word "transient" was
         * standing in for.
         */
        const wait = jitteredDelay((retry + 1) * 4_000);
        const decision = shouldRetryAfterFailure({
          kind: classifyProviderFailure({ err }),
          attempt: retry,
          maxAttempts: FALLBACK_RETRIES,
          waitMs: wait,
          // The command's own ceiling — the withSceneFetchTimeout above.
          estimatedCostMs: 45_000,
          remainingBudgetMs: get_activeBudgetTracker()?.remainingMs?.(),
        });
        if (!decision.retry) {
          if (decision.reason !== "ATTEMPTS_EXHAUSTED") {
            console.warn(
              formatRetryGuard({
                operation: `colorFallback s${sceneIndex} variant ${i + 1}`,
                attempt: retry,
                maxAttempts: FALLBACK_RETRIES,
                decision,
                remainingBudgetMs: get_activeBudgetTracker()?.remainingMs?.(),
                estimatedCostMs: 45_000,
              })
            );
          }
          // A cancellation must end the whole ladder, not just this variant: every remaining
          // command would throw the same thing.
          if (decision.kind === "CANCELLED" || decision.kind === "BUDGET_EXCEEDED") throw err;
        }
        if (decision.retry) {
          const forkPressure = isForkPressureError(err);
          console.warn(
            `[Pipeline] Scene ${sceneIndex}: fallback attempt ${i + 1} failed ` +
            `(${forkPressure ? "fork pressure" : decision.kind.toLowerCase()}) — retry ${retry + 1}/${FALLBACK_RETRIES - 1} in ${(wait / 1000).toFixed(1)}s: ` +
            `${(err as Error).message?.slice(0, 150)}`
          );
          await sleep(wait);
          continue;
        }
        // No retry: report this variant's failure in full and move to the next command.
        const e = err as { message?: string; stderr?: string; code?: string };
        const ffmpegErr = ((e.stderr ?? "").slice(-600) || e.message?.slice(0, 300)) ?? String(err);
        console.warn(`[Pipeline] Scene ${sceneIndex}: fallback attempt ${i + 1} failed [code=${e.code ?? "?"}]: ${ffmpegErr}`);
        break;
      }
    }
  }

  throw pipelineError(PIPELINE_ERROR.FFMPEG, `Scene ${sceneIndex}: all color-fallback attempts failed (duration=${safeDuration}s, workDir=${workDir})`);
}





/** Return clipPath if ffprobe confirms a video stream; never substitute grey placeholders. */
/**
 * RONDE 63: compose-time validation verdicts, keyed by clip content.
 *
 * Bounded and cleared per render (see resetVisualDedupState) so one render cannot inherit
 * another's judgement of a path that has since been rewritten.
 */
const composeClipValidationMemo = new Map<string, boolean>();
const COMPOSE_VALIDATION_MEMO_MAX = 500;

export function resetComposeClipValidationMemo(): void {
  composeClipValidationMemo.clear();
}

/**
 * RONDE 162 — the last place a clip could disappear without saying why.
 *
 * Every drop below is correct: an unreadable file, a stream the montage cannot use, a frame that
 * is nearly all black. What was missing is that the caller filtered the null out and nothing was
 * written down, so the render's own lineage audit reported the asset as VANISHED_WITHOUT_OUTCOME —
 * chosen, adopted, absent from the film, no reason on record. Render 553:
 *
 *     Scene 2: dropping mostly-black clip scene_2_b1_curated_a56087.mp4
 *     Scene 2: dropping mostly-black clip scene_2_b3_curated_a56190.mp4
 *     ...
 *     VANISHED_WITHOUT_OUTCOME  scene_2_b1_curated_a56204.mp4  (and five more)
 *
 * The reason is now filed against the asset, one per drop, naming which check refused it.
 */
async function requireValidClip(
  clipPath: string,
  sceneIndex: number,
  _duration: number,
  _workDir: string,
  lineage?: VisualSourceLedger
): Promise<string | null> {
  const dropped = (reason: string): null => {
    // RONDE 167: by content key too — the curated route registers no path. See recordAssetOutcome.
    lineage?.recordEventForPath(clipPath, "REMOVED", { status: "REMOVED", reason, contentKey: clipContentKey(clipPath) });
    return null;
  };
  if (!(await isValidVideoFile(clipPath)) || isPipelineFallbackClip(clipPath)) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: dropping invalid clip ${path.basename(clipPath)}`);
    /**
     * A placeholder gets its own reason rather than none. RONDE 159 assumed a placeholder carries
     * no lineage record; render 553 disproved it — `scene_1_slot2_guaranteed.mp4` and five like it
     * hold ADOPTED events and were reported VANISHED_WITHOUT_OUTCOME for exactly that reason.
     */
    return dropped(
      isPipelineFallbackClip(clipPath) ? `placeholder_rejected:s${sceneIndex}` : `invalid_file:s${sceneIndex}`
    );
  }
  const meta = await probeVideoStreamMeta(clipPath);
  if (!meta || !montageStreamMetaUsable(meta, montageClipStartSec(sceneIndex, 0))) {
    console.warn(
      `[Pipeline] Scene ${sceneIndex}: dropping clip with unusable stream ${path.basename(clipPath)}`
    );
    return dropped(`unusable_stream:s${sceneIndex}`);
  }
  // Compose gate already checked start/center luma for curated archive beats.
  if (curatedArchiveOnlyVisuals() && curatedClipPathAssetId(clipPath) != null) {
    return clipPath;
  }
  if (await isMostlyBlackClip(clipPath)) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: dropping mostly-black clip ${path.basename(clipPath)}`);
    return dropped(`mostly_black:s${sceneIndex}`);
  }
  return clipPath;
}

// ─── 3c1. Generate Grok Video Clip ──────────────────────────────────────────
export async function generateGrokVideoClip(
  prompt: string,
  duration: number,
  outputPath: string,
  sceneIndex: number
): Promise<string | null> {
  if (!replicateApiKey()) {
    return null; // Fallback to other sources
  }

  try {
    const result = await generateGrokVideo(prompt, Math.min(duration, 8));
    if (!result) return null;

    // Download the video from the URL and save to local file
    const grokOutputPath = outputPath.replace(/\.mp4$/, "_grok.mp4");
    const response = await fetch(result.url, { signal: AbortSignal.timeout(120_000) });
    if (!response.ok) {
      console.warn(`[Pipeline] Scene ${sceneIndex}: Grok download failed (${response.status})`);
      return null;
    }

    const buffer = await response.buffer();
    fs.writeFileSync(grokOutputPath, buffer);
    console.log(`[Pipeline] Scene ${sceneIndex}: Grok video saved (${buffer.length} bytes)`);
    if (fs.existsSync(grokOutputPath) && fs.statSync(grokOutputPath).size > 1000) {
      return grokOutputPath;
    }
    return null;
  } catch (err) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: Grok generation error:`, err);
    return null;
  }
}

