// ─── 3c5. Generate Higgsfield Image-to-Video Clip ───────────────────────────────


// ─── 3c6. Leonardo AI Image → Video (HIGH QUALITY image gen, replaces Stability AI) ─────
// Exported only for direct testability (F3-13) — same zero-behavior-change pattern used
// throughout F3-05 through F3-12 for other module-private functions.
export async function generateLeonardoAIClip(
  prompt: string,
  duration: number,
  outputPath: string,
  sceneIndex: number
): Promise<string | null> {
  if (!leonardoApiKey()) return null;
  try {
    console.log(`[Pipeline] Scene ${sceneIndex}: Generating Leonardo AI image...`);
    const t = Date.now();
    // Step 1: Create generation job
    // F3-13: fetchWithTimeout (real AbortController cancellation) instead of the
    // withTimeout(fetch(...)) zombie-timeout pattern — same upgrade F3-08-A already applied to
    // Stability AI. Method/headers/body/timeout/label are unchanged.
    const genResp = await fetchWithTimeout(
      "https://cloud.leonardo.ai/api/rest/v1/generations",
      30_000,
      `Leonardo AI generate scene ${sceneIndex}`,
      {
        method: "POST",
        headers: { Authorization: `Bearer ${leonardoApiKey()}`, "Content-Type": "application/json" },
        body: JSON.stringify({
          prompt: prompt + ", cinematic, 4K, high quality, professional photography",
          negative_prompt: "blurry, low quality, watermark, text, logo, ugly, deformed",
          modelId: "b24e16ff-06e3-43eb-8d33-4416c2d75876", // Leonardo Kino XL (cinematic)
          width: 1344, height: 768, num_images: 1,
          guidance_scale: 7, num_inference_steps: 30,
          public: false, photoReal: false, alchemy: false,
        }),
      }
    );
    if (!genResp.ok) {
      const errText = await genResp.text();
      console.warn(`[Pipeline] Scene ${sceneIndex}: Leonardo AI error ${genResp.status}: ${errText.slice(0, 200)}`);
      return null;
    }
    const genData = await genResp.json() as { sdGenerationJob?: { generationId: string } };
    const generationId = genData.sdGenerationJob?.generationId;
    if (!generationId) return null;

    // Step 2: Poll for completion (max 60s)
    let imageUrl: string | null = null;
    for (let poll = 0; poll < 12; poll++) {
      await new Promise(r => setTimeout(r, 5000));
      // F3-13: fetchWithTimeout instead of withTimeout(fetch(...)) — poll interval/max attempts
      // and response parsing below are unchanged.
      const pollResp = await fetchWithTimeout(
        `https://cloud.leonardo.ai/api/rest/v1/generations/${generationId}`,
        10_000,
        `Leonardo AI poll scene ${sceneIndex}`,
        { headers: { Authorization: `Bearer ${leonardoApiKey()}` } }
      );
      if (!pollResp.ok) continue;
      const pollData = await pollResp.json() as { generations_by_pk?: { status: string; generated_images?: Array<{ url: string }> } };
      const gen = pollData.generations_by_pk;
      if (gen?.status === "COMPLETE" && gen.generated_images?.[0]?.url) {
        imageUrl = gen.generated_images[0].url;
        break;
      }
      if (gen?.status === "FAILED") break;
    }
    if (!imageUrl) return null;

    // Step 3: Download image and convert to video
    // F3-13: AbortSignal.timeout(20_000) covers the full request lifecycle (headers AND
    // body-read), unlike fetchWithTimeout (which only protects up to headers arriving) — same
    // pattern already proven for Grok/Veo/Higgsfield's downloads in this file and for F3-10's
    // streamArchiveAssetDownload. Streams straight to pngPath via pipeline() instead of
    // Buffer.from(await imgResp.arrayBuffer()), so the image is never fully buffered in memory.
    const imgResp = await fetch(imageUrl, { signal: AbortSignal.timeout(20_000) });
    if (!imgResp.ok || !imgResp.body) return null;
    const pngPath = outputPath.replace(".mp4", "_leonardo.jpg");
    try {
      await pipeline(imgResp.body, fs.createWriteStream(pngPath));
    } catch (err) {
      try { fs.unlinkSync(pngPath); } catch { /* ignore */ }
      throw err;
    }
    console.log(`[Pipeline] Scene ${sceneIndex}: Leonardo AI image in ${((Date.now()-t)/1000).toFixed(1)}s (${(fs.statSync(pngPath).size/1024).toFixed(0)}KB)`);

    // Convert to video with fast Ken Burns
    const fps = 25; const totalFrames = Math.ceil(duration * fps);
    const zoomEnd = 1.05; const zoomStart = 1.0;
    const zoomStep = (zoomEnd - zoomStart) / totalFrames;
    const leonardoOutputPath = outputPath.replace(".mp4", "_leonardo.mp4");
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -loop 1 -i "${pngPath}" ` +
        `-vf "scale=${VIDEO_WIDTH}:${VIDEO_HEIGHT}:force_original_aspect_ratio=increase,crop=${VIDEO_WIDTH}:${VIDEO_HEIGHT},` +
        `zoompan=z='min(zoom+${zoomStep.toFixed(6)},${zoomEnd})':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=${totalFrames}:s=${VIDEO_WIDTH}x${VIDEO_HEIGHT}:fps=${fps}" ` +
        `-t ${duration} -r ${fps} -c:v libx264 ${pipelineFfmpegThreadFlag()} -preset fast -crf 18 -pix_fmt yuv420p "${leonardoOutputPath}"`
      ),
      90_000, `Leonardo AI image to video scene ${sceneIndex}`
    );
    try { fs.unlinkSync(pngPath); } catch { /* ignore */ }
    if (fs.existsSync(leonardoOutputPath) && fs.statSync(leonardoOutputPath).size > 1000) {
      return leonardoOutputPath;
    }
    return null;
  } catch (err) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: Leonardo AI clip failed:`, err);
    return null;
  }
}

// ─── 3c7. Runway Gen-4 Image-to-Video ─────────────────────────────────────────
export async function generateRunwayClip(
  prompt: string,
  imageUrl: string | null,
  duration: number,
  outputPath: string,
  sceneIndex: number
): Promise<string | null> {
  if (!runwayApiKey()) return null;
  try {
    console.log(`[Pipeline] Scene ${sceneIndex}: Generating Runway Gen-4 video...`);
    const t = Date.now();
    const durationSec = Math.min(duration, 10) as 5 | 10;
    const body: Record<string, unknown> = {
      model: "gen4_turbo",
      promptText: prompt,
      duration: durationSec <= 5 ? 5 : 10,
      ratio: "1280:768",
    };
    if (imageUrl) body.promptImage = imageUrl;

    // F3-13: fetchWithTimeout instead of withTimeout(fetch(...)) — same upgrade F3-08-A already
    // applied to Stability AI. Method/headers/body/timeout/label are unchanged.
    const createResp = await fetchWithTimeout(
      "https://api.dev.runwayml.com/v1/image_to_video",
      30_000,
      `Runway create scene ${sceneIndex}`,
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${runwayApiKey()}`,
          "Content-Type": "application/json",
          "X-Runway-Version": "2024-11-06",
        },
        body: JSON.stringify(body),
      }
    );
    if (!createResp.ok) {
      const errText = await createResp.text();
      console.warn(`[Pipeline] Scene ${sceneIndex}: Runway error ${createResp.status}: ${errText.slice(0, 200)}`);
      return null;
    }
    const createData = await createResp.json() as { id: string };
    const taskId = createData.id;
    if (!taskId) return null;

    // Poll for completion (max 3 minutes)
    let videoUrl: string | null = null;
    for (let poll = 0; poll < 36; poll++) {
      await new Promise(r => setTimeout(r, 5000));
      // F3-13: fetchWithTimeout instead of withTimeout(fetch(...)) — poll interval/max attempts
      // and response parsing below are unchanged.
      const pollResp = await fetchWithTimeout(
        `https://api.dev.runwayml.com/v1/tasks/${taskId}`,
        10_000,
        `Runway poll scene ${sceneIndex}`,
        { headers: { Authorization: `Bearer ${runwayApiKey()}`, "X-Runway-Version": "2024-11-06" } }
      );
      if (!pollResp.ok) continue;
      const pollData = await pollResp.json() as { status: string; output?: string[] };
      if (pollData.status === "SUCCEEDED" && pollData.output?.[0]) {
        videoUrl = pollData.output[0];
        break;
      }
      if (pollData.status === "FAILED") break;
    }
    if (!videoUrl) return null;

    // Download video
    // F3-13: AbortSignal.timeout(60_000) covers the full request lifecycle (headers AND
    // body-read), unlike fetchWithTimeout (which only protects up to headers arriving) — same
    // pattern already proven for Grok/Veo/Higgsfield's downloads in this file and for F3-10's
    // streamArchiveAssetDownload. Streams straight to runwayOutputPath via pipeline() instead of
    // Buffer.from(await dlResp.arrayBuffer()), so the video is never fully buffered in memory.
    const dlResp = await fetch(videoUrl, { signal: AbortSignal.timeout(60_000) });
    if (!dlResp.ok || !dlResp.body) return null;
    const runwayOutputPath = outputPath.replace(".mp4", "_runway.mp4");
    try {
      await pipeline(dlResp.body, fs.createWriteStream(runwayOutputPath));
    } catch (err) {
      try { fs.unlinkSync(runwayOutputPath); } catch { /* ignore */ }
      throw err;
    }
    console.log(`[Pipeline] Scene ${sceneIndex}: Runway video in ${((Date.now()-t)/1000).toFixed(1)}s (${(fs.statSync(runwayOutputPath).size/1024/1024).toFixed(1)}MB)`);
    if (fs.existsSync(runwayOutputPath) && fs.statSync(runwayOutputPath).size > 1000) {
      return runwayOutputPath;
    }
    return null;
  } catch (err) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: Runway clip failed:`, err);
    return null;
  }
}

// ─── 3c9. Luma Dream Machine Image-to-Video ────────────────────────────────────
export async function generateLumaClip(
  prompt: string,
  imageUrl: string | null,
  duration: number,
  outputPath: string,
  sceneIndex: number
): Promise<string | null> {
  if (!LUMA_API_KEY) return null;
  try {
    console.log(`[Pipeline] Scene ${sceneIndex}: Generating Luma Dream Machine video...`);
    const t = Date.now();
    const body: Record<string, unknown> = {
      prompt: prompt,
      model: "ray-2",
      resolution: "720p",
      duration: "5s",
      loop: false,
    };
    if (imageUrl) body.keyframes = { frame0: { type: "image", url: imageUrl } };

    const createResp = await withTimeout(
      fetch("https://api.lumalabs.ai/dream-machine/v1/generations", {
        method: "POST",
        headers: { Authorization: `Bearer ${LUMA_API_KEY}`, "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
      30_000, `Luma create scene ${sceneIndex}`
    );
    if (!createResp.ok) {
      const errText = await createResp.text();
      console.warn(`[Pipeline] Scene ${sceneIndex}: Luma error ${createResp.status}: ${errText.slice(0, 200)}`);
      return null;
    }
    const createData = await createResp.json() as { id: string };
    const genId = createData.id;
    if (!genId) return null;

    // Poll for completion (max 3 minutes)
    let videoUrl: string | null = null;
    for (let poll = 0; poll < 36; poll++) {
      await new Promise(r => setTimeout(r, 5000));
      const pollResp = await withTimeout(
        fetch(`https://api.lumalabs.ai/dream-machine/v1/generations/${genId}`, {
          headers: { Authorization: `Bearer ${LUMA_API_KEY}` },
        }),
        10_000, `Luma poll scene ${sceneIndex}`
      );
      if (!pollResp.ok) continue;
      const pollData = await pollResp.json() as { state: string; assets?: { video?: string } };
      if (pollData.state === "completed" && pollData.assets?.video) {
        videoUrl = pollData.assets.video;
        break;
      }
      if (pollData.state === "failed") break;
    }
    if (!videoUrl) return null;

    const dlResp = await fetchWithTimeout(videoUrl, 60_000, `Luma download scene ${sceneIndex}`);
    if (!dlResp.ok) return null;
    const buffer = Buffer.from(await dlResp.arrayBuffer());
    const lumaOutputPath = outputPath.replace(".mp4", "_luma.mp4");
    fs.writeFileSync(lumaOutputPath, buffer);
    console.log(`[Pipeline] Scene ${sceneIndex}: Luma video in ${((Date.now()-t)/1000).toFixed(1)}s (${(buffer.length/1024/1024).toFixed(1)}MB)`);
    if (fs.existsSync(lumaOutputPath) && fs.statSync(lumaOutputPath).size > 1000) {
      return lumaOutputPath;
    }
    return null;
  } catch (err) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: Luma clip failed:`, err);
    return null;
  }
}

// ─── 3c10. Pika Labs Image-to-Video ────────────────────────────────────────────
export async function generatePikaClip(
  prompt: string,
  imageUrl: string | null,
  duration: number,
  outputPath: string,
  sceneIndex: number
): Promise<string | null> {
  if (!PIKA_API_KEY) return null;
  try {
    console.log(`[Pipeline] Scene ${sceneIndex}: Generating Pika Labs video...`);
    const t = Date.now();
    const body: Record<string, unknown> = {
      promptText: prompt,
      model: "pike-2.2",
      options: { frameRate: 24, resolution: "1080p", duration: Math.min(duration, 5) },
    };
    if (imageUrl) body.image = imageUrl;

    const createResp = await withTimeout(
      fetch("https://api.pika.art/v2/generate", {
        method: "POST",
        headers: { Authorization: `Bearer ${PIKA_API_KEY}`, "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
      30_000, `Pika create scene ${sceneIndex}`
    );
    if (!createResp.ok) {
      const errText = await createResp.text();
      console.warn(`[Pipeline] Scene ${sceneIndex}: Pika error ${createResp.status}: ${errText.slice(0, 200)}`);
      return null;
    }
    const createData = await createResp.json() as { id?: string; requestId?: string };
    const taskId = createData.id || createData.requestId;
    if (!taskId) return null;

    // Poll for completion (max 3 minutes)
    let videoUrl: string | null = null;
    for (let poll = 0; poll < 36; poll++) {
      await new Promise(r => setTimeout(r, 5000));
      const pollResp = await withTimeout(
        fetch(`https://api.pika.art/v2/tasks/${taskId}`, {
          headers: { Authorization: `Bearer ${PIKA_API_KEY}` },
        }),
        10_000, `Pika poll scene ${sceneIndex}`
      );
      if (!pollResp.ok) continue;
      const pollData = await pollResp.json() as { status?: string; videos?: Array<{ url: string }>; resultUrl?: string };
      if ((pollData.status === "finished" || pollData.status === "succeeded") && (pollData.videos?.[0]?.url || pollData.resultUrl)) {
        videoUrl = pollData.videos?.[0]?.url || pollData.resultUrl || null;
        break;
      }
      if (pollData.status === "failed") break;
    }
    if (!videoUrl) return null;

    const dlResp = await fetchWithTimeout(videoUrl, 60_000, `Pika download scene ${sceneIndex}`);
    if (!dlResp.ok) return null;
    const buffer = Buffer.from(await dlResp.arrayBuffer());
    const pikaOutputPath = outputPath.replace(".mp4", "_pika.mp4");
    fs.writeFileSync(pikaOutputPath, buffer);
    console.log(`[Pipeline] Scene ${sceneIndex}: Pika video in ${((Date.now()-t)/1000).toFixed(1)}s (${(buffer.length/1024/1024).toFixed(1)}MB)`);
    if (fs.existsSync(pikaOutputPath) && fs.statSync(pikaOutputPath).size > 1000) {
      return pikaOutputPath;
    }
    return null;
  } catch (err) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: Pika clip failed:`, err);
    return null;
  }
}

// ─── 3c11. Manus Forge Built-in Video Generation ──────────────────────────────
export async function generateManusForgeClip(
  prompt: string,
  duration: number,
  outputPath: string,
  sceneIndex: number
): Promise<string | null> {
  const FORGE_API_URL = process.env.BUILT_IN_FORGE_API_URL || "";
  const FORGE_API_KEY = process.env.BUILT_IN_FORGE_API_KEY || "";
  if (!FORGE_API_URL || !FORGE_API_KEY) return null;
  try {
    console.log(`[Pipeline] Scene ${sceneIndex}: Generating Manus Forge video...`);
    const t = Date.now();
    const forgeBase = FORGE_API_URL.replace(/\/+$/, "");

    // Try Manus Forge video generation endpoint
    const createResp = await withTimeout(
      fetch(`${forgeBase}/v1/video/generate`, {
        method: "POST",
        headers: { Authorization: `Bearer ${FORGE_API_KEY}`, "Content-Type": "application/json" },
        body: JSON.stringify({
          prompt: prompt,
          duration: Math.min(duration, 8),
          resolution: "1280x720",
          fps: 24,
        }),
      }),
      30_000, `Manus Forge create scene ${sceneIndex}`
    );
    if (!createResp.ok) {
      const errText = await createResp.text();
      console.warn(`[Pipeline] Scene ${sceneIndex}: Manus Forge error ${createResp.status}: ${errText.slice(0, 200)}`);
      return null;
    }
    const createData = await createResp.json() as { task_id?: string; id?: string; url?: string };

    // If direct URL returned, download immediately
    if (createData.url) {
      const dlResp = await fetchWithTimeout(createData.url, 60_000, `Manus Forge download scene ${sceneIndex}`);
      if (!dlResp.ok) return null;
      const buffer = Buffer.from(await dlResp.arrayBuffer());
      const forgeOutputPath = outputPath.replace(".mp4", "_forge.mp4");
      fs.writeFileSync(forgeOutputPath, buffer);
      console.log(`[Pipeline] Scene ${sceneIndex}: Manus Forge video in ${((Date.now()-t)/1000).toFixed(1)}s`);
      if (fs.existsSync(forgeOutputPath) && fs.statSync(forgeOutputPath).size > 1000) {
        return forgeOutputPath;
      }
      return null;
    }

    // Otherwise poll for task completion
    const taskId = createData.task_id || createData.id;
    if (!taskId) return null;
    let videoUrl: string | null = null;
    for (let poll = 0; poll < 36; poll++) {
      await new Promise(r => setTimeout(r, 5000));
      const pollResp = await withTimeout(
        fetch(`${forgeBase}/v1/video/tasks/${taskId}`, {
          headers: { Authorization: `Bearer ${FORGE_API_KEY}` },
        }),
        10_000, `Manus Forge poll scene ${sceneIndex}`
      );
      if (!pollResp.ok) continue;
      const pollData = await pollResp.json() as { status?: string; url?: string; output_url?: string };
      if ((pollData.status === "completed" || pollData.status === "succeeded") && (pollData.url || pollData.output_url)) {
        videoUrl = pollData.url || pollData.output_url || null;
        break;
      }
      if (pollData.status === "failed") break;
    }
    if (!videoUrl) return null;

    const dlResp = await fetchWithTimeout(videoUrl, 60_000, `Manus Forge download scene ${sceneIndex}`);
    if (!dlResp.ok) return null;
    const buffer = Buffer.from(await dlResp.arrayBuffer());
    const forgeOutputPath = outputPath.replace(".mp4", "_forge.mp4");
    fs.writeFileSync(forgeOutputPath, buffer);
    console.log(`[Pipeline] Scene ${sceneIndex}: Manus Forge video in ${((Date.now()-t)/1000).toFixed(1)}s (${(buffer.length/1024/1024).toFixed(1)}MB)`);
    if (fs.existsSync(forgeOutputPath) && fs.statSync(forgeOutputPath).size > 1000) {
      return forgeOutputPath;
    }
    return null;
  } catch (err) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: Manus Forge clip failed:`, err);
    return null;
  }
}

/** Trim a downloaded file to a short scene clip (shared by Archive, NASA, Wikimedia video). */
// F3-45: temporarily exported (visibility only, no logic changed) so
// server/f345YoutubeCcRuntimeTest.ts can reuse it. Revert to module-private
// once that temporary diagnostic script is deleted.
/**
 * RONDE 64: the start offset, corrected against the file that is actually on disk.
 *
 * `seedId` is what spreads two clips cut from the same source; `startIsExact` marks a start
 * something located deliberately — a transcript hit — which must be honoured rather than
 * improved on. Returns the original when the source cannot be probed.
 */
export async function resolveTrimStartSec(
  sourcePath: string,
  requestedStart: number,
  takeSec: number,
  seedId: string,
  startIsExact = false
): Promise<number> {
  const sourceDur = await probeVideoDurationSec(sourcePath).catch(() => 0);
  if (!Number.isFinite(sourceDur) || sourceDur <= 0) return Math.max(0, requestedStart);

  // A guessed start on a source whose length is now known can be improved on: the guess was made
  // before anything had seen the file. A located one is left alone.
  const start = startIsExact
    ? requestedStart
    : pickLongVideoStartSec(sourceDur, takeSec, seedId) || requestedStart;

  // And whatever it is, it has to exist. Nothing clamped this before: a blind 12-second offset
  // on an eight-second video asked ffmpeg for a second that was not in the file, which yields an
  // empty or single-frozen-frame clip that the size check downstream can still wave through.
  const latest = Math.max(0, sourceDur - takeSec);
  return Math.max(0, Math.min(start, latest));
}

/**
 * RONDE 135 — the technical gate on the routes RONDE 134 could not reach.
 *
 * RONDE 134 put videoResolutionVerdict on two routes: the funnel/pool download and the curated
 * archive clip. That left every DIRECT provider route without it, and there are eleven of them —
 * Wikimedia video, Flickr, SepiaSearch, Europeana, Vimeo CC, media.ccc, NASA, NARA, Internet
 * Archive and YouTube all reach the montage through trimRemoteVideoToClip, and Pexels and Pixabay
 * through trimDownloadedStockClip.
 *
 * Rather than thirteen new call sites, the check goes in the two helpers every one of those routes
 * already funnels through. It sits BEFORE the ffmpeg encode, so an unusable source costs one
 * memoised probe instead of a full libx264 pass — which is the "no unnecessary encode" half of the
 * round as well as the resolution half.
 *
 * No new threshold: the same VIDEO_MIN_SHORT_SIDE_PX (144) RONDE 134 grounded in
 * youtubeMinFormatHeight's own admissible range, and the same 480-line bar that only observes.
 * probeVideoStreamMeta is memoised on inode+ctime, so where a route has already probed the file
 * this is free.
 */
async function videoSourcePassesTechnicalGate(sourcePath: string, label: string): Promise<boolean> {
  const meta = await probeVideoStreamMeta(sourcePath);
  /**
   * RONDE 136 — which floor applies depends on where the clip came from.
   *
   * These helpers are shared by thirteen routes and receive a `label` rather than a provider name,
   * but the labels already name their provider: "Trim Pexels clip 0 scene 2", "YouTube CC RapidAPI
   * scene 2", "Internet Archive scene 1". isStockSource matches on that, and anything it does not
   * recognise keeps the permissive archive floor — the safe direction, since the failure mode of
   * guessing "stock" would be refusing genuine archive footage.
   */
  const verdict = videoResolutionVerdict(meta?.width, meta?.height, minShortSideForSource(label));
  if (!verdict.ok) {
    console.warn(
      formatTechnicalReject({
        beatLabel: label,
        source: label,
        assetId: path.basename(sourcePath),
        contentKey: clipContentKey(sourcePath),
        mediaType: "video",
        verdict,
      })
    );
    return false;
  }
  if (verdict.belowQualityBar && meta) {
    console.log(
      formatBelowQualityBar({
        beatLabel: label,
        source: label,
        contentKey: clipContentKey(sourcePath),
        width: meta.width,
        height: meta.height,
      })
    );
  }
  return true;
}

export async function trimRemoteVideoToClip(
  sourcePath: string,
  outputPath: string,
  duration: number,
  clipStart = 5,
  label = "clip"
): Promise<boolean> {
  if (!(await videoSourcePassesTechnicalGate(sourcePath, label))) return false;
  try {
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -ss ${clipStart} -i "${sourcePath}" -t ${duration} ` +
        `-vf "${STANDARD_VF}" ` +
        `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset veryfast -crf 22 -an -pix_fmt yuv420p "${outputPath}"`
      ),
      90_000,
      `Trim ${label}`
    );
    const written = fs.existsSync(outputPath) && fs.statSync(outputPath).size > 10_000;
    /**
     * RONDE 151 §7 — the offset into the provider's original, written down at last.
     *
     * `clipStart` is a real number: `resolveTrimStartSec` probed the source and clamped it. Until
     * now it was used by the ffmpeg command above and then discarded, which is invisible while the
     * trimmed file exists and becomes a wrong shot the moment a re-render rehydrates the FULL
     * asset from the provider and starts at second 0.
     *
     * Recorded here rather than at thirteen call sites because every direct provider route reaches
     * the montage through this helper — one writer, standing next to the cut it describes.
     */
    if (written) {
      try {
        get_activeSourcingCache()?.lineage.recordSourceTrim(outputPath, {
          inSec: clipStart,
          outSec: clipStart + duration,
        });
      } catch {
        /* provenance bookkeeping must never fail a clip that was produced correctly */
      }
    }
    return written;
  } catch (err) {
    console.warn(`[Pipeline] trimRemoteVideoToClip failed (${label}):`, (err as Error).message);
    return false;
  }
}

// ─── 3c2v. Wikimedia Commons Video Search ───────────────────────────────────
async function fetchWikimediaVideos(
  query: string,
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 2,
  fileTag = "",
  personName = "",
  beatKeywords: string[] = [],
  usedProviderKeys?: Set<string>,
  sourcingCache?: SourcingCache
): Promise<CelebrityClipCandidate[]> {
  if (!query?.trim()) return [];
  if (isWikimediaInCooldown()) return [];
  const results: CelebrityClipCandidate[] = [];
  const UA = { "User-Agent": "Fastvid/1.0 (video generation; CC-licensed clips only)" };
  try {
    // Phase 5 query cache — see cachedProviderSearch. srlimit/srnamespace are fixed, so the
    // request is a pure function of `query`.
    const searchData = await cachedProviderSearch(
      sourcingCache,
      "wikimedia",
      query,
      async (): Promise<{ query?: { search?: Array<{ title: string }> } } | null> => {
        const searchUrl =
          `https://commons.wikimedia.org/w/api.php?action=query&list=search` +
          `&srsearch=${encodeURIComponent(`${query} filetype:video`)}&srnamespace=6&srlimit=15&format=json&origin=*`;
        const searchResp = await providerLimiter("wikimedia").run(() => fetchWithTimeout(searchUrl, 10_000, `Wikimedia video search scene ${sceneIndex}`, { headers: UA }));
        if (!searchResp.ok) {
          logWikimediaHttpFailure("video search", sceneIndex, searchResp);
          markWikimediaSearchResult(false);
          return null;
        }
        markWikimediaSearchResult(true);
        return await searchResp.json() as { query?: { search?: Array<{ title: string }> } };
      },
      "fetchWikimediaVideos"
    );
    if (!searchData) return [];
    providerMetrics(sourcingCache, "wikimedia").resultCount += searchData.query?.search?.length ?? 0;
    const hits = (searchData.query?.search ?? [])
      .filter((r) => {
        const hay = `${r.title} ${query}`.toLowerCase();
        if (personName && !textMentionsPersonName(hay, personName)) return false;
        if (beatKeywords.length > 0 && scoreVisualRelevance(hay, beatKeywords) < 1 && personName) {
          return textMentionsPersonName(hay, personName);
        }
        return true;
      })
      .sort(
        (a, b) =>
          scoreVisualRelevance(`${b.title} ${query}`, beatKeywords) -
          scoreVisualRelevance(`${a.title} ${query}`, beatKeywords)
      )
      .slice(0, count * 3);
    if (!hits.length) return [];

    let downloaded = 0;
    for (let i = 0; i < hits.length && downloaded < count; i++) {
      try {
        const title = hits[i].title;
        // Pre-download visual dedup: skip a Commons page we already adopted this render,
        // before spending the imageinfo call or the download itself — see providerAssetKey.
        if (providerAssetAlreadyUsed(usedProviderKeys, sourcingCache, "wikimedia", title)) continue;
        const infoUrl =
          `https://commons.wikimedia.org/w/api.php?action=query&titles=${encodeURIComponent(title)}` +
          `&prop=imageinfo&iiprop=url|size|mime&format=json&origin=*`;
        const infoResp = await fetchWithTimeout(infoUrl, 10_000, `Wikimedia video info scene ${sceneIndex}`, { headers: UA });
        if (!infoResp.ok) continue;
        const infoData = await infoResp.json() as {
          query?: { pages?: Record<string, { imageinfo?: Array<{ url: string; size?: number; mime?: string }> }> };
        };
        const page = Object.values(infoData.query?.pages || {})[0];
        const imageInfo = page?.imageinfo?.[0];
        if (!imageInfo?.url || !imageInfo.mime?.startsWith("video/")) continue;
        if ((imageInfo.size ?? 0) > 80 * 1024 * 1024) continue;

        const tag = fileTag ? `${fileTag}_` : "";
        const tmpPath = path.join(workDir, `scene_${sceneIndex}_${tag}wikivid_${i}_tmp`);
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_${tag}wikivid_${i}.mp4`),
          "wikimedia",
          title,
          sourcingCache,
          { sceneIndex, sourceUrl: imageInfo.url, title, mediaType: "video", searchRoute: "fetchWikimediaVideos" }
        );
        // F3-05: streams straight to tmpPath instead of buffering the whole clip in memory.
        // P0 fix 1: maxBytes matches the existing 80MB post-hoc ceiling below exactly — this
        // only makes an already-oversized download abort early instead of fully downloading
        // first; the post-hoc range check stays as the authoritative safety net unchanged.
        const { response: dlResp, bytesWritten } = await downloadToFileStreaming(
          imageInfo.url, tmpPath, 45_000, `Wikimedia video download scene ${sceneIndex}`, { headers: UA },
          80 * 1024 * 1024
        );
        if (!dlResp.ok || bytesWritten === null) continue;
        if (bytesWritten < 50_000 || bytesWritten > 80 * 1024 * 1024) {
          try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
          continue;
        }
        providerMetrics(sourcingCache, "wikimedia").downloadCount++;

        if (await trimRemoteVideoToClip(tmpPath, outPath, duration, 3, `Wikimedia video scene ${sceneIndex}`)) {
          // Point 1 (production image-quality hardening): register via the generic
          // sourcingCache/providerAssetKey mechanism (not just the CelebrityClipCandidate.title
          // field below) so every call site — not only the ones that go through
          // adoptBestCelebrityClip — gets this real, Commons-authored page title as providerText.
          if (title) {
            putCachedProviderAsset(sourcingCache, "wikimedia", title, { providerText: { title } });
          }
          results.push({ path: outPath, query, title });
          downloaded++;
          console.log(`[Pipeline] Scene ${sceneIndex}: Wikimedia video added: ${title}`);
        }
        try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
      } catch (err) {
        console.warn(`[Pipeline] Wikimedia video ${i} failed for scene ${sceneIndex}:`, (err as Error).message);
      }
    }
  } catch (err) {
    // RONDE 68: a cancellation FastVid caused is not a provider fault — see isScopeAbortError.
    if (!isScopeAbortError(err)) markWikimediaSearchResult(false);
    console.warn(`[Pipeline] Wikimedia video search failed for scene ${sceneIndex}:`, (err as Error).message);
  }
  return results;
}

/** Archive.org queries for real person footage (news, TV, documentaries) — no API key. */
function buildPersonArchiveVideoQueries(person: string, beatIndex: number, beatText = ""): string[] {
  const personName = coercePersonName(person);
  if (!personName) return [];
  const scriptQs = beatText
    ? scriptEventSearchQueries(beatText, [personName]).map((q) =>
        textMentionsPersonName(q, personName) ? q : `${personName} ${q}`.trim()
      )
    : [];
  /**
   * RONDE 93 (§6) — the archive's own field syntax, plus what the BEAT says. Nothing else.
   *
   * "Adolf Hitler television" and "Adolf celebrity news" were measured going out of here. They
   * were unconditional: every person got `interview`, `television` and `<firstname> celebrity
   * news` appended whether or not the script said anything of the kind — a template written for
   * influencer documentaries, applied to a man who died in 1945. `${first} celebrity news` is
   * worse than wrong; it searches on a bare given name.
   *
   * scriptEventSearchQueries above already supplies event terms, and it supplies them ONLY when
   * the beat's own words trigger them — "interview" for a beat about an interview, "protest" for
   * a beat about a protest. That is the same term, earned instead of assumed, so the capability
   * survives and the guessing does not.
   */
  const rawVariants = [
    ...scriptQs,
    `title:(${personName}) AND mediatype:movies`,
    `collection:tvnews AND ${personName}`,
    `subject:"${personName}"`,
  ];
  const variants = uniqueCoercedQueries(rawVariants, 4);
  const offset = beatIndex % Math.max(1, variants.length);
  return [...variants.slice(offset), ...variants.slice(0, offset)].slice(0, 5);
}

/** Flickr CC video (4,5,6,9,10) — events, interviews uploaded with CC license. */
async function fetchFlickrCCVideos(
  query: string,
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 1,
  fileTag = "",
  personName = "",
  beatKeywords: string[] = [],
  usedProviderKeys?: Set<string>,
  sourcingCache?: SourcingCache
): Promise<string[]> {
  if (!FLICKR_API_KEY?.trim() || !query?.trim()) return [];
  if (isFlickrInCooldown()) return [];
  const results: string[] = [];
  try {
    const perPage = Math.min(12, count * 4);
    // Phase 5 query cache. Flickr's per_page is derived from `count`, which varies per caller,
    // so the page size is folded into the cache key: replaying a 4-result payload for a later
    // 12-result request would have silently shrunk the candidate list. Still exact-match only.
    const searchData = await cachedProviderSearch(
      sourcingCache,
      "flickr",
      `${query}#n${perPage}`,
      async (): Promise<{
        stat?: string;
        photos?: { photo?: Array<{ id: string; secret: string; server: string; title?: string }> };
      } | null> => {
        const searchParams = new URLSearchParams({
          method: "flickr.photos.search",
          api_key: FLICKR_API_KEY,
          text: query,
          media: "videos",
          license: "4,5,6,9,10",
          content_type: "7",
          per_page: String(perPage),
          format: "json",
          nojsoncallback: "1",
        });
        const searchResp = await providerLimiter("flickr").run(() => withTimeout(
          fetch(`https://api.flickr.com/services/rest/?${searchParams}`),
          12_000,
          `Flickr video search scene ${sceneIndex}`
        ));
        if (!searchResp.ok) {
          markFlickrSearchResult(false);
          return null;
        }
        markFlickrSearchResult(true);
        return await searchResp.json() as {
          stat?: string;
          photos?: { photo?: Array<{ id: string; secret: string; server: string; title?: string }> };
        };
      },
      "fetchFlickrCCVideos"
    );
    if (!searchData) return [];
    if (searchData.stat !== "ok") return [];
    providerMetrics(sourcingCache, "flickr").resultCount += searchData.photos?.photo?.length ?? 0;
    const photos = (searchData.photos?.photo ?? [])
      .filter((photo) => {
        const hay = `${photo.title ?? ""} ${query}`.toLowerCase();
        if (personName && !textMentionsPersonName(hay, personName)) return false;
        return true;
      })
      .sort(
        (a, b) =>
          scoreVisualRelevance(`${b.title ?? ""} ${query}`, beatKeywords) -
          scoreVisualRelevance(`${a.title ?? ""} ${query}`, beatKeywords)
      );
    if (!photos.length) return [];

    let downloaded = 0;
    for (let i = 0; i < photos.length && downloaded < count; i++) {
      const photo = photos[i];
      // Pre-download visual dedup: skip a Flickr photo we already adopted this render,
      // before the getSizes call or the download itself — see providerAssetKey.
      if (providerAssetAlreadyUsed(usedProviderKeys, sourcingCache, "flickr", photo.id)) continue;
      try {
        const sizeParams = new URLSearchParams({
          method: "flickr.photos.getSizes",
          api_key: FLICKR_API_KEY,
          photo_id: photo.id,
          format: "json",
          nojsoncallback: "1",
        });
        const sizeResp = await withTimeout(
          fetch(`https://api.flickr.com/services/rest/?${sizeParams}`),
          10_000,
          `Flickr sizes scene ${sceneIndex}`
        );
        if (!sizeResp.ok) continue;
        const sizeData = await sizeResp.json() as {
          stat?: string;
          sizes?: { size?: Array<{ label?: string; source?: string; media?: string }> };
        };
        if (sizeData.stat !== "ok") continue;
        const sizes = sizeData.sizes?.size ?? [];
        const videoSize =
          sizes.find((s) => s.media === "video" && s.source) ??
          sizes.find((s) => s.source && /\.mp4/i.test(s.source)) ??
          sizes.find((s) => /video|mp4|hd/i.test(s.label ?? "") && s.source);
        const videoUrl = videoSize?.source;
        if (!videoUrl) continue;

        const tag = fileTag ? `${fileTag}_` : "";
        const tmpPath = path.join(workDir, `scene_${sceneIndex}_${tag}flickr_${i}_tmp`);
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_${tag}flickr_${i}.mp4`),
          "flickr",
          photo.id,
          sourcingCache,
          { sceneIndex, title: photo.title, mediaType: "image", searchRoute: "fetchFlickrCCVideos" }
        );
        // Fase 4: real Flickr-authored title, independent of our search query.
        putCachedProviderAsset(sourcingCache, "flickr", photo.id, {
          providerText: { title: photo.title },
        });
        // F3-05: streams straight to tmpPath instead of buffering the whole clip in memory.
        // P0 fix 1: maxBytes matches the existing 80MB post-hoc ceiling below exactly.
        const { response: dlResp, bytesWritten } = await downloadToFileStreaming(
          videoUrl,
          tmpPath,
          45_000,
          `Flickr video download scene ${sceneIndex}`,
          { headers: { "User-Agent": "Fastvid/1.0 (CC-licensed clips only)" } },
          80 * 1024 * 1024
        );
        if (!dlResp.ok || bytesWritten === null) continue;
        if (bytesWritten < 50_000 || bytesWritten > 80 * 1024 * 1024) {
          try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
          continue;
        }
        providerMetrics(sourcingCache, "flickr").downloadCount++;
        if (await trimRemoteVideoToClip(tmpPath, outPath, duration, 2, `Flickr video scene ${sceneIndex}`)) {
          results.push(outPath);
          downloaded++;
          console.log(
            `[Pipeline] Scene ${sceneIndex}: Flickr CC video: ${photo.title?.slice(0, 60) ?? query}`
          );
        }
        try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
      } catch (err) {
        console.warn(`[Pipeline] Flickr video ${i} failed scene ${sceneIndex}:`, (err as Error).message);
      }
    }
  } catch (err) {
    // RONDE 68: a cancellation FastVid caused is not a provider fault — see isScopeAbortError.
    if (!isScopeAbortError(err)) markFlickrSearchResult(false);
    console.warn(`[Pipeline] Flickr search failed scene ${sceneIndex}:`, (err as Error).message);
  }
  return results;
}

/** Federated PeerTube search (SepiaSearch) — CC news/interviews, no API key. */
const SEPIA_SEARCH_API = "https://sepiasearch.org/api/v1";

function scoreSepiaSearchHit(
  title: string,
  query: string,
  personName: string,
  beatKeywords: string[]
): number {
  const hay = `${title} ${query}`.toLowerCase();
  if (personName && !textMentionsPersonName(hay, personName)) return -1;
  let score = 3;
  score += scoreVisualRelevance(hay, beatKeywords);
  if (/\b(interview|news|documentary|conference|speech|red carpet|celebrity|talk show)\b/.test(hay)) {
    score += 2;
  }
  return score;
}

async function fetchSepiaSearchVideos(
  queries: string | string[],
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 1,
  fileTag = "",
  personName = "",
  beatKeywords: string[] = [],
  usedProviderKeys?: Set<string>,
  sourcingCache?: SourcingCache
): Promise<CelebrityClipCandidate[]> {
  const queryList = uniqueQueryStrings(Array.isArray(queries) ? queries : [queries]);
  if (!queryList.length) return [];
  // RONDE 20: also honor the download breaker — searching is cheap here, but each failing
  // download costs 55s, so a dead fetch endpoint must skip the whole tier, not just its search.
  if (isSepiaSearchInCooldown() || isSepiaDownloadInCooldown()) return [];

  type RankedHit = {
    uuid: string;
    host: string;
    title: string;
    query: string;
    score: number;
  };

  const results: CelebrityClipCandidate[] = [];
  const seenUuids = new Set<string>();
  const ranked: RankedHit[] = [];

  try {
    // Fire all per-query searches concurrently — pure network fetches, results are merged
    // and globally re-sorted by score afterward, so query order doesn't matter.
    const perQueryHits = await Promise.all(
      queryList.slice(0, 4).map(async (query) => {
        try {
          type SepiaHit = {
            uuid: string;
            name?: string;
            duration?: number;
            isLive?: boolean;
            channel?: { host?: string };
          };
          // Phase 5 query cache — count/licence filters are fixed, so the request is a pure
          // function of `query`.
          const data = await cachedProviderSearch(
            sourcingCache,
            "sepiasearch",
            query,
            async (): Promise<{ data?: SepiaHit[] } | null> => {
              const searchUrl = new URL(`${SEPIA_SEARCH_API}/search/videos`);
              searchUrl.searchParams.set("search", query);
              searchUrl.searchParams.set("count", "15");
              searchUrl.searchParams.append("licenceOneOf", "1");
              searchUrl.searchParams.append("licenceOneOf", "2");
              searchUrl.searchParams.append("licenceOneOf", "7");

              const searchResp = await providerLimiter("sepiasearch").run(() => withTimeout(
                fetch(searchUrl.toString(), { headers: { "User-Agent": "Fastvid/1.0 (CC PeerTube clips)" } }),
                14_000,
                `SepiaSearch scene ${sceneIndex}`
              ));
              if (!searchResp.ok) {
                markSepiaSearchResult(false);
                return null;
              }
              markSepiaSearchResult(true);
              return await searchResp.json() as { data?: SepiaHit[] };
            },
            "fetchSepiaSearchVideos"
          );
          if (!data) return [];
          providerMetrics(sourcingCache, "sepiasearch").resultCount += data.data?.length ?? 0;
          return (data.data ?? []).map((item) => ({ item, query }));
        } catch (err) {
          // RONDE 68: a cancellation FastVid caused is not a provider fault — see isScopeAbortError.
          if (!isScopeAbortError(err)) markSepiaSearchResult(false);
          console.warn(`[Pipeline] SepiaSearch query "${query}" failed:`, (err as Error).message);
          return [];
        }
      })
    );

    for (const { item, query } of perQueryHits.flat()) {
      if (ranked.length >= count * 4) break;
      const host = item.channel?.host;
      const uuid = item.uuid;
      if (!host || !uuid || item.isLive || seenUuids.has(uuid)) continue;
      if ((item.duration ?? 0) < 8 || (item.duration ?? 0) > 900) continue;
      const title = item.name ?? "";
      const score = scoreSepiaSearchHit(title, query, personName, beatKeywords);
      if (score < 0) continue;
      seenUuids.add(uuid);
      ranked.push({ uuid, host, title, query, score });
    }

    ranked.sort((a, b) => b.score - a.score);

    let downloaded = 0;
    for (const hit of ranked) {
      if (downloaded >= count) break;
      // Pre-download visual dedup: skip a PeerTube video we already adopted this render,
      // before the per-item metadata call or the download itself — see providerAssetKey.
      if (providerAssetAlreadyUsed(usedProviderKeys, sourcingCache, "sepiasearch", hit.uuid)) continue;
      try {
        const metaUrl = `https://${hit.host}/api/v1/videos/${hit.uuid}`;
        const metaResp = await withTimeout(
          fetch(metaUrl, { headers: { "User-Agent": "Fastvid/1.0" } }),
          12_000,
          `PeerTube meta scene ${sceneIndex}`
        );
        if (!metaResp.ok) continue;
        const meta = await metaResp.json() as {
          name?: string;
          description?: string;
          tags?: Array<{ name?: string } | string>;
          streamingPlaylists?: Array<{
            files?: Array<{
              fileDownloadUrl?: string;
              fileUrl?: string;
              size?: number;
              resolution?: { id?: number };
            }>;
          }>;
        };
        const metaTitle = meta.name ?? hit.title;
        const tagNames = (meta.tags ?? [])
          .map((t) => (typeof t === "string" ? t : t.name ?? ""))
          .filter(Boolean)
          .join(" ");
        const metaHay = `${metaTitle} ${meta.description ?? ""} ${tagNames} ${hit.query}`;
        if (personName && !textMentionsPersonName(metaHay, personName)) continue;
        const metaScore =
          scoreVisualRelevance(metaHay.toLowerCase(), beatKeywords) +
          (textMentionsPersonName(metaHay, personName) ? 3 : 0);
        if (beatKeywords.length > 0 && metaScore < 2 && personName) continue;
        // RONDE 5 / FIX 9 — the keyword floor above only ever applied WHEN a person anchor
        // existed; without one, a single-word overlap was enough to adopt anything. Render
        // 517: the historical rescue path (personName empty on that route) adopted
        // "[SFM Ponies] Little Pip explosive escape" on the word "escape" and
        // "Suicide Commando" (a band) on the word "suicide", and the first one filled two
        // whole scenes. The floor below closes that: with no person anchor, the candidate's
        // PROVIDER-AUTHORED text (title + description + tags — deliberately excluding
        // hit.query, which is our own search string and would make the check circular, per
        // the scriptImageFallback precedent above scoreVisualRelevance) must share at least
        // 2 beat keywords. Real matches ("Hitler bunker Berlin 1945 newsreel") clear this
        // trivially; one-word keyword collisions no longer do. No threshold, ranking or
        // VisionGate change — this only refuses to download obviously off-topic candidates.
        if (!personName && beatKeywords.length > 0) {
          const providerScore = scoreVisualRelevance(
            `${metaTitle} ${meta.description ?? ""} ${tagNames}`.toLowerCase(),
            beatKeywords
          );
          if (providerScore < 2) {
            console.log(
              `[Pipeline] Scene ${sceneIndex}: SepiaSearch candidate rejected (no person anchor, ` +
              `providerScore=${providerScore}<2): ${metaTitle.slice(0, 70)}`
            );
            continue;
          }
        }

        const files = meta.streamingPlaylists?.[0]?.files ?? [];
        const mp4 = files
          .filter((f) => (f.fileDownloadUrl || f.fileUrl) && (f.size ?? 0) > 50_000)
          .sort((a, b) => {
            const resA = a.resolution?.id ?? 720;
            const resB = b.resolution?.id ?? 720;
            const distA = Math.abs(resA - 720);
            const distB = Math.abs(resB - 720);
            if (distA !== distB) return distA - distB;
            return (a.size ?? 0) - (b.size ?? 0);
          })[0];
        const downloadUrl = mp4?.fileDownloadUrl || mp4?.fileUrl;
        if (!downloadUrl || (mp4?.size ?? 0) > 80 * 1024 * 1024) continue;

        const tag = fileTag ? `${fileTag}_` : "";
        const tmpPath = path.join(workDir, `scene_${sceneIndex}_${tag}septube_${downloaded}_tmp`);
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_${tag}septube_${downloaded}.mp4`),
          "sepiasearch",
          hit.uuid,
          sourcingCache,
          { sceneIndex, sourceUrl: downloadUrl, title: hit.title, mediaType: "video", searchRoute: "fetchSepiaSearchVideos" }
        );
        // F3-05: streams straight to tmpPath instead of buffering the whole clip in memory.
        // P0 fix 1: maxBytes matches the existing 80MB post-hoc ceiling below exactly.
        const { response: dlResp, bytesWritten } = await downloadToFileStreaming(
          downloadUrl,
          tmpPath,
          55_000,
          `SepiaSearch download scene ${sceneIndex}`,
          { headers: { "User-Agent": "Fastvid/1.0" } },
          80 * 1024 * 1024
        );
        if (!dlResp.ok || bytesWritten === null) continue;
        if (bytesWritten < 50_000 || bytesWritten > 80 * 1024 * 1024) {
          try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
          continue;
        }
        providerMetrics(sourcingCache, "sepiasearch").downloadCount++;
        if (await trimRemoteVideoToClip(tmpPath, outPath, duration, 5, `SepiaSearch scene ${sceneIndex}`)) {
          // Point 1 (production image-quality hardening): register via the generic
          // sourcingCache/providerAssetKey mechanism so every call site — not only the ones
          // that go through adoptBestCelebrityClip — gets this real, uploader-authored title.
          if (metaTitle) {
            putCachedProviderAsset(sourcingCache, "sepiasearch", hit.uuid, { providerText: { title: metaTitle } });
          }
          results.push({ path: outPath, query: hit.query, title: metaTitle });
          downloaded++;
          // RONDE 20: a completed download proves the peertube fetch endpoint is alive.
          markSepiaDownloadResult(true);
          console.log(
            `[Pipeline] Scene ${sceneIndex}: SepiaSearch CC video (score ${hit.score}): ${metaTitle.slice(0, 60)}`
          );
        }
        try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
      } catch (err) {
        // RONDE 20: 43 of render 526's 225 timeouts were "SepiaSearch download exceeded 55s" —
        // the most expensive single timeout in the pipeline, and invisible to the search-only
        // breaker because the search that produced these hits had succeeded.
        markSepiaDownloadResult(false);
        console.warn(`[Pipeline] SepiaSearch item failed scene ${sceneIndex}:`, (err as Error).message);
      }
    }
  } catch (err) {
    console.warn(`[Pipeline] SepiaSearch failed scene ${sceneIndex}:`, (err as Error).message);
  }
  return results;
}

/** GDELT TV News queries — real US/UK broadcast mentions (Internet Archive TV). */
function buildGdeltTvQueries(personName: string, beatText: string, beatIndex: number): string[] {
  const quoted = `"${personName}"`;
  const clean = beatText.replace(/\[visual:[^\]]*\]/gi, " ").trim();
  const eventQs = scriptEventSearchQueries(clean, [personName]);
  const out: string[] = [];
  for (let i = 0; i < GDELT_TV_STATIONS.length; i++) {
    const station = GDELT_TV_STATIONS[(beatIndex + i) % GDELT_TV_STATIONS.length];
    out.push(`${quoted} station:${station}`);
  }
  for (let i = 0; i < Math.min(2, eventQs.length); i++) {
    const station = GDELT_TV_STATIONS[(beatIndex + i + 1) % GDELT_TV_STATIONS.length];
    out.push(`"${eventQs[i]}" station:${station}`);
  }
  return [...new Set(out)].slice(0, 5);
}

function parseGdeltArchivePreviewUrl(
  previewUrl: string
): { identifier: string; startSec: number; endSec: number } | null {
  const m = previewUrl.match(/archive\.org\/details\/([^#?]+)#start\/(\d+)\/end\/(\d+)/i);
  if (!m) return null;
  const startSec = parseInt(m[2], 10);
  const endSec = parseInt(m[3], 10);
  if (!Number.isFinite(startSec) || !Number.isFinite(endSec) || endSec <= startSec) return null;
  return { identifier: decodeURIComponent(m[1]), startSec, endSec };
}

async function resolveArchiveVideoFileUrl(
  identifier: string,
  sceneIndex: number
): Promise<string | null> {
  const metaUrl = `https://archive.org/metadata/${identifier}/files`;
  const metaResp = await withTimeout(
    fetch(metaUrl, { headers: { "User-Agent": "Fastvid/1.0 (TV news clips)" } }),
    12_000,
    `Archive TV metadata scene ${sceneIndex}`
  );
  if (!metaResp.ok) return null;
  const metaData = await metaResp.json() as {
    result?: Array<{ name: string; format: string; size?: string }>;
  };
  const videoFiles = (metaData.result ?? []).filter((f) =>
    ["h.264", "MPEG4", "MP4", "Ogg Video", "WebM"].includes(f.format)
  );
  if (!videoFiles.length) return null;
  const videoFile = videoFiles.sort(
    (a, b) => parseInt(a.size || "999999999", 10) - parseInt(b.size || "999999999", 10)
  )[0];
  return `https://archive.org/download/${identifier}/${encodeURIComponent(videoFile.name)}`;
}

async function trimArchiveStreamToClip(
  videoUrl: string,
  outputPath: string,
  startSec: number,
  clipDur: number,
  label: string,
  fastMode = false
): Promise<boolean> {
  try {
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -ss ${startSec} -i "${videoUrl}" -t ${clipDur} ` +
          `-vf "${STANDARD_VF}" ` +
          `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset veryfast -crf 22 -an -pix_fmt yuv420p "${outputPath}"`
      ),
      fastMode ? 50_000 : 120_000,
      `Archive stream trim ${label}`
    );
    return fs.existsSync(outputPath) && fs.statSync(outputPath).size > 10_000;
  } catch (err) {
    console.warn(`[Pipeline] trimArchiveStreamToClip failed (${label}):`, (err as Error).message);
    return false;
  }
}

/**
 * GDELT TV News API — real celebrity mentions on CNN/FOX/MSNBC/BBC (Internet Archive TV).
 * Free, no API key; searches closed captions and returns precise broadcast clips.
 */
export async function fetchGdeltTvNewsClips(
  queries: string | string[],
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 1,
  fileTag = "",
  personName = "",
  beatKeywords: string[] = [],
  fastMode = false,
  sourcingCache?: SourcingCache,
  usedProviderKeys?: Set<string>
): Promise<CelebrityClipCandidate[]> {
  const queryList = uniqueQueryStrings(Array.isArray(queries) ? queries : [queries]);
  if (!queryList.length) return [];
  // RONDE 19/20: honor both GDELT breakers — its search endpoint (4×22s station queries per beat)
  // and its per-clip download endpoint (12s each, the dominant cost). Once either has failed
  // repeatedly, skip the whole tier instead of re-paying those timeouts on every beat.
  if (isGdeltInCooldown() || isGdeltDownloadInCooldown()) return [];

  const results: CelebrityClipCandidate[] = [];
  const seenPreviews = new Set<string>();
  let downloaded = 0;

  type GdeltClip = {
    preview_url: string;
    snippet?: string;
    show?: string;
    station?: string;
    query: string;
    score: number;
  };
  const ranked: GdeltClip[] = [];

  try {
    const queryCap = fastMode ? 2 : queryList.length;
    // Fire all per-query searches concurrently — pure network fetches, results are merged
    // and globally re-sorted by score afterward, so query order doesn't matter.
    type GdeltRawClip = { preview_url?: string; snippet?: string; show?: string; station?: string };
    // RONDE 19: track whether GDELT's endpoint actually responded this call so the breaker can trip
    // on a run of pure timeouts. A query that responds (even with zero clips) counts as reachable.
    let gdeltAnyResponse = false;
    let gdeltAnyError = false;
    const perQueryClips = await Promise.all(
      queryList.slice(0, queryCap).map(async (query) => {
        try {
          // Fase 3/9 (beeldkwaliteit vervolgpatch): GDELT was the one provider still doing a
          // raw fetch outside the render-scoped query cache every other provider already uses —
          // same cachedProviderSearch helper, so a query already searched this render (by this
          // beat or an earlier one) neither re-hits the network nor re-parses a fresh payload.
          const data = await cachedProviderSearch(
            sourcingCache,
            "gdelt_tv",
            query,
            async (): Promise<{ clips?: GdeltRawClip[] } | null> => {
              const apiUrl =
                `${GDELT_TV_API}?query=${encodeURIComponent(query)}&mode=ClipGallery&format=json` +
                `&maxrecords=${fastMode ? 4 : 8}&timespan=5y`;
              const resp = await withTimeout(
                fetch(apiUrl, { headers: { "User-Agent": "Fastvid/1.0 (GDELT TV news)" } }),
                fastMode ? 14_000 : 22_000,
                `GDELT TV search scene ${sceneIndex}`
              );
              if (!resp.ok) return null;
              const text = await resp.text();
              if (text.includes("must contain at least one station")) return null;
              try {
                return JSON.parse(text) as { clips?: GdeltRawClip[] };
              } catch {
                return null;
              }
            },
            "fetchGdeltTvNewsClips"
          );
          gdeltAnyResponse = true;
          return (data?.clips ?? []).map((clip) => ({ clip, query }));
        } catch (err) {
          // RONDE 68: a cancellation FastVid caused is not a provider fault — see the note on
          // isScopeAbortError's use at the other provider catches.
          if (!isScopeAbortError(err)) gdeltAnyError = true;
          console.warn(`[Pipeline] GDELT TV query "${query}" failed:`, (err as Error).message);
          return [];
        }
      })
    );
    // Trip/reset the breaker: reachable (any response) resets the streak; an all-timeout batch
    // increments it toward the cooldown. A batch that neither responded nor errored (e.g. all
    // cache hits) leaves the streak untouched.
    if (gdeltAnyResponse) markGdeltSearchResult(true);
    else if (gdeltAnyError) markGdeltSearchResult(false);

    const flatClips = perQueryClips.flat();
    providerMetrics(sourcingCache, "gdelt_tv").resultCount += flatClips.length;

    for (const { clip, query } of flatClips) {
      if (ranked.length >= (fastMode ? count * 2 : count * 4)) break;
      if (!clip.preview_url || seenPreviews.has(clip.preview_url)) continue;
      const hay = `${clip.snippet ?? ""} ${clip.show ?? ""} ${query}`.toLowerCase();
      if (personName && !textMentionsPersonName(hay, personName)) continue;
      const score =
        scoreVisualRelevance(hay, beatKeywords) + (textMentionsPersonName(hay, personName) ? 4 : 0);
      seenPreviews.add(clip.preview_url);
      ranked.push({
        preview_url: clip.preview_url,
        snippet: clip.snippet,
        show: clip.show,
        station: clip.station,
        query,
        score,
      });
    }

    ranked.sort((a, b) => b.score - a.score);

    for (const hit of ranked) {
      if (downloaded >= count) break;
      const parsed = parseGdeltArchivePreviewUrl(hit.preview_url);
      if (!parsed) continue;
      // Fase 1 (beeldkwaliteit vervolgpatch): identity is the specific broadcast SEGMENT
      // (identifier + start second), not just the archive.org identifier — two different
      // moments of the same broadcast are genuinely different clips and must stay adoptable
      // separately; only the exact same segment, found again via a different query/cascade,
      // should be treated as the same asset.
      const segmentId = `${parsed.identifier}@${Math.round(parsed.startSec)}`;
      // Pre-download visual dedup: skip a GDELT segment we already adopted this render, before
      // the archive.org file-URL resolution or the trim/download itself — see providerAssetKey.
      if (providerAssetAlreadyUsed(usedProviderKeys, sourcingCache, "gdelt_tv", segmentId)) continue;
      try {
        const videoUrl = await resolveArchiveVideoFileUrl(parsed.identifier, sceneIndex);
        if (!videoUrl) continue;
        const segmentDur = Math.min(duration, parsed.endSec - parsed.startSec, 60);
        if (segmentDur < 5) continue;

        const tag = fileTag ? `${fileTag}_` : "";
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_${tag}gdelt_${downloaded}.mp4`),
          "gdelt_tv",
          segmentId,
          sourcingCache,
          { sceneIndex, mediaType: "video", searchRoute: "fetchGdeltTvNewsClips" }
        );
        providerMetrics(sourcingCache, "gdelt_tv").downloadCount++;
        const ok = await trimArchiveStreamToClip(
          videoUrl,
          outPath,
          parsed.startSec,
          segmentDur,
          `GDELT TV scene ${sceneIndex}`,
          fastMode
        );
        if (ok) {
          results.push({ path: outPath, query: hit.query, title: hit.show ?? hit.snippet });
          downloaded++;
          // RONDE 20: a completed download proves the clip endpoint is reachable — reset the
          // download breaker's streak (see the catch below).
          markGdeltDownloadResult(true);
          console.log(
            `[Pipeline] Scene ${sceneIndex}: GDELT TV news (${hit.station ?? "TV"}): ` +
              `${hit.show?.slice(0, 50) ?? hit.snippet?.slice(0, 50)}`
          );
        }
      } catch (err) {
        // RONDE 20: RONDE 19's breaker only watched GDELT's SEARCH step, but 65 of render 526's
        // 73 GDELT timeouts were here — "Archive TV metadata exceeded 12s", the per-clip download
        // that runs AFTER a successful search. Because a successful search reset the streak, the
        // search-only breaker could never see this failure mode, so GDELT kept costing 12s per
        // clip all render long. Count download failures on their own streak.
        markGdeltDownloadResult(false);
        console.warn(`[Pipeline] GDELT clip failed scene ${sceneIndex}:`, (err as Error).message);
      }
    }
  } catch (err) {
    console.warn(`[Pipeline] GDELT TV search failed scene ${sceneIndex}:`, (err as Error).message);
  }
  return results;
}

/** Europeana — EU broadcast/documentary video (CC/PD), requires free API key. */
export async function fetchEuropeanaVideos(
  queries: string | string[],
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 1,
  fileTag = "",
  personName = "",
  beatKeywords: string[] = [],
  usedProviderKeys?: Set<string>,
  sourcingCache?: SourcingCache
): Promise<CelebrityClipCandidate[]> {
  if (!europeanaSourcingEnabled() || !EUROPEANA_API_KEY?.trim()) return [];
  if (isEuropeanaInCooldown()) return [];
  const queryList = uniqueQueryStrings(Array.isArray(queries) ? queries : [queries]);
  if (!queryList.length) return [];

  const results: CelebrityClipCandidate[] = [];
  const seenIds = new Set<string>();
  let downloaded = 0;
  const authHeader = { Authorization: `ApiKey ${EUROPEANA_API_KEY.trim()}` };
  // F3-29: same cancellation-awareness as fetchInternetArchiveClips — stop searching/
  // downloading as soon as the render has been cancelled, instead of continuing to spend
  // network/API calls on a result nothing will ever use.
  const cancelled = () => {
    const videoId = getActiveVideoId();
    return videoId != null && isVideoGenerationCancelRequested(videoId);
  };
  if (cancelled()) return results;

  for (const query of queryList.slice(0, 3)) {
    if (downloaded >= count) break;
    if (cancelled()) break;
    try {
      type EuropeanaItem = { id?: string; title?: string[]; edmPreview?: string };
      // Phase 5 query cache — qf/reusability/rows are fixed, so the request is a pure
      // function of `query`.
      const searchData = await cachedProviderSearch(
        sourcingCache,
        "europeana",
        query,
        async (): Promise<{ items?: EuropeanaItem[] } | null> => {
          const searchUrl = new URL("https://api.europeana.eu/record/v2/search.json");
          searchUrl.searchParams.set("query", query);
          searchUrl.searchParams.set("qf", "TYPE:VIDEO");
          searchUrl.searchParams.set("reusability", "open");
          // Credit optimization: each candidate needs its own record-fetch to check edmRights
          // (the required per-item license gate — unchanged), so this bounds the worst case where
          // most results in a page lack an explicit rights URL. 6 still gives a real chance of
          // finding a licensed item per query; the item loop below already breaks the moment
          // `downloaded >= count` is reached, so this only caps the miss case, not the normal one.
          searchUrl.searchParams.set("rows", "6");

          const searchResp = await providerLimiter("europeana").run(() => withTimeout(
            fetch(searchUrl.toString(), { headers: { ...authHeader, "User-Agent": "Fastvid/1.0" } }),
            14_000,
            `Europeana search scene ${sceneIndex}`
          ));
          if (!searchResp.ok) {
            markEuropeanaSearchResult(false);
            return null;
          }
          markEuropeanaSearchResult(true);
          return await searchResp.json() as { items?: EuropeanaItem[] };
        },
        "fetchEuropeanaVideos"
      );
      if (!searchData) continue;
      providerMetrics(sourcingCache, "europeana").resultCount += searchData.items?.length ?? 0;
      const items = (searchData.items ?? [])
        .filter((item) => {
          const title = (item.title ?? []).join(" ");
          const hay = `${title} ${query}`.toLowerCase();
          if (personName && !textMentionsPersonName(hay, personName)) return false;
          return true;
        })
        .sort(
          (a, b) =>
            scoreVisualRelevance(`${(b.title ?? []).join(" ")} ${query}`, beatKeywords) -
            scoreVisualRelevance(`${(a.title ?? []).join(" ")} ${query}`, beatKeywords)
        );

      for (const item of items) {
        if (downloaded >= count) break;
        if (cancelled()) break;
        const recordId = item.id;
        if (!recordId || seenIds.has(recordId)) continue;
        seenIds.add(recordId);
        // Pre-download visual dedup: skip a Europeana record we already adopted this render,
        // before the per-item record call or the download itself — see providerAssetKey.
        if (providerAssetAlreadyUsed(usedProviderKeys, sourcingCache, "europeana", recordId)) continue;
        try {
          type EuropeanaRecord = {
            object?: {
              aggregations?: Array<{ edmIsShownBy?: string; edmIsShownAt?: string; edmRights?: string | string[] }>;
              proxies?: Array<{ dcCreator?: string[] | Record<string, string[]> }>;
            };
          };
          // Phase 6 provider asset cache: the same mechanism already proven for Internet
          // Archive — two cascades can surface the same Europeana recordId via two different
          // queries, so the per-item record (metadata + edmRights license) call is cached per
          // identifier, including a cached license *rejection*.
          const cachedAsset = getCachedProviderAsset(sourcingCache, "europeana", recordId);
          if (cachedAsset && cachedAsset.licenseAllowed === false) {
            providerMetrics(sourcingCache, "europeana").licenseRejectedCacheHits++;
            continue;
          }
          let recordData = cachedAsset?.metadata as EuropeanaRecord | undefined;
          if (!recordData) {
            const recordUrl = `https://api.europeana.eu/record/v2${recordId}.json?profile=rich`;
            const recordResp = await withTimeout(
              fetch(recordUrl, { headers: { ...authHeader, "User-Agent": "Fastvid/1.0" } }),
              12_000,
              `Europeana record scene ${sceneIndex}`
            );
            if (!recordResp.ok) continue;
            recordData = await recordResp.json() as EuropeanaRecord;
            providerMetrics(sourcingCache, "europeana").metadataCount++;
            providerMetrics(sourcingCache, "europeana").licenseCalls++;
            putCachedProviderAsset(sourcingCache, "europeana", recordId, {
              canonicalUrl: `https://www.europeana.eu/item${recordId}`,
              metadata: recordData,
            });
          } else {
            providerMetrics(sourcingCache, "europeana").metadataCacheHits++;
            providerMetrics(sourcingCache, "europeana").licenseCacheHits++;
          }
          const aggregations = recordData.object?.aggregations ?? [];
          const mediaAgg = aggregations.find((a) => a.edmIsShownBy) ?? aggregations.find((a) => a.edmIsShownAt);
          const mediaUrl = mediaAgg?.edmIsShownBy ?? mediaAgg?.edmIsShownAt;
          if (!mediaUrl || !/\.(mp4|webm|mov|m4v)/i.test(mediaUrl)) continue;

          // F3-30 license-safety gate: the search already filters reusability=open, but that's
          // a query-level hint, not a per-item guarantee — require an explicit rights URL on
          // THIS item's aggregation before it's ever downloaded. No rights URL → skip, never
          // "found it, so it must be free".
          const rawRights = mediaAgg?.edmRights;
          const rightsUrl = Array.isArray(rawRights) ? rawRights[0] : rawRights;
          if (!rightsUrl?.trim()) {
            // Cache the rejection (Phase 6) so a later cascade that resurfaces this recordId
            // skips it above without repeating the record call. The gate itself is unchanged.
            putCachedProviderAsset(sourcingCache, "europeana", recordId, { licenseAllowed: false });
            continue;
          }
          putCachedProviderAsset(sourcingCache, "europeana", recordId, { licenseAllowed: true });
          // Point 1 (production image-quality hardening): Europeana's own search-result title
          // (already used above for relevance scoring/person filtering) was never registered as
          // providerText, so adoptClip's relevance floor and the entity/person gates couldn't
          // see it.
          const europeanaTitle = (item.title ?? []).join(" ").trim();
          if (europeanaTitle) {
            putCachedProviderAsset(sourcingCache, "europeana", recordId, {
              providerText: { title: europeanaTitle },
            });
          }

          const creatorField = recordData.object?.proxies?.find((p) => p.dcCreator)?.dcCreator;
          const sourceCreator = Array.isArray(creatorField)
            ? creatorField[0]
            : creatorField
            ? Object.values(creatorField)[0]?.[0]
            : undefined;

          const tag = fileTag ? `${fileTag}_` : "";
          const tmpPath = path.join(workDir, `scene_${sceneIndex}_${tag}euro_${downloaded}_tmp`);
          const outPath = tagPathWithProviderAsset(
            path.join(workDir, `scene_${sceneIndex}_${tag}euro_${downloaded}.mp4`),
            "europeana",
            recordId,
            sourcingCache,
            { sceneIndex, sourceUrl: mediaUrl, mediaType: "video", searchRoute: "fetchEuropeanaVideos" }
          );
          // F3-05: streams straight to tmpPath instead of buffering the whole clip in memory.
          // P0 fix 1: maxBytes matches the existing 80MB post-hoc ceiling below exactly.
          const { response: dlResp, bytesWritten } = await downloadToFileStreaming(
            mediaUrl,
            tmpPath,
            55_000,
            `Europeana download scene ${sceneIndex}`,
            { headers: { "User-Agent": "Fastvid/1.0" } },
            80 * 1024 * 1024
          );
          if (!dlResp.ok || bytesWritten === null) continue;
          if (bytesWritten < 50_000 || bytesWritten > 80 * 1024 * 1024) {
            try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
            continue;
          }
          providerMetrics(sourcingCache, "europeana").downloadCount++;
          if (await trimRemoteVideoToClip(tmpPath, outPath, duration, 3, `Europeana scene ${sceneIndex}`)) {
            results.push({
              path: outPath,
              query,
              sourceUrl: `https://www.europeana.eu/item${recordId}`,
              sourcePlatform: "europeana",
              sourceCreator,
              licenseUrl: rightsUrl,
              license: rightsUrl,
              title: (item.title ?? []).join(" ") || undefined,
            });
            downloaded++;
            console.log(
              `[Pipeline] Scene ${sceneIndex}: Europeana video: ${(item.title ?? []).join(" ").slice(0, 60)}`
            );
          }
          try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
        } catch (err) {
          console.warn(`[Pipeline] Europeana item failed scene ${sceneIndex}:`, (err as Error).message);
        }
      }
    } catch (err) {
      // RONDE 68: a cancellation FastVid caused is not a provider fault — see isScopeAbortError.
      if (!isScopeAbortError(err)) markEuropeanaSearchResult(false);
      console.warn(`[Pipeline] Europeana search failed scene ${sceneIndex}:`, (err as Error).message);
    }
  }
  return results;
}

/** Vimeo Creative Commons — interviews/documentaries (requires free access token). */
async function fetchVimeoCCVideos(
  queries: string | string[],
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 1,
  fileTag = "",
  personName = "",
  beatKeywords: string[] = [],
  usedProviderKeys?: Set<string>,
  sourcingCache?: SourcingCache
): Promise<CelebrityClipCandidate[]> {
  if (!VIMEO_ACCESS_TOKEN?.trim()) return [];
  const queryList = uniqueQueryStrings(Array.isArray(queries) ? queries : [queries]);
  if (!queryList.length) return [];
  if (isVimeoInCooldown()) return [];

  const results: CelebrityClipCandidate[] = [];
  const vimeoHeaders = {
    Authorization: `Bearer ${VIMEO_ACCESS_TOKEN.trim()}`,
    Accept: "application/vnd.vimeo.*+json;version=3.4",
    "User-Agent": "Fastvid/1.0",
  };
  const seenUris = new Set<string>();
  let downloaded = 0;

  for (const query of queryList.slice(0, 3)) {
    if (downloaded >= count) break;
    try {
      type VimeoHit = { uri?: string; name?: string; description?: string };
      // Phase 5 query cache — per_page/sort/fields are fixed, so the request is a pure
      // function of `query`.
      const searchData = await cachedProviderSearch(
        sourcingCache,
        "vimeo",
        query,
        async (): Promise<{ data?: VimeoHit[] } | null> => {
          const searchUrl =
            `https://api.vimeo.com/videos?query=${encodeURIComponent(query)}&filter=CC` +
            `&per_page=10&sort=relevant&fields=uri,name,description,link`;
          const searchResp = await providerLimiter("vimeo").run(() => withTimeout(
            fetch(searchUrl, { headers: vimeoHeaders }),
            14_000,
            `Vimeo CC search scene ${sceneIndex}`
          ));
          if (!searchResp.ok) {
            markVimeoSearchResult(false);
            return null;
          }
          markVimeoSearchResult(true);
          return await searchResp.json() as { data?: VimeoHit[] };
        },
        "fetchVimeoCCVideos"
      );
      if (!searchData) continue;
      providerMetrics(sourcingCache, "vimeo").resultCount += searchData.data?.length ?? 0;

      for (const video of searchData.data ?? []) {
        if (downloaded >= count) break;
        const uri = video.uri;
        if (!uri || seenUris.has(uri)) continue;
        const hay = `${video.name ?? ""} ${video.description ?? ""} ${query}`.toLowerCase();
        if (personName && !textMentionsPersonName(hay, personName)) continue;
        if (beatKeywords.length > 0 && scoreVisualRelevance(hay, beatKeywords) < 1) continue;
        seenUris.add(uri);
        // Pre-download visual dedup: skip a Vimeo video we already adopted this render,
        // before the per-item detail call or the download itself — see providerAssetKey.
        if (providerAssetAlreadyUsed(usedProviderKeys, sourcingCache, "vimeo", uri)) continue;

        try {
          const detailUrl = `https://api.vimeo.com${uri}?fields=download,name`;
          const detailResp = await withTimeout(
            fetch(detailUrl, { headers: vimeoHeaders }),
            12_000,
            `Vimeo detail scene ${sceneIndex}`
          );
          if (!detailResp.ok) continue;
          const detail = await detailResp.json() as {
            download?: Array<{ link?: string; quality?: string; size?: number }>;
          };
          const dl =
            detail.download
              ?.filter((d) => d.link && (d.size ?? 0) < 80 * 1024 * 1024)
              .sort((a, b) => {
                const qa = parseInt((a.quality ?? "720").replace(/\D/g, ""), 10) || 720;
                const qb = parseInt((b.quality ?? "720").replace(/\D/g, ""), 10) || 720;
                return Math.abs(qa - 720) - Math.abs(qb - 720);
              })[0] ?? detail.download?.find((d) => d.link);
          const downloadUrl = dl?.link;
          if (!downloadUrl) continue;

          const tag = fileTag ? `${fileTag}_` : "";
          const tmpPath = path.join(workDir, `scene_${sceneIndex}_${tag}vimeo_${downloaded}_tmp`);
          const outPath = tagPathWithProviderAsset(
            path.join(workDir, `scene_${sceneIndex}_${tag}vimeo_${downloaded}.mp4`),
            "vimeo",
            uri,
            sourcingCache,
            { sceneIndex, mediaType: "video", searchRoute: "fetchVimeoCCVideos" }
          );
          // F3-05: streams straight to tmpPath instead of buffering the whole clip in memory.
          // P0 fix 1: maxBytes matches the existing 80MB post-hoc ceiling below exactly.
          const { response: dlResp, bytesWritten } = await downloadToFileStreaming(
            downloadUrl,
            tmpPath,
            55_000,
            `Vimeo download scene ${sceneIndex}`,
            { headers: { "User-Agent": "Fastvid/1.0" } },
            80 * 1024 * 1024
          );
          if (!dlResp.ok || bytesWritten === null) continue;
          if (bytesWritten < 50_000 || bytesWritten > 80 * 1024 * 1024) {
            try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
            continue;
          }
          providerMetrics(sourcingCache, "vimeo").downloadCount++;
          if (await trimRemoteVideoToClip(tmpPath, outPath, duration, 5, `Vimeo CC scene ${sceneIndex}`)) {
            // Point 1 (production image-quality hardening): register via the generic
            // sourcingCache/providerAssetKey mechanism so every call site — not only the ones
            // that go through adoptBestCelebrityClip — gets this real, uploader-authored title.
            if (video.name) {
              putCachedProviderAsset(sourcingCache, "vimeo", uri, { providerText: { title: video.name } });
            }
            results.push({ path: outPath, query, title: video.name });
            downloaded++;
            console.log(`[Pipeline] Scene ${sceneIndex}: Vimeo CC video: ${video.name?.slice(0, 60)}`);
          }
          try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
        } catch (err) {
          console.warn(`[Pipeline] Vimeo item failed scene ${sceneIndex}:`, (err as Error).message);
        }
      }
    } catch (err) {
      // RONDE 68: a cancellation FastVid caused is not a provider fault — see isScopeAbortError.
      if (!isScopeAbortError(err)) markVimeoSearchResult(false);
      console.warn(`[Pipeline] Vimeo CC search failed scene ${sceneIndex}:`, (err as Error).message);
    }
  }
  return results;
}

/** media.ccc.de — CC-BY conference talks (strong for Musk/Tesla/tech figures). */
async function fetchMediaCccVideos(
  query: string,
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 1,
  fileTag = "",
  usedProviderKeys?: Set<string>,
  sourcingCache?: SourcingCache
): Promise<string[]> {
  if (!query?.trim()) return [];
  if (isMediaCccInCooldown()) return [];
  const results: string[] = [];
  try {
    type MediaCccEvent = {
      title?: string;
      recordings?: Array<{
        mime_type?: string;
        folder?: string;
        filename?: string;
        recording_url?: string;
        length?: number;
        high_quality?: boolean;
      }>;
    };
    // Phase 5 query cache — the search URL is a pure function of `query`.
    const data = await cachedProviderSearch(
      sourcingCache,
      "media_ccc",
      query,
      async (): Promise<{ events?: MediaCccEvent[] } | null> => {
        const searchUrl = `https://api.media.ccc.de/public/events/search?q=${encodeURIComponent(query)}`;
        const searchResp = await providerLimiter("mediaccc").run(() => withTimeout(
          fetch(searchUrl, { headers: { "User-Agent": "Fastvid/1.0 (media.ccc.de CC)" } }),
          12_000,
          `media.ccc search scene ${sceneIndex}`
        ));
        if (!searchResp.ok) {
          markMediaCccSearchResult(false);
          return null;
        }
        markMediaCccSearchResult(true);
        return await searchResp.json() as { events?: MediaCccEvent[] };
      },
      "fetchMediaCccVideos"
    );
    if (!data) return [];
    const events = data.events ?? [];
    providerMetrics(sourcingCache, "media_ccc").resultCount += events.length;

    let downloaded = 0;
    for (const event of events) {
      if (downloaded >= count) break;
      const recs = event.recordings ?? [];
      const videoRec =
        recs.find((r) => r.mime_type === "video/mp4" && r.recording_url) ??
        recs.find(
          (r) =>
            r.recording_url &&
            /video\/mp4|\.mp4/i.test(`${r.mime_type ?? ""} ${r.filename ?? ""}`) &&
            /h264|mp4/i.test(`${r.folder ?? ""} ${r.filename ?? ""}`)
        );
      if (!videoRec?.recording_url) continue;
      if ((videoRec.length ?? 0) > 0 && (videoRec.length ?? 0) < 8) continue;
      // Pre-download visual dedup: media.ccc's typed search response never carries a discrete
      // event/recording ID, so its recording_url (already known here, before download) is the
      // canonical-URL fallback documented in the provider-key scheme — skip a recording we
      // already adopted this render before spending the download.
      if (providerAssetAlreadyUsed(usedProviderKeys, sourcingCache, "media_ccc", videoRec.recording_url)) continue;

      try {
        const tag = fileTag ? `${fileTag}_` : "";
        const tmpPath = path.join(workDir, `scene_${sceneIndex}_${tag}ccc_${downloaded}_tmp`);
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_${tag}ccc_${downloaded}.mp4`),
          "media_ccc",
          videoRec.recording_url,
          sourcingCache,
          { sceneIndex, sourceUrl: videoRec.recording_url, mediaType: "video", searchRoute: "fetchMediaCccVideos" }
        );
        // Fase 4: real media.ccc-authored talk title, independent of our search query.
        putCachedProviderAsset(sourcingCache, "media_ccc", videoRec.recording_url, {
          providerText: { title: event.title },
        });
        // F3-05: streams straight to tmpPath instead of buffering the whole clip in memory.
        // P0 fix 1: maxBytes matches the existing 120MB post-hoc ceiling below exactly.
        const { response: dlResp, bytesWritten } = await downloadToFileStreaming(
          videoRec.recording_url,
          tmpPath,
          90_000,
          `media.ccc download scene ${sceneIndex}`,
          { headers: { "User-Agent": "Fastvid/1.0" } },
          120 * 1024 * 1024
        );
        if (!dlResp.ok || bytesWritten === null) continue;
        let cccFileSize: number;
        try {
          cccFileSize = fs.statSync(tmpPath).size;
        } catch {
          continue;
        }
        if (cccFileSize < 80_000 || cccFileSize > 120 * 1024 * 1024) {
          try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
          continue;
        }
        providerMetrics(sourcingCache, "media_ccc").downloadCount++;
        if (await trimRemoteVideoToClip(tmpPath, outPath, duration, 10, `media.ccc scene ${sceneIndex}`)) {
          results.push(outPath);
          downloaded++;
          console.log(`[Pipeline] Scene ${sceneIndex}: media.ccc video: ${event.title?.slice(0, 60)}`);
        }
        try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
      } catch (err) {
        console.warn(`[Pipeline] media.ccc download failed scene ${sceneIndex}:`, (err as Error).message);
      }
    }
  } catch (err) {
    // RONDE 68: a cancellation FastVid caused is not a provider fault — see isScopeAbortError.
    if (!isScopeAbortError(err)) markMediaCccSearchResult(false);
    console.warn(`[Pipeline] media.ccc search failed scene ${sceneIndex}:`, (err as Error).message);
  }
  return results;
}

function personMatchesTechCccTopic(personName: string, beatText = ""): boolean {
  const hay = `${personName} ${beatText}`.toLowerCase();
  return /\b(musk|tesla|spacex|bezos|zuckerberg|jobs|gates|cybertruck|starlink|jenner|kardashian|celebrity|billionaire)\b/.test(
    hay
  );
}

/**
 * Real celebrity/person video without YouTube quota (all persons, script-aware queries):
 * Wikimedia → GDELT TV News → SepiaSearch → Archive → Europeana → Vimeo CC → CCC → Flickr.
 */
async function fetchPersonCelebrityVideoClips(
  personName: string,
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number,
  fileTag: string,
  beatIndex: number,
  beatText = "",
  fastMode = false,
  usedProviderKeys?: Set<string>,
  sourcingCache?: SourcingCache
): Promise<CelebrityClipCandidate[]> {
  // RONDE 90 (§2): forcePerson is right here and only here — this function exists to fetch
  // footage OF `personName`, so the person is the caller's own proven subject rather than an
  // inference about the sentence. Everything else the queries add must still come from the beat.
  return withSearchProvenance(buildVerifiedQueryContextForBeat(beatText, { forcePerson: personName }), () =>
    fetchPersonCelebrityVideoClipsInner(personName, duration, workDir, sceneIndex, count, fileTag, beatIndex, beatText, fastMode, usedProviderKeys, sourcingCache)
  );
}

async function fetchPersonCelebrityVideoClipsInner(
  personName: string,
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number,
  fileTag: string,
  beatIndex: number,
  beatText = "",
  fastMode = false,
  usedProviderKeys?: Set<string>,
  sourcingCache?: SourcingCache
): Promise<CelebrityClipCandidate[]> {
  const results: CelebrityClipCandidate[] = [];
  const beatKeywords = buildPersonBeatRelevanceKeywords(personName, beatText);
  const scriptQueries = buildPersonCelebrityVideoQueries(personName, beatText, beatIndex);
  const gdeltQueries = buildGdeltTvQueries(personName, beatText, beatIndex);
  const candidateTarget = fastMode ? Math.max(count, 2) : Math.max(count * 2, 4);
  const scriptQueryCap = fastMode ? 3 : scriptQueries.length;

  for (const q of scriptQueries.slice(0, scriptQueryCap)) {
    if (results.length >= candidateTarget) break;
    const wikiHits = await fetchWikimediaVideos(
      q,
      duration,
      workDir,
      sceneIndex,
      candidateTarget - results.length,
      fileTag,
      personName,
      beatKeywords,
      usedProviderKeys,
      sourcingCache
    );
    results.push(...wikiHits);
  }

  if (results.length < candidateTarget) {
    const gdeltHits = await fetchGdeltTvNewsClips(
      gdeltQueries,
      duration,
      workDir,
      sceneIndex,
      fastMode ? 1 : candidateTarget - results.length,
      fileTag,
      personName,
      beatKeywords,
      fastMode,
      sourcingCache,
      usedProviderKeys
    );
    results.push(...gdeltHits);
  }

  if (results.length < candidateTarget) {
    const septubeHits = await fetchSepiaSearchVideos(
      scriptQueries.slice(0, fastMode ? 3 : scriptQueries.length),
      duration,
      workDir,
      sceneIndex,
      candidateTarget - results.length,
      fileTag,
      personName,
      beatKeywords,
      usedProviderKeys,
      sourcingCache
    );
    results.push(...septubeHits);
  }

  if (results.length < candidateTarget) {
    const archiveHits = await fetchInternetArchiveClips(
      buildPersonArchiveVideoQueries(personName, beatIndex, beatText),
      duration,
      workDir,
      sceneIndex,
      candidateTarget - results.length,
      fileTag,
      personName,
      beatKeywords,
      usedProviderKeys,
      sourcingCache
    );
    results.push(...archiveHits);
  }

  if (results.length < candidateTarget && europeanaSourcingEnabled() && EUROPEANA_API_KEY && !fastMode) {
    const euroHits = await fetchEuropeanaVideos(
      scriptQueries,
      duration,
      workDir,
      sceneIndex,
      candidateTarget - results.length,
      fileTag,
      personName,
      beatKeywords,
      usedProviderKeys,
      sourcingCache
    );
    results.push(...euroHits);
  }

  if (!fastMode && results.length < candidateTarget && VIMEO_ACCESS_TOKEN) {
    const vimeoHits = await fetchVimeoCCVideos(
      scriptQueries,
      duration,
      workDir,
      sceneIndex,
      candidateTarget - results.length,
      fileTag,
      personName,
      beatKeywords,
      usedProviderKeys,
      sourcingCache
    );
    results.push(...vimeoHits);
  }

  if (results.length < candidateTarget && personMatchesTechCccTopic(personName, beatText)) {
    const cccPaths = await fetchMediaCccVideos(
      personName,
      duration,
      workDir,
      sceneIndex,
      candidateTarget - results.length,
      fileTag,
      usedProviderKeys,
      sourcingCache
    );
    for (const p of cccPaths) {
      results.push({ path: p, query: `${personName} conference` });
    }
  }

  if (results.length < candidateTarget && FLICKR_API_KEY) {
    for (const q of scriptQueries.slice(0, 3)) {
      if (results.length >= candidateTarget) break;
      const flickrPaths = await fetchFlickrCCVideos(
        q,
        duration,
        workDir,
        sceneIndex,
        candidateTarget - results.length,
        fileTag,
        personName,
        beatKeywords,
        usedProviderKeys,
        sourcingCache
      );
      for (const p of flickrPaths) {
        results.push({ path: p, query: q });
      }
    }
  }

  const seen = new Set<string>();
  return results
    .filter((c) => {
      if (seen.has(c.path)) return false;
      seen.add(c.path);
      return true;
    })
    .sort(
      (a, b) =>
        scoreCelebrityCandidate(b, beatText, personName, beatKeywords) -
        scoreCelebrityCandidate(a, beatText, personName, beatKeywords)
    )
    .slice(0, candidateTarget);
}

// ─── 3c2n. NASA Images & Video Library (public domain US gov footage) ─────────
// F3-48: exported (visibility only, no logic changed) so
// videoPipeline.f348NasaAssetParsing.test.ts can cover the asset-manifest parsing fix directly.
export async function fetchNasaVideoClips(
  query: string,
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 2,
  usedProviderKeys?: Set<string>,
  sourcingCache?: SourcingCache
): Promise<string[]> {
  if (!query?.trim()) return [];
  if (isNasaInCooldown()) return [];
  const results: string[] = [];
  try {
    type NasaItem = { data?: Array<{ nasa_id?: string; title?: string }> };
    // Phase 5 query cache — the search URL is a pure function of `query`.
    const data = await cachedProviderSearch(
      sourcingCache,
      "nasa",
      query,
      async (): Promise<{ collection?: { items?: NasaItem[] } } | null> => {
        const searchUrl = `https://images-api.nasa.gov/search?q=${encodeURIComponent(query)}&media_type=video`;
        const searchResp = await providerLimiter("nasa").run(() => withTimeout(
          fetch(searchUrl, { headers: { "User-Agent": "Fastvid/1.0 (NASA public domain footage)" } }),
          12_000,
          `NASA video search scene ${sceneIndex}`
        ));
        if (!searchResp.ok) {
          markNasaSearchResult(false);
          return null;
        }
        markNasaSearchResult(true);
        return await searchResp.json() as { collection?: { items?: NasaItem[] } };
      },
      "fetchNasaVideoClips"
    );
    if (!data) return [];
    const items = data.collection?.items ?? [];
    let fetched = 0;
    for (const item of items) {
      if (fetched >= count) break;
      const nasaId = item.data?.[0]?.nasa_id;
      const title = item.data?.[0]?.title ?? nasaId;
      if (!nasaId) continue;
      // Pre-download visual dedup: skip a NASA asset we already adopted this render, before
      // the asset-manifest call or the download itself — see providerAssetKey.
      if (providerAssetAlreadyUsed(usedProviderKeys, sourcingCache, "nasa", nasaId)) continue;
      try {
        const assetResp = await withTimeout(
          fetch(`https://images-api.nasa.gov/asset/${nasaId}`, { headers: { "User-Agent": "Fastvid/1.0" } }),
          12_000,
          `NASA asset ${nasaId}`
        );
        if (!assetResp.ok) continue;
        // F3-48: the NASA asset-manifest endpoint (images-api.nasa.gov/asset/{id}) does NOT
        // return a bare array of URL strings — like the sibling /search endpoint above, it
        // wraps its items in the same collection.items envelope, but each item here is
        // { href: string } rather than { data: [...] }. Treating the raw response as string[]
        // made every single call hit "assets.find is not a function" (assets was really the
        // {collection:{items:[...]}} object), so every NASA candidate failed via the catch
        // block below instead of being parsed. Normalized here to the actual href array;
        // an unexpected/malformed response now yields an empty array via `?? []`, so `.find()`
        // never throws — a genuinely empty/unusable response falls through the two `continue`s
        // below exactly like "no mp4 found" already did, not an exception.
        const assetData = await assetResp.json() as {
          collection?: { items?: Array<{ href?: string }> };
        };
        const assetUrls = (assetData.collection?.items ?? [])
          .map((i) => i.href)
          .filter((u): u is string => typeof u === "string" && u.length > 0);
        if (!assetUrls.length) continue;
        const mp4Path = assetUrls.find((u) => /\.mp4$/i.test(u) && !/~mobile|~thumb|~preview|~small/i.test(u))
          ?? assetUrls.find((u) => /\.mp4$/i.test(u));
        if (!mp4Path) continue;
        // RONDE 26: NASA hrefs carry literal spaces in the asset folder name — render 527 fetched
        // ".../video/NHQ_2019_1018_all woman spacewalk/...". Node's fetch tolerated it, but a raw
        // space in a URL is not valid and any proxy or agent in the path may not. Only spaces are
        // escaped, which keeps this idempotent on hrefs that already arrive percent-encoded.
        const mp4Href = mp4Path.replace(/ /g, "%20");
        const mp4Url = mp4Href.startsWith("http")
          ? mp4Href
          : `https://images-assets.nasa.gov${mp4Href.startsWith("/") ? mp4Href : `/${mp4Href}`}`;

        const tmpPath = path.join(workDir, `scene_${sceneIndex}_nasa_${fetched}_tmp.mp4`);
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_nasa_${fetched}.mp4`),
          "nasa",
          nasaId,
          sourcingCache,
          { sceneIndex, mediaType: "video", searchRoute: "fetchNasaVideoClips" }
        );
        // Fase 4: real NASA-authored title, independent of our search query. Uses the raw field
        // (not the `title` local, which falls back to nasaId when absent) so this never stores
        // an ID pretending to be descriptive text.
        putCachedProviderAsset(sourcingCache, "nasa", nasaId, {
          providerText: { title: item.data?.[0]?.title },
        });
        // F3-05: streams straight to tmpPath instead of buffering the whole clip in memory.
        // P0 fix 1: maxBytes matches the existing 80MB post-hoc ceiling below exactly.
        const { response: dlResp, bytesWritten } = await downloadToFileStreaming(
          mp4Url,
          tmpPath,
          60_000,
          `NASA download scene ${sceneIndex}`,
          { headers: { "User-Agent": "Fastvid/1.0" } },
          80 * 1024 * 1024
        );
        if (!dlResp.ok || bytesWritten === null) continue;
        let nasaFileSize: number;
        try {
          nasaFileSize = fs.statSync(tmpPath).size;
        } catch {
          continue;
        }
        if (nasaFileSize < 50_000 || nasaFileSize > 80 * 1024 * 1024) {
          try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
          continue;
        }

        if (await trimRemoteVideoToClip(tmpPath, outPath, duration, 8, `NASA scene ${sceneIndex}`)) {
          results.push(outPath);
          fetched++;
          console.log(`[Pipeline] Scene ${sceneIndex}: NASA video added: ${title}`);
        }
        try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
      } catch (err) {
        console.warn(`[Pipeline] NASA video ${nasaId} failed for scene ${sceneIndex}:`, (err as Error).message);
      }
    }
  } catch (err) {
    // RONDE 68: a cancellation FastVid caused is not a provider fault — see isScopeAbortError.
    if (!isScopeAbortError(err)) markNasaSearchResult(false);
    console.warn(`[Pipeline] NASA video search failed for scene ${sceneIndex}:`, (err as Error).message);
  }
  return results;
}

// F3-28: US National Archives (NARA) Catalog API v2 — small, isolated adapter, modeled
// directly on fetchNasaVideoClips above (same search→asset→download→trim shape, same
// size gate, same trimRemoteVideoToClip). Requires a free NARA_API_KEY (register at
// https://catalog.archives.gov/api/v2) — optional; the function is a clean no-op without it,
// exactly like the existing FLICKR_API_KEY/VIMEO_ACCESS_TOKEN-gated adapters.
export async function fetchNaraClips(
  query: string,
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 1,
  usedProviderKeys?: Set<string>,
  sourcingCache?: SourcingCache
): Promise<string[]> {
  const naraApiKey = process.env.NARA_API_KEY?.trim();
  if (!naraApiKey || !query?.trim()) return [];
  if (isNaraInCooldown()) return [];
  const results: string[] = [];
  try {
    type NaraHit = { _source?: { record?: {
      title?: string;
      digitalObjects?: Array<{ objectUrl?: string; objectType?: string }>;
    } } };
    // Phase 5 query cache. NARA's `limit` is derived from `count`, which varies per caller, so
    // the limit is folded into the cache key — replaying a 3-result payload for a later
    // 9-result request would have silently shrunk the candidate list. Exact-match only.
    const data = await cachedProviderSearch(
      sourcingCache,
      "nara",
      `${query}#n${count * 3}`,
      async (): Promise<{ body?: { hits?: { hits?: NaraHit[] } } } | null> => {
        const searchUrl = `https://catalog.archives.gov/api/v2/records/search?q=${encodeURIComponent(query)}&limit=${count * 3}`;
        const searchResp = await providerLimiter("nara").run(() => withTimeout(
          fetch(searchUrl, { headers: { "x-api-key": naraApiKey, "User-Agent": "Fastvid/1.0 (NARA public archives)" } }),
          12_000,
          `NARA search scene ${sceneIndex}`
        ));
        if (!searchResp.ok) {
          markNaraSearchResult(false);
          return null;
        }
        markNaraSearchResult(true);
        return await searchResp.json() as { body?: { hits?: { hits?: NaraHit[] } } };
      },
      "fetchNaraClips"
    );
    if (!data) return [];
    const hits = data.body?.hits?.hits ?? [];
    let fetched = 0;
    for (const hit of hits) {
      if (fetched >= count) break;
      const record = hit._source?.record;
      const videoObject = record?.digitalObjects?.find(
        (o) => /\.(mp4|mov|m4v)$/i.test(o.objectUrl ?? "") || /video/i.test(o.objectType ?? "")
      );
      const videoUrl = videoObject?.objectUrl;
      if (!videoUrl) continue;
      // Pre-download visual dedup: NARA's typed search response never carries a discrete
      // naId field, so its objectUrl (already known here, before download) is the
      // canonical-URL fallback documented in the provider-key scheme — skip a record we
      // already adopted this render before spending the download.
      if (providerAssetAlreadyUsed(usedProviderKeys, sourcingCache, "nara", videoUrl)) continue;
      try {
        const tmpPath = path.join(workDir, `scene_${sceneIndex}_nara_${fetched}_tmp.mp4`);
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_nara_${fetched}.mp4`),
          "nara",
          videoUrl,
          sourcingCache,
          { sceneIndex, sourceUrl: videoUrl, title: record?.title, mediaType: "video", searchRoute: "fetchNaraClips" }
        );
        // Fase 4: real NARA-authored record title, independent of our search query.
        putCachedProviderAsset(sourcingCache, "nara", videoUrl, {
          providerText: { title: record?.title },
        });
        // P0 fix 1: maxBytes matches the existing 80MB post-hoc ceiling below exactly.
        const { response: dlResp, bytesWritten } = await downloadToFileStreaming(
          videoUrl,
          tmpPath,
          60_000,
          `NARA download scene ${sceneIndex}`,
          { headers: { "User-Agent": "Fastvid/1.0" } },
          80 * 1024 * 1024
        );
        if (!dlResp.ok || bytesWritten === null) continue;
        let naraFileSize: number;
        try {
          naraFileSize = fs.statSync(tmpPath).size;
        } catch {
          continue;
        }
        if (naraFileSize < 50_000 || naraFileSize > 80 * 1024 * 1024) {
          try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
          continue;
        }
        if (await trimRemoteVideoToClip(tmpPath, outPath, duration, 5, `NARA scene ${sceneIndex}`)) {
          results.push(outPath);
          fetched++;
          console.log(`[Pipeline] Scene ${sceneIndex}: NARA video added: ${record?.title ?? videoUrl}`);
        }
        try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
      } catch (err) {
        console.warn(`[Pipeline] NARA video failed for scene ${sceneIndex}:`, (err as Error).message);
      }
    }
  } catch (err) {
    // RONDE 68: a cancellation FastVid caused is not a provider fault — see isScopeAbortError.
    if (!isScopeAbortError(err)) markNaraSearchResult(false);
    console.warn(`[Pipeline] NARA search failed for scene ${sceneIndex}:`, (err as Error).message);
  }
  return results;
}

export type WebWideVideoCandidate = {
  path: string;
  sourceUrl: string;
  sourcePlatform: string;
  sourceCreator?: string;
  licenseUrl?: string;
  license: string;
  title?: string;
  matchedQuery: string;
};

// F3-29: tier 11 of the source cascade (F3-28) — tried only after own archive + tiers 2-10
// (Internet Archive/YouTube CC/Wikimedia/NARA/Flickr/SepiaSearch/Vimeo/media.ccc/NASA) have
// failed for a beat, and only before Pexels/Pixabay (tiers 12-13). License-safe BY
// CONSTRUCTION, not by inference: the only engine here is Openverse (api.openverse.org, no API
// key required — already used elsewhere in this file for stills, see fetchOpenverseImages
// above), queried with license_type=commercial,modification, which only ever returns items
// Openverse itself has already tagged with an explicit CC license — nothing here is "found on
// the web and assumed free". A second, broader-query YouTube-CC retry was considered (YouTube
// CC is already reusable via fetchYouTubeCCClips) and deliberately left out: YouTube CC already
// ran as tier 3 with richer, more specific queries, so retrying it here with weaker queries
// would only burn extra YouTube API quota for near-zero marginal yield — see the F3-29 report
// for the full reasoning. No new API key is required by any of this.
export async function searchWebWideVideoClips(
  queries: string[],
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 1
): Promise<WebWideVideoCandidate[]> {
  const results: WebWideVideoCandidate[] = [];
  const cancelled = () => {
    const videoId = getActiveVideoId();
    return videoId != null && isVideoGenerationCancelRequested(videoId);
  };
  // RONDE 89: the provider gate. This route fans one beat's queries out across several
  // providers, so a query the contract refuses is dropped here, before any of them is asked.
  const uniqueQueries = uniqueQueryStrings(queries)
    .filter((q) => admitProviderQuery("web_wide", q, "searchWebWideVideoClips") !== null)
    .slice(0, 3);
  if (cancelled()) return results;

  for (const query of uniqueQueries) {
    if (results.length >= count) break;
    if (cancelled()) break;
    try {
      const searchUrl = `https://api.openverse.org/v1/images/?q=${encodeURIComponent(query)}&license_type=commercial,modification&page_size=${count * 3}&format=json`;
      const searchResp = await withTimeout(
        fetch(searchUrl, { headers: { "User-Agent": "Fastvid/1.0 (video generation; contact@fastvid.ai)" } }),
        5000,
        `Web-wide discovery search scene ${sceneIndex}`
      );
      if (!searchResp.ok) continue;
      const payload = await searchResp.json() as {
        results?: Array<{
          id: string; url: string; title?: string; license?: string; license_url?: string;
          creator?: string; foreign_landing_url?: string;
        }>;
      };
      const items = payload.results ?? [];

      for (const item of items) {
        if (results.length >= count) break;
        if (cancelled()) break;
        // License-safety gate (F3-29 §4): reject anything without an explicit license tag —
        // belt-and-braces even though the license_type filter above should already guarantee
        // one. "Findable" is never treated as "usable" on its own.
        if (!item.url || !item.license?.trim()) continue;
        if (!/\.(jpg|jpeg|png|webp)(\?|$)/i.test(item.url)) continue;

        const tmpPath = path.join(workDir, `scene_${sceneIndex}_webwide_${results.length}_tmp.jpg`);
        const outPath = path.join(workDir, `scene_${sceneIndex}_webwide_${results.length}.mp4`);
        try {
          const imgResp = await withTimeout(fetch(item.url), 10_000, `Web-wide image download scene ${sceneIndex}`);
          if (!imgResp.ok) continue;
          const imgBuf = Buffer.from(await imgResp.arrayBuffer());
          if (imgBuf.length < 5000) continue; // existing Openverse-still quality gate, unchanged
          fs.writeFileSync(tmpPath, imgBuf);

          await stillImageToVideo(
            tmpPath, outPath, duration, `Web-wide image to video scene ${sceneIndex}`, false, sceneIndex, 0
          );

          if (fs.existsSync(outPath) && fs.statSync(outPath).size > 10_000) {
            results.push({
              path: outPath,
              sourceUrl: item.foreign_landing_url || item.url,
              sourcePlatform: "openverse",
              sourceCreator: item.creator || undefined,
              licenseUrl: item.license_url || undefined,
              license: item.license,
              title: item.title,
              matchedQuery: query,
            });
            console.log(
              `[Pipeline] Scene ${sceneIndex}: web-wide discovery (Openverse) clip added: ${(item.title ?? item.url).slice(0, 60)}`
            );
          } else {
            try { fs.unlinkSync(outPath); } catch { /* ignore */ }
          }
        } catch (err) {
          console.warn(`[Pipeline] Web-wide candidate failed for scene ${sceneIndex}:`, (err as Error).message);
        } finally {
          try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
        }
      }
    } catch (err) {
      console.warn(`[Pipeline] Web-wide discovery search failed for scene ${sceneIndex}:`, (err as Error).message);
    }
  }
  return results;
}



function isSpaceRelatedTopic(...parts: string[]): boolean {
  const text = parts.filter(Boolean).join(" ").toLowerCase();
  return /space|rocket|nasa|esa|spacex|mars|moon|satellite|launch|orbit|astronaut|shuttle|station|tesla|electric vehicle|factory/i.test(text);
}

// F3-34: Internet Archive license gate. A licenseurl the item's own uploader set
// (metadata.licenseurl — see https://help.archive.org/help/rights/) that is explicitly public
// domain or a commercial+derivatives-permitting Creative Commons license is accepted; NC (-nc),
// ND (-nd), or an unrecognized licenseurl is rejected outright. FastVid trims/re-encodes every
// clip (a derivative) and is used commercially, so NC/ND licenses are never usable regardless of
// how "close" they look.
//
// F3-39: archive.org does not require uploaders to set a machine-readable licenseurl — most of
// the mediatype:movies corpus has none — which this gate was treating identically to "explicitly
// restricted" and rejecting outright. metadata.rights (free text, also uploader-set, an actually
// existing field on the same API response) is now read as a fallback ONLY when licenseurl is
// absent: still rejects when rights is also absent (no invented "probably public domain"), still
// rejects NC/ND wording there too, and only accepts an EXPLICIT public-domain statement — no
// looser than the licenseurl path, just reading a second real field instead of inventing rights
// information. A licenseurl that IS present but unrecognized (not public domain, not a
// permissive CC license) is still an unconditional reject — rights is never consulted to
// override an explicit-but-unrecognized licenseurl.
export function isAllowedInternetArchiveLicense(
  licenseUrl: string | undefined | null,
  rights?: string | undefined | null
): boolean {
  const u = licenseUrl?.trim().toLowerCase();
  if (u) {
    if (u.includes("publicdomain")) return true;
    if (u.includes("creativecommons.org/licenses/")) {
      if (u.includes("-nc") || u.includes("-nd")) return false;
      if (u.includes("/by/") || u.includes("/by-sa/")) return true;
    }
    return false;
  }
  const r = rights?.trim().toLowerCase();
  if (!r) return false;
  if (r.includes("-nc") || r.includes("-nd") || /non.?commercial|no derivative/.test(r)) return false;
  return /public domain|no known copyright|no copyright restrictions/.test(r);
}

// ─── 3c2. Fetch Internet Archive Video Clips ────────────────────────────────
export async function fetchInternetArchiveClips(
  queries: string | string[],
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 2,
  fileTag = "",
  personName = "",
  beatKeywords: string[] = [],
  usedProviderKeys?: Set<string>,
  sourcingCache?: SourcingCache
): Promise<CelebrityClipCandidate[]> {
  if (isInternetArchiveInCooldown()) return [];
  const results: CelebrityClipCandidate[] = [];
  const queryList = Array.isArray(queries) ? queries : [queries];
  const uniqueQueries = uniqueQueryStrings(queryList);
  let fetched = 0;
  // Production fix (log-confirmed): trimRemoteVideoToClip's exec() already correctly refuses to
  // run once the render is cancelled/superseded (throwIfActiveRenderCancelled), and that failure
  // was already being reported — but this function's own per-doc/per-query try/catch treated it
  // exactly like any other single-candidate failure (a bad size, a timeout, a 404) and just moved
  // on to the next candidate. A Railway log showed the resulting waste directly: the same scene's
  // Internet Archive search kept retrying — 88 failed attempts, some against the exact same
  // already-failing item over 18 minutes — after the render had already been cancelled, instead
  // of stopping once cancellation was first observed. This check doesn't change any timeout,
  // retry count, or fallback behavior for a render that's actually still running — it only stops
  // *this* function from continuing to search/download/trim once there's nothing left to use the
  // result for.
  const cancelled = () => {
    const videoId = getActiveVideoId();
    return videoId != null && isVideoGenerationCancelRequested(videoId);
  };
  if (cancelled()) return results;

  for (const query of uniqueQueries) {
    if (fetched >= count) break;
    if (cancelled()) break;
    try {
    // Phase 5 query cache: the search URL is a pure function of `query` (rows/fields are fixed),
    // so an identical query from a second cascade this render replays the parsed payload instead
    // of re-hitting archive.org. The candidate list below is walked in full either way.
    const searchData = await cachedProviderSearch(
      sourcingCache,
      "internet_archive",
      query,
      async (): Promise<{ response?: { docs?: Array<{ identifier: string; title: string }> } } | null> => {
        const searchUrl = `https://archive.org/advancedsearch.php?q=${encodeURIComponent(query)}+AND+mediatype:movies&fl[]=identifier,title&rows=12&output=json`;
        const searchResp = await providerLimiter("internetArchive").run(() => fetchWithTimeout(
          searchUrl,
          IS_RAILWAY ? 6_000 : 10_000,
          `Internet Archive search scene ${sceneIndex}`,
          { headers: { 'User-Agent': 'Fastvid/1.0 (video generation)' } }
        ));
        if (!searchResp.ok) {
          markInternetArchiveSearchResult(false);
          return null;
        }
        markInternetArchiveSearchResult(true);
        return await searchResp.json() as { response?: { docs?: Array<{ identifier: string; title: string }> } };
      },
      "fetchInternetArchiveClips"
    );
    if (!searchData) continue;
    providerMetrics(sourcingCache, "internet_archive").resultCount += searchData.response?.docs?.length ?? 0;
    const docs = (searchData.response?.docs ?? [])
      .filter((doc) => {
        const hay = `${doc.title} ${query}`.toLowerCase();
        if (personName && !textMentionsPersonName(hay, personName)) return false;
        return true;
      })
      .sort(
        (a, b) =>
          scoreVisualRelevance(`${b.title} ${query}`, beatKeywords) -
          scoreVisualRelevance(`${a.title} ${query}`, beatKeywords)
      )
      .slice(0, (count - fetched) * 3);
    if (!docs.length) continue;

    // F3-34 metadata shape (hoisted for the concurrent resolve below).
    type IaMetaData = {
      metadata?: {
        licenseurl?: string | string[];
        rights?: string | string[];
        date?: string | string[];
        year?: string | string[];
      };
      files?: Array<{ name: string; format: string; size?: string }>;
      result?: Array<{ name: string; format: string; size?: string }>;
    };

    // RONDE 15: the per-doc metadata call (the slow part — archive.org's /metadata endpoint
    // routinely hits the 8s timeout) used to run ONE AT A TIME inside `for (const doc of docs)`,
    // so ~12 docs × up to 8s serialised to ~90s/scene and almost nothing was left to download
    // (production logs: internet_archive results=192 but downloads=1, plus 150+ "metadata scene"
    // timeouts). The providerLimiter already permits 4 concurrent IA requests, but the sequential
    // loop only ever used one. Resolve metadata for a batch CONCURRENTLY (capped by the same
    // limiter, so archive.org is not hit harder), then run the UNCHANGED license/size/download/
    // trim decision over the resolved batch IN ORDER. Same candidates, same order, same dedup
    // (filtered before the metadata call, exactly as before), same counters — just no longer
    // serialised behind the slow metadata calls.
    const IA_METADATA_BATCH = 4;
    for (let batchStart = 0; batchStart < docs.length; batchStart += IA_METADATA_BATCH) {
      if (fetched >= count) break;
      if (cancelled()) break;
      const batchDocs = docs
        .slice(batchStart, batchStart + IA_METADATA_BATCH)
        // Pre-download visual dedup: skip an archive.org identifier we already adopted this
        // render, before the metadata call, license check, or download — see providerAssetKey.
        .filter((doc) => !providerAssetAlreadyUsed(usedProviderKeys, sourcingCache, "internet_archive", doc.identifier));

      const resolvedBatch = await Promise.all(batchDocs.map(async (doc): Promise<{ doc: typeof doc; metaData: IaMetaData | null }> => {
        // Cancellation short-circuit (F3-01): a doc whose callback has not started yet — queued
        // behind the limiter, or a later batch — bails before spending a metadata call. Cancellation
        // now stops the search at batch granularity (≤ IA_METADATA_BATCH in-flight) instead of the
        // old per-doc granularity, which still prevents the 88-attempt churn that fix targeted.
        if (cancelled()) return { doc, metaData: null };
        // Phase 6 provider asset cache: two cascades can legitimately surface the same
        // archive.org identifier via two different queries (the query cache above only
        // deduplicates identical queries). The metadata call is per-identifier, so it is cached
        // per-identifier — including a cached license *rejection*, so an item this render
        // already rejected is never re-fetched just to be rejected a second time.
        const cachedAsset = getCachedProviderAsset(sourcingCache, "internet_archive", doc.identifier);
        if (cachedAsset && cachedAsset.licenseAllowed === false) {
          providerMetrics(sourcingCache, "internet_archive").licenseRejectedCacheHits++;
          return { doc, metaData: null };
        }
        let metaData = cachedAsset?.metadata as IaMetaData | undefined;
        if (!metaData) {
          // F3-34: fetch the full item record (metadata + files) — dropping the "/files" suffix
          // returns `{ metadata, files, ... }` in one call so the uploader-provided rights fields
          // are available before any download decision.
          const metaUrl = `https://archive.org/metadata/${doc.identifier}`;
          // RONDE 11: 8s (not 15s) — a slow archive.org metadata endpoint is the common case, and
          // cutting losers fast keeps the pipeline moving. RONDE 15 spends this 8s budget 4-wide.
          const metaResp = await providerLimiter("internetArchive").run(() => fetchWithTimeout(
            metaUrl,
            8_000,
            `Internet Archive metadata scene ${sceneIndex}`,
            { headers: { 'User-Agent': 'Fastvid/1.0 (video generation)' } }
          ));
          if (!metaResp.ok) {
            markInternetArchiveSearchResult(false);
            return { doc, metaData: null };
          }
          markInternetArchiveSearchResult(true);
          metaData = await metaResp.json() as IaMetaData;
          providerMetrics(sourcingCache, "internet_archive").metadataCount++;
          providerMetrics(sourcingCache, "internet_archive").licenseCalls++;
          putCachedProviderAsset(sourcingCache, "internet_archive", doc.identifier, {
            canonicalUrl: `https://archive.org/details/${doc.identifier}`,
            metadata: metaData,
          });
        } else {
          providerMetrics(sourcingCache, "internet_archive").metadataCacheHits++;
          providerMetrics(sourcingCache, "internet_archive").licenseCacheHits++;
        }
        return { doc, metaData: metaData ?? null };
      }));

      for (const { doc, metaData } of resolvedBatch) {
      if (fetched >= count) break;
      if (cancelled()) break;
      if (!metaData) continue;
      try {

        // F3-34/F3-39 license gate: reject before any download unless the item's own metadata
        // carries an explicit, permissive-enough licenseurl OR (when licenseurl is absent) an
        // explicit public-domain statement in metadata.rights. "Found via mediatype:movies" is
        // never treated as "usable" on its own — same reasoning as the existing Europeana/
        // Openverse per-item rights gates. No rights info at all, or a non-commercial/
        // no-derivatives license/statement (FastVid trims/re-encodes and is used commercially),
        // is a reject.
        const rawLicenseUrl = metaData.metadata?.licenseurl;
        const licenseUrl = (Array.isArray(rawLicenseUrl) ? rawLicenseUrl[0] : rawLicenseUrl)?.trim();
        const rawRights = metaData.metadata?.rights;
        const rights = (Array.isArray(rawRights) ? rawRights[0] : rawRights)?.trim();
        /**
         * RONDE 124 — the same gate, but it now says WHICH of two things it found.
         *
         * `isAllowedInternetArchiveLicense` returned one boolean, so an -nc/-nd licence (the
         * rightsholder saying no) and an empty metadata field (nobody filled it in) came out
         * identical. This render's log is 56 lines of the second kind, all of them YouTube
         * mirrors:
         *
         *     Archive item youtube-cS2JdEghHDo has no usable license
         *     (licenseurl=none, rights=none) — skipping
         *
         * VERIFIED behaves exactly as `true` did and REJECTED exactly as `false` did. The only
         * new path is UNVERIFIED on a `youtube-*` identifier with ALLOW_UNVERIFIED_YOUTUBE=true,
         * which lets the item continue to the download, the preview check and the vision gate —
         * all unchanged — while every report it appears in says the rights are unproven.
         */
        const licenseDecision = youtubeLicenseDecision({
          identifier: doc.identifier,
          licenseUrl,
          rights,
        });
        const ytMetrics = providerMetrics(sourcingCache, "youtube_archive");
        if (licenseDecision.youtubeVideoId) {
          /**
           * RONDE 147 — count what the METADATA said, not what the decision concluded.
           *
           * `status` can now be OPERATOR_AUTHORIZED, which is neither verified nor rejected. Left
           * on `status`, the else-branch would have booked every operator-authorised item as a
           * licence REJECTION, and the provider table would report mass refusals on a render that
           * used the footage. `metadataStatus` is exactly the value this counter has always meant.
           */
          if (licenseDecision.metadataStatus === "VERIFIED") ytMetrics.licenseVerified++;
          else if (licenseDecision.metadataStatus === "UNVERIFIED") ytMetrics.licenseUnverified++;
          else ytMetrics.licenseRejected++;
          console.log(`[Pipeline] Scene ${sceneIndex}: ${formatYoutubeLicenseLine(licenseDecision)}`);
        }
        if (!licenseDecision.allowed) {
          // Cache the rejection (Phase 6) so a later cascade that resurfaces this identifier
          // skips it above without repeating the metadata call.
          putCachedProviderAsset(sourcingCache, "internet_archive", doc.identifier, {
            licenseAllowed: false,
          });
          console.warn(
            `[Pipeline] Scene ${sceneIndex}: Archive item ${doc.identifier} has no usable license ` +
            `(licenseurl=${licenseUrl ?? "none"}, rights=${rights ?? "none"}, ` +
            `status=${licenseDecision.status}) — skipping`
          );
          continue;
        }
        putCachedProviderAsset(sourcingCache, "internet_archive", doc.identifier, {
          licenseAllowed: true,
        });
        // Point 1 (production image-quality hardening): archive.org's own search-result title
        // (doc.title) is real, provider-authored text — already used above for relevance
        // scoring/person filtering, but never registered as providerText, so adoptClip's
        // relevance floor and the entity/person gates couldn't see it.
        // Point 8 (visual-selection quality upgrade): archive.org's item metadata also commonly
        // carries a real uploader-supplied date/year (metadata.date / metadata.year) — never
        // invented, only ever passed through when the provider itself returned one — which
        // historicalDateAlignmentScore uses as a soft ranking signal.
        const rawIaDate = metaData.metadata?.date ?? metaData.metadata?.year;
        const iaDateHint = (Array.isArray(rawIaDate) ? rawIaDate[0] : rawIaDate)?.trim();
        if (doc.title || iaDateHint) {
          putCachedProviderAsset(sourcingCache, "internet_archive", doc.identifier, {
            providerText: { title: doc.title, dateHint: iaDateHint },
          });
        }

        const videoFiles = (metaData.files ?? metaData.result ?? []).filter(f =>
          ['h.264', 'MPEG4', 'MP4', 'Ogg Video', 'WebM'].includes(f.format)
        );
        if (!videoFiles.length) continue;

        const videoFile = videoFiles.sort((a, b) =>
          parseInt(a.size || '999999999') - parseInt(b.size || '999999999')
        )[0];

        const MAX_ARCHIVE_SIZE = 50 * 1024 * 1024;
        const knownSize = parseInt(videoFile.size || '0');

        const videoUrl = `https://archive.org/download/${doc.identifier}/${encodeURIComponent(videoFile.name)}`;
        const tag = fileTag ? `${fileTag}_` : "";
        const outPath = tagPathWithProviderAsset(
          path.join(workDir, `scene_${sceneIndex}_${tag}archive_${fetched}.mp4`),
          "internet_archive",
          doc.identifier,
          sourcingCache,
          { sceneIndex, title: doc.title, mediaType: "video", searchRoute: "fetchInternetArchiveClips" }
        );
        const tmpPath = path.join(workDir, `scene_${sceneIndex}_${tag}archive_${fetched}_tmp`);

        if (knownSize > MAX_ARCHIVE_SIZE) {
          // RONDE 8 (render 518): archive.org's WW2/history items are routinely FULL FILMS of
          // 100-700MB whose smallest derivative still exceeds the size cap — they used to be
          // skipped outright, which is why the archive's huge historical holdings never reached
          // a video. Fetch only a short segment via ffmpeg's HTTP range seeking instead; any
          // failure falls back to the exact old behavior (skip this item).
          const segmentSec = Math.max(20, Math.ceil(duration) + 8);
          if (!(await fetchArchiveSegmentViaFfmpeg(videoUrl, tmpPath, segmentSec, sceneIndex))) {
            console.warn(`[Pipeline] Scene ${sceneIndex}: Archive clip too large (${(knownSize / 1024 / 1024).toFixed(1)}MB per metadata) and segment fetch failed, skipping`);
            continue;
          }
          console.log(
            `[Pipeline] Scene ${sceneIndex}: Archive segment fetched from large item ` +
            `(${(knownSize / 1024 / 1024).toFixed(1)}MB full file): ${doc.title ?? doc.identifier}`
          );
        } else {
        // F3-05: streams straight to tmpPath instead of buffering the whole clip in memory.
        // P0 fix 1: maxBytes matches the existing MAX_ARCHIVE_SIZE post-hoc ceiling below exactly.
        // RONDE 8: 18s on Railway killed most real archive reel downloads — 45s everywhere;
        // the per-beat budget above remains the real ceiling.
        const { response: dlResp, bytesWritten } = await downloadToFileStreaming(
          videoUrl,
          tmpPath,
          45_000,
          `Internet Archive download scene ${sceneIndex}`,
          { headers: { 'User-Agent': 'Fastvid/1.0 (video generation)' } },
          MAX_ARCHIVE_SIZE
        );
        if (!dlResp.ok || bytesWritten === null) continue;

        if (bytesWritten > MAX_ARCHIVE_SIZE) {
          console.warn(`[Pipeline] Scene ${sceneIndex}: Archive clip too large (${(bytesWritten / 1024 / 1024).toFixed(1)}MB), skipping`);
          try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
          continue;
        }
        }

        providerMetrics(sourcingCache, "internet_archive").downloadCount++;
        if (await trimRemoteVideoToClip(tmpPath, outPath, duration, 10, `Internet Archive scene ${sceneIndex}`)) {
          results.push({ path: outPath, query, title: doc.title });
          fetched++;
          console.log(`[Pipeline] Scene ${sceneIndex}: Internet Archive clip added: ${doc.title}`);
        }
        try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
      } catch (err) {
        console.warn(`[Pipeline] Scene ${sceneIndex}: Archive item ${doc.identifier} failed:`, (err as Error).message);
      }
      }
    }
    } catch (err) {
      // RONDE 68: a cancellation FastVid caused is not a provider fault — see isScopeAbortError.
      if (!isScopeAbortError(err)) markInternetArchiveSearchResult(false);
      console.warn(`[Pipeline] Scene ${sceneIndex}: Internet Archive search failed for "${query}":`, (err as Error).message);
    }
  }
  return results;
}

/**
 * RONDE 8: fetch a short segment of a LARGE archive.org video without downloading the file.
 * ffmpeg's HTTP demuxer seeks via range requests, so `-ss 90 -t N -c copy` reads only the bytes
 * of that window — this is what unlocks archive.org's full-length historical films (routinely
 * 100-700MB) that the MAX_ARCHIVE_SIZE cap otherwise skips entirely. Starts 90s in to skip
 * title cards/leader footage. Returns false on ANY failure so the caller can fall back to the
 * old skip behavior; never throws.
 */
async function fetchArchiveSegmentViaFfmpeg(
  videoUrl: string,
  outPath: string,
  segmentSec: number,
  sceneIndex: number
): Promise<boolean> {
  try {
    const { spawn: spawnChild } = await import("child_process");
    await ffmpegSemaphore.run(() => new Promise<void>((resolve, reject) => {
      const args = [
        "-y",
        "-ss", "90",
        "-i", videoUrl,
        "-t", String(segmentSec),
        "-c", "copy",
        "-movflags", "+faststart",
        outPath,
      ];
      const child = spawnChild(FFMPEG_BIN, args, { stdio: ["ignore", "ignore", "pipe"] });
      let stderr = "";
      child.stderr.on("data", (d: Buffer) => { stderr += d.toString().slice(-400); });
      const timer = setTimeout(() => {
        try { child.kill("SIGKILL"); } catch { /* ignore */ }
        reject(pipelineError(PIPELINE_ERROR.TIMEOUT, `Archive segment fetch timeout scene ${sceneIndex}`));
      }, 30_000);
      child.on("close", (code: number | null) => {
        clearTimeout(timer);
        if (code === 0) resolve();
        else reject(pipelineError(PIPELINE_ERROR.FFMPEG, `ffmpeg exit ${code}: ${stderr.slice(-160)}`));
      });
      child.on("error", (err: Error) => { clearTimeout(timer); reject(err); });
    }));
    if (fs.existsSync(outPath) && fs.statSync(outPath).size > 50_000 && (await isValidVideoFile(outPath))) {
      return true;
    }
    try { fs.unlinkSync(outPath); } catch { /* ignore */ }
    return false;
  } catch (err) {
    console.warn(
      `[Pipeline] Scene ${sceneIndex}: archive segment fetch failed:`,
      (err as Error).message?.slice(0, 120)
    );
    try { fs.unlinkSync(outPath); } catch { /* ignore */ }
    return false;
  }
}

// ─── 3c3a. Download a YouTube CC clip (RapidAPI first, cloud service fallback) ─
/** RapidAPI's `/dl` payload — only the two format lists this pipeline reads. */
type RapidApiYoutubeMeta = {
  formats?: Array<{ url?: string; mimeType?: string; contentLength?: string; height?: number }>;
  adaptiveFormats?: Array<{ url?: string; mimeType?: string; contentLength?: string; height?: number }>;
  /**
   * RONDE 62: the source length, which this response has been carrying all along.
   *
   * The watch page added in RONDE 60 was meant to supply this, and on Railway it never came
   * through: render 532 logged src=unknown on all 52 plans, so every clip was still cut at a
   * flat second 12. THIS call demonstrably works there — 63 metadata lookups, 34 of them served
   * from cache — and states the duration in the same response the download URL comes from.
   * Different providers spell it differently; all three spellings are read.
   */
  lengthSeconds?: string | number;
  videoDetails?: { lengthSeconds?: string | number };
  duration?: string | number;
};

/** Seconds from a RapidAPI metadata response, 0 when it did not say. */
export function rapidApiYoutubeMetaDurationSec(meta: RapidApiYoutubeMeta | null | undefined): number {
  if (!meta) return 0;
  for (const raw of [meta.lengthSeconds, meta.videoDetails?.lengthSeconds, meta.duration]) {
    if (raw == null) continue;
    const n = typeof raw === "number" ? raw : Number.parseInt(String(raw).trim(), 10);
    if (Number.isFinite(n) && n > 0 && n < 86_400) return n;
  }
  return 0;
}

/**
 * RONDE 56: the YouTube metadata lookup, cached per render and run outside the beat's deadline.
 *
 * Render 531 measured the whole YouTube branch failing in exactly one place:
 *
 *     185 results -> 103 download attempts -> 2 adopted
 *      85 RapidAPI failures, ALL of them:
 *         - aborted by the enclosing scope, never a real timeout
 *         - at the META step, never reaching the download
 *         - granted "own 3s" — the floor of scopedTimeoutMs, i.e. the scene had nothing left
 *      86 attempts for 14 unique video ids
 *      metadataCacheHits=0
 *
 * Two things follow from that, and this function is both of them.
 *
 * CACHED. The same video was looked up roughly six times over, each attempt paying full price
 * and each one cut off. The render-scoped asset cache already exists and already has a
 * `metadata` field and a `metadataCacheHits` counter; nothing was writing to it. A negative
 * result is cached too, so a video that genuinely has no usable format is not re-asked all
 * render — the same reasoning putCachedProviderAsset already applies to licence rejections.
 *
 * OUTSIDE THE BEAT SCOPE. The scene pool's Internet Archive calls complete in 17-23 seconds
 * because they run as a prefetch; this call was running inside `script image` (12s) and
 * `beat fill` (20s) scopes that were already spent by the time it started. AsyncLocalStorage's
 * exit() detaches it, so it gets its own full budget and its own honest timeout.
 *
 * That detachment is safe HERE and would not be for the download. This is a JSON GET: it writes
 * nothing, so an answer arriving after the beat gave up costs a cache entry and nothing else.
 * The download writes to workDir, and a detached write into a directory the render has already
 * cleaned up is the ENOENT class of bug fetchWithTimeout's scope signal exists to prevent — so
 * the download stays inside the scope, unchanged.
 */
async function fetchRapidApiYoutubeMeta(
  videoId: string,
  sceneIndex: number,
  sourcingCache?: SourcingCache
): Promise<RapidApiYoutubeMeta | null> {
  const cached = getCachedProviderAsset(sourcingCache, "youtube_cc", videoId);
  if (cached?.metadata !== undefined) {
    providerMetrics(sourcingCache, "youtube_cc").metadataCacheHits++;
    return (cached.metadata as RapidApiYoutubeMeta | null) ?? null;
  }

  const metaUrl = `https://${RAPIDAPI_YT_HOST}/dl?id=${videoId}`;
  providerMetrics(sourcingCache, "youtube_cc").metadataCount++;
  // exit() runs the callback with no scene-fetch scope in context, so fetchWithTimeout sees no
  // scope signal and no scope deadline: its own 20s is the only limit, exactly as intended.
  const meta = await sceneFetchScopeStorage.exit(async () => {
    try {
      const resp = await providerLimiter("youtube").run(() =>
        fetchWithTimeout(metaUrl, 20_000, `RapidAPI YouTube meta scene ${sceneIndex}`, {
          headers: { "x-rapidapi-host": RAPIDAPI_YT_HOST, "x-rapidapi-key": RAPIDAPI_KEY },
        })
      );
      if (!resp.ok) {
        // Deliberately NOT a breaker failure. A non-ok answer for ONE video says that video has
        // no metadata — it may be private, removed or region-locked — not that RapidAPI is down.
        // Counting it would trip the cooldown on a healthy provider, which is what the original
        // inline code avoided by leaving this branch unmarked. Transport errors (the catch
        // below) are the real provider signal.
        return null;
      }
      markYoutubeSearchResult(true);
      return (await resp.json()) as RapidApiYoutubeMeta;
    } catch (err) {
      if (!isScopeAbortError(err)) markYoutubeSearchResult(false);
      console.warn(
        `[Pipeline] Scene ${sceneIndex}: RapidAPI meta failed for ${videoId}:`,
        (err as Error).message?.slice(0, 120)
      );
      return null;
    }
  });

  putCachedProviderAsset(sourcingCache, "youtube_cc", videoId, { metadata: meta });
  return meta;
}

/**
 * RONDE 60 — look at the YouTube clip before returning it.
 *
 * The beat-image gate built in RONDE 58 hangs off pickBestFunnelCandidate, and YouTube is not a
 * FunnelCandidateSource: youtube_cc clips reach a beat through fetchYouTubeCCClips -> adoptClip,
 * a route the gate never sees. So the source with by far the longest videos — the one whose
 * start offset is the least certain — was the only one never checked against what is actually
 * on screen.
 *
 * Fails open exactly like the funnel's copy: no gate state, no narration, no extractable frame,
 * a model outage or a spent budget all return true and adopt the clip.
 */
/**
 * RONDE 62 — the picture gate for the adoption path.
 *
 * Same contract as the funnel's and YouTube's copies: three frames from across the clip, one
 * judgement, and only a definite "does not fit" costs the clip its place. Everything else — the
 * gate switched off, no narration, no extractable frame, a model outage, the budget spent —
 * returns true and adopts exactly as before.
 */

/**
 * RONDE 103: this is now a thin adapter onto the pipeline's single content decider.
 *
 * It used to hold its own copy of the frame sampling, the judgement call, the cleanup and the
 * logging — one of three such copies, which is how they drifted apart and how two of the three
 * came to key their cache on the picture alone. The behaviour is unchanged from the caller's
 * side; the decision is simply made in one place now. See ./beatVisualRelevance.
 */
async function beatClipPassesImageGate(
  clipPath: string,
  contentKey: string,
  beatText: string,
  opts: VisualAdoptOptions,
  workDir: string,
  sceneIndex: number,
  beatIndex: number,
  dedup: VisualDedupState
): Promise<boolean> {
  const decision = await judgeBeatClipRelevance(dedup, sceneIndex, beatIndex, {
    clipPath,
    contentKey,
    ctx: {
      sceneIndex,
      beatIndex,
      beatText,
      sceneText: opts.sceneText,
      videoTitle: asVideoTitleString(opts.videoTitle) || undefined,
    },
    workDir,
    state: dedup.beatImageGate,
    ledger: dedup.beatRelevance,
    route: "adopt",
  });
  return decision.allowed;
}

async function youtubeClipPassesImageGate(
  clipPath: string,
  workDir: string,
  sceneIndex: number,
  videoId: string,
  scriptGuided?: ScriptGuidedBeatContext
): Promise<boolean> {
  const gate = scriptGuided?.imageGate;
  if (!gate || !beatImageRelevanceGateEnabled() || !scriptGuided?.beatText?.trim()) return true;
  // RONDE 61: YouTube gets a slice of the render's judgements, not all of them. It is judged
  // before a clip is even accepted into the pool, so it spends calls on material that may never
  // be used; the funnel spends them on the clip about to go into the video. Past the slice this
  // adopts as before, exactly like every other way this gate declines to answer.
  if (gate.youtubeJudgementsUsed >= maxYoutubeBeatImageJudgements()) return true;

  const framePaths: string[] = [];
  for (let f = 0; f < JUDGEMENT_FRAME_FRACTIONS.length; f++) {
    const framePath = path.join(workDir, `ytgate_s${sceneIndex}_${videoId.slice(0, 12)}_${f}.jpg`);
    const got = await extractFrameAtFraction(
      clipPath, framePath, JUDGEMENT_FRAME_FRACTIONS[f]!, 8_000
    ).catch(() => false);
    if (got) framePaths.push(framePath);
  }
  const spentBefore = gate.judgementAttempts;
  const judgement = await judgeBeatImage({
    framePaths,
    beatText: scriptGuided.beatText,
    videoTitle: scriptGuided.videoTitle,
    contentKey: clipContentKey(clipPath),
    // RONDE 103: this check runs before a clip is in any beat's pool, so it has narration but no
    // beat slot. Deriving the identity from the narration it DOES have keeps it in its own cache
    // bucket rather than sharing one with every beat that later judges the same video.
    beatIdentity: beatIdentityKey({
      sceneIndex,
      beatIndex: -1,
      beatText: scriptGuided.beatText,
      videoTitle: scriptGuided.videoTitle,
    }),
    state: gate,
  });
  // Only a call that actually cost something counts against YouTube's slice — a cached verdict
  // for a video already judged on an earlier beat is free.
  if (gate.judgementAttempts > spentBefore) gate.youtubeJudgementsUsed++;
  for (const p of framePaths) {
    try { fs.unlinkSync(p); } catch { /* ignore */ }
  }

  console.log(
    `[BeatImageGate] youtube s${sceneIndex} ${videoId.slice(0, 12)} ${judgement.verdict} ` +
      `depicts="${judgement.depicts}" reason="${judgement.reason}" cached=${judgement.cached === true}`
  );
  /**
   * RONDE 104: write the verdict down where the compose barrier can find it.
   *
   * Until now this was the one gate whose answers went only to the log. A YouTube clip refused
   * here was dropped from the pool — but the same asset arriving later by another route (the
   * funnel's own YouTube path, a rescue) reached compose as a path nothing had ever judged, and
   * the barrier had to let it through. Recording it under the clip's CONTENT identity closes
   * that: the refusal now follows the asset, not the file.
   */
  if (scriptGuided.relevanceLedger) {
    recordExternalRelevanceVerdict(
      scriptGuided.relevanceLedger,
      clipPath,
      clipContentKey(clipPath),
      {
        sceneIndex,
        beatIndex: -1,
        beatText: scriptGuided.beatText,
        videoTitle: scriptGuided.videoTitle,
      },
      judgement,
      "youtube_prepool"
    );
  }
  return judgement.verdict !== "does_not_fit";
}

/**
 * FINAL VALIDATION §4 — every way a YouTube fetch can end, named.
 *
 * ── Why a vocabulary and not a boolean ──────────────────────────────────────────────────────
 *
 * `downloadYouTubeCCClip` returns a bare boolean, and until the MASTER YOUTUBE BUILD round it
 * returned `false` in silence. That round added one line distinguishing "no route configured" from
 * "a route failed", which was the difference the first production log needed. It is still not
 * enough to act on: a service that 502s, a service that returns an HTML error page, a transfer the
 * scene budget killed, a video no route offers an mp4 for, and a file that arrives but will not
 * trim are five different problems with five different fixes, and all five printed
 * `status=DOWNLOAD_FAILED`.
 *
 * Worse, two paths still returned `false` with NO line at all — the scene-budget guard and the
 * cloud route's own size floor. A refusal nobody can grep for is the defect this whole programme
 * keeps rediscovering.
 */
export type YoutubeDownloadStatus =
  | "DOWNLOAD_SUCCESS"
  /** No download route is configured at all — a gap in configuration, not a failure. */
  | "DOWNLOAD_UNAVAILABLE"
  /** The transfer ran out of time: its own timeout, or the scene budget that contains it. */
  | "DOWNLOAD_TIMEOUT"
  /** The route answered, and delivered no bytes or too few to be a video. */
  | "DOWNLOAD_EMPTY"
  /** Bytes arrived and are not usable media — the trim/probe refused them. */
  | "DOWNLOAD_INVALID_CONTENT"
  /** The route cannot serve THIS video: no mp4 format, no metadata, or past the size ceiling. */
  | "DOWNLOAD_UNSUPPORTED"
  /** Everything else: an HTTP error status, an unclassified throw. */
  | "DOWNLOAD_FAILED";

/** One route's attempt at one video, kept so the final line can report all of them. */
export type YoutubeDownloadAttempt = {
  route: "cloud" | "rapidapi";
  status: YoutubeDownloadStatus;
  detail: string;
};

/**
 * A thrown error, classified.
 *
 * A scope abort and a fetch timeout are both "we ran out of time" and are reported as such — the
 * operator's action is the same (give the stage more room, or fetch a smaller source), and calling
 * them DOWNLOAD_FAILED sends them looking for a broken service instead.
 */
export function classifyYoutubeDownloadError(err: unknown): YoutubeDownloadStatus {
  if (isScopeAbortError(err)) return "DOWNLOAD_TIMEOUT";
  const msg = (err as Error)?.message ?? "";
  if (matchesAppError(msg, PIPELINE_ERROR.TIMEOUT) || /timeout|aborted|abort/i.test(msg)) {
    return "DOWNLOAD_TIMEOUT";
  }
  return "DOWNLOAD_FAILED";
}

/**
 * Which of several failed attempts the headline should name.
 *
 * Ordered by how much the attempt actually learned about the video. A route that delivered bytes
 * that would not trim tells an operator more than one that refused to answer, so INVALID_CONTENT
 * outranks a bare FAILED. Every attempt is still listed in the line; this only picks the word to
 * grep for.
 */
const YOUTUBE_DOWNLOAD_STATUS_PRIORITY: readonly YoutubeDownloadStatus[] = [
  "DOWNLOAD_INVALID_CONTENT",
  "DOWNLOAD_UNSUPPORTED",
  "DOWNLOAD_TIMEOUT",
  "DOWNLOAD_EMPTY",
  "DOWNLOAD_FAILED",
];

export function summariseYoutubeDownloadAttempts(
  attempts: readonly YoutubeDownloadAttempt[],
  routesConfigured: boolean
): YoutubeDownloadStatus {
  if (attempts.some((a) => a.status === "DOWNLOAD_SUCCESS")) return "DOWNLOAD_SUCCESS";
  if (!routesConfigured && attempts.length === 0) return "DOWNLOAD_UNAVAILABLE";
  for (const status of YOUTUBE_DOWNLOAD_STATUS_PRIORITY) {
    if (attempts.some((a) => a.status === status)) return status;
  }
  /** A route was configured and produced no attempt record — still a failure, never a silence. */
  return routesConfigured ? "DOWNLOAD_FAILED" : "DOWNLOAD_UNAVAILABLE";
}

/**
 * The one line. Emitted on EVERY exit from `downloadYouTubeCCClip`, success included.
 *
 * Presence only for configuration: the service URL and the API key are never printed, only whether
 * they are set — the same rule the preflight follows.
 */
export function formatYoutubeDownloadLine(params: {
  videoId: string;
  sceneIndex: number;
  status: YoutubeDownloadStatus;
  attempts: readonly YoutubeDownloadAttempt[];
  hasCloudRoute: boolean;
  hasRapidRoute: boolean;
  reason: string;
}): string {
  const trail =
    params.attempts.map((a) => `${a.route}:${a.status}`).join(",") || "none";
  return (
    `[YouTubeDownload] video=${params.videoId} scene=${params.sceneIndex} ` +
    `status=${params.status} attempts=${trail} ` +
    `cloudService=${params.hasCloudRoute ? "SET" : "MISSING"} ` +
    `rapidApi=${params.hasRapidRoute ? "SET" : "MISSING"} reason=${params.reason}`
  );
}

export async function downloadYouTubeCCClip(
  videoId: string,
  duration: number,
  clipStart: number,
  outPath: string,
  sceneIndex: number,
  title?: string,
  /** RONDE 56: render-scoped cache, so 86 attempts for 14 videos become 14 lookups. */
  sourcingCache?: SourcingCache,
  /**
   * RONDE 64: true when clipStart was LOCATED (a transcript hit), false when it was guessed.
   * A guess is re-derived once the real source length is known; a located start is honoured.
   */
  startIsExact = false
): Promise<boolean> {
  const cloudDlService = process.env.YOUTUBE_CC_DL_SERVICE?.replace(/\/$/, "") || "";
  const hasCloudRoute = Boolean(cloudDlService);
  const hasRapidRoute = Boolean(RAPIDAPI_KEY);
  /**
   * §4 — every outcome of every route, so the exit line can name the specific one rather than
   * collapsing five different problems into DOWNLOAD_FAILED.
   */
  const attempts: YoutubeDownloadAttempt[] = [];
  const note = (route: YoutubeDownloadAttempt["route"], status: YoutubeDownloadStatus, detail: string) => {
    attempts.push({ route, status, detail });
  };
  /** The single exit point for the line. Called on success and on every failure alike. */
  const reportDownload = (status: YoutubeDownloadStatus, reason: string): void => {
    const line = formatYoutubeDownloadLine({
      videoId, sceneIndex, status, attempts, hasCloudRoute, hasRapidRoute, reason,
    });
    if (status === "DOWNLOAD_SUCCESS") console.log(line);
    else console.warn(line);
  };

  // F3-41: cloud/yt-dlp service tried FIRST — this is the intended primary route (see the F3-40
  // diagnosis: it runs yt-dlp with an ANDROID_VR client workaround on its own infrastructure,
  // which is what actually works around YouTube's server-side bot detection; yt-dlp is
  // deliberately not a local dependency of this repo). RapidAPI stays below as the fallback.
  // Any failure here falls through to the RapidAPI branch instead of aborting the function —
  // unlike the old second-branch version, a failure can no longer be the final word.
  if (cloudDlService) {
    // F3-05: streams to a tmpPath (never directly to outPath) so a network drop mid-download
    // can never leave a corrupt/partial file at outPath — outPath is only ever touched by the
    // atomic fs.renameSync below, and only once the download is complete and size-validated.
    const cloudTmpPath = outPath.replace(/\.mp4$/, "_cloud_tmp.mp4");
    try {
      const dlUrl = `${cloudDlService}/download?id=${videoId}&duration=${duration}&start=${clipStart}`;
      // RONDE 10b: the ytdlp-service requires `Authorization: Bearer <SERVICE_TOKEN>` and returns
      // 401 without it. The token is provided via YOUTUBE_CC_DL_TOKEN so the two services share a
      // secret; when unset the header is simply omitted (backward compatible with a token-less
      // service). This was the missing piece that made the cloud route unusable once deployed.
      const cloudDlToken = process.env.YOUTUBE_CC_DL_TOKEN?.trim();
      const cloudHeaders = cloudDlToken ? { Authorization: `Bearer ${cloudDlToken}` } : {};
      // P0 fix 1: maxBytes matches the existing 80MB post-hoc ceiling below exactly.
      const { response: dlResp, bytesWritten } = await downloadToFileStreaming(
        dlUrl,
        cloudTmpPath,
        youtubeDownloadTimeoutMs(),
        `YouTube CC cloud download scene ${sceneIndex}`,
        { headers: cloudHeaders },
        80 * 1024 * 1024
      );
      if (!dlResp.ok) {
        const errText = await dlResp.text().catch(() => "");
        note("cloud", "DOWNLOAD_FAILED", `http_${dlResp.status}`);
        console.warn(
          `[Pipeline] Scene ${sceneIndex}: Cloud DL service error ${dlResp.status} for ${videoId}: ${errText.slice(0, 100)} — falling back to RapidAPI`
        );
      } else if (bytesWritten === null) {
        note("cloud", "DOWNLOAD_EMPTY", "no_response_body");
        console.warn(
          `[Pipeline] Scene ${sceneIndex}: Cloud DL service returned no body for ${videoId} — falling back to RapidAPI`
        );
      } else {
        let cloudFileSize = -1;
        try { cloudFileSize = fs.statSync(cloudTmpPath).size; } catch { /* leave as -1 */ }
        if (cloudFileSize > 80 * 1024 * 1024) {
          note("cloud", "DOWNLOAD_UNSUPPORTED", `over_size_ceiling_${Math.round(cloudFileSize / 1024 / 1024)}mb`);
          console.warn(
            `[Pipeline] Scene ${sceneIndex}: YouTube CC clip too large (${(cloudFileSize / 1024 / 1024).toFixed(1)}MB), skipping cloud service — falling back to RapidAPI`
          );
        } else if (cloudFileSize > 10_000) {
          fs.renameSync(cloudTmpPath, outPath);
          note("cloud", "DOWNLOAD_SUCCESS", `${cloudFileSize}_bytes`);
          console.log(
            `[Pipeline] Scene ${sceneIndex}: ✅ YouTube CC via cloud service: "${title?.slice(0, 60) ?? videoId}" (${videoId})`
          );
          reportDownload("DOWNLOAD_SUCCESS", "cloud_service");
          return true;
        } else {
          /**
           * §4 — the size floor used to drop the file and say nothing at all, so a service that
           * answers 200 with a stub was indistinguishable from one that was never called.
           */
          note("cloud", "DOWNLOAD_EMPTY", `below_size_floor_${cloudFileSize}_bytes`);
          console.warn(
            `[Pipeline] Scene ${sceneIndex}: Cloud DL returned ${cloudFileSize} bytes for ${videoId} ` +
              `(floor is 10000) — falling back to RapidAPI`
          );
        }
      }
    } catch (err) {
      note("cloud", classifyYoutubeDownloadError(err), (err as Error).message?.slice(0, 60) ?? "threw");
      console.warn(
        `[Pipeline] Scene ${sceneIndex}: Cloud DL failed for ${videoId}:`,
        (err as Error).message, "— falling back to RapidAPI"
      );
    } finally {
      try {
        if (fs.existsSync(cloudTmpPath)) fs.unlinkSync(cloudTmpPath);
      } catch {
        /* ignore */
      }
    }
  }

  // F3-41: RapidAPI fallback — tried when the cloud/yt-dlp service is not configured, errored,
  // or didn't return a usable file. Unchanged from before this fix other than moving second.
  if (RAPIDAPI_KEY) {
    const tmpPath = outPath.replace(/\.mp4$/, "_rapid_tmp.mp4");
    try {
      // RONDE 56: cached per render and fetched outside the beat's deadline — see
      // fetchRapidApiYoutubeMeta. Render 531 lost all 85 of its RapidAPI attempts here, every
      // one of them aborted by an already-spent scene budget before the download ever started.
      const data = await fetchRapidApiYoutubeMeta(videoId, sceneIndex, sourcingCache);
      if (data) {
        // RONDE 27: pick the SMALLEST adequate format, not the one closest to 720p.
        //
        // This route downloads the entire source video and only then trims out the few seconds
        // the beat needs, so the file size is the download time. Render 528 found relevant WWII
        // footage on three separate queries and lost all three to "RapidAPI YouTube download
        // scene N exceeded 90s" — nothing from YouTube reached the cut, and the montage fell back
        // on Ken Burns stills and generic stock. Sorting by "closest to 720" happily chose a
        // half-gigabyte 720p file over a 40MB 480p one of the same video.
        //
        // The clip ends up scaled into a 1920x1080 frame as B-roll behind narration, where the
        // difference between 480p and 720p source is far less visible than the difference between
        // having the shot and not having it. Anything at or above the floor is good enough; below
        // it we still prefer the tallest available rather than dropping to something unusable.
        const pickFormat = (
          formats: Array<{ url?: string; mimeType?: string; contentLength?: string; height?: number }> | undefined
        ) => {
          const mp4 = (formats ?? []).filter((f) => f.url && f.mimeType?.includes("mp4"));
          if (!mp4.length) return undefined;
          const sizeOf = (f: { contentLength?: string }): number => {
            const n = parseInt(f.contentLength || "", 10);
            return Number.isFinite(n) && n > 0 ? n : Number.MAX_SAFE_INTEGER;
          };
          const adequate = mp4.filter((f) => (f.height ?? 720) >= youtubeMinFormatHeight());
          if (adequate.length) return adequate.sort((a, b) => sizeOf(a) - sizeOf(b))[0];
          return mp4.sort((a, b) => (b.height ?? 0) - (a.height ?? 0))[0];
        };

        const format = pickFormat(data.formats) ?? pickFormat(data.adaptiveFormats);
        if (!format?.url) {
          note("rapidapi", "DOWNLOAD_UNSUPPORTED", "no_mp4_format_offered");
        }
        if (format?.url) {
          // F3-05: streams straight to tmpPath instead of buffering the whole clip in memory.
          // P0 fix 1: maxBytes matches the existing 80MB post-hoc ceiling below exactly.
          // RONDE 68: do not start a transfer the budget cannot finish.
          //
          // Render 533 cancelled 150 of these mid-flight — "cancelled by the enclosing scene
          // budget before its own 5s timeout" — and every one of them had already spent the
          // scene's remaining time before dying. That is the time Wikimedia needed for a search
          // it never got to run (0 searches that render), and Internet Archive for the 12
          // results it downloaded none of. A whole video is the most expensive thing this
          // pipeline fetches; it should be the first thing to stand aside, not the last.
          const remainingMs = remainingScopeMs();
          if (remainingMs < YOUTUBE_MIN_DOWNLOAD_WINDOW_MS) {
            console.log(
              `[Pipeline] Scene ${sceneIndex}: skipping YouTube download of ${videoId} — ` +
                `${Math.round(remainingMs / 1000)}s left in the scene budget, not enough to finish`
            );
            /**
             * §4 — this was a bare `return false`. Standing aside for the scene budget is a
             * legitimate decision and the most misread one in the log: it looks exactly like a
             * broken service unless it says so.
             */
            note("rapidapi", "DOWNLOAD_TIMEOUT", `scene_budget_${Math.round(remainingMs / 1000)}s_left`);
            reportDownload("DOWNLOAD_TIMEOUT", "scene_budget_too_short_to_start");
            return false;
          }
          const { response: dlResp, bytesWritten } = await downloadToFileStreaming(
            format.url,
            tmpPath,
            // RONDE 52: 180s was eight times the scope containing it, so this step could never
            // finish. It now takes what is left, and reports honestly when that is not enough.
            scopedTimeoutMs(youtubeDownloadTimeoutMs(), 5_000),
            `RapidAPI YouTube download scene ${sceneIndex}`,
            {
              headers: {
                "User-Agent":
                  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
                Referer: "https://www.youtube.com/",
              },
            },
            80 * 1024 * 1024
          );
          if (!dlResp.ok) {
            note("rapidapi", "DOWNLOAD_FAILED", `http_${dlResp.status}`);
          } else if (bytesWritten === null) {
            note("rapidapi", "DOWNLOAD_EMPTY", "no_response_body");
          }
          if (dlResp.ok && bytesWritten !== null) {
            let rapidFileSize = -1;
            try { rapidFileSize = fs.statSync(tmpPath).size; } catch { /* leave as -1 */ }
            if (rapidFileSize > 80 * 1024 * 1024) {
              note("rapidapi", "DOWNLOAD_UNSUPPORTED", `over_size_ceiling_${Math.round(rapidFileSize / 1024 / 1024)}mb`);
            } else if (rapidFileSize < 50_000) {
              note("rapidapi", "DOWNLOAD_EMPTY", `below_size_floor_${rapidFileSize}_bytes`);
            }
            if (rapidFileSize >= 50_000 && rapidFileSize <= 80 * 1024 * 1024) {
              // RONDE 64: the whole source is on disk here, so stop guessing its length.
              //
              // This route downloads the entire video and only then trims. Every attempt so far
              // to learn the duration before the download — the watch page, the metadata field —
              // was indirect, and the watch page demonstrably does not work on Railway. The file
              // itself always does.
              const resolvedStart = await resolveTrimStartSec(
                tmpPath, clipStart, duration, videoId, startIsExact
              );
              if (Math.abs(resolvedStart - clipStart) > 0.05) {
                console.log(
                  `[Pipeline] Scene ${sceneIndex}: ${videoId} trim start ${clipStart.toFixed(1)}s ` +
                    `→ ${resolvedStart.toFixed(1)}s (source probed)`
                );
              }
              if (
                await trimRemoteVideoToClip(
                  tmpPath,
                  outPath,
                  duration,
                  resolvedStart,
                  `YouTube CC RapidAPI scene ${sceneIndex}`
                )
              ) {
                note("rapidapi", "DOWNLOAD_SUCCESS", `${rapidFileSize}_bytes`);
                console.log(
                  `[Pipeline] Scene ${sceneIndex}: ✅ YouTube CC via RapidAPI: "${title?.slice(0, 60) ?? videoId}" (${videoId})`
                );
                reportDownload("DOWNLOAD_SUCCESS", "rapidapi");
                return true;
              }
              /**
               * §4 — bytes arrived and ffmpeg would not cut a clip out of them. That is a
               * different problem from a download that never happened, and the only one of these
               * statuses that points at the FILE rather than at the route.
               */
              note("rapidapi", "DOWNLOAD_INVALID_CONTENT", "trim_produced_no_clip");
            }
          }
        }
      } else {
        // RONDE 56: the helper already logged and classified the failure (and cached the null so
        // this video is not asked again this render).
        note("rapidapi", "DOWNLOAD_UNSUPPORTED", "no_usable_metadata");
        console.warn(
          `[Pipeline] Scene ${sceneIndex}: RapidAPI returned no usable metadata for ${videoId}`
        );
      }
    } catch (err) {
      // RONDE 52: same as the search path — a thrown timeout never reached the breaker, so 22
      // consecutive RapidAPI failures in render 530 did nothing to stop the 23rd. Scope aborts
      // stay uncounted: those said nothing about RapidAPI's health, and the misleading message
      // they carried is exactly what made this look like a provider outage in the first place.
      if (!isScopeAbortError(err)) markYoutubeSearchResult(false);
      note("rapidapi", classifyYoutubeDownloadError(err), (err as Error).message?.slice(0, 60) ?? "threw");
      console.warn(
        `[Pipeline] Scene ${sceneIndex}: RapidAPI download failed for ${videoId}:`,
        (err as Error).message
      );
    } finally {
      try {
        if (fs.existsSync(tmpPath)) fs.unlinkSync(tmpPath);
      } catch {
        /* ignore */
      }
    }
  }

  /**
   * MASTER YOUTUBE BUILD — a YouTube clip that cannot be fetched says WHY, and says it once.
   *
   * ── The production silence this replaces ────────────────────────────────────────────────────
   *
   * The first real Railway render found twelve YouTube videos, passed all twelve through the
   * licence check with ALLOW_UNVERIFIED_YOUTUBE, and finished with `[YouTubeUsage] used=0`. There
   * was no download line anywhere in six and a half minutes of log, because this function returned
   * a bare `false` — no reason, no distinction, nothing to grep for.
   *
   * That made two completely different situations look identical:
   *
   *   · NO ROUTE CONFIGURED — neither YOUTUBE_CC_DL_SERVICE nor RAPIDAPI_KEY is set, so no
   *     download was ever possible. A configuration gap: search works, ingest does not exist.
   *     This is the state the preflight calls `youtube_download: OPTIONAL/MISSING`, and it is
   *     almost certainly what produced used=0.
   *   · ROUTE CONFIGURED AND FAILED — a service was there and it did not deliver. A real failure
   *     worth investigating.
   *
   * An operator cannot act on the first and must act on the second, so the log now names which one
   * it was. Presence only: the service URL and the key are never printed, only whether they exist.
   */
  const status = summariseYoutubeDownloadAttempts(attempts, hasCloudRoute || hasRapidRoute);
  reportDownload(
    status,
    status === "DOWNLOAD_UNAVAILABLE"
      ? "no_download_route_configured — set YOUTUBE_CC_DL_SERVICE or RAPIDAPI_KEY"
      : attempts.map((a) => `${a.route}=${a.detail}`).join(" ") || "every_configured_route_failed"
  );
  return false;
}

/** Live probe: YouTube CC search + RapidAPI metadata (for /api/health/youtube-probe). */
/**
 * IS YOUTUBE ACTUALLY GOING TO WORK — answered without spending a render.
 *
 * ── Two things this used to get wrong ───────────────────────────────────────────────────────
 *
 * `youtubeCcReady()` asks only about KEYS. It says nothing about ENABLE_YOUTUBE_SOURCING, and that
 * flag is the very first guard `fetchYouTubeCCClips` checks — so this probe could answer "YouTube
 * CC pipeline OK" for a deployment whose renders skip YouTube before reading a single key. That is
 * precisely the state render 562 was in, and a green probe would have made it harder to find, not
 * easier.
 *
 * And it only ever tested the RapidAPI route. `YOUTUBE_CC_DL_SERVICE` — the cloud yt-dlp service,
 * which `downloadYouTubeCCClip` tries FIRST — was never probed, so an operator running only that
 * route got a red light from a working configuration.
 *
 * Both are now part of the answer: the flag is reported, and the download side passes when EITHER
 * route works, naming which one did.
 */
export async function probeYouTubeCcPipeline(): Promise<{
  ready: boolean;
  /** ENABLE_YOUTUBE_SOURCING. Keys without this mean renders never reach the keys. */
  sourcingEnabled: boolean;
  searchStatus: number | null;
  ccResultCount: number;
  rapidApiStatus: number | null;
  rapidApiHasFormat: boolean;
  /** Which download route answered, if any — the pipeline tries cloud first, then RapidAPI. */
  downloadRoute: "cloud" | "rapidapi" | null;
  cloudStatus: number | null;
  sampleVideoId: string | null;
  message: string;
}> {
  const sourcingEnabled = youtubeSourcingEnabled();
  const ready = youtubeCcReady();
  if (!ready) {
    return {
      ready: false,
      sourcingEnabled,
      searchStatus: null,
      ccResultCount: 0,
      rapidApiStatus: null,
      rapidApiHasFormat: false,
      downloadRoute: null,
      cloudStatus: null,
      sampleVideoId: null,
      message: "Set YOUTUBE_API_KEY and RAPIDAPI_KEY (or YOUTUBE_CC_DL_SERVICE)",
    };
  }
  const probeQuery = "SpaceX Falcon 9 rocket launch";
  let searchStatus: number | null = null;
  let ccResultCount = 0;
  let sampleVideoId: string | null = null;
  try {
    const searchUrl = new URL("https://www.googleapis.com/youtube/v3/search");
    searchUrl.searchParams.set("key", process.env.YOUTUBE_API_KEY!.trim());
    searchUrl.searchParams.set("q", probeQuery);
    searchUrl.searchParams.set("type", "video");
    searchUrl.searchParams.set("videoLicense", "creativeCommon");
    searchUrl.searchParams.set("maxResults", "5");
    searchUrl.searchParams.set("part", "snippet");
    // Diagnostic health probe — a stuck request here with no timeout means the /api/health/
    // youtube-probe endpoint itself hangs forever instead of reporting a failure.
    const searchResp = await fetchWithTimeout(searchUrl.toString(), 10_000, "YouTube CC probe search");
    searchStatus = searchResp.status;
    if (searchResp.ok) {
      const data = (await searchResp.json()) as {
        items?: Array<{ id?: { videoId?: string } }>;
      };
      ccResultCount = data.items?.length ?? 0;
      sampleVideoId = data.items?.[0]?.id?.videoId ?? null;
    }
  } catch (err) {
    return {
      ready: true,
      sourcingEnabled,
      searchStatus,
      ccResultCount: 0,
      rapidApiStatus: null,
      rapidApiHasFormat: false,
      downloadRoute: null,
      cloudStatus: null,
      sampleVideoId: null,
      message: `YouTube search failed: ${(err as Error).message}`,
    };
  }

  /**
   * The cloud yt-dlp service, tried first — the same order `downloadYouTubeCCClip` uses.
   *
   * Its `/health` is enough: it reports whether yt-dlp and ffmpeg are present and whether auth is
   * configured, without spending a real download on a probe. A service that answers it is a
   * service the pipeline can reach and that is holding up its end.
   */
  const cloudService = process.env.YOUTUBE_CC_DL_SERVICE?.replace(/\/$/, "") || "";
  let cloudStatus: number | null = null;
  if (cloudService) {
    try {
      const token = process.env.YOUTUBE_CC_DL_TOKEN?.trim();
      const resp = await fetchWithTimeout(
        `${cloudService}/health`,
        10_000,
        "YouTube CC probe cloud service",
        token ? { headers: { Authorization: `Bearer ${token}` } } : {}
      );
      cloudStatus = resp.status;
    } catch {
      cloudStatus = null;
    }
  }

  let rapidApiStatus: number | null = null;
  let rapidApiHasFormat = false;
  if (sampleVideoId && RAPIDAPI_KEY) {
    const host = process.env.RAPIDAPI_YT_HOST || "ytstream-download-youtube-videos.p.rapidapi.com";
    try {
      const metaResp = await fetchWithTimeout(`https://${host}/dl?id=${sampleVideoId}`, 10_000, "YouTube CC probe RapidAPI", {
        headers: {
          "x-rapidapi-host": host,
          "x-rapidapi-key": RAPIDAPI_KEY,
        },
      });
      rapidApiStatus = metaResp.status;
      if (metaResp.ok) {
        const data = (await metaResp.json()) as {
          formats?: Array<{ url?: string; mimeType?: string }>;
          adaptiveFormats?: Array<{ url?: string; mimeType?: string }>;
        };
        const mp4 = [...(data.formats ?? []), ...(data.adaptiveFormats ?? [])].some(
          (f) => f.url && f.mimeType?.includes("mp4")
        );
        rapidApiHasFormat = mp4;
      }
    } catch {
      rapidApiStatus = null;
    }
  }

  const searchOk = searchStatus === 200 && ccResultCount > 0;
  const rapidOk = rapidApiStatus === 200 && rapidApiHasFormat;
  const cloudOk = cloudStatus === 200;
  /** EITHER route is enough — the pipeline falls through cloud to RapidAPI on every download. */
  const downloadRoute: "cloud" | "rapidapi" | null = cloudOk ? "cloud" : rapidOk ? "rapidapi" : null;

  let message = "YouTube CC pipeline OK";
  if (!sourcingEnabled) {
    /**
     * FIRST, because it outranks everything below it. The keys can be perfect and the render will
     * still skip YouTube before reading them — which is exactly what render 562 did.
     */
    message =
      "ENABLE_YOUTUBE_SOURCING is not true — the keys below may be fine, but renders skip " +
      "YouTube before reading them";
  } else if (!searchOk) {
    message =
      searchStatus === 403
        ? "YouTube API key invalid or quota exceeded"
        : `YouTube CC search returned ${ccResultCount} results (HTTP ${searchStatus})`;
  } else if (!downloadRoute) {
    message = cloudService
      ? `No download route answered — cloud service HTTP ${cloudStatus ?? "unreachable"}, ` +
        `RapidAPI HTTP ${rapidApiStatus ?? "error"}`
      : rapidApiStatus === 403 || rapidApiStatus === 401
        ? "RapidAPI key invalid or not subscribed to ytstream-download-youtube-videos"
        : `RapidAPI metadata HTTP ${rapidApiStatus ?? "error"} — no MP4 format`;
  }

  return {
    ready: true,
    sourcingEnabled,
    searchStatus,
    ccResultCount,
    rapidApiStatus,
    rapidApiHasFormat,
    downloadRoute,
    cloudStatus,
    sampleVideoId,
    message,
  };
}

/** Live probe: one Stability Core/Ultra image (for /api/health/stability-probe). */
export async function probeStabilityAI(): Promise<{
  ready: boolean;
  tier: "core" | "ultra";
  httpStatus: number | null;
  imageBytes: number;
  elapsedMs: number;
  message: string;
}> {
  if (!stabilityAiApiKey()?.trim()) {
    return {
      ready: false,
      tier: "core",
      httpStatus: null,
      imageBytes: 0,
      elapsedMs: 0,
      message: "STABILITY_AI_API_KEY not set",
    };
  }
  const useUltra = process.env.STABILITY_AI_TIER === "ultra";
  const tier = useUltra ? "ultra" : "core";
  const endpoint = useUltra
    ? "https://api.stability.ai/v2beta/stable-image/generate/ultra"
    : "https://api.stability.ai/v2beta/stable-image/generate/core";
  const t = Date.now();
  try {
    const form = new FormData();
    form.append("prompt", "Fastvid API probe, photorealistic documentary still, neutral subject, 16:9");
    form.append("aspect_ratio", "16:9");
    form.append("output_format", "png");
    form.append("negative_prompt", "text, watermark, logo");
    form.append("style_preset", "photographic");
    const resp = await withTimeout(
      fetch(endpoint, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${stabilityAiApiKey()}`,
          Accept: "image/*",
        },
        body: form,
      }),
      45_000,
      "Stability AI probe"
    );
    const elapsedMs = Date.now() - t;
    if (!resp.ok) {
      const errText = (await resp.text()).slice(0, 240);
      let message = `Stability HTTP ${resp.status}: ${errText}`;
      if (resp.status === 402) message = "Stability credits exhausted — add balance in Billing";
      if (resp.status === 401) message = "Stability API key invalid";
      return { ready: true, tier, httpStatus: resp.status, imageBytes: 0, elapsedMs, message };
    }
    const raw = Buffer.from(await resp.arrayBuffer());
    const ok = raw.length > 50_000;
    return {
      ready: true,
      tier,
      httpStatus: resp.status,
      imageBytes: raw.length,
      elapsedMs,
      message: ok
        ? `Stability ${tier} OK (${(raw.length / 1024).toFixed(0)} KB in ${(elapsedMs / 1000).toFixed(1)}s)`
        : `Stability returned undersized image (${raw.length} bytes)`,
    };
  } catch (err) {
    return {
      ready: true,
      tier,
      httpStatus: null,
      imageBytes: 0,
      elapsedMs: Date.now() - t,
      message: `Stability probe failed: ${(err as Error).message}`,
    };
  }
}

// ─── 3c3. Fetch YouTube Video Clips (CC + fair-use) ───────────────────────────
// CC first; then standard YouTube when fair-use is enabled (transform required on adopt).
type ScriptGuidedBeatContext = {
  beatText: string;
  videoTitle?: string;
  fastMode?: boolean;
  /**
   * RONDE 60: the render's beat-image judgement budget, so a downloaded YouTube clip can be
   * looked at before it is returned. Optional — a call site without it simply is not gated,
   * which is the same behaviour every other failure mode of the gate produces.
   */
  imageGate?: BeatImageGateState;
  /**
   * RONDE 104: the render's relevance ledger, so a YouTube clip refused here is REMEMBERED.
   *
   * This check runs before a clip is in any beat's pool, so it was the one judgement that never
   * reached the ledger — and a YouTube clip refused here could walk back in through a different
   * route under a name the compose barrier had never seen. Optional for exactly the same reason
   * imageGate is: a call site without it behaves as before.
   */
  relevanceLedger?: BeatRelevanceLedger;
};

type YoutubeSearchRow = {
  item: {
    id?: { videoId?: string };
    snippet?: {
      title?: string;
      description?: string;
      thumbnails?: { high?: { url?: string }; medium?: { url?: string } };
    };
  };
  title: string;
  desc: string;
  thumb?: string;
  rel: number;
};

/**
 * RONDE 10: quota-free YouTube search via RapidAPI (yt-api). Returns rows in the SAME shape the
 * official-API producer returns, so all downstream relevance/person filtering and download code
 * is unchanged. Defensive parsing — the scraped payload shape is not contractually stable — and
 * fails open to [] on anything unexpected. Never used for the strict-CC path (caller-enforced).
 */
async function searchYoutubeViaRapidApi(
  query: string,
  sceneIndex: number,
  maxResults: number
): Promise<{ items?: YoutubeSearchRow["item"][] } | null> {
  // RONDE 89: the provider gate. A query the contract refuses is not sent, and is
  // never repaired or substituted — the caller simply gets nothing.
  if (admitProviderQuery("youtube", query, "searchYoutubeViaRapidApi") === null) return null;
  try {
    const url = `https://${RAPIDAPI_YT_SEARCH_HOST}/search?query=${encodeURIComponent(query)}&type=video`;
    const resp = await providerLimiter("youtube").run(() => fetchWithTimeout(
      url,
      12_000,
      `YouTube RapidAPI search scene ${sceneIndex}`,
      { headers: { "x-rapidapi-host": RAPIDAPI_YT_SEARCH_HOST, "x-rapidapi-key": RAPIDAPI_KEY } }
    ));
    if (!resp.ok) {
      console.warn(`[Pipeline] Scene ${sceneIndex}: YouTube RapidAPI search HTTP ${resp.status} for "${query}"`);
      return null;
    }
    const data = (await resp.json()) as {
      data?: Array<{
        type?: string;
        videoId?: string;
        title?: string;
        description?: string;
        thumbnail?: Array<{ url?: string }>;
      }>;
    };
    const rows = (data.data ?? [])
      .filter((r) => r?.type === "video" && typeof r.videoId === "string" && r.videoId.length > 0)
      .slice(0, maxResults)
      .map((r) => ({
        id: { videoId: r.videoId },
        snippet: {
          title: r.title ?? "",
          description: r.description ?? "",
          thumbnails: {
            high: { url: r.thumbnail?.[r.thumbnail.length - 1]?.url },
            medium: { url: r.thumbnail?.[0]?.url },
          },
        },
      }));
    console.log(`[Pipeline] Scene ${sceneIndex}: YouTube RapidAPI search returned ${rows.length} video(s) for "${query}" (quota-free fallback)`);
    return { items: rows };
  } catch (err) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: YouTube RapidAPI search failed:`, (err as Error).message?.slice(0, 120));
    return null;
  }
}

// F3-45: temporarily exported (visibility only, no logic changed) so
// server/f345YoutubeCcRuntimeTest.ts can reuse it. Revert to module-private
// once that temporary diagnostic script is deleted.
/** RENDER 562 — see SOURCING_DISABLED: warn once per process, not once per scene. */
let youtubeDisabledWarned = false;

/** RENDER 562 — see SEARCH_SKIPPED below: warn once per process, not once per query. */
let youtubeSearchKeyWarned = false;

export async function searchYoutubeVideoCandidates(
  query: string,
  sceneIndex: number,
  /**
   * RONDE 160 — three modes, mapped one-to-one onto the YouTube Data API's own `videoLicense`:
   *   creative_common -> videoLicense=creativeCommon   (CC only)
   *   youtube         -> videoLicense=youtube          (standard licence only)
   *   any             -> no filter at all              (whatever ranks best)
   */
  license: YoutubeLicenseMode,
  relevanceKeywords: string[],
  minRelevanceScore: number,
  requiredPersonName: string,
  maxResults: number,
  sourcingCache?: SourcingCache
): Promise<YoutubeSearchRow[]> {
  const youtubeApiKey = process.env.YOUTUBE_API_KEY;
  if (!youtubeApiKey) {
    /**
     * RENDER 562 — a search that does not happen must say so.
     *
     * This was a bare `return []`. A deployment with ENABLE_YOUTUBE_SOURCING=true and no key
     * searched nothing, logged nothing, and reported `youtube=on` on the route line — so the
     * whole provider was absent from a render with no trace anywhere that it had been asked for.
     * 562's log carries `[YouTubeUsage] used=0` and not one search line, and nothing in it says
     * why.
     *
     * Warned once per render, not once per query: a 16-beat render would otherwise print this
     * fifty times and say nothing more than it does here.
     */
    if (!youtubeSearchKeyWarned) {
      youtubeSearchKeyWarned = true;
      console.warn(
        "[YouTube] SEARCH_SKIPPED reason=YOUTUBE_API_KEY not set — YouTube sourcing is enabled " +
          "but no search key is configured, so no YouTube candidate can enter this render"
      );
    }
    return [];
  }

  const label =
    license === "creative_common" ? "YouTube CC"
      : license === "youtube" ? "YouTube standard"
        : "YouTube fair-use";
  // Phase 5 query cache. Cached at the raw API-payload level, before any relevance/person
  // filtering below — that filtering is caller-specific (relevanceKeywords, requiredPersonName,
  // minRelevanceScore), so two callers sharing a query still get their own ranking from the one
  // shared payload. license/maxResults shape the request itself and are therefore part of the
  // key; the quota-costly search call is what gets spent once.
  // RONDE 16: the cooldown (set by repeated official-API 429s) must skip only the OFFICIAL call,
  // never the quota-free RapidAPI fallback below — that fallback exists precisely for the
  // quota-exhausted case (RONDE 10), yet the old `if (isYoutubeInCooldown()) return []` above
  // suppressed it too, so YouTube CC went fully dark for the whole 45+ minute cooldown. `null`
  // here (never re-hammering the official API) flows straight into the fallback condition.
  const searchData = isYoutubeInCooldown()
    ? null
    : await cachedProviderSearch(
    sourcingCache,
    "youtube_cc",
    `${query}#${license}#n${maxResults}`,
    async (): Promise<{ items?: YoutubeSearchRow["item"][] } | null> => {
      const searchUrl = new URL("https://www.googleapis.com/youtube/v3/search");
      searchUrl.searchParams.set("key", youtubeApiKey);
      searchUrl.searchParams.set("q", query);
      searchUrl.searchParams.set("type", "video");
      /** One decision, shared with the metadata recorded on adoption. `null` means send nothing. */
      const licenseParam = youtubeLicenseParam(license);
      if (licenseParam) searchUrl.searchParams.set("videoLicense", licenseParam);
      searchUrl.searchParams.set("maxResults", String(maxResults));
      searchUrl.searchParams.set("part", "snippet");
      searchUrl.searchParams.set("videoDuration", "medium");
      searchUrl.searchParams.set("order", "relevance");
      searchUrl.searchParams.set("videoEmbeddable", "true");

      // RONDE 52: clamped to the enclosing budget — a flat 15s inside a 22s scope left the
      // metadata call and the download with nothing, which is why render 530 found 60 videos
      // and adopted none of them.
      const searchResp = await providerLimiter("youtube").run(() => fetchWithTimeout(
        searchUrl.toString(),
        scopedTimeoutMs(15_000, 3_000),
        `${label} search scene ${sceneIndex}`
      ));
      if (!searchResp.ok) {
        if (searchResp.status === 429) {
          markYoutubeRateLimited(parseRetryAfterMs(searchResp.headers?.get?.("retry-after")));
        } else {
          markYoutubeSearchResult(false);
        }
        console.warn(`[Pipeline] Scene ${sceneIndex}: ${label} API error ${searchResp.status} for "${query}"`);
        return null;
      }
      markYoutubeSearchResult(true);
      return (await searchResp.json()) as { items?: YoutubeSearchRow["item"][] };
    },
    "searchYoutubeVideoCandidates"
  );
  // RONDE 10: the official search 429s on quota after a few renders. When it yields nothing AND
  // this is the fair-use path (never strict-CC — RapidAPI can't confirm a CC license), fall back
  // to the quota-free RapidAPI search. Opt-in (ENABLE_YOUTUBE_RAPID_SEARCH=true + RAPIDAPI_KEY).
  let effectiveSearchData = searchData;
  if (
    (!effectiveSearchData || (effectiveSearchData.items?.length ?? 0) === 0) &&
    /**
     * Only the unfiltered pass. RapidAPI's scraped search reports no licence at all, so routing a
     * licence-SPECIFIC mode through it would return results this code would then have to label
     * with a licence nobody verified — which is the silent substitution §8 forbids.
     */
    license === "any" &&
    youtubeRapidSearchFallbackEnabled()
  ) {
    effectiveSearchData = await searchYoutubeViaRapidApi(query, sceneIndex, maxResults);
  }
  if (!effectiveSearchData) return [];
  const searchDataResolved = effectiveSearchData;
  providerMetrics(sourcingCache, "youtube_cc").resultCount += searchDataResolved.items?.length ?? 0;

  return (searchDataResolved.items ?? [])
    .map((item) => {
      const title = item.snippet?.title ?? "";
      const desc = item.snippet?.description ?? "";
      const thumb = item.snippet?.thumbnails?.high?.url ?? item.snippet?.thumbnails?.medium?.url;
      const hay = `${title} ${desc} ${query}`;
      if (requiredPersonName && !textMentionsPersonName(hay, requiredPersonName)) {
        return { item, title, desc, thumb, rel: -1 };
      }
      const rel = relevanceKeywords.length > 0 ? scoreVisualRelevance(hay, relevanceKeywords) : 1;
      return { item, title, desc, thumb, rel };
    })
    .filter((row) => row.rel >= minRelevanceScore)
    .sort((a, b) => b.rel - a.rel);
}

export async function fetchYouTubeCCClips(
  queries: string | string[],
  duration: number,
  workDir: string,
  sceneIndex: number,
  count: number = 2,
  relevanceKeywords: string[] = [],
  minRelevanceScore = 1,
  requiredPersonName = "",
  scriptGuided?: ScriptGuidedBeatContext,
  usedProviderKeys?: Set<string>,
  sourcingCache?: SourcingCache
): Promise<string[]> {
  /**
   * RENDER 562 — the two silent exits, and how they were found.
   *
   * The two guards below this one already log their reason. Render 562's log carries NEITHER,
   * which is what proves the function never reached them: it stopped here, and here said nothing.
   * The whole YouTube branch was absent from that render with no line anywhere explaining it, and
   * `[YouTubeUsage] used=0` was the only trace.
   *
   * Once per render, not once per scene: a 3-scene render would otherwise print this three times
   * and a 20-scene render twenty, saying no more than one line does.
   */
  if (!youtubeSourcingEnabled()) {
    if (!youtubeDisabledWarned) {
      youtubeDisabledWarned = true;
      console.warn(
        "[YouTube] SOURCING_DISABLED reason=ENABLE_YOUTUBE_SOURCING is not true — the whole " +
          "YouTube branch is skipped before any key is read"
      );
    }
    return [];
  }
  // RONDE 16: bail on the official-API quota cooldown ONLY when there is no quota-free fallback to
  // try. The RapidAPI fair-use search hits a different host (not Google), so the official cooldown
  // must not suppress it — otherwise the fallback built for the quota-exhausted case never runs.
  // When the fallback IS available, proceed: searchYoutubeVideoCandidates skips the official call
  // during cooldown and routes the fair-use pass through RapidAPI instead.
  if (isYoutubeInCooldown() && !(youtubeRapidSearchFallbackEnabled() && youtubeFairUseEnabled())) {
    console.warn(
      `[Pipeline] Scene ${sceneIndex}: YouTube skipped — the official API is in quota cooldown ` +
        "and the RapidAPI search fallback is not enabled (ENABLE_YOUTUBE_RAPID_SEARCH)"
    );
    return [];
  }
  const results: string[] = [];

  const youtubeApiKey = process.env.YOUTUBE_API_KEY;
  const hasDownloader = !!RAPIDAPI_KEY || !!process.env.YOUTUBE_CC_DL_SERVICE;

  if (!youtubeApiKey) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: YouTube CC skipped — missing YOUTUBE_API_KEY`);
    return [];
  }
  if (!hasDownloader) {
    console.warn(
      `[Pipeline] Scene ${sceneIndex}: YouTube CC skipped — set RAPIDAPI_KEY or YOUTUBE_CC_DL_SERVICE in Railway`
    );
    return [];
  }

  // Normalise: accept single string or array of query variants (specific→broad)
  const queryList = Array.isArray(queries) ? queries : [queries];
  // Deduplicate and filter empty strings
  const uniqueQueries = uniqueQueryStrings(queryList);

  // Track video IDs already downloaded to avoid duplicates across query variants
  const downloadedIds = new Set<string>();
  let fetched = 0;
  /**
   * A ceiling on download ATTEMPTS, not just on accepted clips.
   *
   * RONDE 62 added this because render 532 downloaded 97 YouTube videos and used none: the loop
   * counted only successes, so with the picture gate refusing most candidates it kept
   * downloading through every candidate of every query of every licence pass.
   *
   * RONDE 68 fixes where the counter lives. It was a local, so the ceiling was per CALL, and
   * this function is called about twenty-six times per render. Render 533 logged
   *
   *     26 x "download ceiling reached (6/6 attempts, 0 accepted)"
   *
   * and 150 downloads cancelled by the enclosing scene budget — 26 x 6, almost exactly. The
   * cap fired every time and bounded nothing. Counting on the render-scoped metrics object
   * makes it what the comment always claimed it was.
   */
  const downloadsSoFar = () => providerMetrics(sourcingCache, "youtube_cc").downloadCount;
  const maxDownloadAttempts = youtubeMaxDownloadsPerRender();

  /**
   * RONDE 69: reserve the slot, then download — never the other way round. Render 534 logged
   * 20/20, 21/20, 22/20, 23/20 because the check and the increment sat on opposite sides of two
   * awaits. See claimYoutubeDownloadSlot for why this is the whole fix.
   */
  const claimDownloadSlot = (): boolean =>
    claimYoutubeDownloadSlot(sourcingCache, maxDownloadAttempts);

  const ytDeadline = Date.now() + (IS_RAILWAY ? 88_000 : 55_000);
  const guidedDeadline =
    scriptGuidedClipsEnabled() && scriptGuided?.beatText?.trim()
      ? Date.now() + scriptGuidedBudgetMs(scriptGuided.fastMode ?? IS_RAILWAY)
      : ytDeadline;

  /**
   * RONDE 160 — the licence passes, most permissive LAST.
   *
   * CC first because it is the only material whose reuse the licence itself grants. The explicit
   * standard-licence pass sits before the unfiltered one so that, when it is switched on, a clip
   * that IS standard-licensed is retrieved under a mode that says so rather than arriving
   * anonymously through `any`.
   */
  const licensePasses: Array<{ license: YoutubeLicenseMode; tag: string; fileTag: string }> = [
    { license: "creative_common", tag: "YouTube CC", fileTag: "ytcc" },
  ];
  if (youtubeStandardLicenseEnabled()) {
    licensePasses.push({ license: "youtube", tag: "YouTube standard", fileTag: "ytstd" });
  }
  if (youtubeFairUseEnabled()) {
    licensePasses.push({ license: "any", tag: "YouTube fair-use", fileTag: "ytfu" });
  }

  for (const query of uniqueQueries.slice(0, 2)) {
    if (fetched >= count) break;
    if (downloadsSoFar() >= maxDownloadAttempts) break;
    if (Date.now() > ytDeadline) break;

    for (const pass of licensePasses) {
      if (fetched >= count) break;
      if (downloadsSoFar() >= maxDownloadAttempts) break;
      if (Date.now() > ytDeadline) break;
      if (pass.license === "any" && fetched >= count) break;

      try {
        const items = await searchYoutubeVideoCandidates(
          query,
          sceneIndex,
          pass.license,
          relevanceKeywords,
          minRelevanceScore,
          requiredPersonName,
          Math.max(5, (count - fetched) * 4),
          sourcingCache
        );
        /**
         * RONDE 160 (FASE 8/15) — one line per SOURCE ATTEMPT, in the [Retrieval] vocabulary.
         *
         * A production log has to be able to answer "why was YouTube used for this beat" and "why
         * was it not", and the [Pipeline] lines below answer neither: they say what happened but
         * not which licence mode was tried, so a beat that got nothing from YouTube looked the
         * same as a beat where YouTube was never attempted. Counts and the mode only — never a
         * key, never a URL.
         */
        console.log(
          `[Retrieval] s${sceneIndex} source=youtube mode=${pass.license} attempted=true ` +
            `candidates=${items.length} query=${JSON.stringify(query.slice(0, 80))}`
        );
        if (!items.length) {
          console.warn(
            `[Pipeline] Scene ${sceneIndex}: ${pass.tag} 0 relevant results for "${query}"`
          );
          continue;
        }
        console.log(
          `[Pipeline] Scene ${sceneIndex}: ${pass.tag} found ${items.length} relevant videos for "${query}"`
        );

        let guidedAttempts = 0;
        const maxGuidedAttempts = scriptGuided?.fastMode ? 2 : 3;

        for (const row of items.slice(0, 5)) {
          if (fetched >= count) break;
          if (Date.now() > ytDeadline) break;
          if (downloadsSoFar() >= maxDownloadAttempts) {
            console.log(
              `[Pipeline] Scene ${sceneIndex}: YouTube download ceiling reached for this RENDER ` +
                `(${downloadsSoFar()}/${maxDownloadAttempts} downloads, ${fetched} accepted here)`
            );
            break;
          }
          const item = row.item;
          const videoId = item.id?.videoId;
          if (!videoId || downloadedIds.has(videoId)) continue;
          // Pre-download visual dedup: skip a YouTube video we already adopted this render
          // (possibly via a different cascade/query), before script-guided planning or the
          // download itself — see providerAssetKey.
          if (providerAssetAlreadyUsed(usedProviderKeys, sourcingCache, "youtube_cc", videoId)) continue;

          const title = row.title;
          if (relevanceKeywords.length > 0 && row.rel < minRelevanceScore) {
            console.warn(
              `[Pipeline] Scene ${sceneIndex}: ${pass.tag} skip irrelevant "${title.slice(0, 60)}" (score ${row.rel}/${minRelevanceScore})`
            );
            continue;
          }

          try {
            const clipDur = capYoutubeClipDuration(duration, pass.fileTag);
            // RONDE 62: ask the metadata call that actually works on Railway how long the video
            // is. The watch page added in RONDE 60 was supposed to answer this and did not —
            // render 532 logged src=unknown on all 52 plans — while this same response, which
            // the download needs anyway, has been carrying lengthSeconds the whole time. It is
            // render-cached, so fetching it here rather than inside the download costs nothing.
            const sourceDurationSec =
              rapidApiYoutubeMetaDurationSec(
                await fetchRapidApiYoutubeMeta(videoId, sceneIndex, sourcingCache)
              ) || peekYoutubeVideoContext(videoId)?.durationSec || 0;
            // The old flat 15 was applied to every candidate past the guided-attempt limit —
            // second 15 of a forty-minute documentary is its intro.
            let clipStart =
              sourceDurationSec > 0
                ? pickLongVideoStartSec(sourceDurationSec, clipDur, videoId)
                : 15;
            let startIsExact = false;
            if (
              scriptGuidedClipsEnabled() &&
              scriptGuided?.beatText?.trim() &&
              guidedAttempts < maxGuidedAttempts
            ) {
              guidedAttempts++;
              const plan = await planScriptGuidedClip(
                {
                  videoId,
                  title,
                  description: row.desc,
                  thumbnailUrl: row.thumb,
                  metadataScore: row.rel,
                },
                {
                  beatText: scriptGuided.beatText,
                  keywords: relevanceKeywords,
                  videoTitle: scriptGuided.videoTitle,
                  deadlineMs: Math.min(ytDeadline, guidedDeadline),
                  fastMode: scriptGuided.fastMode,
                  clipDurationSec: clipDur,
                  // Hand over the length we already know, so the planner's fallback scales even
                  // when its own watch-page read comes back empty.
                  sourceDurationSec,
                }
              );
              if (plan.skip) {
                console.log(
                  `[ScriptGuided] Scene ${sceneIndex}: skip YT "${title.slice(0, 55)}" (vision/metadata)`
                );
                continue;
              }
              clipStart = Math.max(0, Math.round(plan.startSec * 10) / 10);
              // RONDE 64: only a transcript hit LOCATED this second. Every other method on the
              // ladder — metadata, thumbnail vision, the default — produced a guess, and a guess
              // is worth re-deriving once the source's real length is on disk.
              startIsExact = plan.method === "transcript";
              console.log(
                `[ScriptGuided] Scene ${sceneIndex}: ${plan.method} @${clipStart}s ` +
                  `src=${plan.sourceDurationSec ? `${Math.round(plan.sourceDurationSec)}s` : "unknown"} ` +
                  `"${title.slice(0, 55)}"`
              );
            }

            const outPath = tagPathWithProviderAsset(
              path.join(workDir, `scene_${sceneIndex}_${pass.fileTag}_${fetched}.mp4`),
              "youtube_cc",
              videoId,
              sourcingCache,
              { sceneIndex, title, mediaType: "video", searchRoute: "fetchYouTubeCCClips" }
            );
            // Fase 4: real YouTube-authored title/description, independent of our search query —
            // adoptClip's generic providerText lookup (see above) picks this up for both
            // AssetDirector ranking and the entity gate.
            putCachedProviderAsset(sourcingCache, "youtube_cc", videoId, {
              providerText: { title, description: row.desc },
              /**
               * RONDE 160 (FASE 4) — WHICH mode found this clip, recorded at the moment it is
               * found. `creative_common` and `youtube` are licence assertions by YouTube; `any`
               * is not one, so no `reported` licence is claimed for it.
               */
              license: youtubeLicenseMetadata(pass.license),
            });
            // RONDE 69: the ceiling is enforced HERE, with nothing awaited between the read and
            // the write. The loop-level checks above stay as cheap early exits; this is the one
            // that holds.
            if (!claimDownloadSlot()) {
              console.log(
                `[Pipeline] Scene ${sceneIndex}: YouTube download ceiling reached for this RENDER ` +
                  `(${downloadsSoFar()}/${maxDownloadAttempts} downloads, ${fetched} accepted here)`
              );
              break;
            }
            const ok = await downloadYouTubeCCClip(
              videoId,
              clipDur,
              clipStart,
              outPath,
              sceneIndex,
              item.snippet?.title,
              // RONDE 56: render-scoped, so the metadata for a video already looked up on an
              // earlier beat is reused instead of re-fetched and re-aborted.
              sourcingCache,
              startIsExact
            );
            if (ok && !(await youtubeClipPassesImageGate(outPath, workDir, sceneIndex, videoId, scriptGuided))) {
              // Rejected on what it shows, not on what it is called. The file is removed so a
              // later beat cannot pick it up off disk, and the loop moves to the next candidate.
              try { fs.unlinkSync(outPath); } catch { /* ignore */ }
              continue;
            }
            if (ok) {
              results.push(outPath);
              downloadedIds.add(videoId);
              fetched++;
              if (pass.license === "any") {
                console.log(
                  `[Pipeline] Scene ${sceneIndex}: ✅ YouTube fair-use clip (transform on adopt): "${title.slice(0, 60)}"`
                );
              }
            }
          } catch (err) {
            console.warn(
              `[Pipeline] Scene ${sceneIndex}: ${pass.tag} video ${videoId} failed:`,
              (err as Error).message
            );
          }
        }
      } catch (err) {
        // RONDE 52: this catch used to swallow the failure without touching the breaker, because
        // markYoutubeSearchResult(false) sits after the `searchResp.ok` check inside the search
        // and a thrown timeout never reaches it. YouTube therefore never tripped its own
        // circuit: render 530 retried it 24 times while Wikimedia correctly stood itself down
        // after three ("3 consecutive search failures — skipping for 3min").
        //
        // A scope abort is explicitly NOT counted. That is the pipeline running out of budget,
        // not the provider misbehaving, and counting it would disable a healthy source because
        // the render happened to be busy — the opposite mistake.
        if (!isScopeAbortError(err)) markYoutubeSearchResult(false);
        console.warn(
          `[Pipeline] Scene ${sceneIndex}: ${pass.tag} search failed for "${query}":`,
          (err as Error).message
        );
      }
    }
  }
  return results;
}

// ─── 3d. Transform Clip for Fair Use ───────────────────────────────────────
// Applies mandatory visual transformations to any stock/archive/YouTube clip:
//   1. Cinematic color grading (contrast + saturation + color curves)
//   2. Scene narration text as subtitle overlay (bottom of frame)
//   3. Vignette effect (darkened edges for cinematic look)
//   4. Slight zoom-in crop (changes framing/composition)
// This makes every clip a transformative derivative work.
async function transformClipForFairUse(
  inputPath: string,
  sceneText: string,
  sceneIndex: number,
  clipIndex: number,
  workDir: string,
  timeoutMs = 120_000
): Promise<string> {
  const outputPath = inputPath.replace(/\.mp4$/, '_transformed.mp4');
  const strict = clipRequiresFairUseTransform(inputPath);

  const grades = [
    { contrast: 1.08, saturation: 1.12, brightness: -0.02 },
    { contrast: 1.10, saturation: 0.95, brightness: -0.03 },
    { contrast: 1.05, saturation: 1.20, brightness: 0.00 },
    { contrast: 1.12, saturation: 0.90, brightness: -0.04 },
    { contrast: 1.06, saturation: 1.08, brightness: 0.01 },
  ];
  const grade = grades[(sceneIndex + clipIndex) % grades.length];
  const vignetteAngle = (0.5 + ((sceneIndex * 3 + clipIndex) % 5) * 0.1).toFixed(2);
  const zoom = 1.06 + ((sceneIndex + clipIndex) % 3) * 0.01;
  const zw = Math.round(VIDEO_WIDTH * zoom);
  const zh = Math.round(VIDEO_HEIGHT * zoom);
  const zoomCrop =
    `scale=${zw}:${zh}:force_original_aspect_ratio=increase,crop=${VIDEO_WIDTH}:${VIDEO_HEIGHT}:(iw-${VIDEO_WIDTH})/2:(ih-${VIDEO_HEIGHT})/2`;
  let filterChain =
    `${zoomCrop},` +
    `eq=contrast=${grade.contrast}:saturation=${grade.saturation}:brightness=${grade.brightness},` +
    `vignette=angle=${vignetteAngle}:mode=forward`;

  const subtitle = sanitizeForDrawtextStrict(sceneText, 72);
  if (subtitle && ffmpegSupportsDrawtext()) {
    filterChain +=
      `,drawtext=text='${subtitle}':fontcolor=white:fontsize=30:x=(w-text_w)/2:y=h-72:` +
      `box=1:boxcolor=black@0.55:boxborderw=10`;
  }

  const TRANSFORM_TIMEOUT_MS = timeoutMs;
  console.log(
    `[Pipeline] Scene ${sceneIndex}: fair-use transform clip ${clipIndex} (${path.basename(inputPath)})` +
      (subtitle ? " + narration subtitle" : "")
  );
  try {
    const { spawn: spawnChild } = await import('child_process');
    // Routed through ffmpegSemaphore — this raw spawn() previously bypassed the shared
    // concurrency gate, and this function sits on the primary per-beat clip-adoption path
    // (clipRequiresFairUseTransform), so an ungated spawn here directly contributes to
    // fork-pressure risk on every render that needs a fair-use transform.
    await ffmpegSemaphore.run(() => new Promise<void>((resolve, reject) => {
      const args = [
        '-y', '-i', inputPath,
        '-vf', filterChain,
        '-c:v', 'libx264', '-preset', 'veryfast', '-crf', '20', '-an', '-pix_fmt', 'yuv420p',
        outputPath
      ];
      const child = spawnChild(FFMPEG_BIN, args, { stdio: ['ignore', 'ignore', 'pipe'] });
      let stderr = '';
      child.stderr.on('data', (d: Buffer) => { stderr += d.toString().slice(-500); });
      const timer = setTimeout(() => {
        console.warn(`[Pipeline] Scene ${sceneIndex}: transform clip ${clipIndex} TIMEOUT after ${TRANSFORM_TIMEOUT_MS/1000}s — killing FFmpeg`);
        try { child.kill('SIGKILL'); } catch { /* ignore */ }
        reject(
          pipelineError(
            PIPELINE_ERROR.TIMEOUT,
            `Transform timeout scene ${sceneIndex} clip ${clipIndex}`
          )
        );
      }, TRANSFORM_TIMEOUT_MS);
      child.on('close', (code: number | null) => {
        clearTimeout(timer);
        if (code === 0) resolve();
        else reject(pipelineError(PIPELINE_ERROR.FFMPEG, `FFmpeg exit ${code}: ${stderr.slice(-200)}`));
      });
      child.on('error', (err: Error) => { clearTimeout(timer); reject(err); });
    }));
    if (fs.existsSync(outputPath) && fs.statSync(outputPath).size > 5_000) {
      if (await isValidVideoFile(outputPath)) {
        try { fs.unlinkSync(inputPath); } catch { /* ignore */ }
        console.log(`[Pipeline] Scene ${sceneIndex}: clip ${clipIndex} transformed for fair use`);
        return outputPath;
      }
      console.warn(`[Pipeline] Scene ${sceneIndex}: transformed clip ${clipIndex} unreadable`);
    }
  } catch (err) {
    console.warn(`[Pipeline] Scene ${sceneIndex}: fair-use transform failed for clip ${clipIndex}:`, (err as Error).message);
  }
  if (strict) return "";
  return inputPath;
}

// P1-A (render 517): title-case FRAMING words that are never part of a real person's name.
// extractPrimaryPersonFromText used to accept the first capitalized run of a documentary title
// verbatim — "Why Hitler Lost the War" produced the literal person lock "Why Hitler", which
// polluted every person-anchored query AND suppressed the historical-documentary handling
// (personTopicLock disables historicalDoc at every branch that checks it). Deliberately free of
// ambiguous real first names (Will, Mark, Grant, Art, Jack, ...) so genuine names never lose tokens.
const TITLE_NON_NAME_WORDS = new Set([
  "why", "how", "what", "when", "where", "which", "whose",
  "the", "a", "an", "this", "that", "these", "those",
  "is", "was", "are", "were", "did", "does", "do",
  "inside", "behind", "before", "after", "during", "about", "against",
  "from", "into", "every", "his", "her", "their", "its", "our", "your", "my",
  "and", "but", "not", "no",
  "story", "stories", "truth", "secret", "secrets", "untold", "history", "historical",
  "real", "really", "rise", "fall", "lost", "won", "became", "revealed", "explained",
  "documentary", "facts", "biography", "final", "last", "first", "days", "war", "world",
  "life", "death", "end", "complete", "ultimate", "full", "deep", "dive",
  // Common documentary-title verbs ("How Napoleon Conquered Europe") — none are name tokens.
  "conquered", "invaded", "escaped", "survived", "killed", "died", "destroyed", "defeated",
  "betrayed", "ruled", "built", "created", "changed", "started", "ended", "failed", "saved",
  "murdered", "married",
  // RONDE 18 (render 524): "Hitler Chose" locked as a person because "chose" is not a framing
  // word — the surname anchor never fired, so the beat searched the fake two-word name instead of
  // the script's real "Adolf Hitler". These decision verbs are title glue, never name tokens.
  "chose", "chosen", "chooses", "decided", "planned", "wanted", "tried", "refused", "ordered",
  // Pronouns/relationship words (render 518: the script scan fabricated the person "His Wife"
  // from the title "Why Hitler Killed Himself — And His Wife"). Never tokens of a real name.
  "himself", "herself", "themselves", "wife", "husband", "mother", "father", "brother",
  "sister", "son", "daughter",
  // RONDE 11 (render 521): capitalized CONCEPT nouns that a documentary title/script surfaces as
  // fake two-word "names" ("Suicide Pact", "Nazi Germany", "As Nazi"). None are person tokens.
  "suicide", "pact", "nazi", "germany", "reich", "führer", "fuhrer", "bunker", "army", "empire",
  "battle", "invasion", "regime", "party", "hours", "moments", "motivations", "as", "into",
  "downfall", "defeat", "victory", "surrender", "escape", "plot", "conspiracy", "mystery",
  "remains", "germans", "allies", "soviets", "russians", "americans",
]);

/**
 * P1-A: strip leading/trailing title framing words from a capitalized run; a run that still
 * contains a framing word mid-name is no name at all. Returns the surviving tokens.
 */
function cleanPersonNameCandidate(candidate: string): string[] {
  const tokens = candidate.trim().split(/\s+/).filter(Boolean);
  while (tokens.length && TITLE_NON_NAME_WORDS.has(tokens[0].toLowerCase())) tokens.shift();
  while (tokens.length && TITLE_NON_NAME_WORDS.has(tokens[tokens.length - 1].toLowerCase())) tokens.pop();
  if (tokens.some((t) => TITLE_NON_NAME_WORDS.has(t.toLowerCase()))) return [];
  return tokens;
}

/** Extract a person name from prompts/titles like "Rumors about Kylie Jenner". */
export function extractPrimaryPersonFromText(
  text?: string,
  /**
   * RONDE 88 (§11): the script body, when the caller has it. A Title Case input yields a name
   * only when that name also appears here — a title is not evidence that a person is in a beat.
   * Omitted (the legacy callers) means Title Case input yields nothing, which is the safe answer.
   */
  corroboration = ""
): string {
  if (!text?.trim()) return "";
  // RONDE 123: `\w` is ASCII, so this used to hand the pattern "G ring" for "Göring".
  const cleaned = stripToNameSafeText(text);
  const aboutMatch = cleaned.match(/\babout\s+([A-Za-z][\w'-]+(?:\s+[A-Za-z][\w'-]+){0,2})/i);
  if (aboutMatch?.[1]) {
    const aboutTokens = cleanPersonNameCandidate(aboutMatch[1]);
    if (aboutTokens.length > 0) return aboutTokens.join(" ");
  }
  const kylieMatch = cleaned.match(/\b(kylie\s+jenner)\b/i);
  if (kylieMatch?.[1]) return "Kylie Jenner";
  const nameMatches = cleaned.match(nameRunRegex(1, 2)) ?? [];
  const skip = new Set(["deep dive", "the story", "a deep", "full story", "rumors about"]);
  for (const candidate of nameMatches) {
    if (skip.has(candidate.toLowerCase())) continue;
    // A full name only when ≥2 clean tokens survive — a single leftover token ("Hitler" from
    // "Why Hitler Lost") is a surname anchor, not a name; see extractPersonSurnameAnchor.
    const tokens = cleanPersonNameCandidate(candidate);
    if (tokens.length < 2) continue;
    /**
     * RONDE 88 (§8/§11) — the same structural check the script scan uses.
     *
     * This function is usually handed a TITLE, and a title capitalises every word, so its
     * capitalisation proves nothing about which words are names. Measured before this line:
     * "Why Hitler Married Eva Braun Just Before The End" → "Eva Braun Just", and
     * "Inside The Final Hours Of Adolf Hitler" → "Of Adolf". checkPersonName splits on function
     * words and, for Title Case input, requires the name to be corroborated by the caller's
     * proven text — a title alone is not evidence that anybody is in any beat.
     */
    const name = tokens.join(" ");
    if (!checkPersonName(name, text, corroboration, { isKnownVerb: isKnownPersonActionVerb }).ok) continue;
    return name;
  }
  return "";
}

/**
 * P1-A: when a title's capitalized run reduces to exactly ONE surviving token after framing-word
 * cleanup ("Why Hitler Lost" → "Hitler"), that token is a surname ANCHOR — not a usable name by
 * itself. The pipeline resolves it against the full names the script itself states
 * (extractPersonNamesFromText + resolvePersonFromSurnameAnchor), so "Why Hitler …" locks to the
 * script's own "Adolf Hitler" instead of a fabricated two-word title fragment.
 */
export function extractPersonSurnameAnchor(text?: string): string {
  if (!text?.trim()) return "";
  // RONDE 123: `\w` is ASCII, so this used to hand the pattern "G ring" for "Göring".
  const cleaned = stripToNameSafeText(text);
  const runs = cleaned.match(nameRunRegex(0, 3)) ?? [];
  for (const run of runs) {
    const tokens = cleanPersonNameCandidate(run);
    if (tokens.length === 1 && tokens[0].length >= 3) return tokens[0];
  }
  return "";
}

/**
 * P1-A: pick the script-stated full name whose LAST token (surname position) matches the title's
 * surname anchor. The surname-position requirement keeps non-person capitalized runs out — a
 * "Chernobyl" anchor never matches "Chernobyl Exclusion Zone", so no lock gets fabricated.
 */
export function resolvePersonFromSurnameAnchor(anchor: string, names: string[]): string {
  const a = anchor.trim().toLowerCase();
  if (!a) return "";
  return names.find((n) => n.toLowerCase().split(/\s+/).pop() === a) ?? "";
}

function extractPrimaryPersonFromTitle(title?: string, corroboration = ""): string {
  return extractPrimaryPersonFromText(title, corroboration);
}

function isPersonCelebrityTopic(topicContext?: string): boolean {
  const t = (topicContext ?? "").toLowerCase();
  if (/\bkylie\b|\bjenner\b|\bkardashian\b/.test(t)) return true;
  return Boolean(extractPrimaryPersonFromText(topicContext));
}

/**
 * RONDE 93 (§6) — the third unconditional source of media suffixes, and the last one.
 *
 * `interview`, `speech`, `news conference` and `red carpet` were appended to every person here
 * too, on top of buildPersonArchiveVideoQueries and buildPersonStockVideoQueries doing the same.
 * Three builders guessing the same four words about anybody the script happens to name.
 *
 * What remains is the name itself, and the beat's OWN visual cue when it has one — `visualCue`
 * comes from extractInlineVisualCues on the beat text, so it is the script speaking. The event
 * terms are not lost: scriptEventSearchQueries supplies each of them the moment the beat gives a
 * reason to.
 */
function buildPersonMediaQueries(person: string, visualCue?: string): string[] {
  const p = coercePersonName(person);
  if (!p) return [];
  const cue = toQueryString(visualCue).split(/\s+/).slice(0, 3).join(" ");
  return uniqueCoercedQueries([p, cue ? `${p} ${cue}` : `${p} archival footage`], 1);
}

interface CelebrityClipCandidate {
  path: string;
  query: string;
  // F3-30: optional structured provenance — populated only by sources that can reliably
  // establish a per-item reuse license (currently fetchEuropeanaVideos). Left undefined by
  // every other producer of this shared shape (IA/Wikimedia/SepiaSearch/Vimeo), which is a
  // no-op for them — this is a pure additive extension of an existing type.
  sourceUrl?: string;
  sourcePlatform?: string;
  sourceCreator?: string;
  licenseUrl?: string;
  license?: string;
  title?: string;
}

// RONDE 9: AWS Rekognition celebrity verification for person-locked renders. Keyed by clip
// content hash so the same clip is never analyzed twice (Rekognition bills per image).
const rekognitionClipPersonsCache = new Map<string, string[]>();

/**
 * RONDE 9: returns true ONLY on strong evidence that the clip shows a DIFFERENT celebrity than
 * the locked person (render 519 adopted mislabeled stock for Eva Braun beats; render 517's
 * SepiaSearch pool carried Putin-comparison videos). Deliberately a NEGATIVE filter:
 * - no Rekognition keys configured → false (feature off, zero behavior change)
 * - no celebrity recognized (B-roll, places, objects, unclear old footage) → false
 * - the locked person recognized → false
 * - any error → false (fail-open, never blocks video production)
 * Only a ≥90-confidence match on somebody else rejects.
 */
async function clipShowsWrongCelebrity(
  clipPath: string,
  personName: string,
  mediaType: "video" | "image",
  durationSec?: number | null
): Promise<boolean> {
  const person = coercePersonName(personName);
  if (!person) return false;
  try {
    // Lazy import: the AWS SDK is heavyweight and only needed when keys are configured.
    const { isRekognitionEnabled, recognizeCelebritiesInFile } = await import("./rekognitionCelebrity");
    if (!isRekognitionEnabled()) return false;
    const key = clipContentKey(clipPath);
    let names = rekognitionClipPersonsCache.get(key);
    if (!names) {
      const rek = await recognizeCelebritiesInFile(clipPath, mediaType, durationSec ?? null);
      names = rek.persons.filter((p) => p.confidence >= 90).map((p) => p.name);
      rekognitionClipPersonsCache.set(key, names);
    }
    if (!names.length) return false;
    const locked = names.some(
      (n) => textMentionsPersonName(n, person) || textMentionsPersonName(person, n)
    );
    if (locked) return false;
    console.log(
      `[Rekognition] clip shows ${names.join(", ")} — not the locked person "${person}", rejecting: ${path.basename(clipPath)}`
    );
    return true;
  } catch (err) {
    console.warn(`[Rekognition] verification skipped:`, (err as Error).message?.slice(0, 120));
    return false;
  }
}

/** True when haystack contains the celebrity name (last name or full name). */
function textMentionsPersonName(haystack: string, personName: string): boolean {
  const name = coercePersonName(personName);
  if (!name) return false;
  const hay = haystack.toLowerCase();
  const parts = name.toLowerCase().split(/\s+/).filter((p) => p.length >= 2);
  if (!parts.length) return false;
  if (parts.length === 1) return hay.includes(parts[0]);
  const last = parts[parts.length - 1];
  if (hay.includes(last)) return true;
  return parts.every((p) => hay.includes(p));
}

/** Beat + person tokens for filtering celebrity search hits. */
function buildPersonBeatRelevanceKeywords(personName: string, beatText: string): string[] {
  const person = coercePersonName(personName);
  const clean = beatText.replace(/\[visual:[^\]]*\]/gi, " ").trim();
  return [
    ...person.split(/\s+/).filter((p) => p.length >= 3),
    ...tokenizeForRelevance(clean),
    ...extractInlineVisualCues(clean).flatMap((c) => tokenizeForRelevance(c)),
  ].filter((k, i, arr) => arr.indexOf(k) === i).slice(0, 18);
}

/**
 * Script-aware celebrity video queries: events + visual cues + person variants.
 * Rotated per beat so each narration line gets a different search angle.
 */
export function buildPersonCelebrityVideoQueries(
  personName: string,
  beatText: string,
  beatIndex: number
): string[] {
  const clean = beatText.replace(/\[visual:[^\]]*\]/gi, " ").trim();
  const persons = [personName];
  const eventQs = scriptEventSearchQueries(clean, persons);
  const visualCues = extractInlineVisualCues(clean);
  const beatTokens = tokenizeForRelevance(clean).filter((t) => t.length >= 4).slice(0, 3);
  const mediaQs = buildPersonMediaQueries(personName, visualCues[0] || beatTokens.join(" "));

  const combined = [
    ...eventQs,
    ...visualCues.map((c) => `${personName} ${c}`.trim()),
    ...beatTokens.map((t) => `${personName} ${t}`),
    ...mediaQs,
  ].filter((q) => {
    const s = toQueryString(q);
    return s.length > 3 && !isBlockedStockQuery(s);
  });

  const unique = [...new Set(combined)];
  const offset = beatIndex % Math.max(1, unique.length);
  const rotated = [...unique.slice(offset), ...unique.slice(0, offset)].slice(0, 7);

  // RONDE 77: the typed combination, in front of the rotation rather than inside it. The rotation
  // exists so consecutive beats about one person do not all fetch the same clip; the typed query
  // already differs per beat because the place, the year and the verb do, so rotating it would
  // only cost the beat its most specific question. personName is forced rather than weighed: the
  // caller is asking a provider for footage OF this person, so a name the beat happens to mention
  // supplies no subject here, and a beat that says "he" carries no name of its own.
  const typed = typedQueryPrefix(clean, { forcePerson: personName })
    .filter((q) => !isBlockedStockQuery(toQueryString(q)))
    .slice(0, 2);
  const head = typed.filter((q) => !rotated.includes(q));
  return [...head, ...rotated];
}

function scoreCelebrityCandidate(
  candidate: CelebrityClipCandidate,
  beatText: string,
  personName: string,
  keywords: string[]
): number {
  const hay = `${candidate.query} ${path.basename(candidate.path)} ${beatText}`.toLowerCase();
  return (
    scoreBeatNarrationMatch(beatText, candidate.query, candidate.path) * 4 +
    scoreVisualRelevance(hay, keywords) +
    (textMentionsPersonName(hay, personName) ? 4 : 0)
  );
}

async function adoptBestCelebrityClip(
  candidates: CelebrityClipCandidate[],
  dedup: VisualDedupState,
  sceneIndex: number,
  beatIndex: number,
  beatText: string,
  workDir: string,
  personName: string,
  opts: VisualAdoptOptions
): Promise<string | null> {
  if (!candidates.length) return null;
  const keywords = opts.keywords ?? buildPersonBeatRelevanceKeywords(personName, beatText);
  const sorted = [...candidates].sort(
    (a, b) =>
      scoreCelebrityCandidate(b, beatText, personName, keywords) -
      scoreCelebrityCandidate(a, beatText, personName, keywords)
  );
  for (const c of sorted) {
    // P0/P1 image-quality patch — Fix 2: real, provider-authored text (not our own search
    // query) is the only usable "external annotation" signal these providers actually return.
    // Registering it here — the single point every CelebrityClipCandidate producer (Wikimedia,
    // GDELT, SepiaSearch, Internet Archive, Vimeo CC, Europeana) already funnels through before
    // adoptClip — gives both scoreAnnotationFingerprint (assetDirector.ts) and the entity gate
    // (hasReliableEntityEvidence) something honest to check besides the query/filename.
    if (c.title) {
      const existing = dedup.clipAnnotationMeta.get(c.path) ?? {};
      dedup.clipAnnotationMeta.set(c.path, { ...existing, providerText: { title: c.title } });
    }
    const clip = await adoptClip(
      [c.path],
      dedup,
      sceneIndex,
      beatIndex,
      beatText,
      workDir,
      c.query,
      opts
    );
    if (clip) return clip;
  }
  return null;
}

/** Script-aware Serp queries — event from narration first, then rotated portrait variants. */
function buildPersonSerpQuery(
  person: string,
  sceneIndex: number,
  beatIndex: number,
  beatText = ""
): string {
  const scriptQs = beatText
    ? scriptEventSearchQueries(beatText, [person]).map((q) =>
        /\b(face|portrait|interview|talking)\b/i.test(q) ? q : `${q} face interview`
      )
    : [];
  if (scriptQs.length) {
    return scriptQs[(sceneIndex + beatIndex) % scriptQs.length];
  }
  /**
   * RONDE 93 (§6) — the script said nothing, so neither does this.
   *
   * Six variants used to fire here when scriptEventSearchQueries came back empty: red carpet,
   * met gala, makeup brand launch, paparazzi. A beat that gives no event cue is a beat that
   * gives no reason to search for a gala, and rotating through six guesses does not turn one of
   * them into an answer. What is left asks for the person, which is the only thing proven.
   */
  const variants = [`${person} face portrait close up`, `${person} portrait`, person];
  return variants[(sceneIndex * 5 + beatIndex) % variants.length];
}

/** Script-anchored image queries: person → event → power word → topic. */
function buildBeatImageSearchQueries(
  beat: SceneBeat,
  scene: Scene,
  videoTitle: string | undefined,
  scenePersons: string[]
): string[] {
  hydrateSceneBeatInPlace(beat);
  const primary = scenePersons[0]?.trim() ?? "";
  const out: string[] = [...beatVisualSearchSubjects(beat.text)];
  if (primary) {
    out.push(buildPersonSerpQuery(primary, scene.index, beat.index, beat.text));
    out.push(`${primary} face portrait photo`);
    for (const eq of scriptEventSearchQueries(beat.text, scenePersons).slice(0, 3)) {
      out.push(eq);
    }
  }
  const power = beat.powerWord?.trim();
  if (power && power.length >= 3 && !isBlockedStockQuery(power)) {
    out.push(primary ? `${primary} ${power}` : power);
  }
  for (const cue of extractInlineVisualCues(beat.text).slice(0, 2)) {
    out.push(primary ? `${primary} ${cue}` : cue);
  }
  const scriptQ = stockQueryFromBeatScript(beat.text, scenePersons, scene.text, videoTitle);
  if (scriptQ) out.push(scriptQ);
  for (const q of [beat.searchQuery, scene.visualCue, scene.pexelsQuery]) {
    const s = toQueryString(q);
    if (s) out.push(s);
  }
  return [...new Set(out.filter((q) => q.length >= 3 && !isBlockedStockQuery(q)))].slice(0, 6);
}

/**
 * Fast still fallback: Serp → Openverse → Wikimedia → YouTube thumb.
 * Used when video search is slow or empty — person, event, or topic image is fine.
 */
async function fetchBeatScriptImageClip(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  scenePersons: string[],
  videoTitle: string | undefined,
  adoptOpts: VisualAdoptOptions,
  tag: string
): Promise<string | null> {
  // RONDE 100B: proof in scope before any provider is asked — see withBeatProvenance.
  return withBeatProvenance(beat, scene, () => fetchBeatScriptImageClipInner(beat, scene, workDir, sceneIndex, clipFetchDur, dedup, scenePersons, videoTitle, adoptOpts, tag), { scenePersons });
}

async function fetchBeatScriptImageClipInner(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  scenePersons: string[],
  videoTitle: string | undefined,
  adoptOpts: VisualAdoptOptions,
  tag: string
): Promise<string | null> {
  const forced = Boolean(adoptOpts.scriptImageFallback);
  if (!forced && !canUseGlobalStillPhoto(dedup)) return null;
  if (!forced) {
    const sceneStillOk =
      dedup.stillPhotosMaxThisScene === 0 ||
      dedup.stillPhotosThisScene < dedup.stillPhotosMaxThisScene;
    if (!sceneStillOk) return null;
  }

  const primary = scenePersons[0] ?? adoptOpts.primaryPerson ?? "";
  const portrait = Boolean(primary) || dedup.personTopicLock;
  const looseOpts: VisualAdoptOptions = {
    ...adoptOpts,
    requireBeatMatch: false,
    scriptAnchored: false,
    scriptImageFallback: true,
    personTopic: portrait,
    primaryPerson: primary || adoptOpts.primaryPerson,
  };
  const queries = buildBeatImageSearchQueries(beat, scene, videoTitle, scenePersons);
  const stillStyleContext: StillStyleContext = {
    beatText: beat.text,
    videoTitle,
    motionGraphicsBudget: {
      used: dedup.motionGraphicsUsed,
      max: maxMotionGraphicsPerVideo(),
    },
  };
  const imageOpts = {
    dedup,
    personPortrait: portrait,
    beatIndex: beat.index,
    stillStyleContext,
  };

  return withSceneFetchTimeout(
    async () => {
      if (SERPAPI_KEY) {
        for (let qi = 0; qi < Math.min(queries.length, 3); qi++) {
          const q = queries[qi];
          const paths = await fetchSerpAPIImages(
            q,
            clipFetchDur,
            workDir,
            sceneIndex,
            1,
            `${tag}_img_serp`,
            {
              ...imageOpts,
              resultOffset: sceneIndex * 3 + beat.index + qi,
            }
          );
          const clip = await adoptClip(
            paths, dedup, sceneIndex, beat.index, beat.text, workDir, q, looseOpts
          );
          if (clip) {
            console.log(
              `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: script image Serp (${q})`
            );
            return clip;
          }
        }
      }
      for (const q of queries.slice(0, 2)) {
        const ovPaths = await fetchOpenverseImages(
          q,
          clipFetchDur,
          workDir,
          sceneIndex,
          1,
          `${tag}_img_ov`,
          imageOpts
        );
        const clip = await adoptClip(
          ovPaths, dedup, sceneIndex, beat.index, beat.text, workDir, q, looseOpts
        );
        if (clip) {
          console.log(
            `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: script image Openverse (${q})`
          );
          return clip;
        }
      }
      if (primary) {
        const wikiPaths = await fetchWikimediaImages(
          primary, clipFetchDur, workDir, sceneIndex, 1, `${tag}_img_wiki`, imageOpts
        );
        const clip = await adoptClip(
          wikiPaths, dedup, sceneIndex, beat.index, beat.text, workDir, primary, looseOpts
        );
        if (clip) {
          console.log(
            `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: script image Wikimedia (${primary})`
          );
          return clip;
        }
      }
      // The YouTube thumbnail tier was removed here — see the note on the fetcher's grave.
      return null;
    },
    beatScriptImageWallMs(dedup.perf),
    `script image s${sceneIndex} b${beat.index}`
  ).catch((err) => {
    console.warn(
      `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: script image skipped:`,
      (err as Error).message
    );
    return null;
  }).finally(() => {
    dedup.motionGraphicsUsed = stillStyleContext.motionGraphicsBudget!.used;
  });
}

/** Last-resort: accept first valid Serp/Wikimedia/YouTube-thumb still (no strict adopt gates). */
async function fetchBeatScriptImageForced(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  scenePersons: string[],
  videoTitle: string | undefined,
  tag: string
): Promise<string | null> {
  // RONDE 100B: proof in scope before any provider is asked — see withBeatProvenance.
  return withBeatProvenance(beat, scene, () => fetchBeatScriptImageForcedInner(beat, scene, workDir, sceneIndex, clipFetchDur, dedup, scenePersons, videoTitle, tag), { scenePersons });
}

async function fetchBeatScriptImageForcedInner(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  scenePersons: string[],
  videoTitle: string | undefined,
  tag: string
): Promise<string | null> {
  const primary = scenePersons[0] ?? dedup.primaryPerson ?? "";
  const portrait = Boolean(primary) || dedup.personTopicLock;
  const queries = buildBeatImageSearchQueries(beat, scene, videoTitle, scenePersons);
  const stillStyleContext: StillStyleContext = {
    beatText: beat.text,
    videoTitle,
    motionGraphicsBudget: {
      used: dedup.motionGraphicsUsed,
      max: maxMotionGraphicsPerVideo(),
    },
  };
  const imageOpts = {
    dedup,
    personPortrait: portrait,
    beatIndex: beat.index,
    stillStyleContext,
  };

  const takeFirstValid = async (paths: string[]): Promise<string | null> =>
    withVisualDedupLock(dedup, async () => {
      for (const p of paths) {
        if (!p || dedup.usedPaths.has(p) || !fs.existsSync(p)) continue;
        if (!(await isValidVideoFile(p))) continue;
        if (isPipelineFallbackClip(p)) continue;
        if (await isMostlyBlackClip(p)) continue;
        dedup.usedPaths.add(p);
        if (isStillPhotoClip(p)) {
          dedup.stillPhotosThisScene++;
          if (canUseGlobalStillPhoto(dedup)) markGlobalStillPhotoUsed(dedup);
        }
        return p;
      }
      return null;
    });

  return withSceneFetchTimeout(
    async () => {
      if (SERPAPI_KEY) {
        for (let qi = 0; qi < Math.min(queries.length, 5); qi++) {
          const q = queries[qi];
          const paths = await fetchSerpAPIImages(
            q,
            clipFetchDur,
            workDir,
            sceneIndex,
            1,
            `${tag}_force_serp`,
            {
              ...imageOpts,
              resultOffset: sceneIndex * 5 + beat.index + qi,
            }
          );
          const clip = await takeFirstValid(paths);
          if (clip) {
            console.log(`[Pipeline] Scene ${sceneIndex} beat ${beat.index}: forced image Serp (${q})`);
            return clip;
          }
        }
      }
      if (primary) {
        const wikiPaths = await fetchWikimediaImages(
          primary, clipFetchDur, workDir, sceneIndex, 1, `${tag}_force_wiki`, imageOpts
        );
        const clip = await takeFirstValid(wikiPaths);
        if (clip) {
          console.log(`[Pipeline] Scene ${sceneIndex} beat ${beat.index}: forced image Wikimedia (${primary})`);
          return clip;
        }
      }
      for (const q of queries.slice(0, 4)) {
        const wikiPaths = await fetchWikimediaImages(
          q, clipFetchDur, workDir, sceneIndex, 1, `${tag}_force_wiki`, imageOpts
        );
        const wikiClip = await takeFirstValid(wikiPaths);
        if (wikiClip) {
          console.log(`[Pipeline] Scene ${sceneIndex} beat ${beat.index}: forced image Wikimedia (${q})`);
          return wikiClip;
        }
        if (UNSPLASH_ACCESS_KEY?.trim()) {
          const unsplashPaths = await fetchUnsplashImages(
            q, clipFetchDur, workDir, sceneIndex, 1, `${tag}_force_unsplash`, { dedup }
          );
          const unsplashClip = await takeFirstValid(unsplashPaths);
          if (unsplashClip) {
            console.log(`[Pipeline] Scene ${sceneIndex} beat ${beat.index}: forced image Unsplash (${q})`);
            return unsplashClip;
          }
        }
      }
      // The YouTube thumbnail tier was removed here — see the note on the fetcher's grave.
      return null;
    },
    beatScriptImageWallMs(dedup.perf) + 5_000,
    `forced image s${sceneIndex} b${beat.index}`
  ).catch(() => null).finally(() => {
    dedup.motionGraphicsUsed = stillStyleContext.motionGraphicsBudget!.used;
  });
}

/** Still-photo clips (Ken Burns from images) — cap these per scene; prefer real stock video. */
function isStillPhotoClip(filePath: string): boolean {
  if (isStockVideoClip(filePath)) return false;
  const base = path.basename(filePath);
  // AI / generated motion clips count as video, not stills
  if (/_ai\.mp4$|_runway_|_kling_|_luma_|_pika_|_veo_|_grok_|_forge_/i.test(base)) return false;
  return /_serp_|_wiki_|_openverse_|_unsplash_|_p0_|_p2_|_yt_\d/i.test(base);
}

/** Standalone motion-graphic beat clip (text/map card) — not B-roll. */
function isMotionGraphicClip(filePath: string): boolean {
  return /_mgfx_/i.test(path.basename(filePath));
}

/** Real stock/archive B-roll video (excludes stills and motion-graphic cards). */
function isRealVideoFootageClip(filePath: string): boolean {
  if (!filePath || isPipelineFallbackClip(filePath)) return false;
  if (isStillPhotoClip(filePath)) return false;
  if (isMotionGraphicClip(filePath)) return false;
  return true;
}

/** Video or Ken Burns still — eligible for per-beat text burned onto the visual (not black/mgfx cards). */
function isVisualOverlayFootageClip(filePath: string): boolean {
  if (!filePath || isPipelineFallbackClip(filePath)) return false;
  if (isMotionGraphicClip(filePath)) return false;
  if (isAIGeneratedClip(filePath) && !isStillPhotoClip(filePath)) return false;
  return (
    isRealVideoFootageClip(filePath) ||
    isStillPhotoClip(filePath) ||
    isCuratedPreparedStillClip(filePath) ||
    isCuratedPreparedVideoClip(filePath)
  );
}

function sceneHasVisualOverlayFootage(clips: string[]): boolean {
  return clips.some((clip) => isVisualOverlayFootageClip(clip));
}


/**
 * DIAGNOSTIC ONLY — a guess at a clip's source from its filename.
 *
 * RONDE 87: this function must never produce an official source attribution. It reads a NAME, and
 * a name says what a file was called, not where its content came from — the two stop agreeing the
 * first time the compose path renames a clip, which it does on every trim, pad, still and overlay.
 * Render 536 shipped 66 clips of which 27 could not be named this way at all.
 *
 * Every official count comes from the lineage ledger (visualSourceLineage.ts). The two remaining
 * callers use this only as a labelled hint alongside the ledger's answer — the compose manifest's
 * `diagnosticNameHint` field and videoQualityReport's `diagnosticBySource` — so that a divergence
 * between the guess and the proof stays VISIBLE instead of being resolved in the guess's favour.
 *
 * If you are adding a caller: you almost certainly want `ledger.providerFor()` or
 * `ledger.providerBucketFor()` instead, and a null answer from those means UNVERIFIED, not
 * "fall back to the filename".
 */
export function inferClipSourceFromPath(filePath: string): string {
  const base = path.basename(filePath).replace(/_transformed(?=\.mp4)$/i, "").toLowerCase();
  // RONDE 64: the provider-asset tag first — it is stamped by tagPathWithProviderAsset and names
  // the provider outright, so it beats every guess below it. Render 532's five source=unknown
  // manifest lines were all clips whose names said what they were.
  const pid = /__pid_([a-z0-9_]+)-[0-9a-f]+/.exec(base);
  if (pid) return pid[1]!;
  const pool = /_pool_([a-z_]+?)_/.exec(base);
  if (pool) return pool[1]!;
  if (/^extend_s\d+b\d+/.test(base)) return "rescue_extend";
  if (/guaranteed/.test(base)) return "guaranteed";
  if (/_ia_archive_|internet_archive/.test(base)) return "internet_archive";
  if (/_ytfu_|_ytcc_|_b\d+_yt_|_yt_\d/i.test(base)) return "youtube";
  if (
    /pexels|_pex_|lr_pex|_b\d+_fast|_fast_vid|_b\d+_script|_script_vid|_golden|_b\d+_lr_pex|scene_\d+_b\d+_vid\d+|person_stock/i.test(
      base
    )
  ) {
    return "pexels";
  }
  if (/serp/i.test(base)) return "serpapi";
  if (/wikivid|_wiki_/i.test(base)) return "wikimedia";
  if (/septube/i.test(base)) return "peertube";
  if (/gdelt/i.test(base)) return "gdelt";
  if (/euro_/i.test(base)) return "europeana";
  if (/vimeo/i.test(base)) return "vimeo";
  if (/openverse/i.test(base)) return "openverse";
  if (/nasa/i.test(base)) return "nasa";
  if (/archive|curated/i.test(base)) return "archive";
  if (/pixabay|_pix_|beat_vid|fb_vid/i.test(base)) return "pixabay";
  if (
    /_ai_fallback|_stability_|_leonardo_|_grok_|_runway_|_kling_|_luma_|_pika_|_veo_|_forge_|scene_\d+_b\d+_ai/i.test(
      base
    )
  ) {
    return "ai";
  }
  if (/_fallback/i.test(base)) return "fallback";
  if (/broll_vid/i.test(base)) return "broll";
  return "unknown";
}

function buildBeatAIPrompt(beat: SceneBeat, scene: Scene, videoTitle?: string): string {
  const muskTopic = isMuskTeslaTopic(videoTitle, beat.text);
  const entities = extractBeatRealEntities(beat.text, scene.text, videoTitle);
  const entityLabel = entities.map((r) => r.id).join(", ");
  const visual =
    beat.powerWord ||
    extractInlineVisualCues(beat.text)[0] ||
    beat.searchQuery ||
    realEntityStockQueriesForBeat(beat.text, scene.text, videoTitle)[0] ||
    deriveBeatStockQuery(beat.text, scene, videoTitle, undefined, muskTopic) ||
    scene.literalVisualCue ||
    scene.visualCue ||
    scene.pexelsQuery;
  const narration = beat.text.replace(/\[visual:[^\]]+\]/gi, "").trim().slice(0, 220);
  return (
    `Cinematic documentary still, photorealistic 16:9, subject: ${visual}. ` +
    `Matches this spoken line: ${narration}. ` +
    `Real-world ${entityLabel || "news"} context, sharp focus, natural lighting, no text or watermark.`
  ).slice(0, 500);
}

/** Kling text-to-video prompt — moving B-roll (not a still); geo + narration from the beat. */
function buildKlingBeatPrompt(beat: SceneBeat, scene: Scene, videoTitle?: string): string {
  const muskTopic = isMuskTeslaTopic(videoTitle, beat.text);
  const entities = extractBeatRealEntities(beat.text, scene.text, videoTitle);
  const entityLabel = entities.map((r) => r.id).join(", ");
  const titleGeo = extractTitleGeoPlaceTags(videoTitle).slice(0, 2).join(", ");
  const beatGeo = buildGeoStockSearchQueries(beat.text, videoTitle).slice(0, 2).join(", ");
  const geoHint = titleGeo || beatGeo;
  const visual =
    beat.powerWord ||
    extractInlineVisualCues(beat.text)[0] ||
    beat.searchQuery ||
    realEntityStockQueriesForBeat(beat.text, scene.text, videoTitle)[0] ||
    deriveBeatStockQuery(beat.text, scene, videoTitle, undefined, muskTopic) ||
    scene.literalVisualCue ||
    scene.visualCue ||
    scene.pexelsQuery;
  const narration = beat.text.replace(/\[visual:[^\]]+\]/gi, "").trim().slice(0, 220);
  return (
    `Cinematic documentary B-roll video footage, photorealistic 16:9, smooth slow camera motion. ` +
    `${geoHint ? `Location: ${geoHint}. ` : ""}` +
    `Subject: ${visual}. ` +
    `Matches spoken narration: ${narration}. ` +
    `Real-world ${entityLabel || "documentary"} context, natural lighting, no on-screen text, no watermark.`
  ).slice(0, 500);
}

/** AI clip only when stock could not match this beat (prompt = narration + visual cue). */
async function fetchBeatAIClip(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  beatIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  videoTitle?: string,
  opts?: { rescueTier?: boolean }
): Promise<string | null> {
  const { perf } = dedup;
  const rescueTier = Boolean(opts?.rescueTier);
  if (rescueTier) {
    if (
      !beatVisualRescueEnabled() ||
      dedup.rescueAiClipsUsed >= beatVisualRescueAiMaxClips(dedup.videoLength)
    ) {
      return null;
    }
  } else if (!perf.enableAiFallback || dedup.aiClipsUsed >= perf.maxAiClipsPerVideo) {
    return null;
  }
  if (!aiProvidersReady()) return null;

  const prompt = buildBeatAIPrompt(beat, scene, videoTitle);
  const outPath = path.join(workDir, `scene_${sceneIndex}_b${beatIndex}_ai_fallback.mp4`);
  const dur = Math.min(Math.max(clipFetchDur, 3), perf.fastStockMode ? 5 : 8);

  let generated: string | null = null;
  // Cheap tier: photoreal still → Ken Burns (~$0.03/beat, broadcast look)
  if (stabilityAiApiKey()) {
    generated = await generateStabilityAIClip(prompt, dur, outPath, sceneIndex);
  }
  if (!generated && leonardoApiKey()) {
    generated = await generateLeonardoAIClip(prompt, dur, outPath, sceneIndex);
  }
  // RONDE 138: last of the cheap tier, and the only one most deployments have a key for.
  if (!generated && openAiImageFallbackEnabled()) {
    generated = await generateOpenAiImageClip(prompt, dur, outPath, sceneIndex);
  }
  // Premium tier only (Runway/Grok ~$0.25+ per clip) — ENABLE_AI_VIDEO_FALLBACK=true
  if (!generated && premiumAiVideoFallbackEnabled()) {
    if (replicateApiKey()) {
      generated = await generateGrokVideoClip(prompt, dur, outPath, sceneIndex);
    }
    if (!generated && GOOGLE_GEMINI_API_KEY) {
      generated = await generateVeoVideoClip(prompt, dur, outPath, sceneIndex);
    }
    if (!generated && runwayApiKey()) {
      generated = await generateRunwayClip(prompt, null, dur, outPath, sceneIndex);
    }
  }
  if (!generated || !(await isValidVideoFile(generated)) || (await isMostlyBlackClip(generated))) {
    return null;
  }

  return withVisualDedupLock(dedup, async () => {
    const contentKey = clipContentKey(generated!);
    if (dedup.usedContentKeys.has(contentKey)) return null;
    dedup.usedPaths.add(generated!);
    dedup.usedContentKeys.add(contentKey);
    if (rescueTier) {
      dedup.rescueAiClipsUsed++;
      console.log(
        `[Pipeline] Scene ${sceneIndex} beat ${beatIndex}: rescue AI ${dedup.rescueAiClipsUsed}/${beatVisualRescueAiMaxClips(dedup.videoLength)} — "${prompt.slice(0, 90)}..."`
      );
    } else {
      dedup.aiClipsUsed++;
      console.log(
        `[Pipeline] Scene ${sceneIndex} beat ${beatIndex}: AI fallback ${dedup.aiClipsUsed}/${perf.maxAiClipsPerVideo} — "${prompt.slice(0, 90)}..."`
      );
    }
    return generated;
  });
}

function extractInlineVisualCues(text: string): string[] {
  return [...text.matchAll(/\[visual:\s*([^\]]+)\]/gi)]
    .map((m) => m[1].trim())
    .filter((v) => v.length > 3 && !isBlockedStockQuery(v));
}

function scoreBeatNarrationMatch(beatText: string, sourceQuery: string, filePath: string): number {
  const tokens = tokenizeForRelevance(beatText).filter((t) => t.length >= 3);
  const hay = `${sourceQuery} ${path.basename(filePath)}`.toLowerCase();
  return scoreVisualRelevance(hay, tokens);
}

/** Map one script token → English Pexels keyword (no scene/title context). */
function translateTokenForPexels(token: string): string | null {
  const t = token.toLowerCase();
  if (RELEVANCE_STOP_WORDS.has(t) || t.length < 3) return null;
  if (DUTCH_STOCK_WORD_MAP[t]) return DUTCH_STOCK_WORD_MAP[t];
  for (const [re, word] of STOCK_TOPIC_WORD_RULES) {
    if (re.test(`\\b${t}\\b`) || re.test(t)) return word;
  }
  return t;
}

/**
 * Stock search terms from beat narration: persons → events → entities.
 * Skips generic wildlife/animal tokens when a named person is in scope.
 */
const STOP_WORDS = new Set([
  "a","an","the","is","are","was","were","be","been","being","have","has","had","do","does","did",
  "will","would","could","should","may","might","shall","can","need","to","of","in","on","at","by",
  "for","with","about","into","through","during","before","after","above","below","between","out",
  "up","down","from","and","or","but","nor","as","if","when","where","while","that","this","these",
  "those","he","she","it","they","we","you","i","his","her","its","their","our","your","my","who",
  "which","what","not","no","so","then","than","also","just","only","even","still","more","most",
  "very","much","many","some","any","all","both","each","few","more","such","own","same","than",
  "too","very","s","t","can","will","just","don","should","now","de","het","een","van","op","en",
  "maar","ook","wordt","werd","heeft","had","zijn","was","er","naar","met","door","over","als","dat",
  "om","uit","aan","bij","te","in","nog","zo","al","want","dan","maar","wel","geen","toch","niet",
  /**
   * RONDE 100B — intensifiers and discourse adverbs, the same class this list already holds.
   *
   * "But here's what truly followed the aftermath" sent the single word "truly" to Pexels as a
   * search subject. It got there through extractBeatSubject's positional fallback, which takes
   * the first words of four letters or more that are not stop words — and "truly" was not on the
   * list, while "very", "just", "only", "even", "still", "also" and "too" already were.
   *
   * The SearchGate cannot catch this one and should not try: the word really is in the beat, so
   * it is properly proven. What it is not is a subject. Nothing named here can appear in a shot,
   * which is exactly the property the words above it share — this extends a closed grammatical
   * class rather than starting an open blocklist of things we happen to dislike.
   */
  "truly","really","actually","simply","literally","basically","essentially","certainly",
  "definitely","probably","perhaps","maybe","however","therefore","meanwhile","instead",
  "suddenly","eventually","ultimately","apparently","obviously","clearly","indeed","rather",
  "echt","werkelijk","eigenlijk","gewoon","natuurlijk","misschien","daarom","ondertussen",
]);

/**
 * RONDE 71 — words that describe an action, a quantity or a moment, not a thing to photograph.
 *
 * STOP_WORDS already removes grammar. What it does not remove is narration verbs and time and
 * quantity filler, and those were reaching the providers because they happened to be long
 * enough and to sit early in the sentence. Deliberately a list of what cannot be photographed:
 * "soldiers", "banner", "airfield", "birthday", "construction" are all concrete and stay.
 */
/**
 * RONDE 77 splits the RONDE 71 vocabulary into named groups. The union below is byte-for-byte the
 * same set the subject extractor already used, so nothing about query subjects changes — but the
 * verb group is now separately addressable. extractActionCue needs exactly the words this set
 * exists to keep OUT of a subject: a verb is wrong as the thing to photograph and right as the
 * thing being done.
 */
const NARRATION_VERB_WORDS = new Set([
  // narration verbs
  "spent","come","came","received","dictated","showed","shown","ended","raised","reached",
  "remained","controlled","described","address","addresses","addressed","married","retreat",
  "retreats","retreated","closing","closed","defending","defended","fighting","fought",
  "scramble","scrambled","gave","given","took","taken","made","went","gone","said","told",
  "began","begun","started","stopped","entered","left","arrived","moved","held","kept",
  "brought","found","felt","knew","thought","become","became","refused","wished","lay",
  "laid","stood","sat","turned","looked","asked","called","used","wrote","written","spoke",
  "spoken","carried","fell","fallen","rose","risen","kill","killed","died","dies","dying",
  "visited","marching","walked","ran","running","meets","meet","met",
]);

const NARRATION_PRONOUN_WORDS = new Set([
  // pronouns and reflexives STOP_WORDS does not carry
  "them","him","himself","herself","itself","themselves","whom","whose","hers","theirs",
]);

const TIME_QUANTITY_WORDS = new Set([
  // time, order and quantity filler
  "final","finally","first","last","latest","next","later","earlier","early","late","then",
  "point","moment","week","weeks","month","months","day","days","hour","hours","minute",
  "minutes","night","morning","evening","today","yesterday","tomorrow","twentieth","eighth",
  "thirtieth","half","constant","constantly","longer","already","almost","nearly","again",
  "once","twice","ever","never","always","often","soon","yet","shortly","meanwhile","inside",
  "outside","under","above","beneath","below","beyond","toward","towards","across","against",
  "little","more","less","several","enough",
]);

const ABSTRACTION_WORDS = new Set([
  // abstractions with nothing to show
  "impact","importance","significance","effect","effects","result","results","reason",
  "reasons","cause","causes","sense","idea","ideas","thing","things","kind","sort","way",
  "ways","part","parts","fact","facts","case","cases","level","state","states","situation",
  "psychological","emotional","mental",
]);

const NUMERAL_UNIT_WORDS = new Set([
  // spelled-out numerals and bare units — "the bunker lay eight and a half metres below" is a
  // measurement, and "bunker eight metres" is not an image anyone can look for.
  "three","four","five","seven","eight","nine","eleven","twelve","dozen","hundred","thousand",
  "million","billion","metre","metres","meter","meters","foot","feet","mile","miles","yard",
  "yards","kilometre","kilometres","kilometer","kilometers","percent","dozens","hundreds",
  "thousands","millions",
]);

const NON_VISUAL_QUERY_WORDS = new Set([
  ...NARRATION_VERB_WORDS,
  ...NARRATION_PRONOUN_WORDS,
  ...TIME_QUANTITY_WORDS,
  ...ABSTRACTION_WORDS,
  ...NUMERAL_UNIT_WORDS,
]);

/**
 * Everything NON_VISUAL_QUERY_WORDS keeps out of a query subject EXCEPT the verbs.
 *
 * The distinction the split exists for: "raised" is a bad thing to photograph and a good thing to
 * say something is doing. extractActionCue excludes this set, not the union — excluding the union
 * rejected every verb the union was built to collect, which is how "raised" came back empty.
 * "later", "them" and "metres" stay excluded, because they are not actions either.
 */
const NON_ACTION_QUERY_WORDS = new Set([
  ...NARRATION_PRONOUN_WORDS,
  ...TIME_QUANTITY_WORDS,
  ...ABSTRACTION_WORDS,
  ...NUMERAL_UNIT_WORDS,
]);

/**
 * Month names. Capitalised in narration and period markers in their own right, but three of them
 * collide with ordinary words STOP_WORDS carries — "may" the modal, "march" the verb, "august"
 * the adjective — so "on the eighth of May" lost its month entirely. A capitalised month is a
 * month.
 */
const MONTH_NAMES = new Set([
  "january","february","march","april","may","june",
  "july","august","september","october","november","december",
]);

/** Common sentence openers that are capitalised only because they start the sentence. */
const SENTENCE_OPENER_WORDS = new Set([
  "the","a","an","it","he","she","they","we","in","on","at","by","for","with","from","after",
  "before","above","below","during","when","while","that","this","these","those","there","then",
  "but","and","or","as","if","so","by","life","most","many","some","every","each","one","two",
]);

/**
 * Extract the visual subject from a beat sentence.
 *
 * RONDE 71 — chosen by meaning, not by position.
 *
 * This used to take "the first three unique words of four letters or more that are not stop
 * words". Whether that produced a usable query depended entirely on where the concrete nouns
 * happened to sit in the sentence. Measured on real documentary narration:
 *
 *     "Berlin was under constant bombardment in the last week of April 1945."
 *                                                    -> berlin under constant
 *     "It was his final birthday, the twentieth of April 1945."
 *                                                    -> final birthday twentieth
 *     "Hitler received military reports that described armies which no longer existed."
 *                                                    -> hitler received military
 *
 * while sentences that happen to open with their subject came out fine. Documentary narration
 * does both constantly, so the extractor was not broken but unreliable — which for a production
 * render is the same problem.
 *
 * The order of preference is the brief's: concrete entities first, then everything else.
 *
 *   1. proper nouns — capitalisation is what separates Führerbunker, Reichstag, Dunkirk,
 *      Spitfire and the Blitz from spent, under, constant and twentieth. A word capitalised
 *      mid-sentence is a name; a capitalised sentence opener is only a name when it is not one
 *      of the ordinary words a sentence can start with.
 *   2. concrete common nouns — soldiers, bunker, banner, airfield, construction.
 *   3. an explicit year, but only one this beat itself states (see RONDE 71 fix 2).
 *
 * Nothing that describes an action, a quantity or a moment is eligible at all.
 *
 * No new LLM call, no new API, no new dependency: two word sets and the capitalisation the
 * script already carries.
 */
function beatSubjectCandidates(clean: string): { proper: string[]; common: string[]; year: string } {
  const proper: string[] = [];
  const common: string[] = [];
  const seen = new Set<string>();
  // Sentence-initial position is per sentence, not per beat: a beat can hold several.
  for (const sentence of clean.split(/(?<=[.!?])\s+/)) {
    const tokens = sentence.split(/\s+/).filter(Boolean);
    tokens.forEach((raw, i) => {
      const word = raw.replace(/[^\p{L}\p{N}'-]/gu, "");
      if (word.length < 3) return;
      const lower = word.toLowerCase();
      if (seen.has(lower)) return;
      const capitalisedMonth = word[0] !== word[0]!.toLowerCase() && MONTH_NAMES.has(lower);
      if (!capitalisedMonth && (STOP_WORDS.has(lower) || NON_VISUAL_QUERY_WORDS.has(lower))) return;
      // A pure number is a year or a count; years are handled separately, counts are not visual.
      if (/^\d+$/.test(word)) return;
      const capitalised = word[0] !== word[0]!.toLowerCase();
      const isProperNoun = capitalised && (i > 0 || !SENTENCE_OPENER_WORDS.has(lower));
      // Three letters is enough for a name — May, RAF, Ford — but not for a common noun, where
      // it is almost always grammar the stop list has not happened to catch.
      if (word.length < 4 && !isProperNoun) return;
      seen.add(lower);
      (isProperNoun ? proper : common).push(lower);
    });
  }
  // Only a year the beat itself states — never one inherited from the video title.
  const year = clean.match(/\b(1[5-9]\d{2}|20\d{2})\b/)?.[0] ?? "";
  return { proper, common, year };
}

function extractBeatSubject(beatText: string, persons: string[] = []): string {
  const clean = beatText.replace(/\[visual:[^\]]*\]/gi, " ").trim();
  const { proper, common, year } = beatSubjectCandidates(clean);

  // If a person is named, they anchor the query and the best remaining ENTITY joins them —
  // previously this was "the first non-stop word", which is how "Eva Braun come" happened.
  if (persons.length > 0) {
    const person = persons[0]!;
    const personWords = new Set(person.toLowerCase().split(/\W+/).filter(Boolean));
    const notPerson = (w: string) => !personWords.has(w);
    const extra = proper.find(notPerson) ?? common.find(notPerson) ?? "";
    return extra ? `${person} ${extra}` : person;
  }

  // Entities first, then concrete nouns, then the beat's own year if it stated one.
  const ranked = [...proper, ...common].slice(0, 3);
  if (ranked.length === 0) {
    /**
     * RONDE 103 (phase 10) — nothing concrete survived, so this beat has no subject.
     *
     * What stood here was the positional heuristic RONDE 71 replaced, kept as a fallback: the
     * first three words of four letters or more that are not stop words, and failing that the
     * first two words of the sentence. RONDE 71 measured what that produces — "berlin under
     * constant", "final birthday twentieth", "hitler received military" — and the fact that it
     * only runs when the good extractor found nothing does not make it better. It makes it worse:
     * a beat whose every concrete word was filtered out is exactly the beat whose leftovers are
     * grammar.
     *
     * Returning "" is the honest answer, and it is not the end of the line. Both callers already
     * treat an empty subject as "ask the scene, then the title, then ask nothing" — a cascade
     * that goes to real text rather than to the first two words of this sentence. This is the
     * same reasoning that removed "documentary" in RONDE 100B, applied one level further in.
     *
     * Deliberately NOT another stop word: the failure was never a missing entry in a list. It was
     * a rule that picks by position instead of by meaning, and the fix is to stop picking.
     */
    return "";
  }
  // The year rides along only when there is room and it is not already in the words.
  if (year && ranked.length < 3) ranked.push(year);
  return ranked.join(" ");
}

export function scriptStockSearchQueries(
  beatText: string,
  persons: string[] = [],
  sceneText = "",
  videoTitle?: string
): string[] {
  const subject = extractBeatSubject(beatText, persons);
  if (subject && subject.length >= 2) {
    const queries: string[] = [subject];
    // Add a person-only fallback if person is present
    if (persons.length > 0) {
      queries.push(persons[0]);
    }
    return [...new Set(queries.filter(q => q.length >= 2 && !isBlockedStockQuery(q)))].slice(0, 3);
  }

  // P0/P1 image-quality patch — Fix 3: extractBeatSubject failed (beatText itself carried no
  // usable words). Before collapsing to the maximally generic "documentary", reuse context this
  // function already received but previously ignored (sceneText, videoTitle) via the same
  // deterministic subject-extraction/stop-word machinery above — no new LLM call, existing
  // helpers only.
  if (persons.length > 0) return [persons[0]];
  const sceneSubject = sceneText ? extractBeatSubject(sceneText, persons) : "";
  if (sceneSubject && sceneSubject.length >= 2) return [sceneSubject];
  const titleWords = (videoTitle ?? "")
    .split(/\W+/)
    .filter((w) => w.length >= 4 && !STOP_WORDS.has(w.toLowerCase()));
  if (titleWords.length > 0) return [titleWords.slice(0, 3).join(" ")];
  /**
   * RONDE 100B — nothing left, so ask for nothing.
   *
   * This used to return ["documentary"]. No beat text, no scene text, no title and no person
   * means there is no subject; "documentary" is not that subject, it is a word describing the
   * genre of the video being made. Production sent it to Pexels dozens of times in one render
   * and it is exactly the kind of plausible-looking invention this whole line of work exists to
   * stop: a query that cannot be wrong because it is not about anything.
   *
   * An empty list is the honest answer. Every consumer already drops empty/short queries
   * (filterQueryStrings, buildBeatVisualQueryList's length filter, and the gate's EMPTY_QUERY
   * check), so this asks one fewer provider rather than asking for the wrong thing.
   */
  return [];
}

function isGenericNatureStockWord(word: string): boolean {
  return PERSON_OFFTOPIC_VISUAL_RE.test(word) ||
    /^(wildlife|ocean|bird|forest|zoo|animal|fish|beach|sunset|nature|flower|garden)$/i.test(word.trim());
}

function stockQueryFromBeatScript(
  beatText: string,
  persons: string[] = [],
  sceneText = "",
  videoTitle?: string
): string {
  // RONDE 100B: "" when the script proves no subject — see scriptStockSearchQueries.
  return scriptStockSearchQueries(beatText, persons, sceneText, videoTitle)[0] ?? "";
}

/** Licensed Pexels/Pixabay/b-roll — not authentic archival footage. */
function isLicensedStockClip(filePath: string): boolean {
  const base = path.basename(filePath).toLowerCase();
  return /pexels|_pex_|pixabay|_pix_|broll_vid|_golden|_fast_vid|_lr_pex|scene_\d+_b\d+_vid\d+/i.test(
    base
  );
}

/** Real downloaded video that is not a Ken Burns still or licensed stock clip. */
function isAuthenticVideoClip(filePath: string): boolean {
  return isRealVideoClip(filePath) && !isLicensedStockClip(filePath);
}

function maxStillPhotosGlobal(dedup: VisualDedupState): number {
  if (curatedArchiveOnlyVisuals()) {
    return archiveMaxImageClipsPerVideo(dedup.videoLength);
  }
  if (dedup.perf.fastStockMode) return 16;
  if (dedup.personTopicLock) return Math.max(10, dedup.perf.maxBeatsPerScene * 3);
  if (minimizeStockFootageEnabled()) return 6;
  return 4;
}

function canUseGlobalStillPhoto(dedup: VisualDedupState): boolean {
  return dedup.stillPhotosUsedGlobal < maxStillPhotosGlobal(dedup);
}

function markGlobalStillPhotoUsed(dedup: VisualDedupState): void {
  dedup.stillPhotosUsedGlobal++;
}

function maxStillPhotosForScene(_sceneIndex: number, hasPerson: boolean, personTopicLock = false): number {
  if (personTopicLock) return 4;
  if (minimizeStockFootageEnabled()) return hasPerson ? 3 : 2;
  return hasPerson ? 3 : 2;
}

function beatMentionsPerson(beatText: string, personName: string): boolean {
  const name = coercePersonName(personName);
  if (!name) return false;
  const lower = beatText.toLowerCase();
  const parts = name.toLowerCase().split(/\s+/).filter((p) => p.length >= 2);
  if (parts.length >= 2) {
    if (parts.every((p) => lower.includes(p))) return true;
    // Phase 12: narration commonly refers to a person by surname only after first introducing
    // them ("Jenner announced...", not "Kylie Jenner announced..."). Was checking parts[0]
    // (first name), missing this common phrasing — matches the already-correct sibling
    // textMentionsPersonName (line 8660), which falls back to the last name.
    return lower.includes(parts[parts.length - 1]);
  }
  return parts.length === 1 && lower.includes(parts[0]);
}

const PERSON_NAME_SKIP_PHRASES = new Set([
  "deep dive", "breaking news", "the truth", "red carpet", "social media", "united states",
  "new york", "los angeles", "full story", "no comment", "under the", "life under",
  "decoding the", "rumors about", "facts fiction", "exclusive interview",
]);

/**
 * RONDE 72 — a capitalised run is not a person just because it is capitalised.
 *
 * extractPersonNamesFromText matched /[A-Z][a-z]+(\s+[A-Z][a-z]+)+/ and called every hit a
 * person. Measured on the real function:
 *
 *     "The construction of the Eiffel Tower."       -> ["Eiffel Tower"]
 *     "British Spitfire fighters scramble…"         -> ["British Spitfire"]
 *
 * A building and an aircraft, handed to the primaryPerson lock, to resolveScenePersons and to
 * the query builders as literal names — and, since RONDE 71's ranking work, worth +12 in
 * entityMatchTierScore when a candidate's provider text happens to echo them.
 *
 * These are the head nouns that make a capitalised run a THING. A run containing any of them is
 * never a person. Deliberately head nouns rather than full phrases: enumerating "Eiffel Tower",
 * "Brandenburg Gate" and "Reich Chancellery" one by one never ends, while "tower", "gate" and
 * "chancellery" cover the class.
 */
/**
 * RONDE 73 splits the RONDE 72 vocabulary into named groups. The union below is byte-for-byte
 * the same set the person classifier already used, so nothing about that changes — but the
 * structure group is now separately addressable, because "a capitalised run ending in a BUILDING
 * noun is a place" is true while "a run ending in an ORGANISATION noun is a place" is not: it
 * would read "The Red Army" as a location.
 */
const PLACE_STRUCTURE_WORDS = new Set([
  "tower","bridge","palace","castle","cathedral","chancellery","reichstag","bunker","museum",
  "station","hall","gate","wall","monument","memorial","square","stadium","airport","airfield",
  "harbour","harbor","factory","plant","works","abbey","church","temple","mosque","prison",
  "camp","fortress","citadel","barracks","headquarters","embassy","parliament","capitol",
  "university","college","school","hospital","library","theatre","theater","hotel","tunnel",
  "canal","dam","port","dock","quay","pier","observatory","lighthouse","garden","park",
]);

const VEHICLE_WORDS = new Set([
  "spitfire","hurricane","messerschmitt","panzer","tiger","sherman","lancaster","mustang",
  "junkers","heinkel","stuka","zeppelin","bomber","fighter","fighters","tank","tanks","ship",
  "boat","submarine","u-boat","carrier","cruiser","destroyer","battleship","frigate","convoy",
  "train","locomotive","aircraft","plane","jet","rocket","missile","truck","lorry","jeep",
]);

const ORGANISATION_WORDS = new Set([
  "army","navy","luftwaffe","wehrmacht","waffen","gestapo","corps","division","regiment",
  "brigade","battalion","infantry","artillery","cavalry","guard","forces","troops","command",
  "reich","empire","republic","union","federation","party","ministry","council","committee",
  "bureau","agency","department","commission","authority","alliance","coalition","front",
  "offensive","campaign","operation","battle","siege","invasion","uprising","revolution",
]);

const GENERIC_GEOGRAPHY_WORDS = new Set([
  "city","town","village","river","mountain","mountains","island","islands","sea","ocean",
  "lake","valley","desert","forest","coast","bay","gulf","strait","street","avenue","road",
  "district","province","county","state","kingdom","territory","region","border","frontier",
  // directional modifiers: they only ever qualify a place ("Eastern Poland", "Lower Saxony")
  "eastern","western","northern","southern","central","upper","lower","greater","outer","inner",
]);

const NON_PERSON_ENTITY_WORDS = new Set([
  ...PLACE_STRUCTURE_WORDS,
  ...VEHICLE_WORDS,
  ...ORGANISATION_WORDS,
  ...GENERIC_GEOGRAPHY_WORDS,
]);

/**
 * Verbs only a person performs. Evidence that a BARE capitalised token — "Churchill", "Hitler" —
 * is a name rather than a place, which the two-token requirement could never see.
 *
 * Deliberately excludes copulas and auxiliaries. "Berlin was under bombardment" and "Dunkirk had
 * fallen" must stay places, and "was"/"had" are true of everything.
 */
const PERSON_ACTION_VERBS = new Set([
  "said","says","told","tells","wrote","writes","spoke","speaks","addressed","addresses",
  "announced","announces","declared","declares","ordered","orders","commanded","commands",
  "dictated","dictates","promised","promises","warned","warns","replied","replies","asked",
  "asks","argued","argues","insisted","insists","admitted","admits","confessed","denied",
  "believed","believes","decided","decides","refused","refuses","agreed","agrees","hoped",
  "feared","knew","knows","thought","thinks","wanted","wants","planned","plans","intended",
  "married","marries","divorced","died","dies","killed","kills","survived","survives","fled",
  "flees","escaped","escapes","retreated","retreats","returned","returns","arrived","arrives",
  "entered","enters","left","leaves","remained","remains","stayed","stays","travelled",
  "traveled","visited","visits","met","meets","greeted","led","leads","ruled","rules",
  "governed","governs","resigned","resigns","appointed","appoints","dismissed","signed",
  "signs","gave","gives","took","takes","received","receives","sent","sends","summoned",
  "celebrated","celebrates","watched","watches","listened","waited","waits","walked","walks",
  "sat","stood","turned","looked","looks","smiled","laughed","wept","shouted","whispered",
  // RONDE 88 — the verbs a HISTORICAL documentary actually uses about its subject.
  //
  // Measured gap: "Hitler invaded Poland in 1939" produced PERSON=[] and the query "Poland
  // invaded", because "invaded" was nowhere on this list. The list already is the pipeline's
  // person-evidence vocabulary; these are the same kind of word, for the genre this product is
  // built for. Every one takes a human subject.
  "invaded","invades","conquered","conquers","attacked","attacks","defeated","defeats",
  "surrendered","surrenders","captured","captures","liberated","liberates","occupied","occupies",
  "bombed","bombs","besieged","launched","launches","seized","seizes","annexed","annexes",
  "crossed","crosses","marched","marches","advanced","advances","withdrew","withdraws",
  "negotiated","negotiates","betrayed","betrays","purged","purges","executed","executes",
  "founded","founds","built","builds","discovered","discovers","published","publishes",
  "studied","studies","researched","taught","teaches","painted","paints","composed","composes",
]);

/**
 * RONDE 88 — is this token a verb the pipeline already recognises?
 *
 * Used only to judge Title Case text, where capitalisation proves nothing about any word. Reads
 * the existing PERSON_ACTION_VERBS vocabulary rather than introducing a second list, and also
 * accepts the regular past-tense morphology that vocabulary is built from, so a title verb nobody
 * listed ("Frobnicated") is still refused as a name token.
 */
function isKnownPersonActionVerb(token: string): boolean {
  const t = token.trim().toLowerCase();
  if (!t) return false;
  if (PERSON_ACTION_VERBS.has(t)) return true;
  return t.length >= 6 && t.endsWith("ed");
}

/** Lower-cased place vocabulary the pipeline already carries, for O(1) lookup. */
const GEO_SLUG_SET = new Set(ALL_GEO_SLUGS.map((s) => s.toLowerCase()));

function normaliseNameToken(token: string): string {
  return token.toLowerCase().replace(/[^\p{L}\p{N}'-]/gu, "");
}

/** A head noun that names a thing. Decisive on its own: "Eiffel Tower" is not a person. */
function isThingToken(token: string): boolean {
  return NON_PERSON_ENTITY_WORDS.has(normaliseNameToken(token));
}

/**
 * A token that appears in the place vocabulary. NOT decisive on its own inside a full name:
 * "washington" and "lincoln" are both places and surnames, so "George Washington" must survive.
 * A run is a place only when EVERY token is one; a lone token is treated as a place by default.
 */
function isPlaceToken(token: string): boolean {
  return GEO_SLUG_SET.has(normaliseNameToken(token));
}

/** A single capitalised token that names a thing or a place, never a person on its own. */
function isNonPersonToken(token: string): boolean {
  return isThingToken(token) || isPlaceToken(token);
}

/**
 * Does this sentence give evidence that `token` is a person?
 *
 * Two signals, both from text the beat already carries: the token performs an action only a
 * person performs, or it holds a possessive ("Hitler's testament"). Nothing else — a bare
 * capitalised word with no such evidence stays what it was, a candidate the pipeline does not
 * claim to have identified.
 */
function sentenceSupportsPerson(sentence: string, token: string, depth = 0): boolean {
  if (depth > 4) return false;
  const escaped = token.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  if (new RegExp(`\\b${escaped}'s\\b`, "i").test(sentence)) return true;
  const after = new RegExp(`\\b${escaped}\\b[\\s,]+([a-z]+)`, "i").exec(sentence);
  if (after?.[1] && PERSON_ACTION_VERBS.has(after[1].toLowerCase())) return true;
  /**
   * RONDE 88 (§2) — coordination carries the evidence across.
   *
   * Measured: "Churchill and Roosevelt met at Casablanca" kept only Roosevelt. The verb "met"
   * sits behind the SECOND name, so the first one had nothing directly after it but "and" and
   * was dropped — and the beat then searched for one of the two men it names.
   *
   * This is grammar, not a guess: "X and Y <person-verb>" makes X and Y the same kind of thing,
   * and the evidence for one is the evidence for both. Only a coordinating conjunction counts,
   * and the partner must itself be capitalised and pass the same verb test.
   *
   * RONDE 90 (§5) — a comma coordinates a list exactly as "and" coordinates a pair.
   *
   * Measured: "Churchill, Roosevelt and Stalin met at Yalta" kept Roosevelt and Stalin and lost
   * Churchill, because the only thing behind Churchill was a comma. §5 is absolute that no name a
   * beat states may be dropped, and "A, B and C <verb>" is one list — the last member carries the
   * verb for all of them. The recursion walks forward along the list only, so it terminates; the
   * depth cap is belt-and-braces against a pathological sentence.
   */
  const coordinated = new RegExp(
    `\\b${escaped}\\b\\s*(?:,\\s*|,?\\s*(?:and|&)\\s+)(\\p{Lu}[\\p{Ll}'’-]+)`, "u"
  ).exec(sentence);
  if (coordinated?.[1]) return sentenceSupportsPerson(sentence, coordinated[1], depth + 1);
  const coordinatedBefore = new RegExp(`(\\p{Lu}[\\p{Ll}'’-]+)\\s*,?\\s*(?:and|&)\\s+${escaped}\\b`, "u").exec(sentence);
  if (coordinatedBefore?.[1]) {
    const partner = coordinatedBefore[1]!;
    const partnerAfter = new RegExp(`\\b${partner}\\b[\\s,]+([a-z]+)`, "i").exec(sentence);
    if (partnerAfter?.[1] && PERSON_ACTION_VERBS.has(partnerAfter[1].toLowerCase())) return true;
  }
  return false;
}

/**
 * RONDE 73 — the place a beat is actually about, for the QUERY PATH ONLY.
 *
 * mediaResearchEngine.extractLocationPhrase already answers this question, and it answers it
 * wrongly for documentary narration. Measured on the real function:
 *
 *     "…in the Führerbunker in April 1945."          -> "April"
 *     "…over the Reichstag in April 1945."           -> "April"
 *     "The Brandenburg Gate stood in ruins…"         -> null
 *     "Churchill … after the fall of France."        -> null
 *
 * Three causes: the regex requires a capital immediately after the preposition, so "in the
 * Führerbunker" cannot match while "in April" can; "of" is not in its preposition list; and it
 * takes the first match rather than the best one.
 *
 * It is NOT fixed in place. It feeds classifyBeatFocus, and a beat whose focus flips from
 * "location" to something else changes beatFocusPenalty — an indirect ranking change this round
 * explicitly excludes. So this is a separate function, called only from the query path, and
 * extractLocationPhrase keeps returning exactly what it returned before.
 *
 * No new vocabulary: MONTH_NAMES (RONDE 71), PLACE_STRUCTURE_WORDS (RONDE 72's structures group)
 * and the pipeline's existing GEO_SLUG_SET do all the work.
 */
/**
 * Both cases spelled out on purpose: the pattern below must NOT carry the `i` flag, because that
 * would fold \p{Lu} and make every lower-case word match the capitalised-run pattern.
 */
const PLACE_PREPOSITIONS =
  "[Ii]n|[Aa]t|[Nn]ear|[Oo]ver|[Aa]cross|[Tt]hrough|[Ii]nside|[Oo]utside|[Aa]round|" +
  "[Ww]ithin|[Bb]eneath|[Bb]elow|[Aa]bove|[Oo]f|[Ff]rom|[Ii]nto|[Oo]nto|[Tt]oward|[Tt]owards";

/** A capitalised run of 1–3 words, e.g. "Führerbunker", "Brandenburg Gate", "Reich Chancellery". */
const CAPITALISED_RUN_SOURCE = "\\p{Lu}[\\p{L}'-]+(?:\\s+\\p{Lu}[\\p{L}'-]+){0,2}";

/** "The Brandenburg Gate" -> "Brandenburg Gate". Narration capitalises its articles at a full stop. */
function stripLeadingArticle(phrase: string): string {
  return phrase.replace(/^(?:the|a|an)\s+/i, "").trim();
}

function isMonthPhrase(phrase: string): boolean {
  const first = phrase.trim().split(/\s+/)[0]?.toLowerCase() ?? "";
  return MONTH_NAMES.has(first);
}

/** True when the phrase's LAST word names a building or site — "Brandenburg Gate", "Reichstag". */
function endsInPlaceStructure(phrase: string): boolean {
  const last = phrase.trim().split(/\s+/).pop()?.toLowerCase().replace(/[^\p{L}\p{N}'-]/gu, "") ?? "";
  return PLACE_STRUCTURE_WORDS.has(last);
}

/** Every word of the phrase is in the place vocabulary — "Berlin", "Soviet Russia". */
function isKnownGeoPhrase(phrase: string): boolean {
  const words = phrase.trim().split(/\s+/).filter(Boolean);
  return words.length > 0 && words.every((w) => isPlaceToken(w));
}

/**
 * The beat's place, or "" when the beat names none.
 *
 * Order of preference, vocabulary-driven rather than pattern-driven:
 *   1. a capitalised run ending in a BUILDING noun, wherever it sits — this is what finds "The
 *      Brandenburg Gate stood in ruins", where no preposition introduces it;
 *   2. a prepositional phrase the geo or structure vocabulary recognises — "over the Reichstag",
 *      "of France";
 *   3. any remaining prepositional phrase that is not a month — "Führerbunker" is in no
 *      vocabulary at all and is still plainly where this beat is set;
 *   4. a bare capitalised run that is entirely place vocabulary — "Berlin was under bombardment".
 * A month is never a place, at any step.
 */
export function extractVisualPlacePhrase(beatText: string): string {
  const text = (beatText ?? "").replace(/\[visual:[^\]]*\]/gi, " ").trim();
  if (!text) return "";
  const runs = [...text.matchAll(new RegExp(CAPITALISED_RUN_SOURCE, "gu"))]
    .map((m) => stripLeadingArticle(m[0]))
    .filter((r) => r && !isMonthPhrase(r));

  // 1. building nouns, anywhere in the sentence.
  const structure = runs.find(endsInPlaceStructure);
  if (structure) return structure;

  // 2 + 3. prepositional phrases; the article, when present, must be a whole word.
  const prepositional = new RegExp(
    `\\b(?:${PLACE_PREPOSITIONS})\\s+(?:(?:the|a|an)\\s+)?(${CAPITALISED_RUN_SOURCE})`,
    "gu"
  );
  const candidates: string[] = [];
  for (const m of text.matchAll(prepositional)) {
    const phrase = stripLeadingArticle(m[1] ?? "");
    if (phrase && !isMonthPhrase(phrase)) candidates.push(phrase);
  }
  const vocabHit = candidates.find((c) => endsInPlaceStructure(c) || isKnownGeoPhrase(c));
  if (vocabHit) return vocabHit;
  if (candidates.length > 0) return candidates[0]!;

  // 4. a bare place name the beat opens with.
  return runs.find(isKnownGeoPhrase) ?? "";
}

/**
 * RONDE 77 — the action a beat describes.
 *
 * The typed representation has carried person, place, time, event and object; `action` was named
 * in every brief since RONDE 73 and never existed. EVENT_CUE_RE covers a small set of fixed
 * documentary verbs — "died", "married", "surrendered" — and says nothing about "dictated",
 * "raised" or "addressed", which is why those beats reached the providers with no verb at all.
 *
 * Two sources, in that order, and no new list of names or events:
 *   1. PERSON_ACTION_VERBS — the verbs RONDE 72 already assembled as person evidence. Reused
 *      here, not copied, and not modified: adding to it would change person classification.
 *   2. generic morphology — a lower-case word of five letters or more ending in "ed" that no
 *      other vocabulary claims. That is what catches "raised" without anyone having listed it.
 *
 * Copulas and auxiliaries are excluded by construction: "was", "had" and "were" are in neither
 * source. Capitalised words are skipped so "United" in "United States" is never read as a verb.
 *
 * Returns "" when the beat describes no action — the common case, and callers must treat it as
 * "nothing to add", never as evidence of anything. The morphological branch is deliberately
 * generous: it will occasionally read a state ("finished") as an action. An action only ever
 * appears in a query behind an entity that anchors it, so a loose verb costs a low-ranked query
 * and never the subject of the search.
 */
export function extractActionCue(beatText: string): string {
  const text = (beatText ?? "").replace(/\[visual:[^\]]*\]/gi, " ");
  const tokens = text.split(/\s+/).filter(Boolean);
  let morphological = "";
  for (const raw of tokens) {
    const word = raw.replace(/[^\p{L}'-]/gu, "");
    if (word.length < 3) continue;
    // A capitalised word mid-sentence is a name, not a verb.
    if (word[0] !== word[0]!.toLowerCase()) continue;
    const lower = word.toLowerCase();
    if (PERSON_ACTION_VERBS.has(lower)) return lower;
    if (
      !morphological &&
      word.length >= 5 &&
      lower.endsWith("ed") &&
      !STOP_WORDS.has(lower) &&
      !NON_ACTION_QUERY_WORDS.has(lower) &&
      !isNonPersonToken(lower)
    ) {
      morphological = lower;
    }
  }
  return morphological;
}

/**
 * RONDE 77 — the typed query family from beat text alone.
 *
 * The four RONDE 73 call sites and the two RONDE 75 ones go through typedRetrievalQueriesForBeat,
 * which needs a SceneBeat, a Scene and the dedup state. Most of the pipeline's query builders have
 * none of those — they receive a string, which is why the RONDE 76 audit found 68 of 102 provider
 * call sites still asking the untyped question.
 *
 * This is the same combination, built from the same extractors, requiring only the text. It calls
 * no query builder at all, which is what keeps it safe to drop into one: nothing here can
 * re-enter the builder that invoked it.
 *
 * RONDE 78 — THE BEAT'S PERSON WINS, whatever the caller supplies.
 *
 * RONDE 77 had two modes and one of them was wrong. `forcePerson` let a caller's name replace the
 * beat's, so a celebrity fetch for Hitler on the beat
 *
 *     "Churchill addressed the nation after the fall of France."
 *
 * asked "Adolf Hitler France" first. The reasoning was that the caller is fetching footage OF a
 * named person — but a beat that names Churchill is about Churchill, and asking the archive about
 * the wrong man is not a retrieval strategy. There is now one rule for both callers:
 *
 *     beat person   -> primary retrieval context
 *     supplied name -> secondary, interleaved behind it
 *
 * The two families are interleaved rather than concatenated, so the supplied name still reaches
 * the provider at position 2 and the scene-level fallback a pronoun beat depends on is intact.
 * When the beat names nobody, the supplied name is the only person there is and leads by default.
 */
export function typedQueryPrefix(
  beatText: string,
  opts: { scenePersons?: string[]; forcePerson?: string; sceneText?: string } = {}
): string[] {
  return buildPrioritisedQueries(buildVerifiedQueryContextForBeat(beatText, opts)).map((q) => q.query);
}

/**
 * RONDE 103 (phases 9–13) — the two typed questions this beat leads with.
 *
 * Exported because the RONDE 77 §G mutation guard has to measure the same two. It used to compute
 * them itself, as `typedQueryPrefix(...).slice(0, 2)`, and a second definition of "which queries
 * are the typed ones" is exactly the kind of duplicate that drifts silently: the test kept
 * passing while measuring a different pair from the one the pipeline sent.
 *
 * One question per RUNG, descending. Taking both slots off the top rung would ask two narrow
 * variants of the same question and drop the broader one entirely — that is not a descent, and a
 * beat whose narrow question finds nothing would be left with no fallback on this path. A beat
 * that supports only one rung still fills both slots from it, exactly as before.
 */
export function typedQueryLead(beatText: string, scenePersons: string[] = []): string[] {
  const ladder = typedQueryLadder(beatText, { scenePersons });
  const out: string[] = [];
  for (const rung of ladder) {
    const pick = rung.queries.find((q) => !out.includes(q));
    if (pick) out.push(pick);
    if (out.length >= 2) break;
  }
  if (out.length < 2 && ladder[0]) {
    for (const q of ladder[0].queries) {
      if (out.length >= 2) break;
      if (!out.includes(q)) out.push(q);
    }
  }
  return out;
}

/**
 * RONDE 103 (phases 9–13) — the same questions, asked narrowest first.
 *
 * `typedQueryPrefix` returns them in the RONDE 90 priority order, where names lead. That rule is
 * about which terms lead the STRING and it is not weakened here: this reorders the LIST, level 4
 * down to level 1, keeping the priority order inside each level exactly as it was.
 *
 * The difference it makes is which question a caller that takes only the first two actually asks.
 * On "Hitler directed the defence of Berlin from the bunker in 1945" the priority list leads with
 * "Hitler Berlin" — a question that returns anything ever shot in Berlin with Hitler in it —
 * while the beat also supports "Hitler Berlin bunker 1945". Asking the second one first is how a
 * beat gets the picture it is actually about, and it is also most of the answer to why a render
 * spent 1667 provider queries to fill twenty slots: the broad questions return the most and fit
 * the least, so every one of their results costs a download and a judgement to throw away.
 */
export function typedQueryLadder(
  beatText: string,
  opts: { scenePersons?: string[]; forcePerson?: string; sceneText?: string } = {}
): Array<{ level: 1 | 2 | 3 | 4; queries: string[] }> {
  return buildBeatSearchLadder(buildVerifiedQueryContextForBeat(beatText, opts)).map((rung) => ({
    level: rung.level,
    queries: rung.queries.map((q) => q.query),
  }));
}

/**
 * RONDE 88 — the beat's PROVEN typed context, with provenance on every term.
 *
 * Three measured defects are closed here, and each one is a rule of §1–§13:
 *
 *   · Every person the beat names is kept, in order. "Churchill and Roosevelt met at Casablanca"
 *     produced only "Roosevelt Casablanca"; Churchill was silently dropped by persons[0].
 *   · A supplied person — from the scene, or from the video's title — is admitted ONLY when the
 *     beat's own text or the scene text proves the connection. §7 and §11: a title is not evidence
 *     that a person appears in a sentence. "Eva Braun Just France" and "Adolf Hitler France" were
 *     both measured on a beat naming neither of them.
 *   · A term that cannot be proven is still RECORDED, marked unverified with the route that
 *     produced it, so validateSearchQuery can name it in the rejection rather than the query
 *     silently going out one word lighter.
 */
export function buildVerifiedQueryContextForBeat(
  beatText: string,
  opts: {
    scenePersons?: string[];
    forcePerson?: string;
    sceneText?: string;
    /**
     * RONDE 160 — the USER'S OWN PROMPT (`videos.prompt`), verbatim. Never the title.
     *
     * Threaded so that the word naming the video's subject is usable in a query even on a beat
     * that does not happen to repeat it — the "WWII" rejection this round reproduced. See
     * `QueryTokenSource` in searchQueryContract.ts for why the prompt is admissible and the title
     * is not. Omitting it leaves behaviour exactly as it was.
     */
    topic?: string;
  } = {}
): VerifiedQueryContext {
  const text = (beatText ?? "").trim();
  /**
   * RONDE 90 (§3) — the beat's own words plus the scene that contains them are the evidence.
   *
   * The video's TITLE is deliberately not here. §7/§9: a title is a claim about the video, not
   * about this sentence, and admitting it as evidence is exactly how "Adolf Hitler France" was
   * measured on a beat that names neither. A term the title supplies and the script does not is
   * unproven, and stays unproven.
   *
   * RONDE 160 — the user's PROMPT is a different thing and travels in its own field, not in the
   * evidence, so a log can still tell "the beat said this" from "the person asked for this".
   *
   * FINAL VALIDATION — and when no caller supplied one, the render's ambient topic is used.
   *
   * R160 added the `topic` parameter and never wired it: the first real production render blocked
   * 101 of 157 queries, "WWII" named eighteen times, on a video the person had asked for by that
   * word. The four helpers that reach this function take a bare beat string and are called from
   * dozens of sites with no render object in scope, so the prompt is set once at the top of the
   * render (`withRenderTopic`) and read here. An explicit `opts.topic` still wins, and outside a
   * render scope `getRenderTopic()` is undefined and behaviour is exactly as it was.
   */
  const ctx = emptyQueryContext(
    [text, (opts.sceneText ?? "").trim()].filter(Boolean).join(" "),
    (opts.topic ?? getRenderTopic() ?? "").trim()
  );
  if (!text) return ctx;

  /**
   * RONDE 88 (§13) — persons in the order the beat states them.
   *
   * extractPersonNamesFromText returns full names before bare surnames, so "Hitler met Eva Braun"
   * came back as ["Eva Braun", "Hitler"] and the first query read "Eva Braun Hitler". The order
   * of a query's names is the order the sentence puts them in.
   */
  const named = extractPersonNamesFromText(text);
  const positionOf = (name: string): number => {
    const idx = text.toLowerCase().indexOf(name.toLowerCase());
    return idx < 0 ? Number.MAX_SAFE_INTEGER : idx;
  };
  for (const name of [...named].sort((a, b) => positionOf(a) - positionOf(b))) {
    ctx.persons.push(provenToken(name, "person", "beat_text", text));
  }
  /**
   * RONDE 88 (§7/§11) — a supplied person is proven only when something states the connection.
   *
   * forcePerson and scenePersons are NOT the same claim, and conflating them was the bug:
   *
   *   forcePerson  the caller is explicitly fetching footage OF this person — a celebrity
   *                fetch for Adolf Hitler is about Adolf Hitler by definition. That is the
   *                caller's own proven context, not an inference about the sentence.
   *   scenePersons a list assembled from the scene AND from the video's title. A title is not
   *                evidence that anybody appears in any given sentence, which is how
   *                "Eva Braun Just France" and "Adolf Hitler France" were both measured on a
   *                beat that names neither. Admitted only when the scene text says so.
   *
   * A name that fails checkPersonName is refused on either route — a caller cannot launder a
   * sentence fragment into a query by passing it as forcePerson.
   */
  const forced = toQueryString(opts.forcePerson ?? "");
  if (forced && !ctx.persons.some((p) => p.term.toLowerCase() === forced.toLowerCase())) {
    ctx.persons.push(
      checkPersonName(forced, forced, "", { isKnownVerb: isKnownPersonActionVerb }).ok
        ? provenToken(forced, "person", "proven_entity", forced)
        : { term: forced, type: "person", source: "title_inference", verified: false }
    );
  }
  for (const raw of opts.scenePersons ?? []) {
    const name = toQueryString(raw);
    if (!name) continue;
    if (ctx.persons.some((p) => p.term.toLowerCase() === name.toLowerCase())) continue;
    const inScene = Boolean(opts.sceneText) && checkPersonName(name, opts.sceneText!).ok;
    ctx.persons.push(
      inScene
        ? provenToken(name, "person", "scene_text", opts.sceneText ?? "")
        : { term: name, type: "person", source: "title_inference", verified: false }
    );
  }

  const place = extractVisualPlacePhrase(text);
  if (place) ctx.places.push(provenToken(place, "place", "beat_text", text));
  const action = extractActionCue(text);
  if (action) ctx.actions.push(provenToken(action, "action", "beat_text", text));
  const typed = buildTypedRetrievalContext(text, {
    persons: ctx.persons.filter((p) => p.verified).map((p) => p.term),
    place,
    action,
  });
  if (typed.event) ctx.events.push(provenToken(typed.event, "event", "beat_text", text));
  if (typed.object) ctx.objects.push(provenToken(typed.object, "object", "beat_text", text));
  if (typed.year) ctx.years.push(provenToken(typed.year, "year", "beat_text", text));
  if (typed.time && typed.time !== typed.year) ctx.time.push(provenToken(typed.time, "time", "beat_text", text));
  return ctx;
}

/*
 * RONDE 91 (§1) — guardProviderQuery was removed here.
 *
 * RONDE 88 built it as "the last gate before a provider is asked anything". RONDE 89 then built
 * the real gate (cachedProviderSearch / admitProviderQuery, both now searchGateDecision) and
 * every provider was routed through that instead — but the old function was left behind, still
 * exported, still holding a second, weaker copy of the decision: it validated, and it did not
 * know about tickets, strict mode, the audit counters or the ambient beat context.
 *
 * A repo-wide scan found zero callers, static or dynamic. A second gate that nothing calls is
 * not harmless: it is the obvious thing for a future call site to reach for, and it would have
 * admitted queries the real gate refuses. ronde91SearchCleanup asserts it stays gone.
 */

/** Capitalized names from narration (Kylie Jenner, Elon Musk, …). */
export function extractPersonNamesFromText(text: string): string[] {
  if (!text?.trim()) return [];
  const found = new Set<string>();
  // RONDE 123: `[a-z]` cannot read `ö`, so this run broke AT the diacritic and the two halves
  // were matched as separate names — see personNameChars.ts for the measurement.
  const fullNames = text.match(nameRunRegex(1)) ?? [];
  for (const name of fullNames) {
    const n = name.trim();
    if (n.length < 5 || PERSON_NAME_SKIP_PHRASES.has(n.toLowerCase())) continue;
    // P1-A2 (render 518): a capitalized title fragment inside the script ("His Wife", "Why
    // Hitler Killed Himself") must never be treated as a person — every consumer of this list
    // (the primaryPerson lock chain, resolveScenePersons, the stock-query builders) uses it as
    // literal person names. Framing words SPLIT the run instead of rejecting it wholesale, so
    // a real name embedded after one ("… His Wife Eva Braun …" → "Eva Braun") still survives.
    let segment: string[] = [];
    const segments: string[][] = [];
    for (const token of n.split(/\s+/)) {
      if (TITLE_NON_NAME_WORDS.has(token.toLowerCase())) {
        if (segment.length) segments.push(segment);
        segment = [];
      } else {
        segment.push(token);
      }
    }
    if (segment.length) segments.push(segment);
    for (const seg of segments) {
      const joined = seg.join(" ");
      if (seg.length < 2 || joined.length < 5) continue;
      if (PERSON_NAME_SKIP_PHRASES.has(joined.toLowerCase())) continue;
      /**
       * RONDE 88 (§8) — the structural check, in front of the historical blocklist.
       *
       * TITLE_NON_NAME_WORDS above splits on words somebody remembered to add. It did not carry
       * "just", "of" or "purged", which is how "Eva Braun Just", "Of Adolf" and "Stalin Purged"
       * were measured reaching providers. checkPersonName refuses on grammar instead: no function
       * word inside a name, every token name-shaped, the whole name contiguous in this very text,
       * and — for Title Case input, where capitalisation proves nothing — corroboration required.
       */
      if (!checkPersonName(joined, text, "", { isKnownVerb: isKnownPersonActionVerb }).ok) continue;
      /**
       * RONDE 72: a run naming a thing is not a person. One head noun is decisive — "Eiffel
       * Tower" carries "tower", "British Spitfire" carries "spitfire".
       *
       * RONDE 125: a name particle is exempt, because several of them are also ordinary nouns.
       * "bin" is the clearest case — measured, "Mohammed bin Salman" was refused here as a thing,
       * on the container. "bar", "al" and "den" have the same problem. A particle only ever
       * appears BETWEEN two of a name's own words (checkPersonName enforces that), so exempting
       * it cannot let a thing through: the head noun that would name one is still checked.
       */
      const significant = seg.filter((t) => !isNameParticleToken(t));
      if (significant.some(isThingToken)) continue;
      // Place names are only decisive when the WHOLE run is one. "New York" is a place;
      // "George Washington" is a person whose surname happens to also name places.
      if (significant.length > 0 && significant.every(isPlaceToken)) continue;
      found.add(joined);
    }
  }

  // RONDE 72: a bare surname, when the sentence itself says it is a person.
  //
  // The two-token requirement is deliberate — a lone capitalised word is ambiguous, and
  // extractPersonSurnameAnchor/resolvePersonFromSurnameAnchor already resolve a title's anchor
  // against full names the script states elsewhere. But a beat that only ever says "Churchill"
  // or "Hitler" gave the pipeline nothing at all, so the person-name lock, resolveScenePersons
  // and the query builders all treated the beat as person-less.
  //
  // A single token is accepted only when it names no thing or place AND the sentence shows it
  // acting as a person. "Berlin was under bombardment" and "Dunkirk had fallen" stay places:
  // "was" and "had" are not person verbs, and both words are in the geo vocabulary anyway.
  for (const sentence of text.split(/(?<=[.!?])\s+/)) {
    const singles = sentence.match(singleNameTokenRegex(3)) ?? [];
    for (const token of singles) {
      if (found.has(token)) continue;
      // Already covered by a full name in this text ("Hitler" beside "Adolf Hitler").
      if ([...found].some((n) => n.split(/\s+/).includes(token))) continue;
      if (TITLE_NON_NAME_WORDS.has(token.toLowerCase())) continue;
      if (PERSON_NAME_SKIP_PHRASES.has(token.toLowerCase())) continue;
      if (isNonPersonToken(token)) continue;
      /**
       * RONDE 88 (§9) — a pronoun is never a person.
       *
       * Measured before this line existed: "She addressed the nation after the fall of France"
       * produced PERSON=["She"], and the beat's first provider query was "She France". The
       * single-token branch only asked whether the sentence showed the token ACTING like a
       * person, and "addressed" is on the person-verb list, so a capitalised pronoun at the start
       * of a sentence passed every check. Function words are refused for the same reason.
       */
      if (isPronounToken(token) || isFunctionWord(token)) continue;
      if (!sentenceSupportsPerson(sentence, token)) continue;
      found.add(token);
    }
  }
  const kylie = text.match(/\b(kylie\s+jenner)\b/i);
  if (kylie?.[1]) found.add("Kylie Jenner");
  const musk = text.match(/\b(elon\s+musk)\b/i);
  if (musk?.[1]) found.add("Elon Musk");
  return Array.from(found);
}

/**
 * Real-world events spoken on this beat → stock/YouTube search phrases.
 *
 * RONDE 100B rewrote what this emits. Every line used to be a mapping from a trigger to a
 * DIFFERENT word: a beat saying "premiere" asked providers for "red carpet", "scandal" asked for
 * "news conference", "billion" asked for "business news". The trigger was evidence; the output
 * was not, and none of those words appear anywhere in the script. The SearchGate then rejected
 * them as UNVERIFIED_TERM — the builder was manufacturing work for the gate to throw away, and
 * on the renders where a scope was missing they went out to providers unchecked.
 *
 * Now the beat's own word is the query. `\b(a|b|c)\b` tells us which of the alternatives the
 * narration actually used, and that is what gets asked for. Two entries are gone rather than
 * rewritten, because neither had a visual word to fall back on: "scandal|controversy|backlash"
 * pointed at a press conference nobody mentioned, and "billion|million|deal|acquisition|ipo"
 * pointed at generic business news. A sum of money is not footage.
 *
 * The person prefix stays: `persons` is derived from this same beat, so it is proven.
 */
function scriptEventSearchQueries(beatText: string, persons: string[]): string[] {
  const t = beatText.toLowerCase();
  const primary = persons[0] ?? "";
  const out: string[] = [];

  /** Push what the beat SAID, optionally anchored to the person the beat named. */
  const spoken = (re: RegExp) => {
    const m = t.match(re);
    const said = m?.[1]?.trim();
    if (!said) return;
    out.push(primary ? `${primary} ${said}` : said);
  };

  spoken(/\b(interviews?)\b/);
  spoken(/\b(keynote|speech|presentation|address)\b/);
  spoken(/\b(red carpet|premiere|gala|awards?)\b/);
  spoken(/\b(launch|unveiling|announcement|debut)\b/);
  spoken(/\b(trial|court|lawsuit|verdict|sentencing)\b/);
  spoken(/\b(wedding|engagement|divorce)\b/);
  spoken(/\b(protest|demonstration|rally)\b/);
  spoken(/\b(concert|performance|tour)\b/);
  spoken(/\b(rocket launch|falcon|starship|spacex)\b/);
  spoken(/\b(tesla|cybertruck|gigafactory)\b/);

  return [...new Set(out.filter((q) => q.length >= 3 && !isBlockedStockQuery(q)))];
}

function resolveScenePersons(scene: Scene, videoTitle?: string, globalPrimaryPerson?: string): string[] {
  const persons = new Set(
    (scene.personNames ?? []).map(coercePersonName).filter((n) => n.length > 0)
  );
  for (const n of extractPersonNamesFromText(scene.text)) persons.add(n);
  const titlePerson =
    coercePersonName(globalPrimaryPerson) || extractPrimaryPersonFromTitle(coerceVisionString(videoTitle));
  if (titlePerson) persons.add(titlePerson);
  return Array.from(persons);
}

/**
 * Eén kernwoord per zin: persoon > event > sterkste inhoudswoord (uit narratie).
 * Primair zoekanker per beat — geen [VISUAL:] tags in script.
 */
function extractPowerWordFromSentence(sentence: string, persons: string[] = []): string {
  const clean = sentence.replace(/\[visual:[^\]]*\]/gi, " ").trim();
  if (!clean) return "documentary";

  for (const person of persons) {
    if (beatMentionsPerson(clean, person)) {
      const first = person.split(/\s+/)[0]?.trim();
      return first && first.length >= 3 ? first : person;
    }
  }

  const eventQs = scriptEventSearchQueries(clean, persons);
  if (eventQs[0]) {
    const ev = eventQs[0].split(/\s+/).slice(-2).join(" ").trim() || eventQs[0];
    if (ev.length >= 3) return ev;
  }

  const tokens = tokenizeForRelevance(clean);
  const scoreToken = (w: string): number => {
    if (DUTCH_STOCK_WORD_MAP[w]) return 120;
    for (const [re] of STOCK_TOPIC_WORD_RULES) {
      if (re.test(`\\b${w}\\b`) || re.test(w)) return 90;
    }
    return w.length;
  };
  const ranked = [...tokens].sort((a, b) => scoreToken(b) - scoreToken(a));
  for (const tok of ranked) {
    const w = translateTokenForPexels(tok);
    if (w && !isBlockedStockQuery(w) && !isGenericNatureStockWord(w)) return w;
  }

  const longest = tokens.sort((a, b) => b.length - a.length)[0];
  if (longest && longest.length >= 4) {
    const w = translateTokenForPexels(longest);
    if (w) return w;
  }

  return stockQueryFromBeatScript(clean, persons, "", undefined);
}

/** Ordered queries for one beat — max 2 script subjects, then geo fallbacks. */
export function buildBeatVisualQueryList(
  beatText: string,
  scene: Scene,
  videoTitle: string | undefined,
  scenePersons: string[],
  maxQueries: number
): string[] {
  const anchor = resolveBeatScriptVisualAnchor(beatText);
  const beatAnchored = buildGeoStockSearchQueries(beatText, videoTitle);
  // RONDE 77: the typed combination leads. This is the central lever the RONDE 76 audit pointed
  // at — seven call sites reach the providers through this one list, and every one of them was
  // asking with the anchor word alone. "Adolf Hitler" and "berlin city skyline" both still go,
  // one place further down; the cap grows by exactly what was added so nothing is evicted.
  /**
   * RONDE 103 (phases 9–13): the narrowest question the beat supports leads, then the next
   * narrowest. Two queries as before — the change is WHICH two, not how many. A beat that proves
   * an event now spends its two slots on "Hitler Berlin bunker 1945" and "Battle of Berlin"
   * rather than on "Hitler Berlin" and "Hitler", which is the difference between asking about
   * this shot and asking about the whole war.
   */
  const typed = typedQueryLead(beatText, scenePersons);
  // Person context (e.g. "Adolf Hitler") is resolved once per scene/video, not per beat — many
  // beats refer to the subject with a pronoun ("he", "his") instead of repeating the name, so
  // without this a beat like "He then gave the order..." never even tries a person-name query,
  // missing archive footage that a name match would otherwise score very highly (+200 in
  // scoreCuratedAsset). Listed first so it always survives the maxQueries cap below.
  const ordered = [
    ...typed,
    ...scenePersons,
    ...anchor.searchSubjects,
    ...beatAnchored.slice(0, 2),
  ].filter((q) => toQueryString(q).length > 2 && !isBlockedStockQuery(toQueryString(q)));

  const unique = [...new Set(ordered.map((q) => toQueryString(q)))];
  const typedKept = unique.filter((q) => typed.includes(q)).length;
  return unique.slice(0, Math.max(2, maxQueries) + typedKept);
}

function hydrateSceneBeatInPlace(beat: SceneBeat): SceneBeat {
  return hydrateBeatScriptVisuals(beat);
}

function beatMediaSearchQueries(beat: SceneBeat, videoTitle?: string): string[] {
  hydrateSceneBeatInPlace(beat);
  return queryStringsMinLen(
    [...beatVisualSearchSubjects(beat.text), beat.searchQuery, videoTitle],
    3
  ).slice(0, 3);
}

// ─── Beat-level visual matching (narration ↔ footage alignment) ───────────────
const VO_SCENE_TAIL_SEC = 0.35;

/** True when every montage beat already passed CLIP at adopt time — skip redundant compose QA. */
function sceneMontageBeatsPassedAdoptVision(
  sceneIndex: number,
  clipBeatIndices: number[],
  dedup: VisualDedupState,
  minScore = targetClipVisionScore()
): boolean {
  if (clipBeatIndices.length === 0) return false;
  const beats = new Set(clipBeatIndices);
  for (const beatIdx of beats) {
    const entry = dedup.clipAdoptAudit.find(
      (e) => e.sceneIndex === sceneIndex && e.beatIndex === beatIdx
    );
    if (!entry || typeof entry.visionScore10 !== "number" || entry.visionScore10 < minScore) {
      return false;
    }
  }
  return true;
}

async function applyVoiceAlignmentToBeats(
  beats: SceneBeat[],
  sceneAudioPath: string | undefined,
  sceneDuration: number,
  dedup?: VisualDedupState,
  sceneIndex?: number
): Promise<void> {
  /**
   * RENDER 562 — the scene's beats, recorded before anything can decide not to align them.
   *
   * This is the one function every beat-resolving route calls, and it is called with the array the
   * route is about to fill clips for, so it is the honest single point of record. The array is
   * stored BY REFERENCE and both branches below return early without touching it — a scene whose
   * beats came word-timed from the TTS planner has them already, and "no alignment was needed" is
   * not "there are no beats". Recording after the early returns is what would lose them.
   *
   * Nothing here decides, searches or aligns. It remembers.
   */
  if (dedup && sceneIndex != null && beats.length > 0) {
    dedup.sceneBeatsBySceneIndex.set(sceneIndex, beats);
  }
  if (dedup && sceneIndex != null && dedup.ttsSceneBeats.get(sceneIndex)?.length) {
    return;
  }
  if (dedup && dedup.ttsSceneBeats.size > 0 && ttsWordAlignmentEnabled()) {
    return;
  }
  if (!sceneAudioPath || !fs.existsSync(sceneAudioPath)) return;
  const voiceSec = Math.max(0.5, sceneDuration - VO_SCENE_TAIL_SEC);
  await alignSceneBeatsToVoiceAudio(beats, sceneAudioPath, voiceSec, montageXfadeSec());
}

function ttsPlannedBeatToSceneBeat(
  planned: TtsPlannedBeat,
  scene: Scene,
  videoTitle: string | undefined,
  scenePersons: string[]
): SceneBeat {
  const text = planned.text;
  const intent = resolveBeatVisualIntent(text);
  const subjects = beatVisualSearchSubjects(text);
  const visualAnchor = extractPrimaryVisualAnchor(text);
  const geoTag = extractPrimaryGeoSearchTag(text);
  let powerWord = subjects[0] ?? extractPowerWordFromSentence(text, scenePersons);
  if (visualAnchor) powerWord = visualAnchor;
  else if (geoTag) powerWord = geoTag;
  let searchQuery =
    subjects[0] ?? visualAnchor ?? geoTag ?? simplifyStockSearchWord(powerWord, text, true);
  if (!searchQuery || isBlockedStockQuery(searchQuery)) {
    searchQuery = stockQueryFromBeatScript(text, scenePersons, scene.text, videoTitle);
  }
  const visualCues = extractInlineVisualCues(text);
  const visualDescription =
    visualCues[0] ??
    beatVisualDescriptionFromIntent(text) ??
    (visualAnchor || geoTag || subjects[1] || undefined);
  return {
    index: planned.index,
    text,
    searchQuery,
    powerWord,
    keywords: buildRelevanceKeywords(scene, text),
    holdSec: planned.holdSec,
    voiceStartSec: planned.voiceStartSec,
    voiceEndSec: planned.voiceEndSec,
    visualDescription,
  };
}

function resolveSceneBeats(
  scene: Scene,
  duration: number,
  beatCap: number,
  videoTitle: string | undefined,
  scenePersons: string[],
  dedup: VisualDedupState
): SceneBeat[] {
  const ttsPlan =
    !isFastShortVideoLength(dedup.videoLength) ? dedup.ttsSceneBeats.get(scene.index) : undefined;
  if (ttsPlan?.length) {
    return ttsPlan.map((p) => hydrateBeatScriptVisuals(ttsPlannedBeatToSceneBeat(p, scene, videoTitle, scenePersons)));
  }
  return buildSceneBeats(scene, duration, beatCap, videoTitle, scenePersons).map((b) =>
    hydrateBeatScriptVisuals(b)
  );
}

/**
 * How many of a beat's vetted candidates are actually prepared.
 *
 * RONDE 84 — this was the reason a beat almost never had a choice.
 *
 * The scan above builds a queue of up to `tryCap` candidates that already passed the beat
 * minimum, the score floor and the geo/literal gates — six of them on a long video
 * (min(archiveBeatTopCandidates=24, maxVisualCandidatesPerBeatTry=6)). This function then said
 * how many of those six get downloaded and trimmed, and every branch answered 2, including the
 * `fastMode ? 2 : 2` ternary whose two arms are the same number. Four vetted candidates were
 * discarded unused on every beat.
 *
 * Measured on render 536 (18 scenes, 8-10 bucket): 594 "source video too short" rejections, 13
 * of 18 scenes ending with a montage too short for their own duration, and not one
 * [VisualSelection] line in the whole render — that line only prints when a beat has more than
 * one candidate to compare, and no beat ever did.
 *
 * The wave loop that consumes this returns as soon as one candidate succeeds, so raising the cap
 * costs nothing on a beat whose first candidate works. It only spends time where the beat would
 * otherwise have come back empty — which is exactly the case this is meant to fix.
 *
 * Bounded by the scan's own cap rather than a second hardcoded number, so the two can no longer
 * disagree silently. fastMode and relaxed keep exactly the 2 they have today: the 1-minute path
 * has a tight wall-clock budget and is not what this round is about, and `relaxed` is already a
 * widening retry running at concurrency 1.
 */
export function archivePrepareAttemptsPerBeat(fastMode: boolean, relaxed: boolean, tryCap: number): number {
  if (relaxed) return 2;
  if (fastMode && strictVoiceVisualMatchEnabled()) return 2;
  if (fastMode) return 2;
  return Math.max(2, Math.min(tryCap, ARCHIVE_PREPARE_ATTEMPTS_MAX));
}

/** Ceiling on prepared candidates per beat, so a widened scan cap can never fan out unbounded. */
export const ARCHIVE_PREPARE_ATTEMPTS_MAX = 6;

function archivePrepareConcurrency(fastMode: boolean, relaxed: boolean): number {
  if (relaxed) return 1;
  if (fastMode && strictVoiceVisualMatchEnabled()) return 4;
  // Run candidate prep more in parallel so trying more candidates per beat
  // (maxVisualCandidatesPerBeatTry) doesn't add proportional wall-clock time.
  return fastMode ? 3 : 2;
}
const RELEVANCE_STOP_WORDS = new Set([
  "the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for", "of", "with", "by", "from",
  "is", "are", "was", "were", "be", "been", "being", "have", "has", "had", "will", "would", "could",
  "should", "may", "might", "this", "that", "these", "those", "it", "its", "we", "they", "he", "she",
  "you", "i", "my", "our", "their", "his", "her", "your", "as", "so", "if", "not", "no", "up", "out",
  "about", "into", "than", "then", "when", "where", "who", "which", "what", "how", "all", "each", "more",
  "most", "also", "just", "very", "over", "after", "before", "through", "during", "between", "while",
  "because", "since", "even", "only", "still", "now", "here", "there", "some", "any", "every", "one",
  "two", "three", "first", "second", "third", "new", "like", "said", "says", "fact", "facts", "minute",
  "rumor", "rumors", "gossip", "exclusive", "breaking", "truth", "story", "decode", "decoding",
]);

interface SceneBeat {
  index: number;
  text: string;
  searchQuery: string;
  /** Kernwoord uit deze zin — primair zoekanker voor stock/YouTube. */
  powerWord: string;
  keywords: string[];
  /** Seconds this beat stays on screen (3–4 default, up to 7 when merged). */
  holdSec: number;
  /** Script [visual:…] cue or visual anchor — fed into CLIP gate. */
  visualDescription?: string;
  /** TTS-aligned window within scene voice (seconds). */
  voiceStartSec?: number;
  voiceEndSec?: number;
}

export interface VisualDedupState {
  usedPaths: Set<string>;
  usedPexelsIds: Set<number>;
  usedPixabayIds: Set<number>;
  usedContentKeys: Set<string>;
  /** FIX 1/2 — funnel candidate ids (`${source}:${assetId}`) already selected as a beat's
   *  winner in this render. Keyed on the candidate's own stable provider identity rather
   *  than clipContentKey, because a funnel clip's filename embeds `scene_N_bM_`, so
   *  clipContentKey() yields a per-beat-unique `file:` key that can never match across
   *  beats. Read by buildDownloadShortlist() and pickBestFunnelCandidate(). */
  usedFunnelCandidateIds: Set<string>;
  usedCategories: Map<string, number>;
  globalBeatIndex: number;
  muskHeroFetchUsed: boolean;
  /** Last adopted real stock clip (any topic) — reused instead of color/black placeholders. */
  lastMuskStockClip: string | null;
  /** Last adopted real (non-fallback) clip this video — used for extendLastClip rescue. */
  lastRealClip: string | null;
  /** Video-level visual context (persons, period, locations, styles) — built once per render. */
  videoVisualContext?: VideoVisualContext;
  aiClipsUsed: number;
  /** AI clips used only in visual rescue tier (separate cap from main AI fallback). */
  rescueAiClipsUsed: number;
  /** Kling AI video clips (Wikimedia fallback tier). */
  klingClipsUsed: number;
  entityYoutubeFetchesUsed: number;
  /** Licensed Pexels/Pixabay clips used (capped when minimizeStockFootage). */
  stockBeatsUsed: number;
  /**
   * RONDE 8 (render 518): scenes whose montage came up shorter than the voice and were padded
   * with a gray filler. The export gate previously scored such a render 100/100 ("0 fallback
   * beats") because a gray PAD is not a fallback CLIP — this makes the gap visible in the
   * persisted quality report instead of only as a mid-render warn line.
   */
  grayPadScenes: number[];
  /** RONDE 132 §10: how short each montage was, so a 0.3s rounding is not reported like a 12s freeze. */
  montageShortfalls: Array<{
    sceneIndex: number;
    shortBySec: number;
    uniqueClips: number;
    neededClips: number;
  }>;
  /**
   * Production fix (Hitler-render finding, Problem 10): a whole SCENE (not just one beat)
   * that had to fall all the way back to generateColorFallback as its final composed output —
   * i.e. every real sourcing/rescue attempt for that scene failed. Tracked separately from
   * clipAdoptAudit's per-beat "fallback" source because this specific last-resort path replaces
   * the scene's entire composed video and is not itself recorded as a per-beat adoption. Read by
   * the final export validation to fail the render explicitly instead of shipping it.
   */
  sceneRescueColorFallbackCount: number;
  /** Ken Burns / Serp stills allowed this scene (0 = video only). */
  stillPhotosThisScene: number;
  stillPhotosMaxThisScene: number;
  /** Whole-video cap on still-image clips (Serp/Openverse/Wikimedia stills). */
  stillPhotosUsedGlobal: number;
  /** Source image URLs already used (prevents same Google Image twice). */
  usedImageUrls: Set<string>;
  /** Curated admin archive asset IDs already used this video. */
/*
 * RONDE 34 (point 8) — DEDUP SCOPES, stated once so no route can drift between them.
 *
 * RENDER-WIDE (one VisualDedupState, lives for the whole video)
 *   usedContentKeys ............ every clip's content identity; the last line of defence, and
 *                                what stops the same footage appearing twice in one video.
 *   usedCuratedAssetIds ........ curated archive asset rows already adopted.
 *   usedCuratedStorageUrls ..... the storage files behind them, so two rows pointing at one file
 *                                cannot both be adopted (RONDE 34 point 1 finally populates it).
 *   usedPexelsIds / usedFunnelCandidateIds / crossVideoExcludeIds ... same idea per source.
 *
 * RESCUE-BATCH-WIDE (a fresh pair of Sets per compose rescue, deliberately NOT the render-wide
 * ones — this code only runs because normal sourcing already failed, and a render-wide exclusion
 * there starves the rescue into a colour card instead of feeding it)
 *   rescueUsedAssetIds / rescueUsedStorageUrls ... passed to generateGuaranteedBeatClip, which
 *                                marks each pick, so slot N+1 cannot re-take slot N's asset.
 *   the same Set is handed to fetchWikimediaImages as excludeUrls, keyed on the Commons file URL.
 *
 * SCENE-WIDE (local to one compose or one scene fill)
 *   seenKeys / seenRecover / collected ... prevent duplicates inside a single montage.
 *
 * RETRY-WIDE
 *   None by design. A retry inherits the render-wide sets (so it cannot resurrect footage the
 *   video already used) and starts a NEW rescue batch (so a failed attempt's exclusions do not
 *   permanently narrow the next one).
 */
  usedCuratedAssetIds: Set<number>;
  /**
   * RONDE 131: what the persistent search memory saved this render.
   *
   * On VisualDedupState rather than in a new object because this is already the per-render state
   * every sourcing path threads, and a counter that outlived a render would be a lie the moment
   * two renders shared a worker.
   */
  searchMemoryMetrics: SearchMemoryRecallMetrics;
  /** Archive assets this render offered because an earlier video proved them (RONDE 131). */
  recalledAssetIds: Set<number>;
  /** RONDE 132 §2: unique/reused/refused counts across every dedup identity. */
  visualDedupStats: VisualDedupStats;
  /**
   * RONDE 140: what the open-web source policy refused this render, and how much it looked at.
   *
   * Here for the same reason searchMemoryMetrics is: this is the per-render state every sourcing
   * path already threads, and a counter that outlived a render would be a lie the moment two
   * renders shared a worker.
   */
  openWebPolicyStats: OpenWebPolicyStats;
  /**
   * RONDE 132 §2 — provider+id, render-wide.
   *
   * The provider axis existed only as a `usedProviderKeys` PARAMETER threaded into each fetcher,
   * so it was scoped to a call chain rather than to the video: two routes asking two providers for
   * the same beat each carried their own set. This is the render-wide one, written at every adopt
   * point, so "have we already used this provider asset in this video" finally has an answer that
   * outlives one call. The per-fetcher parameter is untouched.
   */
  usedProviderKeys: Set<string>;
  /** Storage URLs from curated archive — blocks same file twice even with different IDs. */
  usedCuratedStorageUrls: Set<string>;
  /** Cap modern historian interview B-roll (looks like one frozen talking head). */
  curatedInterviewClipsUsed: number;
  /** Cap Ken Burns still-image beats when archive video is available. */
  curatedImageClipsUsed: number;
  /** Moving archive footage adopted (opening montage targets video first). */
  archiveVideoClipsUsed: number;
  /** Live beat progress for dashboard (visual stage). */
  visualBeatsCompleted: number;
  visualBeatsTotal: number;
  /** Target video length key for opening-footage policy (e.g. "1", "8-10"). */
  videoLength: string;
  /** FFmpeg text cards / map beats rendered this video. */
  motionGraphicsUsed: number;
  /** Scene/video archive pool — legacy; sentence montage uses per-beat search. */
  archiveCandidatePool: CuratedCandidatePick[] | null;
  /** Cache archive asset lists within one video (speeds per-sentence search). */
  archiveAssetsCache: Map<number, ArchiveAssetRow[]>;
  /** RONDE 34: asset.id -> storageUrl, resolved from the caches above. "" means "looked, not found". */
  curatedStorageUrlById: Map<number, string>;
  /** Per-video seed so archive picks differ between generations. */
  varietySeed: number;
  /** Assets used in recent same-topic videos — skipped when pool allows. */
  crossVideoExcludeIds: Set<number>;
  /**
   * RONDE 159 — scenes allowed to fetch at compose time despite local-only mode.
   *
   * Granted only to a scene that is genuinely short of footage while the render still holds real
   * wall-clock headroom; see composeMayFetchForStarvedScene. Per scene rather than per render,
   * because scenes compose in parallel and one starved scene must not open the door for the rest.
   */
  composeFetchExemptScenes: Set<number>;
  /** RONDE 164: one funnel audit per beat, tallied at render end. */
  archiveSourcingAudits: ArchiveSourcingAudit[];
  /** asset.id → prepared beat MP4 (avoid re-trim when next zin tries same file). */
  preparedArchiveClips: Map<string, string>;
  /** asset.id → shared raw source file (one disk copy per video). */
  materializedArchiveRaw: Map<number, string>;
  /** ElevenLabs word-timed beats per scene (when available). */
  ttsSceneBeats: Map<number, TtsPlannedBeat[]>;
  /**
   * THE SCENE'S OWN BEATS, kept where no clip-list rebuild can reach them.
   *
   * ── What render 562 did ───────────────────────────────────────────────────────────────────
   *
   *     [CinematicPipeline] inputs scenes=0 beats=0 planned=0 dropped=3
   *     [CinematicPipeline] dropped scene 0: no beat could be planned, the scene is not in the edit
   *     [RenderJob] video=562 route=legacy_compose RENDER_FALLBACK_USED
   *
   * `beats=0` is the whole story: that counter increments once per beat the planner is HANDED, so
   * the planner was handed none. Not one beat failed a check — there were no beats to check, and
   * the plan's own reason ("no beat with both a voice window and a rehydratable clip") described a
   * comparison that never happened. With no plan there is no EDL, so no graphics, captions, SFX or
   * Remotion ran on that render either.
   *
   * The beats reached the planner through `sceneVisualResults[i].beats`, an OPTIONAL field on a
   * record that fourteen places reassign. Several rebuild it from scratch — `{ clips,
   * beatDurations }` — and every one of those silently drops the beat list. Render 562's last
   * write for all three scenes was the cheapest of them:
   *
   *     [Pipeline] Scene 0: strict refill already attempted this render — guaranteed fill instead
   *     [Pipeline] Scene 1: strict refill already attempted this render — guaranteed fill instead
   *     [Pipeline] Scene 2: strict refill already attempted this render — guaranteed fill instead
   *
   * ── Why a separate record and not a spread at each site ───────────────────────────────────
   *
   * A rule that fourteen assignment sites must remember is the same seam that has already failed
   * three times in this file (R53's `recordClipAdopt`, R62's still/moving counters, R70's beat
   * audit — each had exactly one caller and reported zero for every other route). Beats are a fact
   * about the SCENE'S NARRATION, not about any one clip list, so a rebuilt clip list cannot
   * invalidate them and they do not belong to that record in the first place. Written once, in the
   * one function every beat-resolving route calls; read by the cinematic planner.
   */
  sceneBeatsBySceneIndex: Map<number, SceneBeat[]>;
  /**
   * RENDER 562 — the metadata screen that runs before any download. See candidateSubjectGate.ts.
   * Render-scoped so two concurrent renders cannot spend each other's budget or read each
   * other's verdicts, exactly as beatImageGate is.
   */
  candidateSubjectGate: CandidateSubjectGateState;
  lock: Promise<void>;
  perf: PipelinePerfProfile;
  /** Named celebrity from user prompt (e.g. Kylie Jenner) — anchor every beat's stock search. */
  primaryPerson: string;
  personTopicLock: boolean;
  /**
   * Tracks how many times each Pexels query term has been used as the winning anchor this video.
   * Used by the variety enforcer to promote least-used anchors for successive beats, so
   * "Amsterdam canal", "Dutch cycling", "Netherlands bicycle" all get used instead of
   * repeating "Amsterdam canal" for every Netherlands beat.
   */
  usedPexelsAnchors: Map<string, number>;
  /**
   * The topic key returned by extractVideoTopicAnchorsWithKey for the most recent beat.
   * Used to detect topic switches mid-video and log them for debugging.
   * e.g. "amsterdam" → "wwii" → "amsterdam" when a Netherlands video discusses WWII occupation.
   */
  currentBeatTopicKey: string;
  /** Reject reasons during adoptClip (for quality report). RONDE 70: the per-beat tally inside
   *  it is uncapped, so a late beat can no longer report a rejection count it did not earn. */
  clipRejectAudit: ClipRejectAudit;
  /** RONDE 70: per-beat funnel record — offered/eligible/adopted/vision, one status per beat. */
  beatOutcomeAudit: BeatOutcomeAudit;
  /** Successfully adopted clips per beat (for geo export gate). */
  clipAdoptAudit: ClipAdoptEntry[];
  /**
   * RONDE 111: one line per scene that came up short of footage, and what was done about it.
   *
   * Collected here rather than printed and forgotten, because "why does this scene look frozen"
   * is asked days later about a specific video — the same reason RONDE 106 moved the render's
   * other reports out of stdout. Rendered into the pipeline report's warnings section.
   */
  coverageDecisions: string[];
  /**
   * RONDE 112: beats the subject fallback has already been tried on.
   *
   * It runs the full search cascade a second time for one beat, so it gets exactly one attempt —
   * both rescue ladders can reach it and neither should pay for the other's miss.
   */
  subjectFallbackBeats: Set<string>;
  /**
   * RONDE 58: verdicts and spend for the vision gate that looks at the frame and says whether it
   * belongs under this narration. Render-scoped so two concurrent renders cannot read each
   * other's verdicts or spend each other's budget.
   */
  beatImageGate: BeatImageGateState;
  /**
   * RONDE 103: what the single content decider decided, per clip path.
   *
   * Same lifetime and the same reasoning as beatImageGate above — one render, no leakage. This is
   * what makes a decision survive the hand-off between the route that made it and the compose
   * barrier that enforces it. See ./beatVisualRelevance.
   */
  beatRelevance: BeatRelevanceLedger;
  /**
   * RONDE 61: funnel candidates the beat-image gate has REFUSED. Separate from
   * usedFunnelCandidateIds, which is a soft variety preference the picker restores when
   * everything has been used — this one is never restored.
   */
  beatImageRejectedIds: Set<string>;
  /**
   * RONDE 131: what the content decider SAID when it refused, read and counted.
   *
   * Same render lifetime as the gate state above and for the same reason. The gate's `depicts`
   * and `reason` are prose about one refusal; this is the render's distribution over them, which
   * is what turns "21 does_not_fit" into a statement about whether better queries or better
   * catalogues would have fixed it. See ./visualMismatchFeedback.
   */
  mismatchTally: MismatchTally;
  /**
   * RONDE 132 — beats that have already had their one corrected-query research pass.
   *
   * `s{scene}b{beat}`. This is the whole of the "maximaal één extra research-pass" rule: a beat
   * whose key is in here is never researched again, whatever it is refused for afterwards. Kept
   * beside the other per-render sets for the same reason they are — two concurrent renders on one
   * worker must not be able to spend each other's passes.
   */
  mismatchResearchedBeats: Set<string>;
  /** RONDE 132: what the research passes cost and what they bought. */
  researchTally: ResearchTally;
  /**
   * RONDE 142 — how long one source clip has been carried by extendLastClip.
   *
   * Video 548 filled 13 empty beats by extending the same clip and put one picture on screen for
   * 41.38 of its 95.84 seconds. Each extension was short and legitimate on its own; nothing
   * counted the run. See ./extendHoldBudget.
   */
  extendHold: ExtendHoldState;
  /**
   * RONDE 142 — the last mismatch kind the gate produced for each beat, keyed `s{scene}b{beat}`.
   *
   * Written at the shared gate so it covers every route, and read by the research pass. Before
   * this, the research pass could only see refusals that happened inside the funnel's own loop,
   * which is why video 548 had four QUESTION-blame refusals and zero research attempts.
   */
  lastMismatchByBeat: Map<string, MismatchKind>;
  /** Sticky NL/US segment lock for comparison documentaries. */
  segmentGeoLock: BeatGeoRegion | null;
  /** Pipeline wall-clock start (ms) — used for turbo sourcing on 1-min videos. */
  pipelineStartedMs?: number;
  /** Near the length's own deadline — finish visuals and export rather than keep searching. */
  forceExportMode?: boolean;
  /** Per-step timing for compose/visual bottleneck diagnosis. */
  stepTiming?: PipelineStepTiming;
  /** When true, beat adopt / rescue must not use network (compose render phase). */
  composeNetworkBlocked?: boolean;
  /** Global visual blueprint from Master Documentary Director (set once, pre-retrieval). */
  videoBlueprint?: import("./masterDocumentaryDirector").VideoBlueprint;
  /** Full documentary plan (contracts, shot mix, emotional curve) from PlanningEngine. */
  documentaryPlan?: import("./documentaryPlanningEngine").DocumentaryPlan;
  /** Budget tracker that records how many of each visual type has been used. */
  visualBudgetTracker?: import("./masterDocumentaryDirector").VisualBudgetTracker;
  /**
   * RONDE 29: running moving/still split of everything adopted this render.
   *
   * Until now nothing measured the result, so the RONDE 27 moving-footage ranking bonus was
   * flat — it pushed just as hard on a montage that was already all video as on one that was
   * all Ken Burns stills. These two counters close that loop (see movingShareDeficit) and are
   * also what the quality report's mix line is built from.
   */
  movingClipCount: number;
  stillClipCount: number;
  /**
   * RONDE 180 — every asset this VIDEO has already adopted, so a repeat can be penalised.
   *
   * On the render state rather than per scene, because the complaint it answers is a viewer seeing
   * the same shot come back, and that does not care which scene found it the second time. R170
   * built the ledger and the penalty; nothing constructed one, so `selectCandidatesFromPool` was
   * called with no context at all and the penalty could never apply.
   */
  usageLedger: UsageLedger;
  /** RONDE 62: consecutive beats where every plan-rescue round missed. */
  planRescueMissStreak: number;
  /** Clips adopted so far in the current scene — used by Asset Director for shot variety. */
  assetDirectorSceneClips: string[];
  /** Clips adopted in the previous scene — used for style continuity checks. */
  assetDirectorPrevSceneClips: string[];
  /** Active entity name inferred from the current beat narration. */
  assetDirectorActiveEntity: string | null;
  /** Active location inferred from the current beat narration. */
  assetDirectorActiveLocation: string | null;
  /** Active era/period inferred from the current beat narration. */
  assetDirectorActiveEra: string | null;
  /** Tracks how many callbacks have been placed per motif key. */
  assetDirectorCallbacksPlaced: Map<string, number>;
  /** Annotation metadata keyed by local clip path — populated when archive clips are prepared. */
  clipAnnotationMeta: Map<string, CandidateMeta>;
  /** Motion target (0–100) from VisualRhythmEngine, keyed by "s{si}b{bi}". */
  beatRhythmTargets: Map<string, number>;
  /** Pre-generated graphic clips keyed by "s{sceneIndex}b{beatIndex}". */
  graphicClips: Map<string, string>;
  /** Aggregate usage stats for the editorial graphics engine. */
  graphicsUsageSummary: GraphicsUsageSummary;
  /** How many consecutive beats were resolved from archive-only (resets on any external hit). */
  consecutiveArchiveBeats: number;
  /** Style fingerprint of the most recently completed scene — used for editorial memory. */
  editorialMemory: SceneStyleMemory | null;
  /** Documentary Taste Model context — persists across the full render. */
  tasteModelCtx: TasteModelContext;
  /** Scene indices that already had a full refillSceneStrictVoiceMatch() pass this render.
   *  That function redoes an entire scene's beat-fill from scratch — own archive, Wikimedia,
   *  Internet Archive, Europeana, Openverse, stock, AI — for every beat. Multiple independent
   *  recovery layers in the pipeline can each call it for the same still-short scene (initial
   *  P5A retrieval recovery, the shared "empty after fetch" sweep, the final "still short" pass),
   *  and none of them previously checked whether an earlier layer had already exhausted the
   *  exact same search space. A scene whose external sources are genuinely down or exhausted
   *  doesn't get a different answer on a 2nd or 3rd identical attempt minutes later — it just
   *  pays the full cost again. See refillSceneStrictVoiceMatch's callers. */
  strictRefillAttemptedScenes: Set<number>;
  /** F3-49: "s{sceneIndex}b{beatIndex}" keys for which fetchHistoricalBeatVideo's full
   *  HISTORICAL_SOURCE_TIER_ORDER cascade (Internet Archive, YouTube CC, Wikimedia, NARA,
   *  Flickr, SepiaSearch, Vimeo, media.ccc, NASA — up to 27 external search/metadata/
   *  license/download attempts) has already run for this beat this render. Same
   *  already-exhausted-search-space problem as strictRefillAttemptedScenes above, but at
   *  beat granularity: the primary path (fetchBeatArchivalThenPexels) and the rescue path
   *  (fetchHistoricalBeatRescue, reached when every later fallback for the same beat also
   *  misses) both call fetchHistoricalBeatVideo with queries built from the same
   *  beat.text/beat.searchQuery, so an unguarded 2nd call just re-runs the identical cascade.
   *  Marked only once the cascade has actually started (first external call point), so a
   *  cancellation/exception before that point never poisons a future genuine first attempt. */
  historicalCascadeAttemptedBeats: Set<string>;
  /** Phase 10: dHash perceptual fingerprints of clips already adopted this video — catches
   *  near-duplicate footage (same event from a different archive/encode) that usedCuratedAssetIds/
   *  usedCuratedStorageUrls can't, since those only block the exact same asset row/file twice. */
  usedFingerprints: bigint[];
  /** Phase 10: curated-archive usage count by archive name this video — biases which
   *  near-tied-score candidate gets tried first toward less-used archives, without ever
   *  letting a lower-scoring candidate be preferred over a higher-scoring one. */
  usedArchiveNames: Map<string, number>;
  /** F3-04: every candidate path adoptClip has considered for a scene (adopted or not), keyed by
   *  sceneIndex. Populated by adoptClip itself (never inferred from a filename pattern), so a
   *  post-scene sweep can safely delete whichever candidates never got adopted by ANY beat once
   *  all of that scene's concurrently-running beats have finished — see
   *  sweepUnadoptedSceneCandidates. Cleared per scene once swept. */
  sceneCandidatePaths: Map<number, Set<string>>;
  /** Render-scoped query cache + provider asset cache + sourcing counters. Lives here rather
   *  than in a module-level store so it is created and discarded with exactly the same lifetime
   *  as usedContentKeys — one render, no cross-render leakage. See createSourcingCache. */
  sourcingCache: SourcingCache;
}

/**
 * Whether we can spend a licensed stock (Pexels/Pixabay) clip on this beat.
 */
function canUseLicensedStockBeat(dedup: VisualDedupState): boolean {
  if (!dedup.perf.minimizeStockFootage) return true;
  if (dedup.perf.maxStockBeatsPerVideo <= 0) return false;
  return dedup.stockBeatsUsed < dedup.perf.maxStockBeatsPerVideo;
}

function markLicensedStockBeatUsed(dedup: VisualDedupState): void {
  if (dedup.perf.minimizeStockFootage) dedup.stockBeatsUsed++;
}

const MAX_CURATED_INTERVIEW_CLIPS_PER_VIDEO = 2;

function curatedInterviewBudget(dedup: VisualDedupState): { used: number; max: number } {
  return { used: dedup.curatedInterviewClipsUsed, max: MAX_CURATED_INTERVIEW_CLIPS_PER_VIDEO };
}

function curatedImageBudget(dedup: VisualDedupState): { used: number; max: number } {
  const max = archiveMaxImageClipsPerVideo(dedup.videoLength);
  const used = Math.max(dedup.curatedImageClipsUsed, dedup.stillPhotosUsedGlobal);
  return { used, max };
}

function canUseDocumentaryStill(dedup: VisualDedupState): boolean {
  const { used, max } = curatedImageBudget(dedup);
  return used < max;
}

function markDocumentaryStillUsed(dedup: VisualDedupState): void {
  dedup.stillPhotosUsedGlobal++;
  dedup.curatedImageClipsUsed = Math.max(dedup.curatedImageClipsUsed, dedup.stillPhotosUsedGlobal);
}

function archiveNeedsOpeningFootage(dedup: VisualDedupState): boolean {
  if (isFastShortVideoLength(dedup.videoLength)) return false;
  if (!curatedArchiveOnlyVisuals() || !archivePreferVideoClips()) return false;
  return dedup.archiveVideoClipsUsed < archiveMinVideoClipsTarget(dedup.videoLength);
}

/**
 * After the turbo threshold, prefer stock and skip slow archive retries.
 *
 * RONDE 81: no longer 1-minute only. The threshold is a fraction of the length's own wall-clock
 * target (see escalationThresholdMs), so a 1-minute video keeps its 5-minute trigger and a long
 * video gets the same shape scaled to its budget instead of no escalation at all.
 */
function visualSourcingTurbo(dedup: VisualDedupState): boolean {
  if (!dedup.pipelineStartedMs) return false;
  return Date.now() - dedup.pipelineStartedMs > visualSourcingTurboMs(dedup.videoLength);
}

/** Late in the budget — archive+stock parallel race to guarantee finish before the hard cap.
 *  RONDE 81: applies to every length, at that length's own threshold. */
function isPipelineRushMode(dedup: VisualDedupState): boolean {
  if (!dedup.pipelineStartedMs) return false;
  return Date.now() - dedup.pipelineStartedMs > pipelineRushModeMs(dedup.videoLength);
}

/** Last resort before the hard cap — short archive+stock race, then guaranteed clips.
 *  RONDE 81: applies to every length, at that length's own threshold. */
function isPipelineEmergencyFinish(dedup: VisualDedupState): boolean {
  if (!dedup.pipelineStartedMs) return false;
  return Date.now() - dedup.pipelineStartedMs > pipelineEmergencyFinishMs(dedup.videoLength);
}

function ensurePipelineForceExport(dedup: VisualDedupState): void {
  if (!isPipelineEmergencyFinish(dedup)) return;
  if (!dedup.forceExportMode) {
    dedup.forceExportMode = true;
    console.warn(
      `[Pipeline] Force-export mode (≥${Math.round(pipelineEmergencyFinishMs(dedup.videoLength) / 60_000)} min) — finishing with archive+stock then compose`
    );
  }
}

function markCuratedArchiveClipUsage(dedup: VisualDedupState, clipPath: string): void {
  if (isCuratedPreparedStillClip(clipPath)) {
    markDocumentaryStillUsed(dedup);
    return;
  }
  if (curatedClipPathAssetId(clipPath) != null) {
    dedup.archiveVideoClipsUsed++;
  }
}

export function createVisualDedupState(
  perf: PipelinePerfProfile,
  topic?: { primaryPerson?: string; personTopicLock?: boolean; videoId?: number }
): VisualDedupState {
  const state: VisualDedupState = {
    usedPaths: new Set(),
    searchMemoryMetrics: createSearchMemoryRecallMetrics(),
    recalledAssetIds: new Set(),
    visualDedupStats: createVisualDedupStats(),
    openWebPolicyStats: createOpenWebPolicyStats(),
    usedProviderKeys: new Set(),
    usedPexelsIds: new Set(),
    usedPixabayIds: new Set(),
    usedContentKeys: new Set(),
    usedFunnelCandidateIds: new Set(),
    usedCategories: new Map(),
    globalBeatIndex: 0,
    muskHeroFetchUsed: false,
    lastMuskStockClip: null,
    lastRealClip: null,
    aiClipsUsed: 0,
    rescueAiClipsUsed: 0,
    klingClipsUsed: 0,
    entityYoutubeFetchesUsed: 0,
    stockBeatsUsed: 0,
    grayPadScenes: [],
    montageShortfalls: [],
    sceneRescueColorFallbackCount: 0,
    stillPhotosThisScene: 0,
    stillPhotosMaxThisScene: 0,
    stillPhotosUsedGlobal: 0,
    usedImageUrls: new Set(),
    usedCuratedAssetIds: new Set(),
    usedCuratedStorageUrls: new Set(),
    usedFingerprints: [],
    usedArchiveNames: new Map(),
    sceneCandidatePaths: new Map(),
    curatedInterviewClipsUsed: 0,
    curatedImageClipsUsed: 0,
    archiveVideoClipsUsed: 0,
    visualBeatsCompleted: 0,
    visualBeatsTotal: 0,
    videoLength: "15-20",
    motionGraphicsUsed: 0,
    archiveCandidatePool: null,
    curatedStorageUrlById: new Map(),
    archiveAssetsCache: new Map(),
    varietySeed: 0,
    crossVideoExcludeIds: new Set(),
    composeFetchExemptScenes: new Set(),
    archiveSourcingAudits: [],
    preparedArchiveClips: new Map(),
    materializedArchiveRaw: new Map(),
    ttsSceneBeats: new Map(),
    sceneBeatsBySceneIndex: new Map(),
    candidateSubjectGate: createCandidateSubjectGateState(),
    lock: Promise.resolve(),
    perf,
    primaryPerson: topic?.primaryPerson?.trim() ?? "",
    personTopicLock: Boolean(topic?.personTopicLock && topic?.primaryPerson?.trim()),
    usedPexelsAnchors: new Map(),
    currentBeatTopicKey: "",
    clipRejectAudit: createClipRejectAudit(),
    beatOutcomeAudit: createBeatOutcomeAudit(),
    clipAdoptAudit: createClipAdoptAudit(),
    coverageDecisions: [],
    subjectFallbackBeats: new Set<string>(),
    beatImageGate: createBeatImageGateState(),
    beatRelevance: createBeatRelevanceLedger(),
    beatImageRejectedIds: new Set<string>(),
    mismatchTally: createMismatchTally(),
    mismatchResearchedBeats: new Set<string>(),
    researchTally: createResearchTally(),
    extendHold: createExtendHoldState(),
    lastMismatchByBeat: new Map<string, MismatchKind>(),
    segmentGeoLock: null,
    stepTiming: new PipelineStepTiming(),
    assetDirectorSceneClips: [],
    assetDirectorPrevSceneClips: [],
    assetDirectorActiveEntity: null,
    assetDirectorActiveLocation: null,
    assetDirectorActiveEra: null,
    assetDirectorCallbacksPlaced: new Map(),
    clipAnnotationMeta: new Map(),
    beatRhythmTargets: new Map(),
    graphicClips: new Map(),
    graphicsUsageSummary: emptyUsageSummary(),
    consecutiveArchiveBeats: 0,
    editorialMemory: null,
    tasteModelCtx: {
      clipUsageCount: new Map(),
      recentShotHistory: [],
      recentEmotions: [],
      activeEntity: null,
      activeEra: null,
      beatText: "",
    },
    strictRefillAttemptedScenes: new Set(),
    historicalCascadeAttemptedBeats: new Set(),
    sourcingCache: createSourcingCache(topic?.videoId),
    movingClipCount: 0,
    stillClipCount: 0,
    usageLedger: newLedger(),
    planRescueMissStreak: 0,
  };
  // RONDE 86: every recordClipAdopt call in this file hands over `dedup.clipAdoptAudit`, so
  // binding the ledger to that array once here wires lineage into all of them at once — and
  // makes it impossible for a future adoption route to record an audit entry without one.
  bindLineageLedger(state.clipAdoptAudit, state.sourcingCache.lineage);
  /**
   * RENDER 563 — the same binding, for the question "did anybody look at this picture".
   *
   * Bound here for the identical reason stated above: all 35 adoption sites hand over this one
   * array, so a route cannot adopt a beat's picture without the relevance ledger being reachable
   * at the moment it does. That is what lets the render NAME the routes that adopt unjudged
   * footage instead of anyone reading 35 call sites and deciding which look risky.
   */
  bindRelevanceLedger(state.clipAdoptAudit, state.beatRelevance);
  // Same reasoning on the refusal side: recordClipReject is the one point every gate reports to.
  state.clipRejectAudit.lineage = state.sourcingCache.lineage;
  return state;
}

