type VisualAdoptOptions = {
  muskTopic?: boolean;
  personTopic?: boolean;
  primaryPerson?: string;
  keywords?: string[];
  sceneText?: string;
  videoTitle?: string;
  /** Rich CLIP query context (semantic summary, [visual:] cue). */
  visualDescription?: string;
  semanticSummary?: string;
  /** Hero/opening: require Tesla/SpaceX tokens in slug or query. */
  requireMuskBrand?: boolean;
  /** Clip must match words in the beat narration (real footage on-topic). */
  requireBeatMatch?: boolean;
  /** Vidrush literal matching: reject clips with zero narration overlap. */
  scriptAnchored?: boolean;
  /** Script-matched still fallback — trust search query, skip strict entity/person gates. */
  scriptImageFallback?: boolean;
};

async function withVisualDedupLock<T>(dedup: VisualDedupState, fn: () => Promise<T>): Promise<T> {
  let release!: () => void;
  const gate = new Promise<void>((resolve) => {
    release = resolve;
  });
  const prev = dedup.lock;
  dedup.lock = prev.then(() => gate);
  await prev;
  try {
    return await fn();
  } finally {
    release();
  }
}

const BLOCKED_STOCK_TAGS_RE =
  /emoji|cartoon|animation|icon|illustration|graphic|pattern|sticker|clipart|motion graphics|3d render|abstract background|wallpaper|seamless loop|looping|campfire|bonfire|fireplace|bbq|barbecue|driving|dashcam|highway|bridge|miniature|scale model|toy|diorama|tabletop|model rocket|shuttle|saturn|apollo|lunar|moon landing|moon surface|science fiction|sci-fi|vhs|glitch|vintage space|archival|textile|weaving|loom|garment factory|fabric mill|crime scene|forensic|police tape|news reporter|journalist|reporter microphone|hazmat suit|investigation|murder|courtroom/i;

const MUSK_TOPIC_TOKENS = ["tesla", "spacex", "musk", "electric", "ev", "battery", "gigafactory", "falcon", "starship", "cybertruck", "automotive", "rocket", "launch"];

/** When narration names a real company/product, clip slug/query must show that same entity (real-world footage). */
type RealEntityRule = {
  id: string;
  mentionRe: RegExp;
  clipMustMatchRe: RegExp;
  stockQueries: string[];
  youtubeQueries: string[];
  /**
   * RONDE 177 — WHAT the named entity is.
   *
   * Added so the cinematic engine's `VisualIntent.brands` / `.companies` / `.objects` can be filled
   * from a table that already knows every one of these names, instead of a second name list or a
   * guess made at read time. Tesla is a company and the Cybertruck is a product; that is a fact
   * about the world, not a search term, and nothing in the query path reads this field.
   *
   * `person` is here so the people in this table are NOT offered as brands. A beat that says
   * "Elon Musk" would otherwise put an animated icon labelled "Elon Musk" on screen, and the
   * person channel (extractPersonNamesFromText) already answers that question properly.
   */
  kind: "person" | "company" | "brand" | "object";
};

/**
 * RONDE 100B — the entity's NAME is proven by the mention; its activities are not.
 *
 * These lists used to append an activity to every name: "Kylie Jenner red carpet", "Kylie Jenner
 * makeup launch", "Elon Musk Tesla keynote", "Tesla Model 3 production line", "Titanic sinking
 * 1912 documentary" — and stockQueries carried bare genre words like "celebrity", "fashion",
 * "car", "brain", "technology". A beat that says "Kylie Jenner" proves that Kylie Jenner is the
 * subject. It does not prove a red carpet, a makeup launch, or an interview; those were chosen
 * by this table, not by the script, and a provider asked for a red carpet will happily return
 * one whatever the narration was about.
 *
 * What remains is the entity's own proper name — including full product names like "Falcon 9"
 * and "RMS Titanic", which are names rather than invented topics. When the narration DOES
 * describe an activity, scriptEventSearchQueries supplies that word from the beat itself, and
 * the two combine on the evidence instead of on a guess.
 *
 * mentionRe and clipMustMatchRe are untouched: they filter candidates, they do not build
 * queries, and loosening or tightening a filter is a separate question from inventing a term.
 */
const REAL_ENTITY_RULES: RealEntityRule[] = [
  {
    id: "kylie",
    kind: "person",
    mentionRe: /\b(kylie\s+jenner|kylie\b|jenner\b)/i,
    clipMustMatchRe: /\b(kylie|jenner|kardashian|celebrity|influencer|makeup|fashion)\b/i,
    stockQueries: ["Kylie Jenner"],
    youtubeQueries: ["Kylie Jenner"],
  },
  {
    id: "musk",
    kind: "person",
    mentionRe: /\b(elon\s+musk|musk)\b/i,
    clipMustMatchRe: /\b(musk|elon|tesla|spacex)\b/i,
    stockQueries: ["Elon Musk"],
    youtubeQueries: ["Elon Musk"],
  },
  {
    id: "tesla",
    kind: "company",
    mentionRe: /\btesla\b/i,
    clipMustMatchRe: /\btesla\b/i,
    stockQueries: ["Tesla"],
    youtubeQueries: ["Tesla"],
  },
  {
    id: "spacex",
    kind: "company",
    mentionRe: /\bspacex\b/i,
    clipMustMatchRe: /\b(spacex|falcon|starship)\b/i,
    stockQueries: ["SpaceX"],
    youtubeQueries: ["SpaceX"],
  },
  {
    id: "falcon9",
    kind: "brand",
    mentionRe: /\bfalcon\s*9\b/i,
    clipMustMatchRe: /\b(falcon|spacex)\b/i,
    stockQueries: ["Falcon 9"],
    youtubeQueries: ["Falcon 9"],
  },
  {
    id: "starship",
    kind: "brand",
    mentionRe: /\bstarship\b/i,
    clipMustMatchRe: /\b(starship|spacex)\b/i,
    stockQueries: ["Starship"],
    youtubeQueries: ["Starship"],
  },
  {
    id: "cybertruck",
    kind: "brand",
    mentionRe: /\bcybertruck\b/i,
    clipMustMatchRe: /\b(tesla|cybertruck)\b/i,
    stockQueries: ["Cybertruck"],
    youtubeQueries: ["Tesla Cybertruck"],
  },
  {
    id: "gigafactory",
    kind: "brand",
    mentionRe: /\bgigafactory\b/i,
    clipMustMatchRe: /\b(tesla|gigafactory)\b/i,
    stockQueries: ["Gigafactory"],
    youtubeQueries: ["Tesla Gigafactory"],
  },
  {
    id: "model3",
    kind: "brand",
    mentionRe: /\bmodel\s*[3y]\b/i,
    clipMustMatchRe: /\b(tesla|model)\b/i,
    stockQueries: ["Tesla Model 3", "Tesla Model Y"],
    youtubeQueries: ["Tesla Model 3", "Tesla Model Y"],
  },
  {
    id: "starlink",
    kind: "brand",
    mentionRe: /\bstarlink\b/i,
    clipMustMatchRe: /\b(starlink|spacex|satellite)\b/i,
    stockQueries: ["Starlink"],
    youtubeQueries: ["SpaceX Starlink"],
  },
  {
    id: "neuralink",
    kind: "company",
    mentionRe: /\bneuralink\b/i,
    clipMustMatchRe: /\b(neuralink|brain|neuroscience)\b/i,
    stockQueries: ["Neuralink"],
    youtubeQueries: ["Neuralink"],
  },
  {
    id: "titanic",
    kind: "object",
    mentionRe: /\b(rms\s+titanic|titanic)\b/i,
    clipMustMatchRe: /\b(titanic|rms|liner|iceberg|southampton|1912|shipwreck|white\s+star)\b/i,
    stockQueries: ["RMS Titanic", "Titanic"],
    youtubeQueries: ["RMS Titanic", "Titanic"],
  },
];

/**
 * RONDE 177 — the named entities this beat proves, grouped by what they are.
 *
 * ── Why this reads the rules table rather than the beat ──────────────────────────────────────
 *
 * `VisualIntent.brands` / `.companies` / `.objects` were permanently empty in production, so the
 * shot planner's object rules and the motion-graphics planner's brand icon could never fire. This
 * is what fills them, and the whole point is that it introduces no new matching: the entities come
 * from `extractBeatRealEntities` — the same matcher the retrieval path uses — and each name is the
 * rule's own `stockQueries[0]`, which RONDE 100B already established as the entity's proper name
 * and nothing more.
 *
 * People are deliberately dropped. `extractPersonNamesFromText` is the person channel and it feeds
 * `VisualIntent.people`; offering "Elon Musk" as a brand would put an animated icon with his name
 * on screen.
 */
export function beatNamedEntitiesByKind(beatText: string): {
  brands: string[];
  companies: string[];
  objects: string[];
} {
  const out = { brands: [] as string[], companies: [] as string[], objects: [] as string[] };
  for (const rule of extractBeatRealEntities(beatText)) {
    const name = rule.stockQueries[0]?.trim();
    if (!name) continue;
    const bucket =
      rule.kind === "brand" ? out.brands :
      rule.kind === "company" ? out.companies :
      rule.kind === "object" ? out.objects :
      null;
    if (bucket && !bucket.includes(name)) bucket.push(name);
  }
  return out;
}

export function extractBeatRealEntities(beatText: string, _sceneText = "", _videoTitle = ""): RealEntityRule[] {
  const fromBeat = REAL_ENTITY_RULES.filter((r) => r.mentionRe.test(beatText));
  if (fromBeat.length > 0) return fromBeat;
  for (const cue of extractInlineVisualCues(beatText)) {
    const fromCue = REAL_ENTITY_RULES.filter((r) => r.mentionRe.test(cue));
    if (fromCue.length > 0) return fromCue;
  }
  return [];
}

/**
 * P0/P1 image-quality patch — Fix 1: reliable entity evidence.
 *
 * The search query that produced a candidate is never proof of what the candidate actually
 * shows — a provider can and does return mislabeled/irrelevant hits for a perfectly good query.
 * A candidate only counts as having entity evidence when there is SOME independently-authored
 * signal to check the rule against:
 *   - curated-archive annotation (`meta.annotation`) — the pipeline's own AI-derived
 *     persons/objects/location/era fields for this exact asset, or
 *   - provider-supplied text (`meta.providerText` — title/description/tags, as returned by the
 *     source itself), which is authored independently of whatever query this render happened to
 *     search with.
 * `sourceQuery` and the positional download filename are deliberately excluded — see
 * `clipSatisfiesRealEntities` below.
 */
export function hasReliableEntityEvidence(rules: RealEntityRule[], meta?: CandidateMeta): boolean {
  const ann = meta?.annotation;
  if (ann) {
    const annHay = [
      ...(ann.persons?.named ?? []),
      ...(ann.persons?.categories ?? []),
      ...(ann.objects ?? []),
      ...(ann.actions ?? []),
      ann.location?.continent, ann.location?.country, ann.location?.region, ann.location?.city,
      ann.environment?.setting,
      ann.historicalContext?.event, ann.historicalContext?.period,
      ann.historicalContext?.year, ann.historicalContext?.decade, ann.historicalContext?.century,
    ].filter(Boolean).join(" ").toLowerCase();
    if (annHay && rules.some((r) => r.clipMustMatchRe.test(annHay))) return true;
  }
  const pt = meta?.providerText;
  if (pt) {
    const providerHay = [pt.title, pt.description, pt.tags].filter(Boolean).join(" ").toLowerCase();
    if (providerHay && rules.some((r) => r.clipMustMatchRe.test(providerHay))) return true;
  }
  return false;
}

export function clipSatisfiesRealEntities(
  rules: RealEntityRule[],
  meta?: CandidateMeta
): boolean {
  if (rules.length === 0) return true;
  // P0/P1 image-quality patch: a search query containing "Elon Musk" does not prove Elon Musk
  // is in the pixels — it only proves what we searched for. sourceQuery/filename used to be the
  // sole "evidence" here, which made this gate pass by construction on every candidate a
  // REAL_ENTITY_RULES-triggering query itself produced. Now this gate requires independently-
  // authored evidence (archive annotation or provider title/description/tags); with neither
  // available, the conservative outcome is reject, not an unproven pass.
  return hasReliableEntityEvidence(rules, meta);
}

function realEntityStockQueriesForBeat(beatText: string, sceneText: string, videoTitle?: string): string[] {
  const rules = extractBeatRealEntities(beatText, sceneText, videoTitle ?? "");
  return [...new Set(
    rules.flatMap((r) => r.stockQueries.map((q) => simplifyStockSearchWord(q, beatText, true)))
  )];
}

function realEntityYoutubeQueriesForBeat(beatText: string, sceneText: string, videoTitle?: string): string[] {
  const rules = extractBeatRealEntities(beatText, sceneText, videoTitle ?? "");
  return [...new Set(rules.flatMap((r) => r.youtubeQueries))];
}

function realEntityScore(rules: RealEntityRule[], sourceQuery: string, filePath: string): number {
  if (rules.length === 0) return 0;
  const hay = `${sourceQuery} ${path.basename(filePath)}`.toLowerCase();
  return rules.filter((r) => r.clipMustMatchRe.test(hay)).length * 4;
}

const BLOCKED_STOCK_QUERY_RE =
  /\b(subscribe|like button|thumbs up|thumbs down|social media ui|notification bell|emoji|icon animation|button animation|wallpaper|seamless loop|motion graphics|scale model|miniature|toy rocket|model rocket|space shuttle|shuttle model|saturn v|apollo|lunar|moon landing|moon surface|diorama|replica rocket|mission control|astronaut suit|vintage nasa|archival footage|science fiction|sci-fi|cgi rocket|crime scene|forensic|police tape|murder|courtroom)\b/i;

/** Reject model/CGI/archival-looking clips (Pexels slugs + local filenames). */
const BLOCKED_STOCK_VISUAL_RE =
  /shuttle|saturn|apollo|lunar|moon[- ]?landing|moon[- ]?surface|miniature|diorama|tabletop|model[- ]?rocket|scale[- ]?model|toy[- ]?rocket|replica|maquette|science[- ]?fiction|sci[- ]?fi|cgi|3d[- ]?animation|vhs|glitch|vintage[- ]?space|archival|old[- ]?nasa|space[- ]?shuttle|saturn[- ]?v|rocket[- ]?model|model[- ]?launch|volkswagen|vw\b|ford\b|bmw|mercedes|audi\b|toyota factory|honda factory|container ship|cargo ship|freight ship|bulk carrier|ferry|passenger boat|catamaran|harbor cruise|shipping port|port crane|logistics hub|cargo terminal|container terminal|river boat|canal boat|textile mill|weaving factory|yarn factory|fabric mill|sewing factory|highway|motorway|freeway|country road|rural road|pickup truck|desert road|coastal road|dashcam|night driving/i;

const BLOCKED_MUSK_COMPETITOR_RE =
  /\b(volkswagen|vw|ford|gm|general motors|bmw|mercedes|audi|toyota|honda|hyundai|kia|rivian|lucid)\b/i;

/** Wildlife/nature stock that must never appear on Musk/Tesla/SpaceX videos. */
const MUSK_OFFTOPIC_VISUAL_RE =
  /\b(dolphin|dolphins|whale|whales|shark|sharks|sea turtle|ocean wildlife|underwater mammal|reef|jellyfish|penguin|polar bear|safari|zoo animal|aquarium|swimming with|marine life|tropical fish)\b/i;

/** Animals / random nature B-roll that must not appear on named-celebrity videos (e.g. Kylie → flamingos). */
const PERSON_OFFTOPIC_VISUAL_RE =
  /\b(flamingo|flamingos|peacock|parrot|zoo|safari|wildlife|aquarium|dolphin|whale|penguin|giraffe|elephant|lion|tiger|bear|crocodile|snake|monkey|gorilla|zebra|hippo|bird flock|flock of birds|exotic bird|pink birds)\b/i;

/** Opening = hero Tesla car / SpaceX pad first. */
const OPENING_MUSK_QUERIES = HERO_MUSK_QUERIES;

/** Only these rocket/space queries may yield rocket-category clips on Musk/Tesla topics. */
const MUSK_APPROVED_ROCKET_QUERY_RE =
  /\b(rocket|spacex|falcon|starship)\b|falcon\s*9.*(land|boost|recover|drone\s*ship)|starship.*(pad|boca|texas|static)|spacex.*crew\s*dragon/i;

function stockVisualCategory(query: string, filePath?: string): string {
  const combined = `${query} ${path.basename(filePath ?? "")}`.toLowerCase();
  if (/miniature|diorama|tabletop|toy|model rocket|scale model|saturn|apollo|lunar|moon[- ]?landing|moon[- ]?surface|space shuttle|shuttle|vhs|glitch|sci[- ]?fi|cgi/.test(combined)) {
    return "blocked_model";
  }
  if (/textile|weaving|loom|yarn factory|fabric mill|sewing factory|ferry|catamaran|river boat|canal|harbor cruise|container ship|cargo ship|shipping port|port crane|logistics hub|cargo terminal|container terminal|warehouse district|distribution center|highway|motorway|freeway|country road|rural road|pickup truck|pickup|semi truck|freight truck|delivery truck|desert road|coastal road|dashcam/.test(combined)) {
    return "blocked_offtopic";
  }
  if (/\b(pickup|pick-up|off[- ]?road truck)\b/.test(combined) && !/\btesla\b/.test(combined)) {
    return "blocked_offtopic";
  }
  if (/gigafactory|solar.*(factory|plant|roof)|factory.*solar|solar panel.*roof/.test(combined)) return "gigafactory";
  if (/solar|photovoltaic|panel array|sun panel/.test(combined)) return "solar";
  if (/tesla|supercharger|model [3syx]|cybertruck/.test(combined)) return "tesla";
  if (/falcon|spacex|starship|rocket|launch pad|booster|spacecraft|ignition/.test(combined)) return "rocket";
  if (/robot arm|humanoid|cybernetic|prosthetic arm/.test(combined)) return "robot";
  if (/assembly line|manufacturing|factory|gigafactory|welding plant/.test(combined)) return "factory";
  if (/astronaut|mission control|orbit|satellite deploy|space station/.test(combined)) return "space";
  return "generic";
}

function categoryLimitFor(dedup: VisualDedupState, category: string, muskTopic = false): number {
  if (muskTopic) {
    if (category === "rocket") return 1;
    if (category === "space") return 0;
    if (category === "generic") return 2;
  }
  return STOCK_CATEGORY_LIMITS[category] ?? 2;
}

function muskBrandScore(sourceQuery: string, filePath: string): number {
  const t = `${sourceQuery} ${path.basename(filePath)}`.toLowerCase();
  let s = 0;
  if (/\btesla\b/.test(t)) s += 3;
  if (/\bspacex\b/.test(t)) s += 3;
  if (/\bfalcon\b|\bstarship\b|\bcybertruck\b/.test(t)) s += 2;
  return s;
}

function hasMuskBrandSignal(sourceQuery: string, filePath: string): boolean {
  if (muskBrandScore(sourceQuery, filePath) >= 1) return true;
  return /\b(tesla|spacex|falcon|starship|cybertruck|gigafactory|supercharger|model 3)\b/i.test(sourceQuery);
}

function categoryAtLimit(dedup: VisualDedupState, category: string, muskTopic = false): boolean {
  if (category === "blocked_model" || category === "blocked_offtopic") return true;
  const limit = categoryLimitFor(dedup, category, muskTopic);
  return (dedup.usedCategories.get(category) ?? 0) >= limit;
}

function pickMuskGoldenQuery(globalBeat: number, beatIndex = 0): string {
  const idx = (globalBeat * 3 + beatIndex) % GOLDEN_MUSK_QUERIES.length;
  return GOLDEN_MUSK_QUERIES[idx];
}

/** Normalize scene stock fields from scene narration (not video title). */
function sanitizeSceneStockQueries(scene: Scene, videoTitle?: string): void {
  const sceneScript = scene.text.trim();
  const persons = resolveScenePersons(scene, videoTitle);
  const fromScene = stockQueryFromBeatScript(sceneScript, persons, sceneScript, videoTitle);
  const queries = buildBeatVisualQueryList(sceneScript, scene, videoTitle, persons, 4);
  if (scene.literalVisualCue && PERSON_OFFTOPIC_VISUAL_RE.test(scene.literalVisualCue)) {
    scene.literalVisualCue = fromScene;
  }
  scene.pexelsQuery = fromScene;
  scene.visualCue = fromScene;
  scene.pexelsQueries = queries.length > 0 ? queries : [fromScene];
  scene.brollQueries = persons.length > 0
    ? [`${persons[0]} interview`].filter((q) => q.length >= 3)
    : [];
  if (persons.length > 0) scene.personNames = persons;
}

/** Rewrite LLM scene queries that cause CGI/model rocket hits on Pexels. */
function sanitizeSceneForMuskTopic(scene: Scene, sceneIndex: number, videoTitle?: string): void {
  if (!isMuskTeslaTopic(videoTitle, scene.text)) return;
  const fallback = pickMuskGoldenQuery(sceneIndex, 0);
  const safe = (raw: unknown): string => {
    const trimmed = toQueryString(raw);
    if (!trimmed) return fallback;
    const cat = stockVisualCategory(trimmed);
    if (cat === "blocked_model" || isBlockedStockQuery(trimmed)) return fallback;
    if (cat === "solar" && !/solar|photovoltaic|zon\b|sun\b/.test(scene.text.toLowerCase())) return fallback;
    if (cat === "space") return fallback;
    if (cat === "rocket" && !isMuskApprovedRocketQuery(trimmed)) {
      return "rocket";
    }
    if (isAmbiguousRocketQuery(trimmed)) return fallback;
    return simplifyStockSearchWord(trimmed, scene.text);
  };
  if (scene.literalVisualCue) scene.literalVisualCue = safe(scene.literalVisualCue);
  scene.pexelsQuery = safe(scene.pexelsQuery);
  scene.visualCue = safe(scene.visualCue);
  scene.pexelsQueries = (scene.pexelsQueries ?? []).map(safe).filter((q, i, arr) => q && arr.indexOf(q) === i);
  scene.brollQueries = (scene.brollQueries ?? []).map((q) => {
    const cat = stockVisualCategory(toQueryString(q));
    if (cat === "tesla" || cat === "factory" || cat === "robot") return safe(q);
    return "factory";
  });
}

/** Celebrity/person videos: never search wildlife metaphors (flamingo etc.) — anchor on the named person. */
function sanitizeSceneForPersonTopic(scene: Scene, primaryPerson: string): void {
  const anchor = coercePersonName(primaryPerson);
  if (!anchor) return;
  const first = anchor.split(/\s+/)[0] ?? anchor;
  const safe = (raw: unknown): string => {
    const trimmed = toQueryString(raw);
    // RONDE 93 (§6): an off-topic cue is replaced by the PERSON, not by an interview nobody
    // mentioned. This function exists to stop a celebrity scene searching for flamingos; the
    // full name is the correction, and it is the one term that is actually proven here.
    if (!trimmed || PERSON_OFFTOPIC_VISUAL_RE.test(trimmed)) {
      return anchor;
    }
    if (/\b(wildlife|bird|zoo|animal|flamingo|ocean|dolphin)\b/i.test(trimmed)) {
      return anchor;
    }
    const lower = trimmed.toLowerCase();
    if (!lower.includes(first.toLowerCase()) && !/\b(celebrity|interview|fashion|makeup|red carpet)\b/i.test(lower)) {
      return anchor;
    }
    return simplifyStockSearchWord(trimmed, `${anchor} ${scene.text}`, true);
  };
  if (scene.literalVisualCue) scene.literalVisualCue = safe(scene.literalVisualCue);
  scene.pexelsQuery = anchor;
  // RONDE 93 (§6): the anchor is the person the scene is about — proven. "interview",
  // "celebrity" and "fashion" were three more constants appended to every one of them.
  scene.visualCue = safe(scene.visualCue) || anchor;
  scene.pexelsQueries = [...new Set([anchor, first, ...(scene.pexelsQueries ?? []).map(safe)])]
    .filter((q) => q.length >= 3 && !PERSON_OFFTOPIC_VISUAL_RE.test(q))
    .slice(0, 4);
  scene.brollQueries = [anchor, first].filter((q) => !isBlockedStockQuery(q));
  if (!scene.personNames?.length) scene.personNames = [anchor];
}

function isMuskApprovedRocketQuery(q: string): boolean {
  return MUSK_APPROVED_ROCKET_QUERY_RE.test(q);
}

function isAmbiguousRocketQuery(q: string): boolean {
  const lower = q.toLowerCase();
  if (!/\brocket\b/.test(lower) && !/\bspace shuttle\b/.test(lower)) return false;
  return !isMuskApprovedRocketQuery(q);
}

function isPipelineFallbackClip(filePath: string): boolean {
  return /_fallback\.mp4$/i.test(path.basename(filePath));
}

/**
 * RONDE 34 (point 1): the storage URL of the curated asset a prepared clip came from, or
 * undefined when this render has no record of it.
 *
 * Every markCuratedAssetUsed call site in this file is a generic pushClip/rejectClip helper that
 * only ever receives a clip PATH — the asset row lives inside the sourcing function that already
 * returned. Threading the row out to all eight would mean changing the signature of every
 * adoption callback and every sourcing function feeding them, so instead the id encoded in the
 * filename (which curatedClipPathAssetId already reads, and which the pipeline itself wrote
 * there) is used to look the asset up in state this render has ALREADY loaded.
 *
 * The URL therefore always comes from the asset row, never from the path: the path only supplies
 * the id. When the asset is not in either cache the answer is undefined and the caller marks the
 * id alone — exactly today's behaviour, never a guess.
 */
export function curatedStorageUrlForClip(clipPath: string, dedup: VisualDedupState): string | undefined {
  const assetId = curatedClipPathAssetId(clipPath);
  if (assetId == null) return undefined;
  const memoed = dedup.curatedStorageUrlById.get(assetId);
  if (memoed !== undefined) return memoed || undefined;
  let found: string | undefined;
  for (const pick of dedup.archiveCandidatePool ?? []) {
    if (pick.asset.id === assetId) { found = pick.asset.storageUrl; break; }
  }
  if (found === undefined) {
    outer: for (const rows of dedup.archiveAssetsCache.values()) {
      for (const row of rows) {
        if (row.id === assetId) { found = row.storageUrl; break outer; }
      }
    }
  }
  // Negative results are memoised as "" so a miss costs one scan per asset, not one per adopt.
  dedup.curatedStorageUrlById.set(assetId, found ?? "");
  return found || undefined;
}

async function probeClipMeanLuma(filePath: string, atSec: number): Promise<number | null> {
  for (const bin of FFMPEG_PATHS()) {
    try {
      const { stdout: buf } = await withSceneFetchTimeout(
        () => execFileRaw(bin, [
          "-y", "-threads", "1", "-ss", atSec.toFixed(2), "-i", filePath,
          "-vframes", "1", "-vf", "scale=64:36,format=gray", "-f", "rawvideo", "-",
        ]),
        10_000,
        `luma ${path.basename(filePath)}@${atSec}`
      );
      if (buf.length === 0) return null;
      let sum = 0;
      for (let i = 0; i < buf.length; i++) sum += buf[i];
      return sum / buf.length;
    } catch {
      /* try next ffmpeg binary */
    }
  }
  return null;
}

async function probeClipRegionMeanLuma(
  filePath: string,
  atSec: number,
  region: "left" | "right" | "center"
): Promise<number | null> {
  const crop =
    region === "left"
      ? "crop=iw/8:ih:0:0"
      : region === "right"
        ? "crop=iw/8:ih:iw-iw/8:0"
        : "crop=iw/3:ih/3:iw/3:ih/3";
  for (const bin of FFMPEG_PATHS()) {
    try {
      const { stdout: buf } = await withSceneFetchTimeout(
        () => execFileRaw(bin, [
          "-y", "-threads", "1", "-ss", atSec.toFixed(2), "-i", filePath,
          "-vframes", "1", "-vf", `${crop},scale=32:32,format=gray`, "-f", "rawvideo", "-",
        ]),
        10_000,
        `luma ${path.basename(filePath)}@${atSec}:${region}`
      );
      if (buf.length === 0) return null;
      let sum = 0;
      for (let i = 0; i < buf.length; i++) sum += buf[i];
      return sum / buf.length;
    } catch {
      /* try next ffmpeg binary */
    }
  }
  return null;
}

/** Source has baked-in black pillar/letterbox bars (not our gray pad). */
async function hasEmbeddedBlackBars(filePath: string): Promise<boolean> {
  const sampleTimes = [0.35, 1.0, 2.5];
  for (const t of sampleTimes) {
    const left = await probeClipRegionMeanLuma(filePath, t, "left");
    const right = await probeClipRegionMeanLuma(filePath, t, "right");
    const center = await probeClipRegionMeanLuma(filePath, t, "center");
    if (left === null || right === null || center === null) continue;
    if (left < 24 && right < 24 && center > 38) return true;
  }
  return false;
}

// Phase 12: precomputedDurationSec lets a caller that already has this clip's duration (e.g.
// montageClipPassesComposeGate's probeVideoStreamMeta result) skip the redundant re-probe below.
// Omitting it preserves the original probing behavior for any other caller.
async function isMostlyBlackClip(filePath: string, precomputedDurationSec?: number): Promise<boolean> {
  if (isPipelineFallbackClip(filePath)) return true;
  const curatedStill = isCuratedPreparedStillClip(filePath);
  // Blur-fill stills darken edges by design — not embedded letterbox bars.
  if (!curatedStill && (await hasEmbeddedBlackBars(filePath))) {
    console.warn(`[Pipeline] Rejecting clip with embedded black bars: ${path.basename(filePath)}`);
    return true;
  }
  // Curated archive clips: reject if too dark — threshold 25 (was 12, too permissive).
  // B&W archival clips have low luma by design; we still skip near-pitch-black ones.
  if (curatedArchiveOnlyVisuals() && curatedClipPathAssetId(filePath) != null) {
    const dur = precomputedDurationSec ?? (await probeVideoDurationSec(filePath));
    const sampleTimes = [0.12, 0.45, 1.0, Math.max(0.2, dur * 0.55)];
    let darkCount = 0;
    for (const t of sampleTimes) {
      const ts = Math.min(t, Math.max(0.1, dur - 0.08));
      const luma = curatedStill
        ? await probeClipRegionMeanLuma(filePath, ts, "center")
        : await probeClipMeanLuma(filePath, ts);
      if (luma !== null && luma < 25) darkCount++;
    }
    // Reject if ALL sampled frames are too dark (avoids dropping B&W clips with bright contrast)
    return darkCount >= sampleTimes.length;
  }
  // Railway: one luma sample — full blackdetect runs 3+ FFmpeg probes per clip
  if (IS_RAILWAY) {
    const mid = await probeClipMeanLuma(filePath, 0.5);
    return mid !== null && mid < 24;
  }
  const dur = precomputedDurationSec ?? (await probeVideoDurationSec(filePath));
  const sampleTimes = [0.2, 0.9, 2.0];
  if (dur > 2.5) sampleTimes.push(Math.max(0.3, dur - 0.35));
  let darkSamples = 0;
  for (const t of sampleTimes) {
    const mean = await probeClipMeanLuma(filePath, Math.min(t, Math.max(0, dur - 0.1)));
    if (mean !== null && mean < 34) darkSamples++;
  }
  if (darkSamples >= 2) return true;
  try {
    const cmd =
      `"${FFMPEG_BIN}" -y -i "${filePath}" -vf "blackdetect=d=0.06:pix_th=0.10" -an -f null -`;
    const { stderr } = await withSceneFetchTimeout(() => exec(cmd), 12_000, `blackdetect ${path.basename(filePath)}`);
    const out = typeof stderr === "string" ? stderr : String(stderr ?? "");
    const startMatch = out.match(/black_start:([\d.]+)/g);
    const endMatch = out.match(/black_end:([\d.]+)/g);
    if (!startMatch?.length || !endMatch?.length) return false;
    let blackDur = 0;
    for (let i = 0; i < Math.min(startMatch.length, endMatch.length); i++) {
      const start = parseFloat(startMatch[i].replace("black_start:", ""));
      const end = parseFloat(endMatch[i].replace("black_end:", ""));
      if (!isNaN(start) && !isNaN(end) && end > start) blackDur += end - start;
    }
    const totalDur = dur > 0 ? dur : 4;
    if (totalDur > 0 && blackDur / totalDur > 0.12) return true;
  } catch {
    /* fall through */
  }
  const mid = await probeClipMeanLuma(filePath, 0.5);
  return mid !== null && mid < 28;
}

function isMuskTeslaTopic(videoTitle?: string, sceneText?: string): boolean {
  const text = `${videoTitle ?? ""} ${sceneText ?? ""}`.toLowerCase();
  return /musk|tesla|spacex|starlink|gigafactory|cybertruck|falcon|starship|elon/.test(text);
}

function buildTopicContext(userPrompt: unknown, videoTitle: unknown): string {
  const prompt = asVideoTitleString(userPrompt);
  const title = asVideoTitleString(videoTitle);
  return [prompt, title].filter(Boolean).join(" — ").slice(0, 240);
}

function isOffTopicVisualForMusk(sourceQuery: string, filePath: string): boolean {
  const hay = `${sourceQuery} ${path.basename(filePath)}`.toLowerCase();
  if (MUSK_OFFTOPIC_VISUAL_RE.test(hay)) return true;
  if (/\b(ocean wave|beach sunset|tropical beach|underwater|snorkel|diving)\b/.test(hay) && !hasMuskBrandSignal(sourceQuery, filePath)) {
    return true;
  }
  return false;
}

export function isOffTopicVisualForPersonTopic(
  sourceQuery: string,
  filePath: string,
  primaryPerson: string,
  providerTitle?: string
): boolean {
  const hay = `${sourceQuery} ${path.basename(filePath)}`.toLowerCase();
  if (PERSON_OFFTOPIC_VISUAL_RE.test(hay)) return true;
  const person = coercePersonName(primaryPerson);
  const parts = person.toLowerCase().split(/\s+/).filter((p) => p.length >= 3);
  const queryMentionsPerson =
    (parts.length >= 2 && parts.every((p) => hay.includes(p))) ||
    (parts.length === 1 && hay.includes(parts[0]));
  if (queryMentionsPerson) {
    // Point 4 (final production hardening): a query built FROM primaryPerson trivially
    // "mentions" them — that alone is not independent evidence the visual actually shows that
    // person. When the provider itself supplied real title text, corroborate against it before
    // trusting the query's self-reference: if the title clearly points somewhere else (matches
    // one of the existing off-topic blocklists) and doesn't itself mention the person, don't
    // let the query override that. No providerText available -> unchanged existing behavior.
    if (providerTitle && providerTitle.trim()) {
      const titleHay = providerTitle.toLowerCase();
      const titleMentionsPerson =
        (parts.length >= 2 && parts.every((p) => titleHay.includes(p))) ||
        (parts.length === 1 && titleHay.includes(parts[0]));
      if (
        !titleMentionsPerson &&
        (PERSON_OFFTOPIC_VISUAL_RE.test(titleHay) || MUSK_OFFTOPIC_VISUAL_RE.test(titleHay))
      ) {
        return true;
      }
    }
    return false;
  }
  if (/\b(celebrity|interview|red carpet|paparazzi|influencer|makeup|fashion)\b/.test(hay)) return false;
  if (MUSK_OFFTOPIC_VISUAL_RE.test(hay)) return true;
  return false;
}

function hasBlockedStockTags(tags?: string): boolean {
  return BLOCKED_STOCK_TAGS_RE.test(tags ?? "");
}

function isBlockedStockQuery(q: string): boolean {
  if (BLOCKED_STOCK_QUERY_RE.test(q)) return true;
  if (isAmbiguousRocketQuery(q)) return true;
  if (/\b(highway|motorway|freeway|country road|rural road|pickup truck|off road truck|desert road|coastal road|ferry route)\b/i.test(q)) {
    return true;
  }
  return false;
}

function isRejectedPexelsVideo(video: { url?: string }): boolean {
  const slug = (video.url ?? "").toLowerCase();
  return BLOCKED_STOCK_VISUAL_RE.test(slug) || BLOCKED_MUSK_COMPETITOR_RE.test(slug);
}

function isRejectedStockClip(filePath: string, sourceQuery = ""): boolean {
  const combined = `${sourceQuery} ${path.basename(filePath)}`.toLowerCase();
  if (BLOCKED_STOCK_VISUAL_RE.test(combined)) return true;
  if (hasBlockedStockTags(combined)) return true;
  return false;
}

function isPublishableChapterTitle(title: string | undefined): boolean {
  if (!title?.trim()) return false;
  const lower = title.trim().toLowerCase();
  const blocked = new Set([
    "hook", "call to action", "cta", "intro", "introduction", "outro", "conclusion", "opening", "closing",
  ]);
  if (blocked.has(lower)) return false;
  if (/^(section|part|chapter|scene)\s*\d*$/i.test(lower)) return false;
  return title.trim().length >= 4;
}

// ─── Visual dedup: stable per-provider asset identity ──────────────────────
// Every external fetch*Clips function below (Internet Archive, YouTube CC, Wikimedia,
// Flickr, SepiaSearch, Europeana, Vimeo, media.ccc, NASA, NARA) discards its provider's own
// stable ID (archive.org identifier, YouTube videoId, Commons page title, etc.) once it
// returns a bare downloaded file path — so two different fetch cascades (e.g. the historical
// tier cascade in fetchHistoricalBeatVideo and researchBeatClipUnified's own parallel search)
// that independently find the SAME underlying asset each produce a differently-named local
// file, and the old clipContentKey() (file:${size}:${basename}) never recognized them as the
// same content. providerAssetKey + tagPathWithProviderAsset close that gap without changing
// any fetch function's return type: the provider ID is hashed (never the raw id — keeps
// arbitrary titles/URIs with spaces/colons/slashes out of on-disk filenames and out of the
// keyword-based reject filters that scan basenames) and embedded directly in the downloaded
// filename, so clipContentKey can recover the exact same key regardless of which cascade,
// sceneIndex, or file-tag produced the file — see the PROVIDER_ASSET_TAG_RE branch below.
// Exported (visibility only, no logic changed) so the visual-dedup test suite can assert on
// exact key equality/inequality directly, matching the F3-48-style precedent elsewhere in this
// file for exporting a pure helper purely so a test can cover it without spinning up network mocks.
/**
 * RONDE 135 — one definition, in the module that owns dedup identity.
 *
 * This function's body used to live here while visualDedupRegistry kept a SECOND, different one
 * for the very same Set — see providerAssetIdentityKey there for what that cost. Re-exported under
 * its own long-standing name so every existing caller and test is unchanged.
 */
export function providerAssetKey(provider: string, id: string): string {
  return providerAssetIdentityKey(provider, id);
}

/** Embeds a providerAssetKey into a downloaded clip's filename (right before the extension) so
 *  clipContentKey can recover it post-download without any fetch function's return type
 *  changing. No-ops (returns outPath unchanged) when id is empty — callers then fall back to
 *  clipContentKey's existing file:${size}:${basename} heuristic, per the documented fallback
 *  chain (stable provider ID → canonical URL → existing content-key heuristic).
 */
export function tagPathWithProviderAsset(
  outPath: string,
  provider: string,
  id: string | undefined,
  /**
   * RONDE 88 — the render's sourcing cache, so the lineage is opened HERE.
   *
   * RONDE 87 recorded external provenance inside putCachedProviderAsset, gated on the cache entry
   * carrying a `localPath`. Nothing in the codebase ever writes that field: all eighteen callers
   * pass metadata only. The branch was dead, so every external provider — Wikimedia, Internet
   * Archive, YouTube CC, Pexels, SepiaSearch, NARA, Europeana, NASA, LoC, Flickr — produced no
   * lineage record at all and would have reported as UNVERIFIED in its own audit. Only the curated
   * archive, which opens its record from the DB row, was ever covered.
   *
   * This function is the correct place and always was: it is called by every downloader at the
   * one instant the provider NAME, the provider's own ASSET ID and the destination PATH are all in
   * hand, straight from that provider's API response. Nothing is read from a filename.
   *
   * Optional so the pure string behaviour is unchanged for any caller that has no cache (tests,
   * tools). Recorded BEFORE the download runs, matching the curated path, so a failed download has
   * a record to attach its reason to instead of vanishing into a bare count.
   */
  cache?: SourcingCache,
  meta?: {
    sceneIndex?: number;
    beatIndex?: number;
    sourceUrl?: string;
    title?: string;
    mediaType?: "video" | "image" | "graphic" | "unknown";
    query?: string;
    /** RONDE 96: the narration this asset is meant to illustrate, when the caller knows it. */
    beatText?: string;
    /**
     * RONDE 95 (§2) — the gate route that produced this candidate.
     *
     * Every downloader knows its own name; none of them passed it on, so a clip could be traced
     * back to the words it was found by but not to the call site that chose them. The label is the
     * same one the [SearchGate] report uses, so a provider whose results go wrong can be followed
     * from the summary line to the exact fetcher and then to the individual assets it produced.
     */
    searchRoute?: string;
  }
): string {
  if (!id?.trim()) return outPath;
  const key = providerAssetKey(provider, id).replace(":", "-");
  const ext = path.extname(outPath);
  const tagged = `${outPath.slice(0, -ext.length)}__pid_${key}${ext}`;
  if (cache?.lineage) {
    const contentKey = providerAssetKey(provider, id);
    if (!cache.lineage.resolve(tagged, contentKey)) {
      const record = cache.lineage.createLineage({
        videoId: cache.lineage.videoId,
        sceneIndex: meta?.sceneIndex ?? -1,
        beatIndex: meta?.beatIndex ?? -1,
        beatText: meta?.beatText,
        candidateId: contentKey,
        contentKey,
        provider,
        providerAssetId: id,
        sourceUrl: meta?.sourceUrl,
        localPath: tagged,
        mediaType: meta?.mediaType ?? "unknown",
        query: meta?.query,
        searchRoute: meta?.searchRoute,
        assetTitle: meta?.title,
        route: "primary",
      });
      cache.lineage.recordEvent(record.lineageId, "DOWNLOAD_STARTED", { status: "OK" });
    }
  }
  return tagged;
}

/**
 * RONDE 88: the download that `tagPathWithProviderAsset` opened a lineage for either produced the
 * file or it did not, and both are facts worth recording against the asset.
 *
 * Called by each downloader once it knows the outcome. A no-op when the ledger never saw the path
 * — which is itself visible, as a candidate that reached a download without being recorded.
 */
export function recordProviderDownloadOutcome(
  cache: SourcingCache | undefined,
  taggedPath: string,
  ok: boolean,
  reason?: string
): void {
  if (!cache?.lineage) return;
  const record = cache.lineage.resolve(taggedPath);
  if (!record) return;
  if (ok) {
    cache.lineage.recordEvent(record.lineageId, "DOWNLOAD_SUCCEEDED", { status: "OK" });
  } else {
    cache.lineage.recordEvent(record.lineageId, "DOWNLOAD_FAILED", {
      status: "FAILED",
      reason: normalizeFailureReason(reason),
    });
  }
}

// ─── Render-scoped sourcing cache (query cache + provider asset cache) ─────
// Deliberately NOT a second dedup/cache system: this hangs off the existing VisualDedupState
// (see its `sourcingCache` field) so it is created, scoped and discarded with exactly the same
// lifetime as usedContentKeys/usedPaths, and it reuses providerAssetKey — the same identity
// function the pre-download dedup gate and clipContentKey already agree on — as its asset key.
//
// Two distinct jobs, one object:
//  * queries: the same provider + the exact same normalized query must not hit the network twice
//    within one render. Cached at the *parsed search payload* level rather than by short-
//    circuiting the call to an empty result: a later cascade re-running the identical search
//    still walks the identical candidate list (so it can pick candidate #4 when the first
//    cascade adopted #1), it just does so without a second HTTP round trip. Skipping blind would
//    have silently reduced how many candidates a second cascade could consider.
//  * assets: per-provider-asset metadata/license verdicts, so an asset that two cascades both
//    surface pays for its metadata + license check exactly once per render.
//
// Conservative by construction (per spec): exact normalized-string equality only — "World War II
// Germany" and "Germany during World War II" stay separate entries. No semantic/fuzzy matching.
export interface ProviderAssetCacheEntry {
  provider: string;
  providerAssetId: string;
  canonicalUrl?: string;
  /** Raw provider metadata payload, as already parsed by the fetcher. */
  metadata?: unknown;
  /** Result of the provider's license check — false is cached too, so a rejected asset
   *  surfaced again by another cascade is not re-fetched just to be rejected again. */
  licenseAllowed?: boolean;
  /**
   * RONDE 160 (FASE 4) — the licence the provider ITSELF reports, kept as metadata.
   *
   * Deliberately separate from `licenseAllowed`, which is this pipeline's yes/no verdict. The two
   * answer different questions and only one of them survives a policy change: "YouTube says this
   * carries its standard licence" is a fact about the asset, while "we were allowed to use it" is
   * a fact about the settings at the moment it was fetched. Recording only the verdict is how a
   * finished video ends up unable to say what it was made of.
   *
   * `retrievedUnder` is the search mode that surfaced it, which is not the same claim: a clip
   * found by the unfiltered `any` pass has no licence assertion attached to it at all, and saying
   * so is more honest than guessing one.
   */
  license?: {
    /** The provider's own licence string, verbatim. Absent when the provider did not say. */
    reported?: string;
    /** The retrieval mode that returned it — "creative_common" | "youtube" | "any". */
    retrievedUnder?: string;
    embeddable?: boolean;
    syndicated?: boolean;
  };
  localPath?: string;
  storageUrl?: string;
  durationSec?: number;
  width?: number;
  height?: number;
  fileSize?: number;
  contentKey?: string;
  /**
   * Fase 4 (beeldkwaliteit vervolgpatch): real, provider-authored text — title/description/tags
   * as returned by the source itself, never invented. Kept separate from `metadata` (which stays
   * the provider's raw, differently-shaped payload for the two existing license-check
   * consumers) so this field has one predictable shape for every provider that sets it.
   * Consumed generically in `adoptClip` — see the providerText fallback lookup there — so a
   * provider only needs to call putCachedProviderAsset with this field; no per-provider wiring
   * into AssetDirector is required.
   */
  providerText?: {
    title?: string;
    description?: string;
    tags?: string;
    /**
     * Point 8 (visual-selection quality upgrade): a real, provider-authored date/year string
     * (e.g. archive.org's metadata.date), never invented. Optional — most providers don't
     * expose one, and its absence must never itself be treated as a rejection signal (see
     * historicalDateAlignmentScore).
     */
    dateHint?: string;
  };
}

/** Per-provider counters (Phase 20). Plain numbers on a render-scoped object — no I/O, no
 *  awaits, nothing that can fail or block the render. Surfaced once at the end of a render
 *  through the existing PipelineStepTiming console summary. */
export interface ProviderSourcingMetrics {
  /** RONDE 124 — licence classification counts (see ./youtubeLicenseStatus). */
  licenseVerified: number;
  licenseUnverified: number;
  licenseRejected: number;
  /** How many of this provider's assets reached the finished video. */
  usedCount: number;
  searchCount: number;
  searchLatencyMs: number;
  resultCount: number;
  queryCacheHits: number;
  /** A query was NOT found in the cache and had to actually search — i.e. searchCount's
   *  complement, tracked as its own counter so callers don't have to infer it. */
  queryCacheMisses: number;
  metadataCount: number;
  metadataCacheHits: number;
  /** A provider-asset lookup missed the cache entirely (first sighting of this id this render,
   *  or no sourcingCache supplied). */
  assetCacheMisses: number;
  /** How many times this provider's per-item license determination actually required a network
   *  call (metadata/record fetch that carries the license fields) — providers whose license is
   *  embedded in the search response itself (no separate per-item call) never increment this. */
  licenseCalls: number;
  /** A cached (already-fetched) asset's ALLOWED license verdict was reused instead of
   *  re-fetching metadata/license for it. */
  licenseCacheHits: number;
  /** A cached REJECTED verdict was honoured — the asset was skipped without any network call. */
  licenseRejectedCacheHits: number;
  downloadCount: number;
  downloadCacheHits: number;
  duplicateSkipped: number;
  acceptedCount: number;
  /**
   * RONDE 70 — categories D and E, told apart at last.
   *
   * eligibleCount is bumped where a candidate has passed EVERY gate; adoptedCount only where it
   * actually became a beat's clip. Between the two the file still has to validate and, when the
   * clip needs one, a fair-use transform still has to produce a file. A candidate that clears
   * every gate and falls in that gap is category D, and nothing measured it.
   *
   * acceptedCount is left exactly as it was and is NOT an alias of either: these are two new
   * counters at two distinct points, so `eligible > adopted` is now directly readable.
   */
  eligibleCount: number;
  adoptedCount: number;
}

export interface SourcingCache {
  /** `${provider}|${normalized query}` → parsed search payload from the first execution. */
  queries: Map<string, unknown>;
  /**
   * RONDE 100B — providers whose work FastVid cut short this render.
   *
   * A scope abort is the pipeline running out of budget, not the provider failing. The circuit
   * breakers have distinguished the two since RONDE 68 (isScopeAbortError); the search memory
   * did not, so a cancelled provider was remembered as one that "returned nothing usable" and
   * excluded from the next render on the same subject.
   */
  budgetCancelledProviders: Set<string>;
  /** providerAssetKey(provider, id) → what this render already learned about that asset. */
  assets: Map<string, ProviderAssetCacheEntry>;
  /** provider → counters. */
  metrics: Map<string, ProviderSourcingMetrics>;
  /** visionGateCacheHits() at render start — the gate's counter is a process-wide monotonic
   *  total, so the per-render figure is the delta against this baseline. */
  visionHitBaseline: number;
  /** Render-wide totals (Phase 20). */
  totals: {
    duplicateCandidatesSkipped: number;
    duplicateDownloadsPrevented: number;
    visionCacheHits: number;
    assetCacheHits: number;
    queryCacheHits: number;
  };
  /**
   * RONDE 86: where every clip this render downloads actually came from, and how many candidates
   * survived each funnel stage.
   *
   * Lives on the sourcing cache rather than beside it because this is the one object every
   * provider path already threads — putCachedProviderAsset below is the single choke point at
   * which a provider name, a provider asset id, a canonical URL and a local file path are all in
   * hand at the same instant. Recording provenance anywhere later means recovering it from the
   * filename, which is exactly what stopped working.
   */
  lineage: VisualSourceLedger;
}

let sourcingCacheSeq = 0;

export function createSourcingCache(videoId?: number): SourcingCache {
  sourcingCacheSeq += 1;
  const cache: SourcingCache = {
    queries: new Map(),
    budgetCancelledProviders: new Set(),
    assets: new Map(),
    metrics: new Map(),
    visionHitBaseline: visionGateCacheHits(),
    totals: {
      duplicateCandidatesSkipped: 0,
      duplicateDownloadsPrevented: 0,
      visionCacheHits: 0,
      assetCacheHits: 0,
      queryCacheHits: 0,
    },
    // The render id is only ever compared for equality and printed, so a process-local counter
    // plus the start time is enough to keep two concurrent renders apart in one log stream.
    lineage: new VisualSourceLedger({
      renderId: `r${Date.now().toString(36)}-${sourcingCacheSeq}`,
      videoId,
      // RONDE 87 (§B): every lifecycle event is logged as it happens, so a Railway log alone is
      // enough to reconstruct any clip's whole history. Behind a flag because a long render
      // produces thousands of these and the end-of-render summary answers most questions;
      // VISUAL_LINEAGE_EVENT_LOG=true turns on the per-event trail when a specific clip is in
      // question. The events themselves are ALWAYS recorded — only the printing is optional.
      emit:
        process.env.VISUAL_LINEAGE_EVENT_LOG === "true"
          ? (line: string) => console.log(line)
          : undefined,
    }),
  };
  /**
   * RONDE 167 §7 — teach the ledger how a file path maps to an asset identity, once.
   *
   * `clipContentKey` already turns `scene_N_bM_curated_a<id>.mp4` into `curated:asset:<id>`, which
   * is the only handle the curated archive route has: its record is opened from the DB row and the
   * file it writes is never registered as a path. Every outcome writer looked the clip up by path
   * alone and wrote nothing — measured at zero events.
   *
   * Handing the ledger the resolver rather than patching the five writers is the point. A sixth
   * writer added next round cannot reintroduce the bug by forgetting an argument.
   */
  cache.lineage.setContentKeyResolver(clipContentKey);
  return cache;
}

function emptyProviderMetrics(): ProviderSourcingMetrics {
  return {
    searchCount: 0, searchLatencyMs: 0, resultCount: 0, queryCacheHits: 0, queryCacheMisses: 0,
    metadataCount: 0, metadataCacheHits: 0, assetCacheMisses: 0,
    licenseCalls: 0, licenseCacheHits: 0, licenseRejectedCacheHits: 0,
    // RONDE 124: the three licence outcomes, kept apart so a report can say how much material
    // was refused outright versus merely unproven.
    licenseVerified: 0, licenseUnverified: 0, licenseRejected: 0, usedCount: 0,
    downloadCount: 0, downloadCacheHits: 0,
    duplicateSkipped: 0, acceptedCount: 0,
    eligibleCount: 0, adoptedCount: 0,
  };
}

/**
 * Always returns a counter object, never null — when no cache is supplied (every caller that
 * does not thread one, including all existing tests and any fetch invoked outside a render) it
 * returns a throwaway object whose increments go nowhere.
 *
 * This is deliberately total rather than nullable: a nullable version invites
 * `providerMetrics(cache, p)!.someCount++` at call sites, and that non-null assertion is erased
 * at compile time, so an undefined cache turns a pure metrics increment into a runtime
 * TypeError in the middle of a provider fetch. Metrics must never be able to fail a render.
 */
export function providerMetrics(cache: SourcingCache | undefined, provider: string): ProviderSourcingMetrics {
  /**
   * RONDE 142 — the ambient fallback RONDE 173 gave `cachedProviderSearch`, applied here too.
   *
   * ── The bug, from video 558's own log ────────────────────────────────────────────────────────
   *
   *     [SourcingMetrics]   pexels: searches=13 results=0 …
   *
   * while three Pexels clips were downloaded and trimmed in that same render. Two counters about
   * the same thirteen searches, disagreeing, and one of them impossible.
   *
   * The cause is a split that RONDE 173 half-closed. Thirty-seven of the provider fetchers' call
   * sites pass no `sourcingCache`, so:
   *
   *   · `cachedProviderSearch` falls back to the render's own cache (RONDE 173) and counts the
   *     search there — searches=13 is real;
   *   · every `providerMetrics(sourcingCache, …)` INSIDE that same fetcher still received the
   *     undefined parameter, got a fresh throwaway object from the line below, incremented it, and
   *     dropped it on return — results=0, downloads=0, and every other per-provider number the
   *     fetcher tried to record.
   *
   * So the numbers were not merely low. They were counting two different things: the searches were
   * booked against the render, the results against a value nobody could read.
   *
   * ── Why the fix belongs HERE and not at thirty-seven call sites ──────────────────────────────
   *
   * Threading the cache through every fetcher is the same change made thirty-seven times, and the
   * next fetcher added would reintroduce the bug. One line, in the one function every counter goes
   * through, fixes it for all of them and for the ones not yet written.
   *
   * It cannot double-count: the fallback applies only where `cache` is undefined, which is exactly
   * where nothing was being counted at all. And it is the same ambient cache `cachedProviderSearch`
   * already books the searches against, which is precisely what makes the two agree.
   *
   * The empty object is still returned when there is no render context either — a call from a test
   * or a tool must not invent one.
   *
   * ── One thing this changes that is NOT a log line ────────────────────────────────────────────
   *
   * `claimYoutubeDownloadSlot` reads `downloadCount` through this function. A caller that passed no
   * cache was handed a fresh zeroed object on every single call, so for those callers the
   * render-wide YouTube download ceiling counted from zero every time and therefore bounded
   * nothing — the exact failure RONDE 68 moved the counter off a local to fix, reappearing through
   * the other door. With the fallback in place the ceiling finally holds for them too. That is a
   * real behaviour change and it is the intended one, so it has its own test rather than a mention.
   */
  const active = cache ?? get_activeSourcingCache() ?? undefined;
  if (!active) return emptyProviderMetrics();
  let m = active.metrics.get(provider);
  if (!m) {
    m = emptyProviderMetrics();
    active.metrics.set(provider, m);
  }
  return m;
}

/**
 * RONDE 69: reserve a YouTube download slot, or refuse. Reserve first, download second.
 *
 * Render 534 announced the render-wide ceiling four times with a rising number:
 *
 *     ceiling reached for this RENDER (20/20 downloads, 0 accepted here)
 *                                     (21/20 ...)  (22/20 ...)  (23/20 ...)
 *
 * RONDE 68 had moved the counter onto the render-scoped metrics, which was right, but the check
 * still sat at the top of the candidate loop while the increment ran after the download
 * returned — with two awaits in between (planScriptGuidedClip, fetchRapidApiYoutubeMeta). Node
 * is single-threaded but concurrent: several fetchYouTubeCCClips calls interleave at those
 * await points, all read the same count, and all pass a check that was true when they read it
 * and false by the time they acted on it. A ceiling that is checked and acted on across an
 * await is not a ceiling.
 *
 * Read and write here with nothing awaited between them. Within one event loop turn that IS the
 * atomic operation — no lock, no queue, no new concurrency layer, and nothing shared between
 * renders: the counter is the render's own SourcingCache.
 *
 * The limit is on ATTEMPTS, not on successes. A failed download does not return its slot: the
 * 134 downloads of render 533 were nearly all failures, and a ceiling that only counted the
 * successes is exactly the ceiling that did not hold.
 *
 * Returns true when the slot is yours, false when the render is out.
 */
export function claimYoutubeDownloadSlot(
  cache: SourcingCache | undefined,
  maxDownloads: number
): boolean {
  const m = providerMetrics(cache, "youtube_cc");
  if (m.downloadCount >= maxDownloads) return false;
  m.downloadCount++;
  return true;
}

/** Exact-match normalization only: case-folded and whitespace-collapsed. Intentionally does no
 *  stemming, token sorting or synonym mapping — two differently-worded queries for the same
 *  topic must stay two separate searches (spec: "begin bewust conservatief"). */
export function normalizeProviderQuery(query: string): string {
  return query.toLowerCase().trim().replace(/\s+/g, " ");
}

export function providerQueryCacheKey(provider: string, query: string): string {
  return `${provider}|${normalizeProviderQuery(query)}`;
}

/**
 * Runs `search` at most once per (provider, exact normalized query) per render.
 *
 * `search` must return the already-parsed payload (never a Response — those are single-use).
 * A null/undefined result is cached too: a provider that legitimately returned nothing for this
 * exact query will not return something different 30 seconds later in the same render, and
 * re-asking is precisely the duplicate work this exists to remove.
 */
/**
 * RONDE 89 — the gate, for a fetcher that does not go through cachedProviderSearch.
 *
 * The audit found eight provider searches reaching the network without passing the gate: b-roll,
 * Wikimedia images (v0 and v1), YouTube thumbnails, SerpAPI, Openverse, Unsplash and the RapidAPI
 * YouTube search. Restructuring all eight to route through cachedProviderSearch would change their
 * caching behaviour; this applies the SAME enforcement code at their entry instead.
 *
 * Returns the query when it may be sent, or null when it must not be. A null answer means the
 * caller returns empty — never a substituted or repaired query.
 */
export function admitProviderQuery(
  provider: string,
  query: string | VerifiedSearchQuery,
  route = "legacy_fetcher"
): string | null {
  const decision = searchGateDecision(provider, query, route);
  return decision.admitted ? decision.text : null;
}

/*
 * RONDE 91 (§4) — searchQueryAuditLogEnabled and searchGateDecision moved to searchQueryContract,
 * so that scenePool and wikimediaGeoSearch reach the SAME decision rather than a second copy.
 * admitProviderQuery and cachedProviderSearch below still call it; nothing about the decision
 * itself changed.
 */

export async function cachedProviderSearch<T>(
  cache: SourcingCache | undefined,
  provider: string,
  /**
   * RONDE 89 (§4): a bare string, or a VerifiedSearchQuery carrying its own proof.
   *
   * A string cannot say where it came from, which is exactly why it cannot be trusted here. It is
   * accepted so the pipeline keeps sourcing while the remaining call sites are migrated, but it is
   * counted as a bypass attempt on every single call and named in the end-of-render report — the
   * difference between a known gap and an invisible one.
   */
  query: string | VerifiedSearchQuery,
  search: () => Promise<T>,
  route = "provider_search"
): Promise<T> {
  /**
   * RONDE 88/89/90 — THE provider gate.
   *
   * Every provider search in this file funnels through here, which makes it the one place a query
   * can be refused for all of them at once. RONDE 89's audit found eight fetchers that reached the
   * network without passing this point (b-roll, Wikimedia images v0 and v1, YouTube thumbnails,
   * SerpAPI, Openverse, Unsplash, the RapidAPI YouTube search); they are routed through it now.
   *
   * RONDE 90 moved the decision itself into searchGateDecision, shared verbatim with
   * admitProviderQuery, so the two entry points cannot enforce different contracts. Three
   * outcomes, and only three:
   *   · verified, by the caller's own ticket or against the ambient beat context   -> sent
   *   · anything the validator refuses                                             -> not sent
   *   · nothing backing it at all                                                  -> not sent
   *     in strict mode (the default), counted as a bypass attempt either way
   */
  const decision = searchGateDecision(provider, query, route);
  const text = decision.text;
  if (!decision.admitted) return [] as unknown as T;
  /**
   * RONDE 173 — fall back to the render's own cache when the caller had none to give.
   *
   * `if (!cache) return search()` was the whole leak: 37 of the seven provider fetchers' 72 call
   * sites pass nothing, so a hundred and fifty-six searches in render 555 went to the network with
   * no dedup and no counting. The cache is per-render on RenderCtx, so this changes WHERE the cache
   * comes from and nothing about what a search returns — a hit replays the identical payload the
   * miss stored.
   */
  const activeCache = cache ?? get_activeSourcingCache() ?? undefined;
  if (!activeCache) return search();
  const key = providerQueryCacheKey(provider, text);
  const m = providerMetrics(activeCache, provider);
  if (activeCache.queries.has(key)) {
    m.queryCacheHits++;
    activeCache.totals.queryCacheHits++;
    return activeCache.queries.get(key) as T;
  }
  m.queryCacheMisses++;
  const t0 = Date.now();
  let payload: T;
  try {
    payload = await search();
  } catch (err) {
    // RONDE 100B: remember that this provider was cut off, so the search memory does not read a
    // cancellation as "this source has nothing" — see SourcingCache.budgetCancelledProviders.
    if (isScopeAbortError(err)) activeCache.budgetCancelledProviders.add(provider.trim().toLowerCase());
    throw err;
  }
  m.searchCount++;
  m.searchLatencyMs += Date.now() - t0;
  activeCache.queries.set(key, payload);
  return payload;
}


/** Reads this render's cached knowledge about one provider asset (Phase 6). Callers that go on
 *  to reuse cached metadata/license (rather than just checking a cached rejection) additionally
 *  increment their own provider's metadataCacheHits/licenseCacheHits — this function only
 *  tracks the generic "did we already know this asset" fact. */
export function getCachedProviderAsset(
  cache: SourcingCache | undefined,
  provider: string,
  id: string
): ProviderAssetCacheEntry | null {
  if (!cache || !id?.trim()) return null;
  const hit = cache.assets.get(providerAssetKey(provider, id)) ?? null;
  if (hit) {
    cache.totals.assetCacheHits++;
  } else {
    providerMetrics(cache, provider).assetCacheMisses++;
  }
  return hit;
}

/** Records/merges what this render learned about one provider asset (Phase 6/8). */
export function putCachedProviderAsset(
  cache: SourcingCache | undefined,
  provider: string,
  id: string,
  entry: Partial<ProviderAssetCacheEntry>
): void {
  if (!cache || !id?.trim()) return;
  const key = providerAssetKey(provider, id);
  const prev = cache.assets.get(key);
  const merged: ProviderAssetCacheEntry = {
    ...(prev ?? { provider, providerAssetId: id }),
    ...entry,
    provider,
    providerAssetId: id,
  };
  cache.assets.set(key, merged);
  /**
   * RONDE 88 — this function ENRICHES a lineage record; it does not create one.
   *
   * RONDE 86/87 made it the recorder, gated on `merged.localPath`. That was wrong twice over.
   * Nothing in the codebase ever writes `localPath` — all eighteen callers pass metadata only — so
   * the branch was dead and every external provider went unrecorded. And even had it worked, this
   * function is called for metadata and licence checks on assets that are never downloaded, so it
   * is the wrong moment: it would have filed rows for candidates that produced no clip.
   *
   * tagPathWithProviderAsset is the right moment and is now the only creator — provider, asset id
   * and destination path in one call, before the download. What is genuinely useful here is the
   * provider-authored title and canonical URL, which usually arrive AFTER the tag was stamped. So
   * this fills those in on a record that already exists, and creates nothing.
   */
  // Optional-chained: this function is exported and several callers hand it a hand-built cache
  // object with no ledger on it. Provenance is a best-effort enrichment here, never a requirement.
  const known = cache.lineage?.resolve(`unused:${key}`, merged.contentKey ?? key);
  if (known) {
    if (merged.canonicalUrl && !known.originalUrl) known.originalUrl = merged.canonicalUrl;
    if (merged.storageUrl && !known.sourceUrl) known.sourceUrl = merged.storageUrl;
    if (merged.providerText?.title && !known.assetTitle) known.assetTitle = merged.providerText.title;
  }
}

/**
 * Single choke point for the pre-download dedup skip, so every provider reports the skip the
 * same way. Returns true when this exact asset was already adopted this render — the caller
 * must then `continue` without any metadata/license/download/ffmpeg/CLIP work.
 */
export function providerAssetAlreadyUsed(
  usedProviderKeys: Set<string> | undefined,
  cache: SourcingCache | undefined,
  provider: string,
  id: string | undefined
): boolean {
  if (!id?.trim()) return false;
  if (!usedProviderKeys?.has(providerAssetKey(provider, id))) return false;
  if (cache) {
    cache.totals.duplicateCandidatesSkipped++;
    cache.totals.duplicateDownloadsPrevented++;
    providerMetrics(cache, provider).duplicateSkipped++;
  }
  return true;
}

/** Emits the render's sourcing counters through the existing timing/console tracing. Never
 *  throws and never awaits anything — Phase 20's "metrics mogen de render niet blokkeren".
 *
 *  The provider-level breakdown fields (queryCacheMisses, assetCacheMisses, licenseCalls,
 *  licenseCacheHits, licenseRejectedCacheHits) are summed here from `cache.metrics` rather than
 *  duplicated as separately-incremented render totals — one source of truth, no risk of the two
 *  drifting apart. `videoId` is optional so existing/other call sites need not change. */
export function logSourcingMetrics(cache: SourcingCache | undefined, videoId?: number): void {
  try {
    if (!cache) return;
    const t = cache.totals;
    t.visionCacheHits = Math.max(0, visionGateCacheHits() - cache.visionHitBaseline);

    let searchCount = 0, queryCacheMisses = 0, metadataCount = 0, licenseCalls = 0;
    let licenseCacheHits = 0, licenseRejectedCacheHits = 0, downloadCount = 0, assetCacheMisses = 0;
    for (const m of cache.metrics.values()) {
      searchCount += m.searchCount;
      queryCacheMisses += m.queryCacheMisses;
      metadataCount += m.metadataCount;
      licenseCalls += m.licenseCalls;
      licenseCacheHits += m.licenseCacheHits;
      licenseRejectedCacheHits += m.licenseRejectedCacheHits;
      downloadCount += m.downloadCount;
      assetCacheMisses += m.assetCacheMisses;
    }
    // Render-level rollup, section-10 log format: every field is either an existing tracked
    // total or a straightforward sum of the per-provider counters above — no new mutable state.
    const networkCallsAvoided = t.queryCacheHits + t.assetCacheHits + licenseRejectedCacheHits;
    const downloadsAvoided = t.duplicateDownloadsPrevented;
    console.log(
      `[SourcingMetrics] videoId=${videoId ?? "-"} ` +
      `queryHits=${t.queryCacheHits} queryMisses=${queryCacheMisses} ` +
      `assetHits=${t.assetCacheHits} assetMisses=${assetCacheMisses} ` +
      `metadataCalls=${metadataCount} licenseCalls=${licenseCalls} ` +
      `licenseCacheHits=${licenseCacheHits} licenseRejectedCacheHits=${licenseRejectedCacheHits} ` +
      `downloads=${downloadCount} downloadsAvoided=${downloadsAvoided} ` +
      `duplicateAssetsPrevented=${t.duplicateCandidatesSkipped} ` +
      `networkCallsAvoided=${networkCallsAvoided} visionCacheHits=${t.visionCacheHits} ` +
      `searches=${searchCount} providers=${cache.metrics.size}`
    );
    for (const [provider, m] of [...cache.metrics.entries()].sort()) {
      console.log(
        `[SourcingMetrics]   ${provider}: searches=${m.searchCount} (${m.searchLatencyMs}ms) ` +
        `results=${m.resultCount} queryCacheHits=${m.queryCacheHits} queryCacheMisses=${m.queryCacheMisses} ` +
        `metadata=${m.metadataCount} metadataCacheHits=${m.metadataCacheHits} assetCacheMisses=${m.assetCacheMisses} ` +
        `licenseCalls=${m.licenseCalls} licenseCacheHits=${m.licenseCacheHits} licenseRejectedCacheHits=${m.licenseRejectedCacheHits} ` +
        `downloads=${m.downloadCount} duplicateSkipped=${m.duplicateSkipped} ` +
        `accepted=${m.acceptedCount}`
      );
    }
  } catch {
    /* metrics must never affect a render */
  }
}

const PROVIDER_ASSET_TAG_RE = /__pid_([a-z_]+)-([0-9a-f]{16})(?=\.[A-Za-z0-9]+$)/;

export function clipContentKey(filePath: string): string {
  const curatedId = curatedClipPathAssetId(filePath);
  if (curatedId != null) return curatedAssetContentKey(curatedId);
  const base = path.basename(filePath).replace(/_transformed(?=\.mp4)/, "");
  const providerTag = base.match(PROVIDER_ASSET_TAG_RE);
  if (providerTag) return `${providerTag[1]}:${providerTag[2]}`;
  const vidMatch = base.match(/_vid(\d+)/);
  if (vidMatch) return `stock:vid:${vidMatch[1]}`;
  if (isStillPhotoClip(filePath)) {
    try {
      const buf = fs.readFileSync(filePath);
      const sample = buf.subarray(0, Math.min(buf.length, 48_000));
      const hash = createHash("sha256").update(sample).digest("hex").slice(0, 20);
      return `still:${hash}`;
    } catch {
      /* fall through */
    }
  }
  try {
    const stat = fs.statSync(filePath);
    return `file:${stat.size}:${base}`;
  } catch {
    return base;
  }
}

function montageClipStartSec(_sceneIndex: number, clipIndex: number): number {
  // Archive sources often have black leaders — never skip into them when looping segments.
  if (curatedArchiveOnlyVisuals() || documentaryStyleEnabled()) return 0.04;
  return 0.25 * (clipIndex % 7);
}

function estimateBeatHoldSec(text: string, mergedSentenceCount: number): number {
  if (curatedArchiveOnlyVisuals()) {
    const words = text.replace(/\[visual:[^\]]+\]/gi, "").split(/\s+/).filter(Boolean).length;
    const byWords = words / 2.5;
    const est = mergedSentenceCount >= 2 ? Math.max(byWords, archiveVisualBeatSec()) : byWords;
    return Math.max(archiveVisualMinClipSec(), Math.min(archiveVisualMaxClipSec(), est));
  }
  const words = text.replace(/\[visual:[^\]]+\]/gi, "").split(/\s+/).filter(Boolean).length;
  const byWords = words / 2.4;
  if (mergedSentenceCount >= 2 || byWords > 16) {
    return Math.min(
      VIDRUSH_CLIP_HOLD_SEC,
      Math.max(VIDRUSH_CLIP_MAX_SEC + 0.5, Math.min(byWords, VIDRUSH_CLIP_HOLD_SEC))
    );
  }
  return VIDRUSH_BEAT_SEC;
}



function estimateMontageDurationSec(durations: number[]): number {
  const n = durations.length;
  if (n === 0) return 0;
  const avg = durations.reduce((s, d) => s + d, 0) / n;
  const xfade = n > 1 ? montageXfadeSec(avg) : 0;
  return durations.reduce((s, d) => s + d, 0) - (n - 1) * xfade;
}

function montageClipUsableSec(srcMax: number): number {
  const maxClip = effectiveMaxClipSec();
  if (srcMax <= 0.15) return maxClip;
  const trimStart = montageClipStartSec(0, 0);
  return Math.min(maxClip, Math.max(0.35, srcMax - trimStart - 0.05));
}

function resolveMontageClipEffectiveDur(dur: number, sourceMaxSec?: number): number {
  if (!sourceMaxSec || sourceMaxSec <= 0.15) return dur;
  return Math.min(
    dur,
    Math.max(montageMinOnScreenSec(), sourceMaxSec - montageClipStartSec(0, 0) - 0.05)
  );
}

/** Montage length when trims are capped to each clip's probed source duration. */
function effectiveMontageDurationSec(durations: number[], sourceMaxDurs?: number[]): number {
  const capped = durations.map((d, i) => {
    const srcMax = sourceMaxDurs?.[i] ?? 0;
    if (srcMax > 0.15) {
      return Math.min(d, montageClipUsableSec(srcMax));
    }
    return d;
  });
  return estimateMontageDurationSec(capped);
}

function uniqueClipsInOrder(clips: string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const clip of clips) {
    const key = clipContentKey(clip);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(clip);
  }
  return out;
}

function montageClipInputs(clips: string[]): string {
  return clips.map((c) => `-i "${c}"`).join(" ");
}

/**
 * Tail filler for a montage that came up short against the voice track.
 *
 * RONDE 85 — the picture never stops moving.
 *
 * RONDE 26 replaced a flat grey rectangle with holding the last frame, on the reasoning that a
 * grey box reads as a broken player while a held shot is an ordinary documentary device. Render
 * 536 showed what that costs when the shortfall is large: scene 16 had ONE clip covering 7.0s of
 * a 20.8s scene, the coverage backfill searched for five more and found none, and the export
 * carried a 10.6-second frozen frame. The final video's own QA counted 30 frozen segments.
 *
 * A held frame is now not produced at all. The montage is slowed to fill the gap instead, so the
 * shot the narration is describing stays on screen AND stays in motion. Slowing is not a repeat,
 * so it is also the one filler compatible with strictNoVisualRepeat.
 *
 * RONDE 111 caps the ratio at MAX_COVERAGE_SLOWDOWN.
 *
 * RONDE 85 left it uncapped on purpose, reasoning that a cap would leave a remainder and the only
 * things that could fill a remainder were the two it existed to remove. The reasoning was right
 * about the remainder and wrong about the cure: measured against real ffmpeg, a 10x stretch holds
 * each picture 0.59s — under two new pictures per second, with no interpolation anywhere in the
 * chain to invent the frames in between. That is a slideshow of held frames reached through a
 * different filter, and the render's own freezedetect (2.5s threshold) never reported it.
 *
 * So slowing is a finishing touch, not a source of footage. Past the cap the answer has to come
 * from real pictures, which is why the coverage backfill now spends its extra searches on exactly
 * the scenes that would land here — see ensureArchiveMontageVoiceCoverage. A held frame is what
 * remains when that has genuinely run out, and it says so.
 *
 * MONTAGE_TAIL_PAD=freeze restores RONDE 26's held frame and =grey the original rectangle,
 * either without a redeploy.
 */
export function montageTailPadFilterChain(montageDur: number, targetDur: number, context: string): string {
  const mode = process.env.MONTAGE_TAIL_PAD?.trim().toLowerCase();
  const pad = Math.max(0, targetDur - montageDur);
  if (mode === "grey") {
    console.warn(`[Pipeline] ${context}: montage ${pad.toFixed(2)}s short of voice — grey pad`);
    return `tpad=stop_mode=add:stop_duration=${pad.toFixed(3)}:color=0x2a2a2a,`;
  }
  const plan = planCoverageFill(montageDur, targetDur);
  if (mode === "freeze") {
    console.warn(
      `[Pipeline] ${context}: montage ${pad.toFixed(2)}s short of voice — holding last frame (MONTAGE_TAIL_PAD=freeze)`
    );
    return `tpad=stop_mode=clone:stop_duration=${pad.toFixed(3)},`;
  }
  if (plan.action === "none") return "";
  console.warn(`${formatCoverageFillPlan(context, plan)}`);

  // Ahead of FPS_FORMAT_VF's fps=25, which then resamples the stretched timeline back to a
  // constant frame rate. FPS_FORMAT_VF's trailing setpts=PTS-STARTPTS only rebases the origin,
  // so it preserves the spacing this filter just changed.
  const slow = plan.slowdownRatio > 1 ? `setpts=${plan.slowdownRatio.toFixed(6)}*PTS,` : "";
  if (plan.action === "slow") return slow;

  /**
   * RONDE 130 — the last technical fallback, now bounded by the rule the rest of the pipeline
   * obeys.
   *
   * Everything before this has already failed: the beat search, the pool backfill, the targeted
   * re-search on the neediest beat, the short-clip round, re-using the scene's own footage in
   * motion, and slowing to the cap. What this used to do about that was
   *
   *     a clone-mode tpad whose stop_duration was plan.stillShortSec
   *
   * with no ceiling on the duration. Measured on a real MP4, using the production shape of scene
   * 1 (a 3s source against a 34s target):
   *
   *     current chain   34.0s file, longest unchanging picture 28.13s   FAILS the 5s rule
   *     looping instead 34.0s file, longest unchanging picture  0.00s   167 visual changes
   *
   * Twenty-eight seconds of one frame is the thing every round since RONDE 111 has been removing,
   * and it was still reachable here — capped nowhere, on the one path taken precisely when a
   * scene is worst off.
   *
   * So the montage plays again instead of stopping. Footage the viewer has already seen is an
   * ordinary documentary device; a frozen frame is a fault. This is the same judgement RONDE 112
   * made for extendLastClip one layer up, applied at the last place it can still be made.
   *
   * The frame budget is the real constraint: `loop` buffers `size` decoded frames, and at 1080p
   * that is about 3MB each. 300 frames is twelve seconds of source and roughly a gigabyte, which
   * is the most this may take while scenes compose in parallel. Above it the hold stays, capped,
   * and the shortfall is reported as the coverage failure it is rather than absorbed silently.
   */
  /**
   * RONDE 130 — one hold site, not three.
   *
   * Five earlier rounds (85, 86, 87, 88, 89) count the clone-mode pad sites in this file and
   * require exactly TWO, as a guard against a freeze site being added unnoticed. That guard is
   * worth more than the convenience of an early return, so the hold duration is decided here and
   * emitted once at the bottom — and this note avoids spelling the filter out, because the guard
   * counts the text rather than the code.
   */
  const holdCapSec = stillImageMaxSec();
  const MAX_LOOP_SOURCE_FRAMES = 300;
  const srcFrames = Math.max(1, Math.round(montageDur * 25));
  const perPassSec = Math.max(0.1, montageDur * plan.slowdownRatio);
  if (plan.stillShortSec > holdCapSec && srcFrames <= MAX_LOOP_SOURCE_FRAMES && perPassSec > 0.1) {
    const passes = Math.max(2, Math.ceil(targetDur / perPassSec));
    console.warn(
      `[Pipeline] ${context}: ${plan.stillShortSec.toFixed(1)}s would exceed the ` +
        `${holdCapSec.toFixed(1)}s still limit — playing the montage ${passes}x instead of ` +
        `holding a frame (already-seen footage beats a freeze)`
    );
    // loop BEFORE the slowdown: `loop` counts input frames, and setpts changes timestamps rather
    // than frame count, so ordering it the other way makes `size` mean something else.
    /**
     * No trailing `setpts=N/25/TB` here, and that is not an omission: it renumbers every frame at
     * 25fps, which UNDOES the slowdown applied a moment earlier. Measured — the chain produced a
     * 17-second file for a 34-second slot, exactly half, because the 2x stretch was renumbered
     * away. FPS_FORMAT_VF's own `fps=25` resamples the stretched timeline correctly.
     */
    return (
      `loop=loop=${passes - 1}:size=${srcFrames}:start=0,${slow}` +
      `trim=duration=${targetDur.toFixed(3)},setpts=PTS-STARTPTS,`
    );
  }

  /**
   * The absolute last technical fallback.
   *
   * Everything before this has already failed: the beat search, the pool backfill, the targeted
   * re-search on the neediest beat, the short-clip round, re-using the scene's own footage in
   * motion, slowing to the cap, and — since RONDE 130 — playing the montage again. What is left
   * is a hold, and it is bounded by the same limit a photograph obeys.
   *
   * When the shortfall is larger than that limit and the montage cannot be looped, the remainder
   * is a genuine coverage failure and is reported as one rather than absorbed into a longer
   * freeze. That is the whole change: the freeze can no longer grow to fill any gap.
   */
  // The absolute last technical fallback. Bounded now, by the same limit a photograph obeys.
  const holdSec = Math.min(plan.stillShortSec, holdCapSec);
  if (plan.stillShortSec > holdCapSec) {
    console.warn(
      `[Pipeline] ${context}: COVERAGE FAILURE — ${plan.stillShortSec.toFixed(1)}s uncovered and the ` +
        `montage is too large to loop (${srcFrames} frames); holding the last frame for the ` +
        `${holdCapSec.toFixed(1)}s limit only. This scene is genuinely short of footage.`
    );
  }
  return `${slow}tpad=stop_mode=clone:stop_duration=${holdSec.toFixed(3)},`;
}

export function montageTailPadVF(inLabel: string, montageDur: number, outDur: number): string {
  const pad = Math.max(0, outDur - montageDur - 0.04);
  if (pad < 0.08) {
    return `[${inLabel}]${FPS_FORMAT_VF}[vmont]`;
  }
  const chain = montageTailPadFilterChain(
    montageDur,
    montageDur + pad,
    `Montage ${montageDur.toFixed(1)}s vs voice ${outDur.toFixed(1)}s${strictNoVisualRepeat() ? " (strict no-repeat)" : ""}`
  );
  return `[${inLabel}]${chain}${FPS_FORMAT_VF}[vmont]`;
}

function assertMontageClipsUnique(sceneIndex: number, clips: string[]): void {
  const seen = new Set<string>();
  for (const clip of clips) {
    const key = clipContentKey(clip);
    if (seen.has(key)) {
      console.warn(
        `[Pipeline] Scene ${sceneIndex}: duplicate clip content ${path.basename(clip)} (skipped at compose)`
      );
      continue;
    }
    seen.add(key);
  }
}

async function prepareStrictUniqueMontage(
  sceneIndex: number,
  clips: string[],
  beatDurations: number[],
  outDur: number,
  voiceSync?: {
    beats: Array<{ text: string; holdSec: number; voiceStartSec?: number; voiceEndSec?: number }>;
    clipBeatIndices: number[];
    voiceDur: number;
  },
  forceTtsHardCut = false
): Promise<{
  montageDurations: number[];
  sourceMaxDurs: number[];
  estSec: number;
  montagePlan?: TtsMontagePlan;
}> {
  assertMontageClipsUnique(sceneIndex, clips);
  // Phase 12: probed once here and reused below — `clips` never changes within this function,
  // so re-probing after capMontageDurationsToClipFiles (which only adjusts requested durations,
  // not the clip list) previously spawned the same ffprobe calls 3x for identical results.
  const sourceMaxDurs = await probeMontageSourceMaxDurs(clips);
  const defaultXfade = clips.length > 1 ? montageXfadeSec() : 0;
  let montageDurations: number[];
  let montagePlan: TtsMontagePlan | undefined;

  if (voiceSync && voiceSync.clipBeatIndices.length === clips.length) {
    const hardPlan = forceTtsHardCut
      ? computeTtsHardCutMontagePlan(
          voiceSync.beats,
          voiceSync.voiceDur,
          voiceSync.clipBeatIndices,
          sceneIndex
        )
      : null;
    const plan =
      hardPlan ??
      resolveVoiceSyncMontagePlan(
        voiceSync.beats,
        voiceSync.voiceDur,
        voiceSync.clipBeatIndices,
        defaultXfade,
        sceneIndex
      );
    montagePlan = plan;
    montageDurations = plan.durations;
    const xfade = plan.xfadeSec;
    montageDurations = await capMontageDurationsToClipFiles(clips, montageDurations, sourceMaxDurs);
    if (!plan.ttsHardCut) {
      montageDurations = finalizeVoiceSyncedMontageDurations(
        montageDurations,
        voiceSync.voiceDur,
        sourceMaxDurs,
        xfade,
        sceneIndex
      );
    }
    if (plan.ttsHardCut) {
      montagePlan = {
        ...plan,
        durations: montageDurations,
        cutStartsSec: plan.cutStartsSec.slice(0, montageDurations.length),
      };
    }
  } else {
    montageDurations = balanceMontageDurationsForVoice(
      clips.length,
      outDur,
      beatDurations,
      sourceMaxDurs
    );
    montageDurations = await capMontageDurationsToClipFiles(clips, montageDurations, sourceMaxDurs);
    montageDurations = balanceMontageDurationsForVoice(
      clips.length,
      outDur,
      montageDurations,
      sourceMaxDurs
    );
  }
  const estSec = effectiveMontageDurationSec(montageDurations, sourceMaxDurs);
  if (!strictNoVisualRepeat()) {
    return { montageDurations, sourceMaxDurs, estSec, montagePlan };
  }
  if (estSec < outDur - 0.06) {
    const minClips = minClipsForBalancedVoice(outDur);
    console.warn(
      `[Pipeline] Scene ${sceneIndex}: ${clips.length} clips cover ~${estSec.toFixed(1)}s of ${outDur.toFixed(1)}s ` +
        `(need ~${minClips} when balanced) — compose will pad`
    );
  }
  return { montageDurations, sourceMaxDurs, estSec, montagePlan };
}

function archiveTagHintForScene(scene: Scene, videoTitle?: string): string {
  const stubBeat: SceneBeat = {
    index: 0,
    text: scene.text.slice(0, 400),
    searchQuery: scene.pexelsQuery || "",
    powerWord: extractPowerWordFromSentence(scene.text.slice(0, 220)),
    keywords: buildRelevanceKeywords(scene, scene.text),
    holdSec: effectiveBeatSec(),
  };
  const { beatTags, topicAnchors } = buildBeatMatchTags(stubBeat, scene, videoTitle);
  const tags = [...new Set([...beatTags, ...topicAnchors])].slice(0, 6);
  const excerpt = scene.text.replace(/\s+/g, " ").trim().slice(0, 90);
  if (!tags.length) return excerpt ? `"${excerpt}"` : "voeg 4 concrete Engelse tags toe per clip";
  return excerpt
    ? `"${excerpt}" — tags: ${tags.join(", ")}`
    : `tags: ${tags.join(", ")}`;
}

async function assertSceneVisualInventory(
  scene: Scene,
  clips: string[],
  beatDurations: number[],
  sentenceBeats = 0,
  clipBeatIndices?: number[],
  videoTitle?: string
): Promise<void> {
  if (!strictNoVisualRepeat()) return;
  assertMontageClipsUnique(scene.index, clips);
  if (clips.length === 0) {
    console.warn(
      `[Pipeline] Scene ${scene.index}: geen clips na sourcing — compose vult guaranteed fallbacks ` +
        `(${archiveTagHintForScene(scene, videoTitle)})`
    );
    return;
  }
  const minClips = sentenceBeats > 0
    ? Math.max(sentenceBeats, minClipsForBalancedVoice(scene.duration + 0.15))
    : requiredMontageClipsForDuration(scene.duration + 0.15);
  if (clips.length < minClips) {
    console.warn(
      `[Pipeline] Scene ${scene.index}: weinig unieke clips (${clips.length}/${minClips} voor ${scene.duration.toFixed(1)}s) — compose/backfill vult aan`
    );
  }
  if (sentenceBeats > 0 && clipBeatIndices && clipBeatIndices.length === sentenceBeats) {
    const uniqueBeatSlots = new Set(clipBeatIndices);
    if (uniqueBeatSlots.size < sentenceBeats) {
      console.warn(
        `[Pipeline] Scene ${scene.index}: niet elke zin heeft eigen beeld (${uniqueBeatSlots.size}/${sentenceBeats}) — montage vult aan`
      );
    }
  }
}

async function montageClipPassesComposeGate(
  clipPath: string,
  sceneIndex: number,
  clipIndex: number,
  /**
   * RONDE 103 phase 17 — the last barrier.
   *
   * This function is the widest chokepoint the pipeline has: eighteen call sites, and every clip
   * that reaches a composed scene passes one of them. That makes it the right place to ask the
   * one question no route can answer for itself — did anything object to this clip, and was that
   * objection overruled on purpose?
   *
   * The ledger is optional because four of the eighteen call sites are inside compose paths that
   * were handed bare file paths and have no VisualDedupState to read. Those keep the old
   * behaviour rather than being given a fabricated one; see composeBarrierAllows for what an
   * unknown path is allowed to do.
   */
  relevance?: BeatRelevanceLedger
): Promise<boolean> {
  const GATE_TIMEOUT_MS = 25_000;
  const base = path.basename(clipPath);

  if (relevance) {
    /**
     * RENDER 564 — the same rule as on the push route, from the side that knows less.
     *
     * This chokepoint has a scene and a clip INDEX; the narration hangs on a BEAT. The render's
     * adopt audit already maps a clip's basename to the beat it was adopted for, so the scope
     * resolves it rather than this function acquiring a fifth parameter that eighteen call sites
     * would have to supply.
     *
     * A clip the adopt audit does not know — a pad, a derived file — still cannot be placed, and
     * that stays a pass. It is now a NAMED pass instead of a silent one.
     */
    const ensured = await ensureVerdictBeforeCompose({
      clipPath,
      contentKey: clipContentKey(clipPath),
      route: "compose",
    });
    if (ensured.outcome === "beat_unknown" || ensured.outcome === "no_narration") {
      console.warn(
        `[ComposeBarrier] s${sceneIndex} clip ${clipIndex}: UNJUDGED ${base} — ` +
          `${ensured.outcome}; nothing has looked at this picture and nothing can`
      );
    }
    const barrier = composeBarrierAllows(relevance, clipPath, clipContentKey(clipPath));
    if (!barrier.allow) {
      console.warn(
        `[ComposeBarrier] s${sceneIndex} clip ${clipIndex}: BLOCKED ${base} — ${barrier.reason}`
      );
      return false;
    }
  }

  let resolved = false;
  const work = (async (): Promise<boolean> => {
    /**
     * RONDE 138 — an abandoned scope means "cannot check", not "reject".
     *
     * ── What this cost in video 558 ──────────────────────────────────────────────────────────
     *
     * Fourteen clips were thrown away here, ten of them already-downloaded archive files:
     *
     *     Scene 1 beat 4: skipping clip that fails compose gate scene_1_b4_curated_a57618.mp4
     *     Scene 1 beat 4: skipping clip that fails compose gate scene_1_b4_curated_a57654.mp4
     *     Scene 2 beat 0: skipping clip that fails compose gate scene_2_b0_curated_a57566.mp4   ...
     *
     * Every one of them had already been downloaded, passed the technical gate, been judged by
     * Vision and been adopted. Scene 1 ended with 2 unique clips for 13 needed, and the render
     * reported "19 van 22 beats zonder goedgekeurd eigen beeld".
     *
     * The original reasoning was sound as far as it went: once the scope's withSceneFetchTimeout
     * has fired, every probe below would throw immediately and be swallowed as a false "unusable
     * stream", so running them is waste. But the conclusion did not follow. Skipping a CHECK is not
     * the same as failing it, and a clip does not become unusable because the scene ran out of time
     * looking for OTHER clips.
     *
     * ── Why this is safe ─────────────────────────────────────────────────────────────────────
     *
     * The gate is not skipped. It is answered from a measurement this render already took:
     * probeVideoStreamMeta memoises on the file's inode and ctime, so a file measured earlier is
     * knowable without spawning anything — which is the only objection the abort raises.
     *
     * A file with no prior measurement is still refused. That is deliberate and it is what keeps
     * the derived files honest: pad_combined_*.mp4 and the text-overlay output are written moments
     * before this call and have never been probed, so a half-written ffmpeg result cannot slip
     * through on the strength of "we were in a hurry".
     */
    /**
     * PHASE 1 — adoption is the stronger fact, and it is asked for first.
     *
     * RONDE 138 (above) answered an abandoned scope from a memoised probe, which closed the common
     * case. What it left unstated is the principle: an expired RETRIEVAL budget may stop new work,
     * and may never be a verdict on a clip that has already been found, measured, judged and
     * adopted. A clip whose measurement happened not to be memoised under this exact path was still
     * thrown away, so the outcome depended on a cache rather than on what was known about the clip.
     *
     * `adoptedAtPath` asks the ledger about THIS EXACT PATH — never the derivation chain — so
     * pad_combined_*.mp4 and the text-overlay output, written moments before this call and never
     * examined, cannot inherit their parent's clearance. They fall to the same refusal as before.
     */
    if (sceneFetchAborted()) {
      const known = memoisedVideoStreamMeta(clipPath);
      const usable = known
        ? montageStreamMetaUsable(known, montageClipStartSec(sceneIndex, clipIndex))
        : null;
      const verdict = composeScopeVerdict({
        scopeAborted: true,
        adopted: get_activeSourcingCache()?.lineage?.adoptedAtPath(clipPath) ?? false,
        priorMeasurementUsable: usable,
      });
      const detail =
        known && verdict.decision === "pass" && verdict.basis === "prior_measurement"
          ? `${known.width}x${known.height}, ${known.durationSec.toFixed(2)}s`
          : undefined;
      const line = formatComposeScopeDecision({
        sceneIndex, clipIndex, basename: base, verdict, detail,
      });
      if (verdict.decision === "pass") {
        console.log(line);
        return true;
      }
      console.warn(line);
      return false;
    }
    if (!(await isValidVideoFile(clipPath))) return false;
    const trimStart = montageClipStartSec(sceneIndex, clipIndex);
    const meta = await probeVideoStreamMeta(clipPath);
    if (!meta || !montageStreamMetaUsable(meta, trimStart)) {
      if (!sceneFetchAborted()) {
        console.warn(
          `[Pipeline] Scene ${sceneIndex} clip ${clipIndex}: unusable stream ${base}` +
            (meta ? ` (${meta.width}x${meta.height}, ${meta.durationSec.toFixed(2)}s)` : "")
        );
      }
      return false;
    }
    const curatedId = curatedClipPathAssetId(clipPath);
    if (curatedId != null) {
      const startLuma = await probeClipMeanLuma(clipPath, trimStart + 0.08);
      if (startLuma !== null && startLuma < 14) return false;
      if (strictNoVisualRepeat()) {
        // Reuse the duration already probed above (meta.durationSec) instead of re-probing the
        // same file with a second ffmpeg process — saves one subprocess per gate-check here.
        const probed = meta.durationSec;
        if (probed > 0.15 && probed < archiveVisualMinClipSec() - 0.5) return false;
        const midAt =
          trimStart + Math.min(Math.max(1.0, probed * 0.4), Math.max(0.5, probed - 0.25));
        const centerLuma = await probeClipRegionMeanLuma(clipPath, midAt, "center");
        if (centerLuma !== null && centerLuma < 18) return false;
      }
      return true;
    }
    // Phase 12: meta.durationSec was already probed above (and validated by
    // montageStreamMetaUsable) — pass it through instead of letting isMostlyBlackClip re-probe
    // the same file a second time for this non-curated candidate.
    if (await isMostlyBlackClip(clipPath, meta.durationSec)) return false;
    const startLuma = await probeClipMeanLuma(clipPath, trimStart + 0.08);
    if (startLuma !== null && startLuma < 14) return false;
    return true;
  })().then((v) => { resolved = true; return v; });

  const timeout = new Promise<boolean>((resolve) =>
    setTimeout(() => {
      if (!resolved) {
        console.warn(`[ComposeGate] TIMEOUT s${sceneIndex}b${clipIndex} ${base} after ${GATE_TIMEOUT_MS}ms — skipping clip`);
      }
      resolve(false);
    }, GATE_TIMEOUT_MS)
  );

  return Promise.race([work, timeout]);
}

async function estimateSceneMontageCoverageSec(
  clips: string[],
  beatDurations: number[]
): Promise<number> {
  if (clips.length === 0) return 0;
  const durs =
    beatDurations.length === clips.length
      ? beatDurations
      : clips.map(() => effectiveBeatSec());
  const sourceMaxDurs = await probeMontageSourceMaxDurs(clips);
  return effectiveMontageDurationSec(durs, sourceMaxDurs);
}

/** Coverage after compose-style duration balancing (matches prepareStrictUniqueMontage). */
async function estimateBalancedMontageCoverageSec(
  clips: string[],
  beatDurations: number[],
  outDur: number
): Promise<number> {
  if (clips.length === 0) return 0;
  // Phase 12: probed once and reused below — see the identical fix/comment in
  // prepareStrictUniqueMontage above; `clips` doesn't change within this function, so the two
  // subsequent probes of the same list were always redundant. This function is also called
  // repeatedly inside backfillArchiveMontageFromPool's per-attempt loop, so this 3x-per-call
  // reduction compounds across every backfill iteration.
  const sourceMaxDurs = await probeMontageSourceMaxDurs(clips);
  let balanced = balanceMontageDurationsForVoice(clips.length, outDur, beatDurations, sourceMaxDurs);
  balanced = await capMontageDurationsToClipFiles(clips, balanced, sourceMaxDurs);
  balanced = balanceMontageDurationsForVoice(clips.length, outDur, balanced, sourceMaxDurs);
  return effectiveMontageDurationSec(balanced, sourceMaxDurs);
}

function composeSceneTimeoutMs(clipCount: number, videoLength?: string, sceneDurationSec = 30): number {
  const _b2 = get_activeRenderBudget();
  if (_b2) {
    // Complexity formula: scene_duration × 3s/s + 2.5s per clip, bounded by budget base
    const complexity = Math.round(sceneDurationSec * 3_000 + Math.max(0, clipCount) * 2_500);
    // RONDE 63: the cap has to know that scenes compose side by side.
    //
    // basePerSceneComposeMs is (total × 0.55) / scenes — a scene's SHARE of the compose budget,
    // which is the right number if scenes composed one after another. They do not: composeLimit
    // runs `composeParallelism` of them at once, so a scene's wall clock is roughly that many
    // times its solo time. Render 532 measured exactly that, with parallelism 2:
    //
    //     scene 0   alone 57.5s   alongside scene 1  101.4s
    //     scene 1   alone 65.0s   alongside scene 0  148.2s
    //
    // Both blew the 88s cap, both were abandoned mid-encode, and both were composed again from
    // scratch — 250 seconds of finished work thrown away, a quarter of the whole render. And the
    // discarded attempts kept encoding alongside their own replacements.
    //
    // Multiplying the cap by the parallelism restores the arithmetic rather than loosening it:
    // with P scenes at a time, total wall is (scenes / P) × (base × P) = scenes × base, which is
    // the budget the formula started from.
    const parallelism = Math.max(1, composeParallelismForVideo(videoLength, IS_RAILWAY));
    const cap = _b2.basePerSceneComposeMs * parallelism;
    return Math.round(Math.min(Math.max(complexity, 45_000), cap));
  }
  if (isFastShortVideoLength(videoLength)) return 60_000;
  if (curatedArchiveOnlyVisuals() && clipCount > 8) return 90_000;
  return 75_000;
}

function montageEncodeFlags(montageFilterOpts?: MontageFilterOpts): string {
  const fast = montageFilterOpts?.fastEncode === true;
  const preset = fast ? MONTAGE_SEGMENT_ENCODE_PRESET : "veryfast";
  const crf = fast ? 22 : 18;
  return `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset ${preset} -crf ${crf}`;
}

function formatFfmpegExecError(err: unknown): string {
  const e = err as NodeJS.ErrnoException & { stderr?: string };
  const stderr = typeof e?.stderr === "string" ? e.stderr.trim() : "";
  if (stderr) {
    const lines = stderr
      .split("\n")
      .map((l) => l.trim())
      .filter((l) => l.length > 0);
    const interesting = lines.find((l) =>
      /invalid|error|failed|no such|could not|unable|corrupt|match/i.test(l)
    );
    if (interesting) return interesting.slice(0, 500);
    const last = lines[lines.length - 1];
    if (last) return last.slice(0, 500);
  }
  const base = e?.message ?? String(err);
  if (/Command failed:/i.test(base)) return "FFmpeg montage encode failed";
  return base.slice(0, 500);
}

export async function logComposePreFlight(
  sceneIndex: number,
  clips: string[],
  outputPath: string,
  encodeFlags: string
): Promise<void> {
  const preset = encodeFlags.match(/-preset\s+(\S+)/)?.[1] ?? "?";
  const crf = encodeFlags.match(/-crf\s+(\S+)/)?.[1] ?? "?";
  const codec = encodeFlags.match(/-c:v\s+(\S+)/)?.[1] ?? "?";
  console.log(
    `[ComposePreFlight] Scene ${sceneIndex}: codec=${codec} preset=${preset} crf=${crf} ` +
    `output_wxh=${VIDEO_WIDTH}x${VIDEO_HEIGHT} fps=25 pix_fmt=yuv420p ` +
    `clips=${clips.length} outputPath=${path.basename(outputPath)}`
  );
  const FFPROBE_BIN = process.env.FFPROBE_PATH || "ffprobe";
  for (const clip of clips.slice(0, 5)) {
    if (!clip || !fs.existsSync(clip)) {
      console.warn(`[ComposePreFlight] Scene ${sceneIndex}: clip MISSING ${clip ? path.basename(clip) : "(null)"}`);
      continue;
    }
    const sz = fs.statSync(clip).size;
    try {
      const { stdout } = await withSceneFetchTimeout(
        () => exec(`"${FFPROBE_BIN}" -v error -select_streams v:0 -show_entries stream=width,height,r_frame_rate,pix_fmt,codec_name -of default=noprint_wrappers=1:nokey=0 "${clip}"`),
        5_000,
        `ComposePreFlight probe scene ${sceneIndex}`
      ).catch(() => ({ stdout: "", stderr: "" }));
      console.log(`[ComposePreFlight] Scene ${sceneIndex}: clip=${path.basename(clip)} size=${sz} probe=${stdout.replace(/\n/g, " ").trim().slice(0, 200)}`);
    } catch {
      console.log(`[ComposePreFlight] Scene ${sceneIndex}: clip=${path.basename(clip)} size=${sz} probe=FAILED`);
    }
  }
}

/**
 * RONDE 157 — give the coverage filler a montage long enough that it never has to hold a frame.
 *
 * montageTailPadFilterChain slows the montage to the MAX_COVERAGE_SLOWDOWN cap and, past that,
 * either loops the picture or holds the last frame. Which one it gets is decided by a frame
 * budget: `loop` buffers `size` DECODED frames, so a montage over 300 frames (12 seconds) is too
 * large to loop at 1080p and falls through to the hold. Video 552's scene 1 is exactly that case —
 * 16.9s of montage, 422 frames, too big to loop — so even with the pad wired in it would still
 * have ended on a held frame.
 *
 * Replaying the FILE has no frame budget at all: `-stream_loop` re-reads the input instead of
 * buffering it. So the montage is extended here, to the shortest length from which the existing
 * 2x slowdown reaches the voice on its own — and the filler is then a slowdown, never a hold.
 *
 * Deliberately the minimum: extending to `outDur / MAX_COVERAGE_SLOWDOWN` and letting the cap do
 * the rest means the least replayed footage that still avoids a freeze. Extending all the way to
 * `outDur` would repeat twice as much picture, and RONDE 156 exists because repetition is its own
 * fault. This trades the smallest amount of repeat for a guarantee against the frozen frame.
 *
 * Fail-safe: any failure returns the montage untouched, so the worst case is the behaviour that
 * was there before rather than a scene with no picture.
 */
export async function extendMontageForCoverage(
  montagePath: string,
  montageDur: number,
  outDur: number,
  sceneIndex: number,
  workDir: string,
  composeTimeout: number,
  threadFlag: string
): Promise<{ path: string; dur: number }> {
  const unchanged = { path: montagePath, dur: montageDur };
  if (!(montageDur > 0.4) || !(outDur > 0)) return unchanged;
  const needed = outDur / MAX_COVERAGE_SLOWDOWN;
  // Already long enough for the cap to cover the rest by slowing alone.
  if (montageDur >= needed - 0.05) return unchanged;

  const plays = Math.max(2, Math.ceil(needed / montageDur));
  const extendedPath = path.join(workDir, `scene_${sceneIndex}_seq_montage_ext.mp4`);
  try {
    await withSceneFetchTimeout(
      () => exec(
        // -stream_loop counts EXTRA passes, so one fewer than the number of plays.
        `${FFMPEG_BIN} -y -stream_loop ${plays - 1} -i "${montagePath}" -t ${needed.toFixed(3)} ` +
          `-an -vsync cfr ${threadFlag} -c:v libx264 ${pipelineFfmpegThreadFlag()} ` +
          `-preset ${MONTAGE_SEGMENT_ENCODE_PRESET} -crf 20 -pix_fmt yuv420p ` +
          `-avoid_negative_ts make_zero "${extendedPath}"`
      ),
      composeTimeout,
      `Montage replay for coverage scene ${sceneIndex}`
    );
    const extDur = await probeVideoDurationSec(extendedPath);
    if (extDur > montageDur + 0.05) {
      console.warn(
        `[Pipeline] Scene ${sceneIndex}: montage ${montageDur.toFixed(1)}s cannot reach ` +
          `${outDur.toFixed(1)}s of voice even at the ${MAX_COVERAGE_SLOWDOWN}x cap — playing it ` +
          `${plays}x to ${extDur.toFixed(1)}s so the filler can slow instead of freeze`
      );
      return { path: extendedPath, dur: extDur };
    }
    console.warn(
      `[Pipeline] Scene ${sceneIndex}: montage replay produced ${extDur.toFixed(2)}s — keeping the original`
    );
  } catch (err) {
    console.warn(
      `[Pipeline] Scene ${sceneIndex}: montage replay failed — the finished scene is checked ` +
        `for a short picture and repaired if needed: ${(err as Error)?.message?.slice(0, 140)}`
    );
  }
  return unchanged;
}

async function composePlainMontageScene(
  sceneIndex: number,
  safeClips: string[],
  montageDurations: number[],
  sourceMaxDurs: number[],
  outDur: number,
  voiceDur: number,
  safeAudioPath: string,
  outputPath: string,
  workDir: string,
  fadeFilter: string,
  threadFlag: string,
  composeTimeout: number,
  montageFilterOpts?: MontageFilterOpts
): Promise<boolean> {
  const encodeFlags = montageEncodeFlags(montageFilterOpts);
  await logComposePreFlight(sceneIndex, safeClips, outputPath, encodeFlags);
  const muxMontageWithAudio = async (montageVideoPath: string): Promise<boolean> => {
    const audioIdx = 1;
    const gradeChain = montageFilterOpts?.fastEncode
      ? `[vmont]${FPS_FORMAT_VF}[vout]`
      : `[vmont]${fadeFilter}[vout]`;
    /**
     * RONDE 157 — the montage is filled up to the voice HERE, or the last frame is held.
     *
     * This is the route Railway takes: `if (IS_RAILWAY)` renders the montage sequentially and
     * hands the file to this mux, and the third route falls back to it as well. Both passed the
     * montage straight through `[0:v]FPS_FORMAT_VF[vmont]` and then asked ffmpeg for
     * `-t outDur` seconds of it. When the montage is shorter than the narration, that does not
     * shorten the scene — it writes a file of the full length whose picture stops at the end of
     * the montage. The viewer sees a frozen frame for the difference.
     *
     * Measured on video 552, which carried RONDE 152-156 and still froze:
     *
     *     scene 1   montage est 16.9s < voice 42.9s   → 26.0s gap → 27.25s of unchanging picture
     *     scene 2   montage est  8.5s < voice 21.2s   → 12.7s gap → 12.75s of unchanging picture
     *
     * Both violations the render's own stillness audit reported, to the tenth of a second.
     *
     * The machinery to prevent this already existed and was already correct — RONDE 85 slows,
     * RONDE 111 caps the slowdown, RONDE 130 loops past the cap — but only two of the three
     * routes through this function reached it: the inline xfade route calls montageTailPadVF,
     * and renderSequentialArchiveMontage pads only its SINGLE-clip branch. A scene with two or
     * more clips on the Railway route reached no filler at all. That is why every round that
     * fixed a frozen SOURCE left this frozen picture standing: it is not a source, it is the end
     * of the montage being held by the muxer.
     *
     * The duration is probed rather than estimated, because at this point the file exists and its
     * real length is the number that decides how much filler is needed. A probe that fails leaves
     * the chain exactly as it was and says so — an unmeasured montage must not silently skip the
     * pad.
     */
    const probed = await probeVideoDurationSec(montageVideoPath);
    const extended = await extendMontageForCoverage(
      montageVideoPath,
      probed,
      outDur,
      sceneIndex,
      workDir,
      composeTimeout,
      threadFlag
    );
    const montageVideoIn = extended.path;
    const montageDur = extended.dur;
    let headChain = `[0:v]${FPS_FORMAT_VF}[vmont]`;
    if (montageDur > 0) {
      headChain = montageTailPadVF("0:v", montageDur, outDur);
    } else {
      console.warn(
        `[Pipeline] Scene ${sceneIndex}: could not probe montage length — tail pad skipped here; ` +
          `the finished scene is checked for a short picture and repaired if needed`
      );
    }
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -i "${montageVideoIn}" -i "${safeAudioPath}" ` +
          `-filter_complex "${headChain};${gradeChain};` +
          `[${audioIdx}:a]afade=t=in:st=0:d=0.06,afade=t=out:st=${Math.max(0, voiceDur - 0.15).toFixed(3)}:d=0.12,` +
          `atrim=0:${voiceDur.toFixed(3)},asetpts=PTS-STARTPTS[aout]" ` +
          `-map "[vout]" -map "[aout]" -vsync cfr ` +
          `-t ${outDur.toFixed(3)} ${threadFlag} ${encodeFlags} -c:a aac -b:a 320k -pix_fmt yuv420p "${outputPath}"`
      ),
      composeTimeout,
      `Plain montage+audio scene ${sceneIndex}`
    );
    return fs.existsSync(outputPath) && fs.statSync(outputPath).size > 1000;
  };

  if (IS_RAILWAY) {
    try {
      const montageOnlyPath = path.join(workDir, `scene_${sceneIndex}_seq_montage.mp4`);
      await renderSequentialArchiveMontage(
        safeClips,
        montageDurations,
        sourceMaxDurs,
        sceneIndex,
        outDur,
        workDir,
        montageOnlyPath,
        composeTimeout,
        threadFlag,
        montageFilterOpts
      );
      if (await muxMontageWithAudio(montageOnlyPath)) return true;
    } catch (seqErr) {
      console.warn(
        `[Pipeline] Scene ${sceneIndex}: sequential plain montage failed:`,
        (seqErr as Error).message?.slice(0, 160)
      );
    }
  }

  try {
    const { scaleFilters, mergeFilter, montageLabel } = buildMontageXfadeFilter(
      safeClips.length,
      outDur,
      sceneIndex,
      montageDurations,
      safeClips,
      sourceMaxDurs,
      montageFilterOpts
    );
    const inputs = montageClipInputs(safeClips);
    const estMontage = effectiveMontageDurationSec(montageDurations, sourceMaxDurs);
    const montageOutVF = montageTailPadVF(montageLabel, estMontage, outDur);
    const audioIdx = safeClips.length;
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y ${inputs} -i "${safeAudioPath}" ` +
          `-filter_complex "${scaleFilters}${mergeFilter};${montageOutVF};` +
          (montageFilterOpts?.fastEncode
            ? `[vmont]${FPS_FORMAT_VF}[vout];`
            : `[vmont]${fadeFilter}[vout];`) +
          `[${audioIdx}:a]afade=t=in:st=0:d=0.06,afade=t=out:st=${Math.max(0, voiceDur - 0.15).toFixed(3)}:d=0.12,` +
          `atrim=0:${voiceDur.toFixed(3)},asetpts=PTS-STARTPTS[aout]" ` +
          `-map "[vout]" -map "[aout]" -vsync cfr ` +
          `-t ${outDur.toFixed(3)} ${threadFlag} ${encodeFlags} -c:a aac -b:a 320k -pix_fmt yuv420p "${outputPath}"`
      ),
      composeTimeout,
      `Plain montage scene ${sceneIndex}`
    );
    if (fs.existsSync(outputPath) && fs.statSync(outputPath).size > 1000) return true;
  } catch (inlineErr) {
    console.warn(
      `[Pipeline] Scene ${sceneIndex}: inline plain montage failed, trying sequential segments:`,
      (inlineErr as Error).message?.slice(0, 160)
    );
  }

  try {
    const montageOnlyPath = path.join(workDir, `scene_${sceneIndex}_seq_montage.mp4`);
    await renderSequentialArchiveMontage(
      safeClips,
      montageDurations,
      sourceMaxDurs,
      sceneIndex,
      outDur,
      workDir,
      montageOnlyPath,
      composeTimeout,
      threadFlag
    );
    return await muxMontageWithAudio(montageOnlyPath);
  } catch (seqErr) {
    console.warn(
      `[Pipeline] Scene ${sceneIndex}: sequential plain montage failed:`,
      (seqErr as Error).message?.slice(0, 160)
    );
  }
  return false;
}

const ARCHIVE_MONTAGE_BATCH_SIZE = 4;
const MONTAGE_SEGMENT_ENCODE_PRESET = IS_RAILWAY ? "ultrafast" : "veryfast";

async function xfadeMergeTwoVideos(
  leftPath: string,
  rightPath: string,
  leftDur: number,
  rightDur: number,
  outputPath: string,
  composeTimeout: number,
  threadFlag: string,
  montageFilterOpts?: MontageFilterOpts
): Promise<void> {
  const xfade = montageFilterOpts?.xfadeSec ?? montageXfadeSec((leftDur + rightDur) / 2);
  // Phase 10: grade each branch by its own clip's source instead of applying one fixed
  // grade to both — an AI-generated/stock clip and a real archive clip sitting side by
  // side in the same montage no longer get an identical look.
  const branchNormLeft = `${montageBranchNormVF(classifyDocGradeSourceKind(leftPath))},setpts=PTS-STARTPTS`;
  const branchNormRight = `${montageBranchNormVF(classifyDocGradeSourceKind(rightPath))},setpts=PTS-STARTPTS`;
  if (xfade <= 0.001) {
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -i "${leftPath}" -i "${rightPath}" ` +
          `-filter_complex "[0:v]${branchNormLeft}[v0];[1:v]${branchNormRight}[v1];` +
          `[v0][v1]concat=n=2:v=1:a=0[out]" ` +
          `-map "[out]" -an -vsync cfr ${threadFlag} -c:v libx264 -preset ${MONTAGE_SEGMENT_ENCODE_PRESET} -crf 18 -pix_fmt yuv420p "${outputPath}"`
      ),
      composeTimeout,
      "Concat montage segments (hard cut)"
    );
    return;
  }
  const offset = Math.max(0, leftDur - xfade);
  try {
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -i "${leftPath}" -i "${rightPath}" ` +
          `-filter_complex "[0:v]${branchNormLeft}[v0];[1:v]${branchNormRight}[v1];` +
          `[v0][v1]xfade=transition=dissolve:duration=${xfade.toFixed(3)}:offset=${offset.toFixed(3)}[out]" ` +
          `-map "[out]" -an -vsync cfr ${threadFlag} -c:v libx264 -preset ${MONTAGE_SEGMENT_ENCODE_PRESET} -crf 18 -pix_fmt yuv420p "${outputPath}"`
      ),
      composeTimeout,
      "Merge montage segments"
    );
  } catch (xfadeErr) {
    // xfade can fail when auto_scale can't configure pads (resolution mismatch mid-stream).
    // Fall back to hard-cut concat which is always safe.
    console.warn(`[Pipeline] xfade failed (auto_scale error) — retrying as hard-cut concat: ${(xfadeErr as Error).message?.slice(0, 120)}`);
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -i "${leftPath}" -i "${rightPath}" ` +
          `-filter_complex "[0:v]${branchNormLeft}[v0];[1:v]${branchNormRight}[v1];` +
          `[v0][v1]concat=n=2:v=1:a=0[out]" ` +
          `-map "[out]" -an -vsync cfr ${threadFlag} -c:v libx264 -preset ${MONTAGE_SEGMENT_ENCODE_PRESET} -crf 18 -pix_fmt yuv420p "${outputPath}"`
      ),
      composeTimeout,
      "Merge montage segments (hard-cut fallback)"
    );
  }
}

async function renderMontageVideoOnly(
  clips: string[],
  montageDurations: number[],
  sourceMaxDurs: number[],
  sceneIndex: number,
  targetDur: number,
  outputPath: string,
  composeTimeout: number,
  threadFlag: string,
  montageFilterOpts?: MontageFilterOpts
): Promise<void> {
  const { scaleFilters, mergeFilter, montageLabel } = buildMontageXfadeFilter(
    clips.length,
    targetDur,
    sceneIndex,
    montageDurations,
    clips,
    sourceMaxDurs,
    montageFilterOpts
  );
  const inputs = montageClipInputs(clips);
  const est = effectiveMontageDurationSec(montageDurations, sourceMaxDurs);
  const montageOutVF = montageTailPadVF(montageLabel, est, targetDur);
  await withSceneFetchTimeout(
    () => exec(
      `${FFMPEG_BIN} -y ${inputs} -filter_complex "${scaleFilters}${mergeFilter};${montageOutVF}" ` +
        `-map "[vmont]" -an -vsync cfr -t ${targetDur.toFixed(3)} ${threadFlag} ` +
        `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset ${MONTAGE_SEGMENT_ENCODE_PRESET} -crf 18 -pix_fmt yuv420p "${outputPath}"`
    ),
    composeTimeout,
    `Montage video-only scene ${sceneIndex}`
  );
}

async function renderBatchedArchiveMontage(
  clips: string[],
  montageDurations: number[],
  sourceMaxDurs: number[],
  sceneIndex: number,
  outDur: number,
  workDir: string,
  outputPath: string,
  composeTimeout: number,
  threadFlag: string,
  montageFilterOpts?: MontageFilterOpts
): Promise<void> {
  if (IS_RAILWAY && curatedArchiveOnlyVisuals()) {
    await renderSequentialArchiveMontage(
      clips,
      montageDurations,
      sourceMaxDurs,
      sceneIndex,
      outDur,
      workDir,
      outputPath,
      composeTimeout,
      threadFlag,
      montageFilterOpts
    );
    return;
  }
  const batchSize = ARCHIVE_MONTAGE_BATCH_SIZE;
  if (clips.length <= batchSize) {
    await renderMontageVideoOnly(
      clips,
      montageDurations,
      sourceMaxDurs,
      sceneIndex,
      outDur,
      outputPath,
      composeTimeout,
      threadFlag,
      montageFilterOpts
    );
    return;
  }

  const segmentPaths: string[] = [];
  const segmentDurs: number[] = [];
  for (let start = 0; start < clips.length; start += batchSize) {
    const end = Math.min(start + batchSize, clips.length);
    const batchClips = clips.slice(start, end);
    const batchDurs = montageDurations.slice(start, end);
    const batchSrc = sourceMaxDurs.slice(start, end);
    const batchTarget = effectiveMontageDurationSec(batchDurs, batchSrc);
    const segPath = path.join(workDir, `scene_${sceneIndex}_mseg_${start}.mp4`);
    await renderMontageVideoOnly(
      batchClips,
      batchDurs,
      batchSrc,
      sceneIndex,
      batchTarget + 0.05,
      segPath,
      composeTimeout,
      threadFlag,
      montageFilterOpts
    );
    segmentPaths.push(segPath);
    segmentDurs.push((await probeVideoDurationSec(segPath)) || batchTarget);
  }

  const mergeXfade = montageFilterOpts?.xfadeSec ?? montageXfadeSec();
  let accPath = segmentPaths[0]!;
  let accDur = segmentDurs[0]!;
  for (let i = 1; i < segmentPaths.length; i++) {
    const nextOut =
      i === segmentPaths.length - 1
        ? outputPath
        : path.join(workDir, `scene_${sceneIndex}_macc_${i}.mp4`);
    await xfadeMergeTwoVideos(
      accPath,
      segmentPaths[i]!,
      accDur,
      segmentDurs[i]!,
      nextOut,
      composeTimeout,
      threadFlag,
      montageFilterOpts
    );
    accPath = nextOut;
    accDur =
      (await probeVideoDurationSec(accPath)) ||
      accDur + segmentDurs[i]! - (mergeXfade > 0.001 ? mergeXfade : 0);
  }
}

/**
 * Curated archive clip filenames are deterministic (scene+beat+assetId), with no per-call
 * uniqueness token. Different, independently-running beat-fill/backfill passes each track their
 * own local "already used" set rather than one shared across the whole video, so two passes can
 * both pick the same popular asset for what they each think is a still-open beat. Whichever one
 * loses its own internal candidate race deletes "its" losing file — even when that exact
 * deterministic path is the file another, already-completed pass already committed into this
 * scene's clip list. That race can land in the window between composeSceneVideoInner's own
 * existsSync filter and this segment actually reading the file, so re-derive and regenerate it
 * on the spot from the asset ID baked into the filename rather than failing the whole scene.
 */
async function reviveMissingCuratedMontageClip(
  clipPath: string,
  sceneIndex: number,
  clipIndex: number,
  holdSec: number
): Promise<string> {
  if (fs.existsSync(clipPath) && fs.statSync(clipPath).size > 100) return clipPath;
  const m = path.basename(clipPath).match(/^scene_(\d+)_b(\d+)_curated_a(\d+)(?:_still)?\.mp4$/i);
  if (!m) return clipPath;
  const [, origSceneIndex, beatIndex, assetIdStr] = m;
  const assetId = Number(assetIdStr);
  console.warn(
    `[Pipeline] Scene ${sceneIndex} segment ${clipIndex}: curated clip vanished (asset ${assetId}) — regenerating`
  );
  try {
    const asset = await getMediaArchiveAssetById(assetId);
    if (!asset) return clipPath;
    const workDir = path.dirname(clipPath);
    return await prepareCuratedArchiveClip(
      asset,
      workDir,
      Number(origSceneIndex),
      Number(beatIndex),
      holdSec
    );
  } catch (err) {
    console.warn(
      `[Pipeline] Scene ${sceneIndex} segment ${clipIndex}: regenerate of asset ${assetId} failed:`,
      (err as Error).message?.slice(0, 150)
    );
    return clipPath;
  }
}

async function renderSingleMontageSegment(
  clipPath: string,
  sceneIndex: number,
  clipIndex: number,
  duration: number,
  sourceMaxSec: number,
  outputPath: string,
  composeTimeout: number,
  threadFlag: string,
  segmentBeatText?: string
): Promise<number> {
  clipPath = await reviveMissingCuratedMontageClip(clipPath, sceneIndex, clipIndex, duration);
  let startSec = montageClipStartSec(sceneIndex, clipIndex);
  if (sourceMaxSec > 0.15) {
    startSec = Math.min(startSec, Math.max(0, sourceMaxSec - 0.35));
  }
  let effectiveDur = duration;
  if (sourceMaxSec > 0.15) {
    effectiveDur = resolveMontageClipEffectiveDur(duration, sourceMaxSec);
    effectiveDur = Math.min(effectiveDur, Math.max(0.35, sourceMaxSec - startSec - 0.05));
  } else if (sourceMaxSec === 0) {
    // Duration probe failed after every retry (fork-pressure/corrupt-file case) — this is
    // "unknown", not "no clamp needed". Trusting the assigned `duration` blindly risks xfade
    // running out of decodable frames mid-transition and freezing on the last frame. Fall back
    // to the same conservative floor already used for known-short clips instead.
    startSec = 0;
    effectiveDur = Math.min(duration, montageMinOnScreenSec());
  }
  effectiveDur = Math.max(0.35, effectiveDur);

  const burnDeferred =
    deferFacelessSubtitlesToCompose() &&
    facelessSubtitlesEnabled() &&
    segmentBeatText?.trim() &&
    isVisualOverlayFootageClip(clipPath);
  const lines = burnDeferred ? parseFacelessSubtitleLines(segmentBeatText!) : [];

  const segmentSourceKind = classifyDocGradeSourceKind(clipPath);
  if (burnDeferred && lines.length > 0) {
    const chain = buildFacelessTypewriterDrawtextChain("vprep", "vout", lines, effectiveDur, "bottom-left");
    const filterComplex = `[0:v]${montageBranchNormVF(segmentSourceKind)}[vprep]${chain}`;
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -ss ${startSec.toFixed(3)} -i "${clipPath}" -t ${effectiveDur.toFixed(3)} ` +
          `-filter_complex "${filterComplex}" -map "[vout]" ` +
          `-an -vsync cfr ${threadFlag} ` +
          `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset ${MONTAGE_SEGMENT_ENCODE_PRESET} -crf 18 -pix_fmt yuv420p "${outputPath}"`
      ),
      composeTimeout,
      `Montage segment+text scene ${sceneIndex} clip ${clipIndex}`
    );
  } else {
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -ss ${startSec.toFixed(3)} -i "${clipPath}" -t ${effectiveDur.toFixed(3)} ` +
          `-vf "${montageBranchNormVF(segmentSourceKind)},setpts=PTS-STARTPTS" -an -vsync cfr ${threadFlag} ` +
          `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset ${MONTAGE_SEGMENT_ENCODE_PRESET} -crf 18 -pix_fmt yuv420p "${outputPath}"`
      ),
      composeTimeout,
      `Montage segment scene ${sceneIndex} clip ${clipIndex}`
    );
  }
  return (await probeVideoDurationSec(outputPath)) || effectiveDur;
}

/** Encode each montage clip separately then xfade-merge — avoids auto_scale filter-graph failures. */
async function renderSequentialArchiveMontage(
  clips: string[],
  montageDurations: number[],
  sourceMaxDurs: number[],
  sceneIndex: number,
  outDur: number,
  workDir: string,
  outputPath: string,
  composeTimeout: number,
  threadFlag: string,
  montageFilterOpts?: MontageFilterOpts
): Promise<void> {
  if (clips.length === 0) {
    throw pipelineError(PIPELINE_ERROR.FFMPEG, `Scene ${sceneIndex}: no clips for sequential montage`);
  }
  const segmentPaths: string[] = new Array(clips.length);
  const segmentDurs: number[] = new Array(clips.length);
  const segLimit = pLimit(Math.min(montageSegmentParallelism(IS_RAILWAY), clips.length));
  await Promise.all(
    clips.map((clip, i) =>
      segLimit(async () => {
        const segPath = path.join(workDir, `scene_${sceneIndex}_seq_${i}.mp4`);
        const beatText = montageFilterOpts?.segmentBeatTexts?.[i];
        const dur = await renderSingleMontageSegment(
          clip,
          sceneIndex,
          i,
          montageDurations[i] ?? effectiveBeatSec(),
          sourceMaxDurs[i] ?? 0,
          segPath,
          composeTimeout,
          threadFlag,
          beatText
        );
        segmentPaths[i] = segPath;
        segmentDurs[i] = dur;
      })
    )
  );
  if (segmentPaths.length === 1) {
    const est = segmentDurs[0]!;
    const pad = Math.max(0, outDur - est - 0.04);
    // RONDE 85: the strictNoVisualRepeat guard is gone from this branch. It was here because the
    // filler used to be a held frame, and a scene under a strict no-repeat rule was left short
    // rather than given one. Slowing the clip repeats nothing, so it is allowed under that rule
    // too — and leaving the scene short of its own voice track was never the better outcome.
    const padFilter =
      pad >= 0.08
        ? montageTailPadFilterChain(est, est + pad, `Scene ${sceneIndex} single-clip montage`)
        : "";
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -i "${segmentPaths[0]!}" -vf "${padFilter}${FPS_FORMAT_VF}" ` +
          `-an -vsync cfr -t ${outDur.toFixed(3)} ${threadFlag} ` +
          `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset ${MONTAGE_SEGMENT_ENCODE_PRESET} -crf 18 -pix_fmt yuv420p "${outputPath}"`
      ),
      composeTimeout,
      `Sequential single-clip montage scene ${sceneIndex}`
    );
    return;
  }
  const mergeXfade = montageFilterOpts?.xfadeSec ?? montageXfadeSec();
  let accPath = segmentPaths[0]!;
  let accDur = segmentDurs[0]!;
  for (let i = 1; i < segmentPaths.length; i++) {
    const nextOut =
      i === segmentPaths.length - 1
        ? outputPath
        : path.join(workDir, `scene_${sceneIndex}_seq_acc_${i}.mp4`);
    await xfadeMergeTwoVideos(
      accPath,
      segmentPaths[i]!,
      accDur,
      segmentDurs[i]!,
      nextOut,
      composeTimeout,
      threadFlag,
      montageFilterOpts
    );
    accPath = nextOut;
    accDur =
      (await probeVideoDurationSec(accPath)) ||
      accDur + segmentDurs[i]! - (mergeXfade > 0.001 ? mergeXfade : 0);
  }
}

async function renderInlineMontageToFile(
  sceneIndex: number,
  composeClips: string[],
  montageDurations: number[] | undefined,
  sourceMaxDurs: number[],
  outDur: number,
  outputPath: string,
  composeTimeout: number,
  threadFlag: string,
  montageFilterOpts?: MontageFilterOpts
): Promise<void> {
  const { scaleFilters, mergeFilter, montageLabel } = buildMontageXfadeFilter(
    composeClips.length,
    outDur,
    sceneIndex,
    montageDurations,
    composeClips,
    sourceMaxDurs,
    montageFilterOpts
  );
  const inputs = montageClipInputs(composeClips);
  const estMontageDur = montageDurations
    ? effectiveMontageDurationSec(montageDurations, sourceMaxDurs)
    : effectiveMontageDurationSec(
        Array.from({ length: composeClips.length }, () =>
          computeMontageClipDuration(outDur, composeClips.length)
        ),
        sourceMaxDurs
      );
  const montageOutVF = montageTailPadVF(montageLabel, estMontageDur, outDur);
  await withSceneFetchTimeout(
    () => exec(
      `${FFMPEG_BIN} -y ${inputs} -filter_complex "${scaleFilters}${mergeFilter};${montageOutVF}" ` +
        `-map "[vmont]" -vsync cfr -t ${outDur.toFixed(3)} ${threadFlag} ` +
        `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset veryfast -crf 18 -pix_fmt yuv420p "${outputPath}"`
    ),
    composeTimeout,
    `Inline montage-only scene ${sceneIndex}`
  );
}

async function composeBatchedArchiveSceneWithAudio(
  sceneIndex: number,
  composeClips: string[],
  montageDurations: number[],
  sourceMaxDurs: number[],
  outDur: number,
  voiceDur: number,
  safeAudioPath: string,
  outputPath: string,
  workDir: string,
  fadeFilter: string,
  docOverlays: TimedOverlay[],
  threadFlag: string,
  composeTimeout: number,
  skipEffectLayers: boolean,
  montageFilterOpts?: MontageFilterOpts
): Promise<void> {
  const montageOnlyPath = path.join(workDir, `scene_${sceneIndex}_montage_v.mp4`);
  await renderBatchedArchiveMontage(
    composeClips,
    montageDurations,
    sourceMaxDurs,
    sceneIndex,
    outDur,
    workDir,
    montageOnlyPath,
    composeTimeout,
    threadFlag,
    montageFilterOpts
  );
  const audioFadeOutStart = Math.max(0, voiceDur - 0.15);
  const voiceAudioFilter =
    `[1:a]afade=t=in:st=0:d=0.06,afade=t=out:st=${audioFadeOutStart.toFixed(3)}:d=0.12,` +
    `atrim=0:${voiceDur.toFixed(3)},asetpts=PTS-STARTPTS[aout]`;
  if (skipEffectLayers || docOverlays.length === 0) {
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -i "${montageOnlyPath}" -i "${safeAudioPath}" ` +
          `-filter_complex "[0:v]${FPS_FORMAT_VF}[vout];${voiceAudioFilter}" ` +
          `-map "[vout]" -map "[aout]" -vsync cfr -t ${outDur.toFixed(3)} ${threadFlag} ` +
          `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset veryfast -crf 18 -c:a aac -b:a 320k -pix_fmt yuv420p "${outputPath}"`
      ),
      composeTimeout,
      `Batched montage+audio scene ${sceneIndex}`
    );
    return;
  }
  const videoSrc = montageOnlyPath;
  const otherOverlays = docOverlays;
  if (otherOverlays.length > 0) {
    // Phase 11: this ffmpeg command declares inputs as 0=video, 1=audio, 2+=overlays, so
    // overlay input indices must start at 2 (baseInputCount=2), matching the audioIdx+1
    // pattern used elsewhere (e.g. kineticBaseIdx below). This previously passed
    // baseInputCount=1, generating "[1:v]" for the first overlay — but input 1 is the
    // audio-only file, which has no video stream, so ffmpeg's filtergraph parse failed and
    // the whole call fell through to the plain-montage fallback with overlays silently
    // dropped (year badges/SFX never appear) on the default production compose path.
    const { extraInputs, filterChain, finalLabel } = buildOverlayFilterChain(
      "vmont",
      2,
      [],
      otherOverlays,
      null
    );
    const overlayInputs = extraInputs ? ` ${extraInputs}` : "";
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -i "${videoSrc}" -i "${safeAudioPath}"${overlayInputs} ` +
          `-filter_complex "[0:v]${FPS_FORMAT_VF}[vmont]${filterChain};[${finalLabel}]${fadeFilter}[vout];${voiceAudioFilter}" ` +
          `-map "[vout]" -map "[aout]" -vsync cfr -t ${outDur.toFixed(3)} ${threadFlag} ` +
          `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset veryfast -crf 18 -c:a aac -b:a 320k -pix_fmt yuv420p "${outputPath}"`
      ),
      composeTimeout,
      `Batched montage+overlays scene ${sceneIndex}`
    );
    return;
  }
  await withSceneFetchTimeout(
    () => exec(
      `${FFMPEG_BIN} -y -i "${videoSrc}" -i "${safeAudioPath}" ` +
        `-filter_complex "[0:v]${FPS_FORMAT_VF}[v];[v]${fadeFilter}[vout];${voiceAudioFilter}" ` +
        `-map "[vout]" -map "[aout]" -vsync cfr -t ${outDur.toFixed(3)} ${threadFlag} ` +
        `-c:v libx264 ${pipelineFfmpegThreadFlag()} -preset veryfast -crf 18 -c:a aac -b:a 320k -pix_fmt yuv420p "${outputPath}"`
    ),
    composeTimeout,
    `Batched montage+labels scene ${sceneIndex}`
  );
}

/** Spread voice duration across unique clips without exceeding each source length. */
function balanceMontageDurationsForVoice(
  clipCount: number,
  outDur: number,
  seedDurations: number[] | undefined,
  sourceMaxDurs: number[]
): number[] {
  const n = clipCount;
  if (n === 0) return [];
  const minClip = effectiveMinClipSec();
  const minOnScreen = montageMinOnScreenSec();
  const maxClip = effectiveMaxClipSec();
  const capForIndex = (i: number) => montageClipUsableSec(sourceMaxDurs[i] ?? 0);
  let durs = Array.from({ length: n }, (_, i) => {
    const seed = seedDurations?.[i];
    const cap = capForIndex(i);
    if (seed && seed > 0.1) return Math.min(cap, Math.max(montageMinOnScreenSec(), seed));
    return Math.min(cap, effectiveBeatSec());
  });

  for (let pass = 0; pass < 24; pass++) {
    const est = effectiveMontageDurationSec(durs, sourceMaxDurs);
    if (est >= outDur - 0.08) break;
    let grew = false;
    durs = durs.map((d, i) => {
      const cap = capForIndex(i);
      if (d >= cap - 0.04) return d;
      grew = true;
      return Math.min(cap, d + 0.35);
    });
    if (!grew) break;
  }

  const est = effectiveMontageDurationSec(durs, sourceMaxDurs);
  if (est > outDur + 0.25) {
    const scale = outDur / est;
    durs = durs.map((d, i) =>
      Math.max(minOnScreen, Math.min(capForIndex(i), d * scale))
    );
  }
  return durs;
}

// Phase 12: sourceMaxDurs, when passed, is a caller-supplied probe result for the same `clips`
// array (e.g. already computed via probeMontageSourceMaxDurs moments earlier in the same call) —
// reusing it here avoids re-spawning ffprobe per clip a second time for an unchanged clip list.
// Omitting it preserves the original per-clip probing behavior for any other caller.
async function capMontageDurationsToClipFiles(
  clips: string[],
  durs: number[],
  sourceMaxDurs?: number[]
): Promise<number[]> {
  const capped: number[] = [];
  for (let i = 0; i < clips.length; i++) {
    const req = durs[i] ?? effectiveBeatSec();
    const probed = sourceMaxDurs?.[i] ?? (await probeVideoDurationSec(clips[i]!));
    if (probed > 0.15) {
      const maxUsable = Math.max(effectiveMinClipSec() * 0.4, probed - 0.05);
      if (maxUsable < req - 0.1) {
        console.warn(
          `[Pipeline] Montage clip ${path.basename(clips[i]!)}: capping ${req.toFixed(1)}s → ${maxUsable.toFixed(1)}s (source ${probed.toFixed(1)}s)`
        );
      }
      capped.push(Math.min(req, maxUsable));
    } else {
      capped.push(req);
    }
  }
  return capped;
}

function normalizeMontageDurations(
  durations: number[],
  outDur: number,
  sourceMaxDurs?: number[]
): number[] {
  const n = durations.length;
  if (n === 0) return durations;
  const maxClip = effectiveMaxClipSec();
  const minClip = curatedArchiveOnlyVisuals() ? effectiveMinClipSec() : VIDRUSH_CLIP_MIN_SEC * 0.85;
  const xfade = n > 1 ? montageXfadeSec() : 0;
  const capDur = (d: number, i: number) => {
    let capped = Math.max(minClip, Math.min(maxClip, d));
    const srcMax = sourceMaxDurs?.[i];
    if (srcMax && srcMax > 0.15) {
      capped = Math.min(capped, Math.max(minClip * 0.4, srcMax - 0.05));
    }
    return capped;
  };

  let normalized = durations.map((d, i) => capDur(d, i));
  let total = estimateMontageDurationSec(normalized);
  if (total <= 0.1) return normalized;

  if (total < outDur - 0.35) {
    const scale = outDur / total;
    normalized = normalized.map((d, i) => capDur(d * scale, i));
    total = estimateMontageDurationSec(normalized);
    if (total < outDur - 0.35) {
      const floor = curatedArchiveOnlyVisuals() ? 2.5 : VIDRUSH_CLIP_MIN_SEC * 0.85;
      const even = (outDur + (normalized.length - 1) * xfade) / normalized.length;
      normalized = normalized.map((_, i) => capDur(even, i));
    }
  } else if (total > outDur + 0.35) {
    const scale = outDur / total;
    normalized = normalized.map((d, i) => capDur(Math.max(minClip * 0.85, d * scale), i));
  }
  return normalized;
}










async function probeMontageSourceMaxDurs(clips: string[]): Promise<number[]> {
  const cache = new Map<string, number>();
  const out: number[] = [];
  for (const clip of clips) {
    if (cache.has(clip)) {
      out.push(cache.get(clip)!);
      continue;
    }
    const probed = await probeVideoDurationSec(clip);
    const max = probed > 0.15 ? probed : 0;
    cache.set(clip, max);
    out.push(max);
  }
  return out;
}

/**
 * Keep per-beat timing and beat index when compose drops invalid/duplicate clips.
 *
 * ── RONDE 166 (§10) — two places where an array index was standing in for an identity ────────
 *
 * This function exists BECAUSE compose drops clips, so the position of a kept clip is exactly the
 * thing that cannot be trusted to name its beat — and both of its answers used to rely on it.
 *
 *   1. When `beatDurations` was missing or the wrong length, it returned
 *      `keptClips.map((_, i) => i)`: beat index = position in the kept list. One dropped clip and
 *      every clip after it is attributed to the wrong beat, silently.
 *
 *   2. A kept clip whose content key was not in the map got `?? 0` — attributed to the FIRST BEAT
 *      of the scene. That is worse than a shifted index: it is a specific wrong answer that looks
 *      deliberate.
 *
 * The identity that survives a drop is the CONTENT KEY, which this already computed and then only
 * half-trusted. It is now the only thing used: position in `originalClips` supplies the beat when
 * no explicit `clipBeatIndices` was given, because there the position IS the beat, and everything
 * after that is looked up by key. A clip that still cannot be mapped is REPORTED rather than
 * assigned to beat 0.
 */
function alignMontageMetaWithClips(
  originalClips: string[],
  keptClips: string[],
  beatDurations?: number[],
  clipBeatIndices?: number[]
): { beatDurations: number[]; clipBeatIndices: number[]; unmapped: string[] } {
  const durByKey = new Map<string, number>();
  const idxByKey = new Map<string, number>();
  const haveDurations = Boolean(beatDurations?.length) && beatDurations!.length === originalClips.length;
  for (let i = 0; i < originalClips.length; i++) {
    const key = clipContentKey(originalClips[i]!);
    if (!durByKey.has(key)) {
      durByKey.set(key, haveDurations ? beatDurations![i]! : effectiveBeatSec());
      /** No explicit mapping means position in the ORIGINAL list, which is the beat it was cut for. */
      idxByKey.set(key, clipBeatIndices?.[i] ?? i);
    }
  }
  const unmapped: string[] = [];
  const resolvedIdx = keptClips.map((clip, position) => {
    const known = idxByKey.get(clipContentKey(clip));
    if (known != null) return known;
    /**
     * A kept clip the originals do not contain. Its position is the only thing left to go on, and
     * saying so is the difference between a guess and a silent claim — the old code answered 0.
     */
    unmapped.push(path.basename(clip));
    return position;
  });
  if (unmapped.length > 0) {
    console.warn(
      `[Pipeline] beat mapping: ${unmapped.length} composed clip(s) were not in the source list ` +
        `and fell back to position — ${unmapped.slice(0, 4).join(", ")}`
    );
  }
  return {
    beatDurations: keptClips.map(
      (clip) => durByKey.get(clipContentKey(clip)) ?? effectiveBeatSec()
    ),
    clipBeatIndices: resolvedIdx,
    unmapped,
  };
}

/**
 * RONDE 166 (§10) — the same function, exported for its regression test.
 *
 * Exported rather than made public: the production callers keep using the module-private name, and
 * this exists so the beat-identity rules above can be tested against real files with real content
 * keys instead of being asserted about from the outside.
 */
export const alignMontageMetaWithClipsForTest = alignMontageMetaWithClips;

/** Keep per-beat timing when compose drops invalid/duplicate clips. */
function alignBeatDurationsWithClips(
  originalClips: string[],
  keptClips: string[],
  beatDurations?: number[]
): number[] | undefined {
  if (!beatDurations?.length || beatDurations.length !== originalClips.length) return undefined;
  if (originalClips.length === keptClips.length && originalClips.every((c, i) => c === keptClips[i])) {
    return beatDurations;
  }
  const durByKey = new Map<string, number>();
  for (let i = 0; i < originalClips.length; i++) {
    const key = clipContentKey(originalClips[i]!);
    if (!durByKey.has(key)) durByKey.set(key, beatDurations[i]!);
  }
  const aligned = keptClips.map(
    (clip) => durByKey.get(clipContentKey(clip)) ?? effectiveBeatSec()
  );
  return aligned.length === keptClips.length ? aligned : undefined;
}

/** Default per-clip duration when beat metadata is missing. */
function computeMontageClipDuration(sceneDuration: number, clipCount: number): number {
  if (clipCount <= 0) return effectiveBeatSec();
  const beatSec = effectiveBeatSec();
  const ideal = Math.max(1, Math.ceil(sceneDuration / beatSec));
  if (clipCount >= ideal - 1) return beatSec;
  const xfade = clipCount > 1 ? montageXfadeSec() : 0;
  const evenSplit = (sceneDuration + (clipCount - 1) * xfade) / clipCount;
  return Math.max(effectiveMinClipSec(), Math.min(effectiveMaxClipSec(), evenSplit));
}

function ensureEvenDim(n: number, min = 2): number {
  const v = Math.max(min, Math.round(n));
  return v % 2 === 0 ? v : v + 1;
}

function montageClipPrepFilter(
  inputIndex: number,
  dur: number,
  sceneIndex: number,
  smoothTransition: boolean,
  xfade: number,
  clipPath?: string,
  sourceMaxSec?: number
): string {
  const preNormalized = clipPath ? /_norm_b\d+\.mp4$/i.test(path.basename(clipPath)) : false;
  let startSec = preNormalized ? 0 : montageClipStartSec(sceneIndex, inputIndex);
  if (sourceMaxSec && sourceMaxSec > 0.15) {
    startSec = Math.min(startSec, Math.max(0, sourceMaxSec - 0.35));
  }
  let effectiveDur = dur;
  if (sourceMaxSec && sourceMaxSec > 0.15) {
    effectiveDur = resolveMontageClipEffectiveDur(dur, sourceMaxSec);
    effectiveDur = Math.min(effectiveDur, Math.max(0.35, sourceMaxSec - startSec - 0.05));
  }
  effectiveDur = Math.max(0.35, effectiveDur);
  const start = startSec.toFixed(2);
  const edgeFade =
    smoothTransition && xfade > 0.001 ? Math.min(0.08, effectiveDur * 0.05) : 0;
  const fadeIn = edgeFade;
  const fadeOut = edgeFade;
  const fadeOutStart = Math.max(0, effectiveDur - fadeOut - 0.02);
  const fadeColor = "0x2A2A2A";
  let chain = `[${inputIndex}:v]trim=start=${start}:duration=${effectiveDur.toFixed(3)},`;
  chain += montageBranchNormVF(clipPath ? classifyDocGradeSourceKind(clipPath) : undefined);
  if (fadeIn > 0.05) chain += `,fade=t=in:st=0:d=${fadeIn.toFixed(3)}:color=${fadeColor}`;
  if (fadeOut > 0.05) chain += `,fade=t=out:st=${fadeOutStart.toFixed(3)}:d=${fadeOut.toFixed(3)}:color=${fadeColor}`;
  chain += `,setpts=PTS-STARTPTS[v${inputIndex}]`;
  return chain;
}

/** xfade montage — trim in-filter; optional per-beat durations (3–4s, longer when merged). */
function buildMontageXfadeFilter(
  clipCount: number,
  outDur: number,
  sceneIndex: number,
  clipDurations?: number[],
  clipPaths?: string[],
  sourceMaxDurs?: number[],
  montageOpts?: { xfadeSec?: number; preserveDurations?: boolean }
): { scaleFilters: string; mergeFilter: string; montageLabel: string } {
  const n = Math.max(1, clipCount);
  const minClip = effectiveMinClipSec();
  const maxClip = effectiveMaxClipSec();
  let durs =
    clipDurations?.length === n
      ? clipDurations.map((d, i) => {
          let capped = Math.min(maxClip, Math.max(montageMinOnScreenSec(), d));
          const srcMax = sourceMaxDurs?.[i] ?? 0;
          if (srcMax > 0.15) {
            capped = Math.min(capped, montageClipUsableSec(srcMax));
          }
          return capped;
        })
      : Array.from({ length: n }, () => computeMontageClipDuration(outDur, n));
  const presetTotal = effectiveMontageDurationSec(durs, sourceMaxDurs);
  if (
    !montageOpts?.preserveDurations &&
    (!clipDurations?.length || presetTotal > outDur + 0.35)
  ) {
    durs = normalizeMontageDurations(durs, outDur, sourceMaxDurs);
  }
  durs = durs.map((d, i) => resolveMontageClipEffectiveDur(d, sourceMaxDurs?.[i]));
  const avgDur = durs.reduce((s, d) => s + d, 0) / n;
  const xfade = montageOpts?.xfadeSec ?? montageXfadeSec(avgDur);
  const smooth = curatedArchiveOnlyVisuals() || documentaryStyleEnabled();
  const clipAt = (i: number) => clipPaths?.[i];

  if (n === 1) {
    return {
      scaleFilters: montageClipPrepFilter(0, durs[0], sceneIndex, smooth, xfade, clipAt(0), sourceMaxDurs?.[0]),
      mergeFilter: "",
      montageLabel: "v0",
    };
  }

  const scaleFilters = Array.from({ length: n }, (_, i) =>
    montageClipPrepFilter(i, durs[i], sceneIndex, smooth, xfade, clipAt(i), sourceMaxDurs?.[i])
  ).join(";");

  if (xfade <= 0.001) {
    const concatInputs = Array.from({ length: n }, (_, i) => `[v${i}]`).join("");
    return {
      scaleFilters,
      mergeFilter: `;${concatInputs}concat=n=${n}:v=1:a=0[montage]`,
      montageLabel: "montage",
    };
  }

  let mergeFilter = "";
  let prev = "v0";
  let prevDur = durs[0]!;
  let offset = prevDur - xfade;
  for (let i = 1; i < n; i++) {
    const outLabel = i === n - 1 ? "montage" : `xf${i}`;
    const xfadeTransition = smooth
      ? curatedArchiveOnlyVisuals()
        ? "dissolve"
        : pickMontageXfadeTransition(sceneIndex, i)
      : pickStockMontageXfadeTransition(sceneIndex, i);
    const safeOffset = Math.max(0, Math.min(offset, Math.max(0, prevDur - xfade - 0.01)));
    mergeFilter += `;[${prev}][v${i}]xfade=transition=${xfadeTransition}:duration=${xfade.toFixed(3)}:offset=${safeOffset.toFixed(3)}[${outLabel}]`;
    prev = outLabel;
    prevDur = prevDur + durs[i]! - xfade;
    offset += durs[i]! - xfade;
  }
  return { scaleFilters, mergeFilter, montageLabel: "montage" };
}



function buildTopicAnchoredQueries(
  scene: Scene,
  videoTitle?: string,
  personName?: string,
  _prompt?: string,
  beatText?: string
): string[] {
  const person = personName || scene.personNames?.[0] || extractPrimaryPersonFromTitle(videoTitle) || "";
  const titleLower = asVideoTitleString(videoTitle).toLowerCase();
  const textLower = (beatText ?? scene.text).toLowerCase();
  const script = beatText?.trim() || scene.text;
  const queries: string[] = [];

  queries.push(...scriptStockSearchQueries(script));
  queries.push(
    enrichStockQuery(scene.literalVisualCue ?? "", scene, videoTitle, person, script),
    enrichStockQuery(scene.pexelsQuery, scene, videoTitle, person, script),
    enrichStockQuery(scene.visualCue, scene, videoTitle, person, script),
    ...(scene.pexelsQueries ?? []).map((q) => enrichStockQuery(q, scene, videoTitle, person, script)),
    ...(scene.brollQueries ?? []).map((q) => enrichStockQuery(q, scene, videoTitle, person, script)),
  );

  if (titleLower.includes("tesla") || textLower.includes("tesla")) {
    queries.push("tesla", "factory", "car");
  }
  if (titleLower.includes("spacex") || textLower.includes("spacex") || textLower.includes("rocket")) {
    queries.push("spacex", "rocket");
  }

  const allowSolar = /solar|photovoltaic|sun energy|panel|zon\b|sun\b/.test(textLower);
  return uniqueCoercedQueries(queries, 3, (q) => {
    if (isBlockedStockQuery(q)) return false;
    if (!allowSolar && stockVisualCategory(q) === "solar") return false;
    return true;
  });
}

